# Threads de connexion DMX encore en vol. Un QThread détruit pendant qu'il
# tourne fait tomber le process : on garde une référence jusqu'à sa fin.
_PENDING_DMX_CONNECTS = set()


class _DmxConnectWorker(QThread):
    """Ouvre la sortie DMX hors du thread GUI.

    `ArtNetDMX.connect()` finit sur `serial.Serial()` ou une ouverture D2XX :
    appels système bloquants, sans borne de temps quand le boîtier ne répond
    pas (typique sur macOS quand la puce FTDI est déjà réservée). Appelé sur le
    thread GUI au démarrage, il gelait MyStrow avant même l'affichage de la
    fenêtre — seul un « Forcer à quitter » en sortait.
    """

    result = Signal(bool)

    def __init__(self, dmx, kwargs=None):
        super().__init__(None)
        self._dmx = dmx
        self._kwargs = kwargs or {}

    def run(self):
        try:
            self.result.emit(bool(self._dmx.connect(**self._kwargs)))
        except Exception as e:
            print(f"[DMX] connexion échouée: {e}")
            self.result.emit(False)


class FlowLayout(QLayout):
    """
    Layout qui place les widgets de gauche à droite et passe à la ligne quand
    la largeur est atteinte. Utilisé pour les pastilles de canaux DMX : une
    lyre 32 canaux ne doit pas déborder de la fenêtre.
    """

    def __init__(self, parent=None, margin=0, spacing=4):
        super().__init__(parent)
        self._items = []
        self.setContentsMargins(margin, margin, margin, margin)
        self.setSpacing(spacing)

    def __del__(self):
        while self._items:
            self._items.pop()

    def addItem(self, item):
        self._items.append(item)

    def count(self):
        return len(self._items)

    def itemAt(self, index):
        return self._items[index] if 0 <= index < len(self._items) else None

    def takeAt(self, index):
        return self._items.pop(index) if 0 <= index < len(self._items) else None

    def expandingDirections(self):
        return Qt.Orientations(Qt.Orientation(0))

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._do_layout(QRect(0, 0, width, 0), test_only=True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._do_layout(rect, test_only=False)

    def sizeHint(self):
        return self.minimumSize()

    def minimumSize(self):
        size = QSize()
        for item in self._items:
            size = size.expandedTo(item.minimumSize())
        m = self.contentsMargins()
        return size + QSize(m.left() + m.right(), m.top() + m.bottom())

    def _do_layout(self, rect, test_only):
        m = self.contentsMargins()
        eff = rect.adjusted(m.left(), m.top(), -m.right(), -m.bottom())
        x, y, line_h = eff.x(), eff.y(), 0
        space = self.spacing()

        for item in self._items:
            hint = item.sizeHint()
            next_x = x + hint.width() + space
            if next_x - space > eff.right() and line_h > 0:
                x = eff.x()
                y = y + line_h + space
                next_x = x + hint.width() + space
                line_h = 0
            if not test_only:
                item.setGeometry(QRect(QPoint(x, y), hint))
            x = next_x
            line_h = max(line_h, hint.height())

        return y + line_h - rect.y() + m.bottom()


class ElidedLabel(QLabel):
    """
    QLabel qui tronque son texte avec « … » au lieu de pousser la fenêtre.
    Le texte complet reste accessible en infobulle.
    """

    def __init__(self, text="", parent=None, mode=Qt.ElideRight):
        super().__init__(text, parent)
        self._full_text = text
        self._mode = mode
        self.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Preferred)
        self.setMinimumWidth(0)

    def setText(self, text):
        self._full_text = text or ""
        if self._full_text:
            self.setToolTip(self._full_text)
        self._apply_elide()

    def text(self):
        return self._full_text

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._apply_elide()

    def _apply_elide(self):
        w = max(0, self.width())
        if w <= 0:
            super().setText(self._full_text)
            return
        fm = QFontMetrics(self.font())
        super().setText(fm.elidedText(self._full_text, self._mode, w))
