        self.setWindowTitle(tr("akai_cfg_title"))
        self.setFixedSize(700, 440)
        self.setModal(True)
        self.setStyleSheet("""
            QDialog  { background: #0d0d0d; color: #ddd; }
            QLabel   { background: transparent; border: none; color: #ddd; }
            QCheckBox { color: #aaa; font-size: 10px; spacing: 8px; }
            QCheckBox::indicator {
                width: 14px; height: 14px; border: 1px solid #3a3a3a;
                border-radius: 4px; background: #1a1a1a;
            }
            QCheckBox::indicator:checked { background: #0077bb; border-color: #0099dd; }
            QCheckBox:hover { color: #fff; }
            QSlider::groove:horizontal { height:3px; background:#2a2a2a; border-radius:2px; }
            QSlider::handle:horizontal { width:12px; height:12px; margin:-5px 0;
                background:#0077bb; border-radius:6px; }
            QSlider::sub-page:horizontal { background:#005a99; border-radius:2px; }
        """)

        self._combos = []
        self._faders = []
        # Pages de layout : le dialogue édite les N pages ; le sélecteur en haut
        # choisit la page en cours d'édition. `slots` = page active (construit les combos).
        if pages:
            self._pages = [[dict(s) for s in p] for p in pages]
            self._cur_page = max(0, min(int(page_idx), len(self._pages) - 1))
        else:
            self._pages = [[dict(s) for s in slots]]
            self._cur_page = 0
        slots = self._pages[self._cur_page]
        # Slots d'origine — sert à préserver le réglage fader des colonnes POS
        # (axe pan/tilt + groupe), non éditable ici mais à ne pas écraser.
        self._initial_slots = [dict(s) for s in slots]

        root = QVBoxLayout(self)
        root.setContentsMargins(20, 16, 20, 16)
