    _BASE_PAD_COLORS = [
        QColor("white"), QColor("#ff0000"), QColor("#ff8800"), QColor("#ffdd00"),
        QColor("#00ff00"), QColor("#00dddd"), QColor("#0000ff"), QColor("#ff00ff")
    ]

    def _group_pad_colors(self, group_projs):
        """Retourne (colors[8], cw_dmx_vals[8]) pour les pads AKAI du groupe.

        Les couleurs visuelles sont TOUJOURS les 8 couleurs standard.
        cw_dmx_vals contient les valeurs DMX pré-calculées vers le slot de roue
        le plus proche pour chaque couleur (None si pas de roue de couleurs).
        """
        defaults = self._BASE_PAD_COLORS
        # Chercher une fixture avec roue de couleurs (sans canal RGB direct)
        cw_proj = next(
            (p for p in group_projs
             if getattr(p, 'color_wheel_slots', [])
             and 'R' not in getattr(p, 'dmx_profile', [])),
            None
        )
        if cw_proj:
            slots = cw_proj.color_wheel_slots
            cw_vals = [self._nearest_cw_dmx(c, slots) for c in defaults]
            return list(defaults), cw_vals  # couleurs visuelles inchangées
        return list(defaults), [None] * 8

    @staticmethod
    def _nearest_cw_dmx(target_color: QColor, slots: list) -> int:
        """Retourne la valeur DMX du slot de roue dont la couleur est la plus proche."""
        best_dmx, best_dist = 0, float('inf')
        tr, tg, tb = target_color.red(), target_color.green(), target_color.blue()
        for slot in slots:
            c = QColor(slot.get("color", "#ffffff"))
            dist = (c.red()-tr)**2 + (c.green()-tg)**2 + (c.blue()-tb)**2
            if dist < best_dist:
                best_dist = dist
                best_dmx = int(slot.get("dmx", 0))
        return best_dmx

    def _rebuild_akai_pads(self):
        """Rebuilds the 8x8 pad grid based on current bank preset."""
        # Cache des couleurs par lettre de groupe (calculé une fois par rebuild)
        _group_colors_cache = {}

        def _get_group_colors(slot_letter):
            if slot_letter not in _group_colors_cache:
                internal = AKAI_GROUP_MAP.get(slot_letter, slot_letter)
                group_projs = [p for p in self.projectors if p.group == internal]
                _group_colors_cache[slot_letter] = self._group_pad_colors(group_projs)
            return _group_colors_cache[slot_letter]

        # Clear existing pads
        self.pads.clear()
        while self._pads_grid.count():
            item = self._pads_grid.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        for r in range(8):
            for c in range(8):
                slot = self._fader_map[c]
                if slot["type"] == "group":
                    col_letter = slot.get("group", "A")
                    pad_colors, cw_dmx_vals = _get_group_colors(col_letter)
                    col = pad_colors[r]
                    cw_dmx = cw_dmx_vals[r]
                    b = QPushButton()
                    b.setFixedSize(28, 28)
                    dim_color = QColor(int(col.red() * 0.5), int(col.green() * 0.5), int(col.blue() * 0.5))
                    b.setStyleSheet(f"QPushButton {{ background: {dim_color.name()}; border: 1px solid #2a2a2a; border-radius: 4px; }}")
                    b.setProperty("base_color", col)
                    b.setProperty("color2", None)
                    b.setProperty("dim_color", dim_color)
                    b.setProperty("cw_dmx_val", cw_dmx)  # None si RGB, int si roue de couleurs
                    b.clicked.connect(lambda _, btn=b, fc=c: self.activate_pad(btn, fc))
                elif slot["type"] == "fx":
                    fx_col = slot.get("fx_col", 0)
                    b = QPushButton()
                    b.setFixedSize(28, 28)
                    cfg = self.fx_pads[fx_col][r] if fx_col < _FX_COL_MAX else None
                    active = self.active_fx_pads.get((fx_col, r))
                    if active and cfg:
                        b.setStyleSheet("QPushButton { background: #33ff33; border: 2px solid #ffffff; border-radius: 4px; }")
                    elif cfg:
                        b.setStyleSheet("QPushButton { background: #116611; border: 1px solid #114411; border-radius: 4px; }")
                        b.setToolTip(cfg.get("name", ""))
                    else:
                        b.setStyleSheet("QPushButton { background: #0a1a0a; border: 1px solid #1a2a1a; border-radius: 4px; }")
                    b.setProperty("base_color", QColor("#33ff33"))
                    b.setProperty("color2", None)
                    b.setProperty("fx_col", fx_col)
                    b.setProperty("fx_row", r)
                    b.clicked.connect(lambda _, fc=fx_col, fr=r: self._toggle_fx_pad(fc, fr))
                    b.setContextMenuPolicy(Qt.CustomContextMenu)
                    b.customContextMenuRequested.connect(
                        lambda pos, fc=fx_col, fr=r, btn=b: self._show_fx_context_menu(pos, fc, fr, btn)
                    )
                elif slot["type"] == "pos":
                    pos_col = slot.get("pos_col", 0)
                    b = QPushButton()
                    b.setFixedSize(28, 28)
                    b.setStyleSheet("QPushButton { background: #0a0a22; border: 1px solid #1a1a44; border-radius: 4px; }")
                    b.setProperty("base_color", QColor("#2255ee"))
                    b.setProperty("color2", None)
                    b.setProperty("pos_col", pos_col)
                    b.setProperty("pos_row", r)
                    b.clicked.connect(lambda _, pc=pos_col, pr=r, ca=c: self._activate_position_akai_pad(None, pc, pr, col_akai=ca))
                    b.setContextMenuPolicy(Qt.CustomContextMenu)
                    b.customContextMenuRequested.connect(
                        lambda p, pc=pos_col, pr=r, btn=b: self._show_pos_context_menu(p, pc, pr, btn)
                    )
                elif slot["type"] == "play":
                    action, glyph, color = _play_rows(slot)[r]
                    b = QPushButton(glyph)
                    b.setFixedSize(28, 28)
                    _qc = QColor(color)
                    if action is None:
                        # Pad vide (variante TRANSPORT, lignes inutilisées)
                        b.setStyleSheet(
                            "QPushButton { background: #0e0e0e; border: 1px solid #1a1a1a; "
                            "border-radius: 4px; }"
                        )
                        b.setEnabled(False)
                        b.setProperty("base_color", QColor("#101010"))
                        b.setProperty("play_action", None)
                    else:
                        b.setStyleSheet(
                            f"QPushButton {{ background: {_qc.darker(170).name()}; "
                            f"color: {color}; border: 1px solid {_qc.darker(230).name()}; "
                            f"border-radius: 4px; font-size: 12px; font-weight: bold; }}"
                        )
                        b.setProperty("base_color", _qc)
                        b.setProperty("play_action", action)
                        b.setToolTip({
                            "playpause": "Play / Pause", "prev": "Précédent", "next": "Suivant",
                            "stop": "Stop", "cart0": "Cartouche 1", "cart1": "Cartouche 2",
                            "cart2": "Cartouche 3", "cart3": "Cartouche 4",
                        }.get(action, action))
                        b.clicked.connect(lambda _, a=action: self._activate_play_pad(a))
                    b.setProperty("color2", None)
                else:  # memory
                    mem_col = slot["mem_col"]
                    b = QPushButton()
                    b.setFixedSize(28, 28)
                    b.setStyleSheet("QPushButton { background: #1a1a1a; border: 1px solid #1a1a1a; border-radius: 4px; }")
                    b.setProperty("base_color", QColor("black"))
                    b.setProperty("color2", None)
                    b.setProperty("memory_col", mem_col)
                    b.setProperty("memory_row", r)
                    b.clicked.connect(lambda _, btn=b, mc=mem_col, mr=r, ca=c: self._activate_memory_pad(btn, mc, mr, col_akai=ca))
                    b.setContextMenuPolicy(Qt.CustomContextMenu)
                    b.customContextMenuRequested.connect(
                        lambda pos, mc=mem_col, mr=r, btn=b: self._show_memory_context_menu(pos, mc, mr, btn)
                    )

                self._pads_grid.addWidget(b, r, c)
                self.pads[(r, c)] = b

        # Refresh memory pad styles
        for fi, mc in self._bank_memory_slots():
            for mr in range(8):
                self._style_memory_pad(mc, mr, active=self.active_memory_pads.get(fi) == mr)

        # Refresh position pad styles + LED physique
        for fi, pc in self._bank_pos_slots():
            for pr in range(8):
                self._style_position_akai_pad(pc, pr)
                self._update_pos_pad_led(pc, pr)

        # Refresh active color pads
        for col_idx, btn in list(self.active_pads.items()):
            slot = self._fader_map[col_idx] if col_idx < len(self._fader_map) else None
            if slot and slot["type"] == "group":
                new_btn = self.pads.get((
                    next((r for r in range(8) if self.pads.get((r, col_idx)) and
                          self.pads.get((r, col_idx)).property("base_color") == btn.property("base_color")), 0),
                    col_idx
                ))
                if new_btn:
                    color = new_btn.property("base_color")
                    new_btn.setStyleSheet(f"QPushButton {{ background: {color.name()}; border: 2px solid {color.lighter(130).name()}; border-radius: 4px; }}")
                    self.active_pads[col_idx] = new_btn

        # Colonnes PLAY : LEDs + fader aligné sur le volume courant (défaut 100 %)
        for c in self._play_columns():
            if c in self.faders and hasattr(self, "audio"):
                try:
                    self.faders[c].value = int(round(self.audio.volume() * 100))
                    self.faders[c].update()
                except Exception:
                    pass
        self._refresh_play_leds()

    def _play_columns(self):
        """Indices des colonnes assignées au type 'play'."""
        return [c for c, s in enumerate(self._fader_map) if s.get("type") == "play"]

    def _refresh_play_leds(self):
        """Allume les LEDs des pads des colonnes PLAY sur l'APC (play/pause suit l'état)."""
        if not (MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out):
            return
        try:
            playing = self.player.playbackState() == QMediaPlayer.PlayingState
        except Exception:
            playing = False
        for c in self._play_columns():
            rows = _play_rows(self._fader_map[c]) if c < len(self._fader_map) else _PLAY_ROWS
            for r, (action, _glyph, color) in enumerate(rows):
                if action is None:
                    self.midi_handler.set_pad_led(r, c, 0, brightness_percent=0)
                    continue
                qc = QColor(color)
                vel = rgb_to_akai_velocity(qc)
                if action == "playpause":
                    bri = self.akai_active_brightness if playing else self.akai_inactive_brightness
                else:
                    bri = self.akai_inactive_brightness
                # Passer le VRAI RGB : les LEDs RGB natives (Launchpad MK3) affichent
                # la couleur exacte au lieu de la velocity approximée (orange/rouge → blanc).
                self.midi_handler.set_pad_led(r, c, vel, brightness_percent=bri,
                                              rgb=(qc.red(), qc.green(), qc.blue()))

    def _activate_play_pad(self, action):
        """Déclenche l'action d'un pad de la colonne PLAY (playpause/prev/next/stop/cartN)."""
        try:
            if action == "playpause":
                self.toggle_play()
            elif action == "prev":
                self.previous_media()
            elif action == "next":
                self.next_media()
            elif action == "stop":
                self.player.stop()
                self._stop_all_cartouches()
            elif action.startswith("cart"):
                self.on_cartouche_clicked(int(action[4:]))
        except Exception as e:
            print(f"[play pad] erreur action '{action}': {e}")
        self._refresh_play_leds()

    def _open_fader_slot_picker(self, fader_idx):
        """Ouvre le picker d'assignation directement depuis l'étiquette du fader."""
        cur_slot = self._custom_bank_slots[fader_idx]
        current = cur_slot["label"]
        cur_axis = cur_slot.get("fader_axis") if cur_slot.get("type") == "pos" else None
        cur_group = cur_slot.get("fader_group") if cur_slot.get("type") == "pos" else None
        picker = _SlotPickerPopup(_AKAI_SLOT_OPTIONS, current, self,
                                  enable_pos_config=True, cur_axis=cur_axis, cur_group=cur_group)

        def _apply_slot(value, slot):
            self._custom_bank_slots[fader_idx] = slot
            # Mettre à jour l'étiquette + tooltip
            if fader_idx < len(self._fader_label_widgets):
                lbl = self._fader_label_widgets[fader_idx]
                lbl.setText(_fader_label_text(value))
                lbl.setToolTip(_fader_label_tooltip(slot))
            # Reconstruire les pads et syncer
            self.active_pads.clear()
            self.active_memory_pads.clear()
            self._rebuild_akai_pads()
            self.activate_default_white_pads()
            self._save_akai_config_auto()

        def _on_selected(value):
            if value.startswith("MEM "):
                mem_col = int(value.split()[1]) - 1
                slot = {"type": "memory", "mem_col": mem_col, "label": value}
            elif value.startswith("FX "):
                fx_col = int(value.split()[1]) - 1
                slot = {"type": "fx", "fx_col": fx_col, "label": value}
            elif value.startswith("POS "):
                pos_col = int(value.split()[1]) - 1
                slot = {"type": "pos", "pos_col": pos_col, "label": value}
            elif value == "PLAY":
                slot = {"type": "play", "label": "PLAY"}
            elif value == "SANS SLOT":
                slot = {"type": "play", "slots": False, "label": "SANS SLOT"}
            else:
                slot = {"type": "group", "group": value, "label": value}
            _apply_slot(value, slot)

        def _on_pos_selected(value, axis, group):
            pos_col = int(value.split()[1]) - 1
            slot = {"type": "pos", "pos_col": pos_col, "label": value,
                    "fader_axis": axis, "fader_group": group}
            _apply_slot(value, slot)

        picker.selected.connect(_on_selected)
        picker.pos_selected.connect(_on_pos_selected)
        btn = self._fader_label_widgets[fader_idx]
        pos = btn.mapToGlobal(btn.rect().topLeft())
        picker.move(pos.x(), pos.y() - 360)
        picker.show()
        picker._keep_on_screen()

    def _open_midi_mapping_wizard(self):
        """Ouvre l'assistant de mapping pour configurer un nouveau contrôleur MIDI."""
        wizard = MidiMappingWizard(self.midi_handler, self)
        wizard.profile_saved.connect(self._on_custom_profile_saved)
        wizard.exec()

    def _on_custom_profile_saved(self, profile_path: str):
        """Appelé quand le wizard enregistre un profil — reconnecte le contrôleur."""
        if self.midi_handler:
            self.midi_handler.connect_controller()
            QTimer.singleShot(300, self.activate_default_white_pads)

    def _open_akai_diagnostic(self):
        """Ouvre la fenêtre de diagnostic AKAI."""
        dlg = AkaiDiagnosticDialog(self.midi_handler, self)
        dlg.exec()

    def _open_akai_layout_editor(self):
        """Ouvre l'éditeur de layout du contrôleur (édition multi-pages)."""
        dlg = AkaiLayoutEditorDialog(
            self._custom_bank_slots,
            last_fader_mode=getattr(self, '_last_fader_mode', 'FX'),
            superposition=self.effect_superposition,
            go_mode=self.go_mode,
            active_brightness=self.akai_active_brightness,
            inactive_brightness=self.akai_inactive_brightness,
            parent=self,
            pages=self._bank_pages,
            page_idx=self._bank_page_idx,
        )
        if dlg.exec() != QDialog.Accepted:
            return
        # Récupérer les pages éditées + la page sélectionnée devient la page active
        self._bank_pages = dlg.get_pages()
        self._bank_page_idx = max(0, min(dlg.get_current_index(), len(self._bank_pages) - 1))
        self._custom_bank_slots = self._bank_pages[self._bank_page_idx]
        self.effect_superposition = dlg.get_superposition()
        self.go_mode = dlg.get_go_mode()
        self.akai_active_brightness   = dlg.get_active_brightness()
        self.akai_inactive_brightness = dlg.get_inactive_brightness()
        self._update_tap_go_btn_style()
        self.active_pads.clear()
        self.active_memory_pads.clear()
        self._rebuild_akai_pads()
        try:
            import tablet_server as _ts
            if _ts.is_running():
                _ts.push_layout(self._custom_bank_slots)
        except Exception:
            pass
        if hasattr(self, '_fader_label_widgets'):
            for i, lbl in enumerate(self._fader_label_widgets):
                if i < len(self._fader_map):
                    lbl.setText(_fader_label_text(self._fader_map[i]["label"]))
                    lbl.setToolTip(_fader_label_tooltip(self._fader_map[i]))
        self._sync_controls_to_state()   # reflète l'état courant, ne renvoie aucun DMX
        self._update_bank_page_indicator()
        self._save_akai_config_auto()

    # ── Pages de layout AKAI (navigables en live ◀ ▶) ─────────────────────────

    def _apply_active_bank_layout(self):
        """Applique la page active à l'APC : reconstruit pads/faders, LEDs, labels,
        pousse à la tablette. Partagé par la bascule de page et l'édition."""
        self.active_pads.clear()
        self.active_memory_pads.clear()
        self._rebuild_akai_pads()
        if hasattr(self, '_fader_label_widgets'):
            for i, lbl in enumerate(self._fader_label_widgets):
                if i < len(self._fader_map):
                    lbl.setText(_fader_label_text(self._fader_map[i]["label"]))
                    lbl.setToolTip(_fader_label_tooltip(self._fader_map[i]))
        self._sync_controls_to_state()   # reflète l'état courant, ne renvoie aucun DMX
        self._update_bank_page_indicator()
        try:
            import tablet_server as _ts
            if _ts.is_running():
                _ts.push_layout(self._custom_bank_slots)
                if hasattr(_ts, "push_bank_pages"):
                    _ts.push_bank_pages(len(self._bank_pages), self._bank_page_idx)
        except Exception:
            pass

    def _set_bank_page(self, idx):
        """Bascule sur la page de layout `idx` (bornée).
        Une page = une SURFACE DE CONTRÔLE (quel fader/pad pilote quoi), PAS une scène.
        Le changement de page ne modifie JAMAIS l'état lumineux : on re-mappe les
        contrôles puis on les aligne sur l'état courant du rig (voir _sync_controls_to_state)."""
        pages = getattr(self, "_bank_pages", None)
        if not pages:
            return
        idx = max(0, min(int(idx), len(pages) - 1))
        if idx == self._bank_page_idx and self._custom_bank_slots is pages[idx]:
            self._update_bank_page_indicator()
            return
        self._bank_page_idx = idx
        self._custom_bank_slots = pages[idx]
        self._apply_active_bank_layout()      # rebuild + _sync_controls_to_state (aucun DMX renvoyé)
        self._save_akai_config_auto()

    def _current_group_pad_row(self, col, slot):
        """Ligne du pad de la colonne `col` dont la couleur == base_color COURANTE du groupe.
        Sert à refléter la couleur active sans jamais la modifier. Défaut = 0 (blanc)."""
        groups = self._slot_groups(slot)
        cur = None
        for p in self.projectors:
            if p.group in groups:
                cur = getattr(p, "base_color", None)
                break
        if isinstance(cur, QColor):
            for r in range(8):
                pad = self.pads.get((r, col))
                if pad:
                    pc = pad.property("base_color")
                    if isinstance(pc, QColor) and pc.rgb() == cur.rgb():
                        return r
        return 0

    def _sync_controls_to_state(self):
        """Après un changement de page : la surface de contrôle change, PAS l'état lumineux.
        On aligne seulement les faders et les pads actifs sur l'état COURANT de ce qu'ils
        contrôlent désormais — aucun envoi DMX, aucune perte de lumière (pupitre à pages)."""
        # Pads groupe : refléter la couleur courante de chaque groupe (sans la changer)
        group_rows = {}
        for col, slot in enumerate(self._fader_map):
            if slot.get("type") == "group":
                group_rows[col] = self._current_group_pad_row(col, slot)
        self.activate_default_white_pads(group_rows=group_rows)

        # Faders : refléter le niveau courant de la cible (JAMAIS de set_proj_level)
        try:
            import tablet_server as _ts
            ts_on = _ts.is_running()
        except Exception:
            _ts, ts_on = None, False
        for i in range(8):
            if i not in self.faders or i >= len(self._fader_map):
                continue
            slot = self._fader_map[i]
            stype = slot.get("type")
            if stype == "group":
                groups = self._slot_groups(slot)
                val = 0
                for p in self.projectors:
                    if p.group in groups:
                        val = max(val, int(getattr(p, "level", 0)))
            elif stype == "fx":
                fx_col = slot.get("fx_col", 0)
                val = int(self.fx_amplitudes[fx_col]) if 0 <= fx_col < _FX_COL_MAX else 0
            elif stype == "play":
                # Colonne PLAY : le fader reflète le volume courant du lecteur
                try:
                    val = int(round(self.audio.volume() * 100))
                except Exception:
                    val = 100
            else:
                # mémoire / position : surface neutre, on ne pilote rien
                val = 0
            val = max(0, min(100, val))
            self.faders[i].value = val
            self.faders[i].update()
            if ts_on:
                _ts.push_fader(i, val)

    def _startup_faders_down(self):
        """Démarrage : force TOUS les faders colonnes (0-7) à 0 ET éteint leur cible,
        pour que rien ne soit allumé au lancement. Exécuté tardivement (après les syncs
        de connexion) afin de ne pas se faire remonter."""
        try:
            import tablet_server as _ts
            ts_on = _ts.is_running()
        except Exception:
            _ts, ts_on = None, False
        for i in range(8):
            # La colonne PLAY = volume : ne JAMAIS la baisser au démarrage
            # (sinon le son est coupé au lancement — piège ergonomique).
            if i < len(self._fader_map) and self._fader_map[i].get("type") == "play":
                continue
            if i in self.faders:
                self.faders[i].value = 0
                self.faders[i].update()
                self.set_proj_level(i, 0)
                if ts_on:
                    _ts.push_fader(i, 0)

    def _next_bank_page(self):
        if getattr(self, "_bank_pages", None):
            self._set_bank_page((self._bank_page_idx + 1) % len(self._bank_pages))

    def _prev_bank_page(self):
        if getattr(self, "_bank_pages", None):
            self._set_bank_page((self._bank_page_idx - 1) % len(self._bank_pages))

    def _update_bank_page_indicator(self):
        """Met à jour l'affichage du numéro de page courant (sans total, gain de place)."""
        lbl = getattr(self, "_bank_page_lbl", None)
        if lbl is not None:
            lbl.setText(str(self._bank_page_idx + 1))

    def create_transport_panel(self):
        """Cree le panneau transport avec timeline"""
        frame = QFrame()
        frame.setFixedHeight(150)
        layout = QVBoxLayout(frame)
        layout.setContentsMargins(10, 10, 10, 10)

        # Timeline
        timeline_container = QHBoxLayout()

        self.time_label = QLabel("00:00")
        self.time_label.setStyleSheet("color: #00d4ff; font-weight: bold; font-size: 12px; border: none; background: transparent;")
        self.time_label.setFixedWidth(50)
        timeline_container.addWidget(self.time_label)

        self.timeline = QSlider(Qt.Horizontal)
        self.timeline.setFixedHeight(30)
        self.timeline.setStyleSheet("""
            QSlider::groove:horizontal {
                background: #ffffff;
                height: 12px;
                border-radius: 6px;
                border: 1px solid #00d4ff;
            }
            QSlider::handle:horizontal {
                background: #00d4ff;
                width: 24px;
                height: 24px;
                margin: -6px 0;
                border-radius: 12px;
                border: 3px solid #ffffff;
            }
        """)
        self.player.durationChanged.connect(self.timeline.setMaximum)
        self.player.positionChanged.connect(self.on_timeline_update)
        self.timeline.sliderMoved.connect(self.player.setPosition)
        timeline_container.addWidget(self.timeline)

        self.remaining_label = QLabel("-00:00")
        self.remaining_label.setStyleSheet("color: #ff8800; font-weight: bold; font-size: 12px; border: none; background: transparent;")
        self.remaining_label.setFixedWidth(60)
        self.remaining_label.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        timeline_container.addWidget(self.remaining_label)

        layout.addLayout(timeline_container)

        # Waveform
        self.recording_waveform = RecordingWaveform()
        self.recording_waveform.setFixedHeight(30)
        self.recording_waveform.hide()
        layout.addWidget(self.recording_waveform)

        layout.addSpacing(8)

        # Boutons transport
        btns = QHBoxLayout()
        btns.setSpacing(10)

        side_style = """
            QToolButton {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 #3a3a3a, stop:1 #222222);
                border: 1px solid #555555;
                border-radius: 22px;
                padding: 10px;
            }
            QToolButton:hover {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 #444444, stop:1 #2a2a2a);
                border: 1px solid #00d4ff;
            }
            QToolButton:pressed {
                background: #1a1a1a;
                border: 1px solid #00aacc;
            }
        """

        play_style = """
            QToolButton {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 #006680, stop:1 #003344);
                border: 2px solid #00d4ff;
                border-radius: 32px;
                padding: 14px;
            }
            QToolButton:hover {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 #008aaa, stop:1 #004455);
                border: 2px solid #33eeff;
            }
            QToolButton:pressed {
                background: #002233;
                border: 2px solid #0099bb;
            }
        """

        prev = QToolButton()
        prev.setIcon(create_icon("prev", "#cccccc"))
        prev.setIconSize(QSize(28, 28))
        prev.setFixedSize(52, 52)
        prev.setStyleSheet(side_style)
        prev.setToolTip(tr("mw_prev_media"))
        prev.clicked.connect(lambda: self.seq.play_row(self.seq.current_row - 1))

        self.play_btn = QToolButton()
        self.play_btn.setIcon(create_icon("play", "#ffffff"))
        self.play_btn.setIconSize(QSize(36, 36))
        self.play_btn.setFixedSize(72, 72)
        self.play_btn.setStyleSheet(play_style)
        self.play_btn.setToolTip(tr("mw_play_pause"))
        self.play_btn.clicked.connect(self.toggle_play)

        nxt = QToolButton()
        nxt.setIcon(create_icon("next", "#cccccc"))
        nxt.setIconSize(QSize(28, 28))
        nxt.setFixedSize(52, 52)
        nxt.setStyleSheet(side_style)
        nxt.setToolTip(tr("mw_next_media"))
        nxt.clicked.connect(lambda: self.seq.play_row(self.seq.current_row + 1))

        btns.addStretch()
        btns.addWidget(prev)
        btns.addSpacing(4)
        btns.addWidget(self.play_btn)
        btns.addSpacing(4)
        btns.addWidget(nxt)
        btns.addStretch()
        layout.addLayout(btns)

        return frame

    def trigger_pause_mode(self):
        """Active le mode pause sans clignotement"""
        self.pause_mode = True
        self.player.pause()
        if self.blink_timer:
            self.blink_timer.stop()
            self.blink_timer = None

    def toggle_play(self):
        """Toggle play/pause - gere aussi les TEMPO"""
        # Pause d'un TEMPO en cours
        if self.seq.tempo_running:
            self.seq.tempo_running = False
            self.seq.tempo_paused = True
            self.seq.tempo_timer.stop()
            if self.seq.timeline_playback_timer and self.seq.timeline_playback_timer.isActive():
                self.seq.timeline_playback_timer.stop()
            self.play_btn.setIcon(create_icon("play", "#ffffff"))
            return

        # Reprise d'un TEMPO en pause
        if self.seq.tempo_paused:
            self.seq.tempo_running = True
            self.seq.tempo_paused = False
            self.seq.tempo_timer.start(100)
            if hasattr(self.seq, 'timeline_playback_row') and self.seq.timeline_playback_timer:
                self.seq.timeline_playback_timer.start(50)
            self.play_btn.setIcon(create_icon("pause", "#ffffff"))
            return

        # Lecture normale
        if self.pause_mode:
            if self.blink_timer:
                self.blink_timer.stop()
            self.pause_mode = False
            # Arrêt défensif du timeline si le media courant est en mode Manuel
            current_mode = self.seq.get_dmx_mode(self.seq.current_row)
            if current_mode == "Manuel":
                self.seq.stop_sequence_playback()
            # Repasser sur le widget video (peut être masqué si pause après PAUSE + precharge)
            self.hide_image()
            self.player.play()
            self._update_video_output_state()
        elif self.player.playbackState() == QMediaPlayer.PlayingState:
            self.player.pause()
        else:
            # Rien en lecture. Si la playlist n'a jamais démarré (aucun média
            # chargé), lancer directement le média sélectionné (ou le 1er) —
            # évite d'avoir à double-cliquer sur le premier média.
            if self.seq.current_row < 0 and self.seq.table.rowCount() > 0:
                target = self.seq.table.currentRow()
                if target < 0:
                    target = 0
                self.seq.play_row(target)
            else:
                self.player.play()

    def update_play_icon(self, s):
        """Met a jour l'icone play/pause"""
        if s == QMediaPlayer.PlayingState:
            self.play_btn.setIcon(create_icon("pause", "#ffffff"))
        else:
            self.play_btn.setIcon(create_icon("play", "#ffffff"))
        # Refléter l'état sur la LED play/pause des colonnes PLAY de l'APC
        if hasattr(self, "_refresh_play_leds"):
            self._refresh_play_leds()

    def on_timeline_update(self, position):
        """Met a jour la timeline"""
        try:
            duration = self.player.duration()
            if duration > 0 and self.timeline.maximum() != duration:
                self.timeline.setMaximum(duration)
            if duration > 0:
                position = min(position, duration)
            self.timeline.setValue(position)
            self.time_label.setText(fmt_time(position))
            if duration > 0:
                remaining = duration - position
                self.remaining_label.setText(f"-{fmt_time(remaining)}")
            if self.seq.recording and self.recording_waveform.isVisible():
                self.recording_waveform.set_position(position, duration)
        except:
            pass

    def on_media_status_changed(self, status):
        """Passe automatiquement au suivant ou gere les pauses"""
        if status == QMediaPlayer.EndOfMedia:
            # Guard : le backend WMF (Windows) peut émettre EndOfMedia sur un
            # silence long avant la vraie fin du fichier. On vérifie que la
            # position est bien proche de la durée réelle avant d'agir.
            pos = self.player.position()
            dur = self.player.duration()
            if dur > 0 and pos < dur - 2000:
                return  # Faux EndOfMedia sur un silence — ignorer

            # Verifier que c'est bien le media courant qui est termine
            # (evite qu'un EndOfMedia retarde d'un ancien media avance au mauvais rang)
            source_row = getattr(self, '_media_source_row', self.seq.current_row)
            if source_row != self.seq.current_row:
                # EndOfMedia d'un ancien media: ignorer
                return

            if hasattr(self.seq, 'timeline_playback_timer') and self.seq.timeline_playback_timer and self.seq.timeline_playback_timer.isActive():
                self.seq.timeline_playback_timer.stop()
            if hasattr(self.seq, 'timeline_playback_row'):
                del self.seq.timeline_playback_row
            self.seq.timeline_tracks_data = {}

            if self.seq.recording:
                self.stop_recording()
                return

            # Lecture en boucle : rejouer le même média au lieu d'avancer.
            # singleShot(0) = même garde de ré-entrance que l'avance normale.
            if self.seq.is_row_loop(self.seq.current_row):
                loop_row = self.seq.current_row
                QTimer.singleShot(0, lambda r=loop_row: self.seq.play_row(r))
                return

            current_mode = self.seq.get_dmx_mode(self.seq.current_row)
            next_row = self.seq.current_row + 1

            # IA Lumière : fade-out puis transition
            if current_mode == "IA Lumiere":
                self.audio_ai.reset()
                # Réinitialiser l'état interne des lyres + sections + effets aléatoires
                for attr in ('_ia_lyre_e', '_ia_lyre_phase', '_ia_lyre_last_pos',
                             '_ia_lyre_color_smooth', '_ia_sec', '_ia_rnd_fx',
                             '_ia_lyre_chop_until', '_ia_lyre_beat_idx'):
                    self.__dict__.pop(attr, None)

                def _after_ia_fade():
                    if next_row < self.seq.table.rowCount():
                        self.seq.play_row(next_row)
                    else:
                        print("Fin de la sequence")
                        self.update_play_icon(QMediaPlayer.StoppedState)
                        self._update_video_output_state()

                self._ia_start_fadeout(_after_ia_fade)
                return

            if next_row < self.seq.table.rowCount():
                next_mode = self.seq.get_dmx_mode(next_row)
                if current_mode == "Play Lumiere":
                    self.full_blackout()
                elif current_mode == "Programme" and next_mode == "Manuel":
                    self.full_blackout()

                # Différer l'avance : play_row() fait stop()/setSource()/play()
                # sur le QMediaPlayer. Appelé DIRECTEMENT ici, on muterait le
                # player depuis l'intérieur de son propre signal mediaStatusChanged
                # (ré-entrance) → crash natif intermittent aux transitions de
                # média en playlist. singleShot(0) exécute au tour de boucle suivant.
                QTimer.singleShot(0, lambda r=next_row: self.seq.play_row(r))
            else:
                if current_mode == "Play Lumiere":
                    self.full_blackout()
                print("Fin de la sequence")
                self.update_play_icon(QMediaPlayer.StoppedState)
                self._update_video_output_state()

    def dmx_blackout(self):
        """Blackout DMX uniquement (projecteurs) - conserve l'eclairage AKAI"""
        for idx in range(9):
            if idx in self.faders:
                self.faders[idx].value = 0
                self.faders[idx].update()

        for p in self.projectors:
            p.level = 0
            p.color = QColor("black")
            p.base_color = QColor("black")
            p.strobe_speed = 0   # le strobe est de la lumière : il s'éteint au blackout

    def full_blackout(self):
        """Blackout complet"""
        # Vider les overrides HTP
        if hasattr(self, 'plan_de_feu'):
            self.plan_de_feu.set_htp_overrides(None)

        for idx in range(9):
            if idx in self.faders:
                self.faders[idx].value = 0
                self.faders[idx].update()

        for p in self.projectors:
            p.level = 0
            p.color = QColor("black")
            p.base_color = QColor("black")
            p.strobe_speed = 0   # le strobe est de la lumière : il s'éteint au blackout

        for col, pad in self.active_pads.items():
            if pad:
                old_color = pad.property("base_color")
                dim_color = QColor(int(old_color.red() * 0.5), int(old_color.green() * 0.5), int(old_color.blue() * 0.5))
                pad.setStyleSheet(f"QPushButton {{ background: {dim_color.name()}; border: 1px solid #2a2a2a; border-radius: 4px; }}")
        self.active_pads = {}

        for btn in self.effect_buttons:
            if btn.active:
                btn.active = False
                btn.update_style()

        if self.active_effect is not None:
            self.stop_effect()
            self.active_effect = None

        if MIDI_AVAILABLE and self.midi_handler.midi_out:
            for row in range(8):
                for col in range(8):
                    self.midi_handler.set_pad_led(row, col, 0, 0)

    def activate_pad(self, btn, col_idx):
        """Active un pad dans sa colonne (independant par colonne)"""
        color = btn.property("base_color")
        if col_idx >= len(self._fader_map):
            return
        slot = self._fader_map[col_idx]
        if slot["type"] != "group":
            return

        # Mode REC actif : impossible d'enregistrer sur un pad groupe (A/B/C/D/E/F)
        if self._mem_rec_mode:
            self._mem_rec_mode = False
            if self._rec_mem_btn:
                self._rec_mem_btn.setStyleSheet(
                    "QPushButton { background: #1e1e1e; color: #cc3333; border: 1px solid #3a3a3a; "
                    "border-radius: 4px; font-size: 13px; } "
                    "QPushButton:hover { background: #2a2a2a; color: #ff4444; border-color: #cc3333; }"
                )
                self._rec_mem_btn.setToolTip(tr("mw_rec_mem_hint"))
            self._show_error_toast("✖ Impossible d'enregistrer sur un Groupe — Sélectionnez une mémoire")
            return
        target_groups = self._slot_groups(slot)

        # Desactiver l'ancien pad de CETTE colonne uniquement
        prev = self.active_pads.get(col_idx)
        if prev and prev != btn:
            old_color = prev.property("base_color")
            dim_color = QColor(int(old_color.red() * 0.5), int(old_color.green() * 0.5), int(old_color.blue() * 0.5))
            prev.setStyleSheet(f"QPushButton {{ background: {dim_color.name()}; border: 1px solid #2a2a2a; border-radius: 4px; }}")

        btn.setStyleSheet(f"QPushButton {{ background: {color.name()}; border: 2px solid {color.lighter(130).name()}; border-radius: 4px; }}")
        self.active_pads[col_idx] = btn

        # Appliquer la couleur seulement si le fader de cette colonne est leve
        fader_value = self.faders[col_idx].value if col_idx in self.faders else 0
        for p in self.projectors:
            if p.group in target_groups:
                p.base_color = color
                if fader_value > 0:
                    brightness = fader_value / 100.0
                    p.color = QColor(
                        int(color.red() * brightness),
                        int(color.green() * brightness),
                        int(color.blue() * brightness)
                    )
                    cw_dmx = btn.property("cw_dmx_val")
                    if cw_dmx is not None:
                        p.color_wheel = int(cw_dmx)
                    else:
                        self._update_color_wheel(p, color)

        # Envoi DMX immediat sans attendre le prochain tick
        self.send_dmx_update()

    # Slots génériques de roue de couleurs (repli quand la fixture n'a pas de
    # color_wheel_slots OFL) — mêmes valeurs que le menu du plan de feu (parité).
    _GENERIC_WHEEL_SLOTS = [
        {"dmx": 0, "color": "#ffffff"}, {"dmx": 20, "color": "#ff3300"},
        {"dmx": 42, "color": "#ff8800"}, {"dmx": 64, "color": "#ffff00"},
        {"dmx": 85, "color": "#00cc44"}, {"dmx": 106, "color": "#00ccff"},
        {"dmx": 128, "color": "#0044ff"}, {"dmx": 149, "color": "#cc00ff"},
        {"dmx": 170, "color": "#ff99cc"}, {"dmx": 192, "color": "#ffee88"},
    ]

    def _apply_color_wheel_dmx(self, p, dmx: int) -> None:
        """Pose une valeur DMX de roue de couleurs sur un projecteur (chemin tablette).

        Miroir de `_on_cw` du plan de feu : fixe `color_wheel`, puis reflète la
        couleur du slot le plus proche sur `base_color`/`color` (scène 2D + preview)
        et prend la main manuelle pour que les mémoires ne l'écrasent pas."""
        dmx = max(0, min(255, int(dmx)))
        p.color_wheel = dmx
        slots = getattr(p, 'color_wheel_slots', []) or self._GENERIC_WHEEL_SLOTS
        passed = [s for s in slots if s.get("dmx", 0) <= dmx]
        closest = (max(passed, key=lambda s: s.get("dmx", 0)) if passed
                   else min(slots, key=lambda s: s.get("dmx", 0)))
        qc = QColor(closest.get("color", "#ffffff"))
        if p.level == 0:
            p.level = 100
        br = p.level / 100.0
        p.base_color = qc
        p.color = QColor(int(qc.red() * br), int(qc.green() * br), int(qc.blue() * br))
        p._manual_color = True

    def _update_color_wheel(self, p, color: QColor) -> None:
        """Met à jour p.color_wheel pour les lyres avec roue de couleurs.

        Roue non calibrée → repli sur `_GENERIC_WHEEL_SLOTS`, la table de
        référence de l'app (celle du menu du plan de feu, du chemin tablette et
        des valeurs de départ de l'assistant de calibration). Avant, ce repli
        était une table de teintes SÉPARÉE, et elle contredisait la référence :
        vert partait sur la position « orange », bleu sur « jaune », magenta sur
        « bleu » — 5 pads sur 8 sortaient la mauvaise couleur tant que la roue
        n'était pas calibrée. Une seule table, un seul comportement.
        """
        profile = getattr(p, 'dmx_profile', [])
        if 'ColorWheel' not in profile or 'R' in profile:
            return
        slots = getattr(p, 'color_wheel_slots', []) or self._GENERIC_WHEEL_SLOTS

        def _dist(s):
            sc = QColor(s.get('color', '#ffffff'))
            dr = sc.red()   - color.red()
            dg = sc.green() - color.green()
            db = sc.blue()  - color.blue()
            return dr*dr + dg*dg + db*db

        p.color_wheel = min(slots, key=_dist).get('dmx', 0)

    def activate_pad_dual(self, btn, col_idx):
        """Active un pad bicolore"""
        color1 = btn.property("base_color")
        color2 = btn.property("color2")

        if self.active_dual_pad and self.active_dual_pad != btn:
            self.active_dual_pad.active = False
            self.active_dual_pad.brightness = 0.3
            self.active_dual_pad.update()

        btn.active = not btn.active
        if btn.active:
            btn.brightness = 1.0
            self.active_dual_pad = btn
        else:
            btn.brightness = 0.3
            self.active_dual_pad = None
        btn.update()

        if btn.active:
            patterns = {
                "lat": [color1, color1],
                "contre": [color2, color1, color2, color2, color1, color2]
            }

            for group, pattern in patterns.items():
                projs = [p for p in self.projectors if p.group == group]
                for i, p in enumerate(projs):
                    if i < len(pattern):
                        p.base_color = pattern[i]
                        if p.level > 0:
                            brightness = p.level / 100.0
                            p.color = QColor(
                                int(pattern[i].red() * brightness),
                                int(pattern[i].green() * brightness),
                                int(pattern[i].blue() * brightness)
                            )

    def _toggle_mem_rec_mode(self):
        """Active/desactive le mode REC memoire."""
        self._mem_rec_mode = not self._mem_rec_mode
        if self._rec_mem_btn is None:
            return
        if self._mem_rec_mode:
            self._rec_mem_btn.setStyleSheet(
                "QPushButton { background: #cc3333; color: white; border: 2px solid #ff6666; "
                "border-radius: 4px; font-size: 13px; }"
            )
            self._rec_mem_btn.setToolTip(tr("mw_rec_active"))
        else:
            self._rec_mem_btn.setStyleSheet(
                "QPushButton { background: #1e1e1e; color: #cc3333; border: 1px solid #3a3a3a; "
                "border-radius: 4px; font-size: 13px; } "
                "QPushButton:hover { background: #2a2a2a; color: #ff4444; border-color: #cc3333; }"
            )
            self._rec_mem_btn.setToolTip(tr("mw_rec_mem_hint"))
        # Mettre à jour les tooltips des pads non-mémoire
        self._update_non_mem_pad_tooltips()
        try:
            import tablet_server as _ts
            if _ts.is_running():
                _ts.push_rec_state(self._mem_rec_mode)
        except Exception:
            pass

    def _update_non_mem_pad_tooltips(self):
        """En mode REC, affiche 🚫 sur les pads groupe et FX (non enregistrables en mémoire).
        Les pads POS restent cliquables en REC (pour enregistrer une position)."""
        tip = "🚫" if self._mem_rec_mode else ""
        for (row, col), pad in self.pads.items():
            if col >= len(self._fader_map):
                continue
            slot = self._fader_map[col]
            if slot["type"] in ("group", "fx"):
                pad.setToolTip(tip)
                pad.setToolTipDuration(800 if self._mem_rec_mode else -1)

    def _log_message(self, text: str, level: str = "info"):
        """Envoie un message dans le journal AKAI."""
        log = getattr(self, '_msg_log', None)
        if log is not None:
            log.append_message(text, level)

    def _show_mem_toast(self, text):
        """Log un message de succès dans le journal."""
        self._log_message(text, "success")

    def _show_error_toast(self, text):
        """Log un message d'erreur dans le journal."""
        self._log_message(text, "error")

    def _show_bpm_toast(self, bpm: int):
        """Log le BPM détecté dans le journal."""
        self._log_message(f"TAP tempo : {bpm} BPM", "bpm")

    def _activate_memory_pad(self, btn, mem_col, row, col_akai=None):
        """Active un pad memoire - independant par colonne.
        Chaque colonne memoire est independante : activer un pad dans la colonne 2
        ne desactive pas le pad actif dans la colonne 1.
        Cliquer sur le pad deja actif ne fait rien."""

        # Mode REC : enregistrer l'etat courant sur ce pad
        if self._mem_rec_mode:
            self._record_memory(mem_col, row)
            self._mem_rec_mode = False
            if self._rec_mem_btn:
                self._rec_mem_btn.setStyleSheet(
                    "QPushButton { background: #1e1e1e; color: #cc3333; border: 1px solid #3a3a3a; "
                    "border-radius: 4px; font-size: 13px; } "
                    "QPushButton:hover { background: #2a2a2a; color: #ff4444; border-color: #cc3333; }"
                )
                self._rec_mem_btn.setToolTip(tr("mw_rec_mem_hint"))
            self._log_message(f"Rec MEM {mem_col + 1}.{row + 1} OK", "rec")
            self._blink_memory_pad(mem_col, row)
            return

        if col_akai is None:
            col_akai = self._mem_col_to_fader(mem_col)

        # Clic sur le pad déjà actif → avancer au cue suivant si multi-cue
        if self.active_memory_pads.get(col_akai) == row:
            mem = self.memories[mem_col][row]
            if mem:
                self._mem_ensure_cues(mem)
                if len(mem.get("cues", [])) > 1:
                    self._release_manual_grabs()   # action volontaire → on repeint
                    self._mem_advance_cue(mem_col, row)
                    fader_val = self.faders[col_akai].value if col_akai in self.faders else 0
                    self._recompute_memory_mix()
                    cue_idx = self._mem_cue_idx.get((mem_col, row), 0)
                    n_cues = len(mem["cues"])
                    cue_lbl = mem["cues"][cue_idx].get("label", f"Cue {cue_idx + 1}")
                    self._log_message(f"MEM {mem_col+1}.{row+1} → {cue_lbl} ({cue_idx+1}/{n_cues})", "mem")
                    self._style_memory_pad(mem_col, row, active=True)
                    # Rafraîchir le panel Cues si ouvert sur ce pad
                    if hasattr(self, '_cue_panel') and self._cue_panel.mem_col == mem_col and self._cue_panel.row == row:
                        self._cue_panel.highlight_cue(cue_idx)
            return

        # Activation impossible si aucune memoire stockee
        if self.memories[mem_col][row] is None:
            return

        # Desactiver le pad precedent DANS CETTE COLONNE SEULEMENT
        prev_row = self.active_memory_pads.pop(col_akai, None)
        if prev_row is not None:
            self._clear_memory_from_projectors(mem_col, prev_row)
            self._style_memory_pad(mem_col, prev_row, active=False)
            self._update_memory_pad_led(mem_col, prev_row, active=False)
            self._mem_cue_idx.pop((mem_col, prev_row), None)  # reset cue index
            prev_mem = self.memories[mem_col][prev_row]
            if prev_mem:
                self._mem_ensure_cues(prev_mem)
                prev_eff_name = (prev_mem["cues"][0].get("effect") or {}).get("name") if prev_mem.get("cues") else None
            else:
                prev_eff_name = None
            if prev_eff_name:
                if hasattr(self, 'effect_timer'):
                    self.effect_timer.stop()
                self.active_effect = None
                self.active_effect_config = {}
                self.effect_saved_colors = {}

        # Activer le nouveau pad (cue 0 par défaut)
        self._release_manual_grabs()   # action volontaire → on repeint
        self._mem_cue_idx[(mem_col, row)] = 0
        self.active_memory_pads[col_akai] = row
        self._style_memory_pad(mem_col, row, active=True)
        self._update_memory_pad_led(mem_col, row, active=True)
        fader_val = self.faders[col_akai].value if col_akai in self.faders else 0
        self._recompute_memory_mix()

        mem = self.memories[mem_col][row]
        self._mem_ensure_cues(mem)
        n_cues = len(mem.get("cues", []))
        if n_cues > 1:
            self._log_message(f"MEM {mem_col+1}.{row+1}  [1/{n_cues}]", "mem")
        else:
            self._log_message(f"MEM {mem_col + 1}.{row + 1}", "mem")
        if fader_val == 0:
            self._log_message(f"MEM {mem_col + 1} — fader à 0, rien n'est envoyé", "warn")

        # Démarrer le timer de durée si le cue actif en a une
        self._start_cue_duration(mem_col, row)

        # Réinitialiser la position GO sur le pad activé manuellement
        if self.go_mode:
            self._go_col = mem_col
            self._go_row = row

        self._save_akai_config_auto()
        # Envoi DMX immediat sans attendre le prochain tick
        self.send_dmx_update()

    def trigger_memory(self, mem_col: int, row: int):
        """Slot public — déclenche un pad mémoire depuis le Stream Deck ou un signal externe."""
        if not (0 <= mem_col <= 7 and 0 <= row <= 7):
            return
        if self.memories[mem_col][row] is None:
            return
        self._activate_memory_pad(None, mem_col, row)

    # ── Helpers cues ─────────────────────────────────────────────────────────

    def _mem_ensure_cues(self, mem: dict):
        """Migre l'ancien format {projectors, effect} vers {cues:[...], loop:True}."""
        if mem is None or "cues" in mem:
            return
        cue0 = {
            "label": "Cue 1",
            "projectors": mem.pop("projectors", []),
            "effect": mem.pop("effect", {}),
            "duration": 0,
        }
        mem["cues"] = [cue0]
        mem.setdefault("loop", True)

    def _mem_active_cue(self, mem_col: int, row: int) -> dict:
        """Retourne le cue actuellement actif pour ce pad (dict vide si aucun)."""
        mem = self.memories[mem_col][row]
        if not mem:
            return {}
        self._mem_ensure_cues(mem)
        cues = mem["cues"]
        idx = self._mem_cue_idx.get((mem_col, row), 0)
        if not cues:
            return {}
        return cues[max(0, min(idx, len(cues) - 1))]

    def _release_manual_grabs(self):
        """Rend la main aux mémoires sur tous les projecteurs.

        La prise en main (plan 2D) ne protège que des réécritures PASSIVES —
        typiquement un mouvement de fader. Toute action mémoire volontaire
        (appui pad, clic sur un cue) ou l'avance auto du minutage doit repeindre :
        sinon une fixture reste verrouillée sans que rien ne l'indique, et les
        cues comme le minutage semblent morts.
        """
        for p in self.projectors:
            p._manual_color = False
            p._manual_move = False

    def _mem_advance_cue(self, mem_col: int, row: int) -> bool:
        """Avance au cue suivant. Retourne False si on reste au même (boucle désactivée + fin)."""
        mem = self.memories[mem_col][row]
        if not mem:
            return False
        self._mem_ensure_cues(mem)
        cues = mem["cues"]
        if len(cues) <= 1:
            return False
        idx = self._mem_cue_idx.get((mem_col, row), 0)
        next_idx = idx + 1
        if next_idx >= len(cues):
            if mem.get("loop", True):
                next_idx = 0
            else:
                return False
        self._mem_cue_idx[(mem_col, row)] = next_idx
        return True

    def _mem_go_back_cue(self, mem_col: int, row: int) -> bool:
        """Recule au cue précédent. Retourne False si impossible."""
        mem = self.memories[mem_col][row]
        if not mem:
            return False
        self._mem_ensure_cues(mem)
        cues = mem["cues"]
        if len(cues) <= 1:
            return False
        idx = self._mem_cue_idx.get((mem_col, row), 0)
        prev_idx = idx - 1
        if prev_idx < 0:
            if mem.get("loop", True):
                prev_idx = len(cues) - 1
            else:
                return False
        self._mem_cue_idx[(mem_col, row)] = prev_idx
        return True

    def _open_cue_editor(self, mem_col: int, row: int):
        """Ouvre le panel Cues dans un panneau flottant positionné près du pad."""
        mem = self.memories[mem_col][row]
        if not mem:
            return
        self._mem_ensure_cues(mem)

        # Créer le wrapper flottant une seule fois
        if self._cue_float is None:
            w = QWidget(self, Qt.Tool | Qt.FramelessWindowHint)
            w.setAttribute(Qt.WA_TranslucentBackground)
            w.setFixedSize(650, 580)
            outer = QVBoxLayout(w)
            outer.setContentsMargins(0, 0, 0, 0)

            container = QWidget(w)
            container.setObjectName("cue_float")
            container.setStyleSheet("""
                QWidget#cue_float {
                    background: #0f0f0f;
                    border: 1px solid #2a2a2a;
                    border-radius: 10px;
                }
            """)
            inner = QVBoxLayout(container)
            inner.setContentsMargins(0, 0, 0, 0)
            inner.setSpacing(0)

            # Barre titre avec bouton fermeture
            title_bar = QWidget()
            title_bar.setStyleSheet("background: #141414; border-radius: 10px 10px 0 0;")
            title_bar.setFixedHeight(32)
            tb_lay = QHBoxLayout(title_bar)
            tb_lay.setContentsMargins(12, 0, 8, 0)
            tb_lay.setSpacing(0)
            self._cue_float_lbl = QLabel("Cues")
            self._cue_float_lbl.setStyleSheet("color:#00d4ff; font-size:11px; font-weight:bold; background:transparent;")
            tb_lay.addWidget(self._cue_float_lbl)
            tb_lay.addStretch()
            close_btn = QPushButton("✕")
            close_btn.setFixedSize(20, 20)
            close_btn.setStyleSheet("""
                QPushButton { background:#2a2a2a; border:none; border-radius:4px;
                              color:#888; font-size:10px; font-weight:bold; }
                QPushButton:hover { background:#3a3a3a; color:#fff; }
            """)
            close_btn.clicked.connect(w.hide)
            tb_lay.addWidget(close_btn)
            inner.addWidget(title_bar)
            inner.addWidget(self._cue_panel)
            outer.addWidget(container)
            self._cue_float = w

        self._cue_panel.load(mem_col, row, mem)
        self._cue_panel.highlight_cue(self._mem_cue_idx.get((mem_col, row), 0))
        self._cue_float_lbl.setText(tr("mw_f_cues_mem", a0=mem_col + 1, a1=row + 1))

        # Positionner près du pad
        anchor = None
        for col_akai in self._mem_col_to_faders(mem_col):
            pad = self.pads.get((row, col_akai))
            if pad:
                anchor = pad.mapToGlobal(pad.rect().topRight())
                break
        if anchor is None:
            anchor = self.mapToGlobal(self.rect().center())

        sg = self.screen().availableGeometry()
        fw, fh = self._cue_float.width(), self._cue_float.height()
        x = anchor.x() + 12
        y = anchor.y()
        if x + fw > sg.right():
            x = anchor.x() - fw - 12
        if y + fh > sg.bottom():
            y = sg.bottom() - fh - 8

        self._cue_float.move(x, y)
        self._cue_float.show()
        self._cue_float.raise_()

    def _on_cue_panel_changed(self):
        """Appelé quand le panel Cues modifie la mémoire."""
        mc, r = self._cue_panel.mem_col, self._cue_panel.row
        if mc >= 0:
            active = self.active_memory_pads.get(self._mem_col_to_fader(mc)) == r
            self._style_memory_pad(mc, r, active)
        self._save_akai_config_auto()

    def _on_cue_activated(self, cue_idx: int):
        """Clic/flèche sur le panel Cues → applique ce cue avec fade."""
        mc, r = self._cue_panel.mem_col, self._cue_panel.row
        if mc < 0 or self.memories[mc][r] is None:
            return
        self._release_manual_grabs()   # clic sur un cue = action volontaire
        self._mem_cue_idx[(mc, r)] = cue_idx
        col_akai = self._mem_col_to_fader(mc)
        fader_val = self.faders[col_akai].value if col_akai in self.faders else 100
        self._apply_cue_with_fade(mc, r, fader_val)
        mem = self.memories[mc][r]
        cue_lbl = mem["cues"][cue_idx].get("label", f"Cue {cue_idx+1}")
        n = len(mem["cues"])
        self._log_message(f"MEM {mc+1}.{r+1} → {cue_lbl} ({cue_idx+1}/{n})", "mem")
        self._style_memory_pad(mc, r, active=True)
        self._cue_panel.highlight_cue(cue_idx)
        self._start_cue_duration(mc, r)

    # ── Fade entre cues ───────────────────────────────────────────────────────

    def _on_cue_effect_pick(self, cue_row: int):
        """Ouvre un menu pour assigner/retirer un effet sur un cue."""
        mc, r = self._cue_panel.mem_col, self._cue_panel.row
        if mc < 0 or self.memories[mc][r] is None:
            return
        mem = self.memories[mc][r]
        self._mem_ensure_cues(mem)
        if not (0 <= cue_row < len(mem["cues"])):
            return
        cue = mem["cues"][cue_row]
        current_eff = (cue.get("effect") or {}).get("name", "")

        all_effects = []
        try:
            from effect_editor import BUILTIN_EFFECTS, _load_custom_effects
            all_effects = list(BUILTIN_EFFECTS) + _load_custom_effects()
        except Exception:
            pass

        from PySide6.QtWidgets import QMenu
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu { background:#1a1a1a; border:1px solid #333; border-radius:6px; color:#e0e0e0; }
            QMenu::item { padding:6px 20px; font-size:12px; }
            QMenu::item:selected { background:#1e3a4a; color:#00d4ff; }
            QMenu::item:disabled { color:#444; }
            QMenu::separator { height:1px; background:#2a2a2a; margin:4px 0; }
        """)

        def _set(eff_or_none):
            cue["effect"] = eff_or_none or {}
            name = (eff_or_none or {}).get("name", "")
            self._cue_panel.set_cue_effect(cue_row, name)
            self._save_akai_config_auto()

        act_none = menu.addAction(tr("mw_no_effect"))
        act_none.setCheckable(True)
        act_none.setChecked(not current_eff)
        act_none.triggered.connect(lambda: _set(None))
        menu.addSeparator()

        CATS = ["Strobe / Flash", "Mouvement", "Ambiance", "Couleur", "Permut", "Spécial", "Lyre", "Personnalisés", "Mes Effets"]
        for cat in CATS:
            cat_effs = [e for e in all_effects if e.get("category") == cat]
            if not cat_effs:
                continue
            hdr = menu.addAction(f"  {cat.upper()}")
            hdr.setEnabled(False)
            for eff in cat_effs:
                name_eff = eff.get("name", "")
                emoji = eff.get("emoji", "⚡")
                act = menu.addAction(f"  {emoji} {name_eff}")
                act.setCheckable(True)
                act.setChecked(name_eff == current_eff)
                act.triggered.connect(lambda checked=False, e=dict(eff): _set(e))

        # Positionner sur la cellule Effet
        table = self._cue_panel._table
        item  = table.item(cue_row, 4)
        if item:
            rect = table.visualItemRect(item)
            pos  = table.viewport().mapToGlobal(rect.bottomLeft())
        else:
            pos = self._cue_panel.mapToGlobal(self._cue_panel.rect().center())
        menu.exec(pos)

    def _apply_cue_with_fade(self, mem_col: int, row: int, fader_val: int):
        """Applique le cue actif avec fondu si fade > 0."""
        cue = self._mem_active_cue(mem_col, row)
        fade_secs = float(cue.get("fade", 0))
        if fade_secs <= 0:
            self._apply_memory_to_projectors(mem_col, row, fader_value=fader_val)
            return
        # Snapshot de l'état courant
        self._fade_from = [(p.level, QColor(p.base_color)) for p in self.projectors]
        # Calcul de l'état cible
        brightness = fader_val / 100.0
        to_state = []
        for ps in cue.get("projectors", []):
            if ps["level"] <= 0:
                to_state.append((0, QColor("black")))
            else:
                to_state.append((int(ps["level"] * brightness), QColor(ps["base_color"])))
        while len(to_state) < len(self.projectors):
            to_state.append((0, QColor("black")))
        self._fade_to    = to_state
        self._fade_start = time.time()
        self._fade_dur   = fade_secs
        self._fade_timer.start()
        # Pan/tilt : _fade_tick n'interpole QUE level/couleur. Sans ça, un cue
        # avec fondu n'envoie jamais sa position (le cue sans fondu, lui, passe
        # par _apply_memory_to_projectors qui la gère). On anime sur la durée du
        # fondu pour que la lyre arrive en même temps que la couleur.
        for i, ps in enumerate(cue.get("projectors", [])):
            if i >= len(self.projectors):
                break
            p = self.projectors[i]
            if ("pan" not in ps and "tilt" not in ps) or getattr(p, '_manual_move', False):
                continue
            new_pan  = ps.get("pan",  getattr(p, 'pan',  32768))
            new_tilt = ps.get("tilt", getattr(p, 'tilt', 32768))
            new_pan  = new_pan  * 256 if new_pan  <= 255 else new_pan
            new_tilt = new_tilt * 256 if new_tilt <= 255 else new_tilt
            if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre'):
                self._start_pan_tilt_transition(p, new_pan, new_tilt,
                                                int(fade_secs * 1000))
            else:
                p.pan, p.tilt = new_pan, new_tilt
        # Déclencher/arrêter l'effet du cue
        mem_raw = self.memories[mem_col][row] or {}
        eff_cfg = cue.get("effect") or mem_raw.get("effect") or {}
        new_eff = eff_cfg.get("name", "") if eff_cfg.get("layers") else ""
        cur_eff = getattr(self, "active_effect", None) or ""
        if new_eff != cur_eff:
            if cur_eff:
                self.stop_effect()
                self.active_effect = None
                self.active_effect_config = {}
            if new_eff:
                self.active_effect = new_eff
                self.active_effect_config = eff_cfg
                self.start_effect(new_eff)

    def _fade_tick(self):
        elapsed = time.time() - self._fade_start
        ratio = min(1.0, elapsed / max(0.01, self._fade_dur))
        for i, p in enumerate(self.projectors):
            if i >= len(self._fade_to):
                break
            if getattr(p, '_manual_color', False):
                continue   # pris en main depuis le plan 2D : le fondu l'ignore
            fl, fc = (self._fade_from[i] if i < len(self._fade_from)
                      else (0, QColor("black")))
            tl, tc = self._fade_to[i]
            level = int(fl + (tl - fl) * ratio)
            # fc/tc sont des base_color PURES : on interpole la teinte, puis on
            # applique le niveau. Le moteur DMX exige color == base_color*level/100 ;
            # poser la teinte pure dans color lui fait croire à un effet et pousse
            # le canal Dim à 255 (lyres au plein feu pendant tout le fondu).
            rv = max(0, min(255, int(fc.red()   + (tc.red()   - fc.red())   * ratio)))
            gv = max(0, min(255, int(fc.green() + (tc.green() - fc.green()) * ratio)))
            bv = max(0, min(255, int(fc.blue()  + (tc.blue()  - fc.blue())  * ratio)))
            base = QColor(rv, gv, bv)
            p.level = level
            p.base_color = base
            p.color = QColor(int(rv * level / 100.0),
                             int(gv * level / 100.0),
                             int(bv * level / 100.0))
        if ratio >= 1.0:
            self._fade_timer.stop()

    # ── Durée auto-avance ─────────────────────────────────────────────────────

    def _start_cue_duration(self, mem_col: int, row: int):
        """Démarre le timer de durée pour le cue actif (si duration > 0)."""
        self._dur_timer.stop()
        self._dur_progress_timer.stop()
        if hasattr(self, "_cue_panel"):
            self._cue_panel.set_progress(-1)
        cue = self._mem_active_cue(mem_col, row)
        dur = float(cue.get("duration", 0))
        if dur <= 0:
            return
        self._dur_mem_col = mem_col
        self._dur_row     = row
        self._dur_start   = time.time()
        self._dur_secs    = dur
        self._dur_timer.start(int(dur * 1000))
        self._dur_progress_timer.start()

    def _update_cue_progress(self):
        if self._dur_secs <= 0:
            return
        ratio = min(1.0, (time.time() - self._dur_start) / self._dur_secs)
        if hasattr(self, "_cue_panel"):
            self._cue_panel.set_progress(ratio)

    def _on_duration_elapsed(self):
        self._dur_progress_timer.stop()
        mc, r = self._dur_mem_col, self._dur_row
        if mc < 0 or self.memories[mc][r] is None:
            return
        mem = self.memories[mc][r]
        self._mem_ensure_cues(mem)
        if not self._mem_advance_cue(mc, r):
            if hasattr(self, "_cue_panel"):
                self._cue_panel.set_progress(-1)
            return
        self._release_manual_grabs()   # avance auto du minutage → on repeint
        cue_idx = self._mem_cue_idx.get((mc, r), 0)
        col_akai = self._mem_col_to_fader(mc)
        fader_val = self.faders[col_akai].value if col_akai in self.faders else 100
        self._apply_cue_with_fade(mc, r, fader_val)
        n = len(mem["cues"])
        lbl = mem["cues"][cue_idx].get("label", f"Cue {cue_idx+1}")
        self._log_message(f"MEM {mc+1}.{r+1} → {lbl} ({cue_idx+1}/{n})", "mem")
        self._style_memory_pad(mc, r, active=True)
        if hasattr(self, "_cue_panel") and self._cue_panel.mem_col == mc and self._cue_panel.row == r:
            self._cue_panel.highlight_cue(cue_idx)
        self._start_cue_duration(mc, r)

    def _clear_memory_from_projectors(self, mem_col, row):
        """Remet à zéro les projecteurs actifs du cue courant de cette mémoire."""
        cue = self._mem_active_cue(mem_col, row)
        for i, proj_state in enumerate(cue.get("projectors", [])):
            if i >= len(self.projectors):
                break
            if proj_state["level"] > 0 or any(proj_state.get(k, 0) > 0 for k in ("uv", "amber_boost", "white_boost", "orange_boost", "gobo", "zoom", "strobe_speed")):
                p = self.projectors[i]
                p.level = 0
                p.base_color = QColor("black")
                p.color = QColor("black")
                p.uv           = 0
                p.amber_boost  = 0
                p.white_boost  = 0
                p.orange_boost = 0
                p.gobo         = 0
                p.zoom         = 0
                p.strobe_speed = 0

    def _apply_memory_to_projectors(self, mem_col, row, fader_value=None, trigger_effect=True):
        """Applique le cue courant de la mémoire sur les projecteurs."""
        mem = self.memories[mem_col][row]
        if not mem:
            return
        col_akai = self._mem_col_to_fader(mem_col)
        if col_akai in self._muted_faders:
            return
        self._mem_ensure_cues(mem)
        if fader_value is None:
            col_akai = self._mem_col_to_fader(mem_col)
            fader_value = self.faders[col_akai].value if col_akai in self.faders else 100
        brightness = fader_value / 100.0

        cue = self._mem_active_cue(mem_col, row)
        for i, proj_state in enumerate(cue.get("projectors", [])):
            if i >= len(self.projectors):
                break
            p = self.projectors[i]
            # Pan/tilt pris en main depuis le plan 2D → intouchable jusqu'au CLEAR.
            # Ce chemin est aussi celui des changements de cue AUTOMATIQUES
            # (_on_duration_elapsed) : sans cette garde, la lyre repart toute seule.
            if ("pan" in proj_state or "tilt" in proj_state) \
                    and not getattr(p, '_manual_move', False):
                new_pan  = proj_state.get("pan",  getattr(p, 'pan',  32768))
                new_tilt = proj_state.get("tilt", getattr(p, 'tilt', 32768))
                new_pan  = new_pan  * 256 if new_pan  <= 255 else new_pan
                new_tilt = new_tilt * 256 if new_tilt <= 255 else new_tilt
                if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre'):
                    self._start_pan_tilt_transition(p, new_pan, new_tilt, 500)
                else:
                    p.pan  = new_pan
                    p.tilt = new_tilt
            # Canaux spéciaux toujours restaurés (même si level == 0)
            p.uv           = int(proj_state.get("uv",           0) * brightness)
            p.amber_boost  = int(proj_state.get("amber_boost",  0) * brightness)
            p.white_boost  = int(proj_state.get("white_boost",  0) * brightness)
            p.orange_boost = int(proj_state.get("orange_boost", 0) * brightness)
            p.gobo          = int(proj_state.get("gobo",         0))
            p.gobo_rotation = int(proj_state.get("gobo_rotation", 0))
            p.zoom          = int(proj_state.get("zoom",         0))
            p.strobe_speed  = int(proj_state.get("strobe_speed", 0))
            # Canaux bruts (Mode, Effects…) : valeur brute, jamais scalés par le fader
            p.channel_extras = dict(proj_state.get("channel_extras", {}) or {})
            # Couleur prise en main depuis le plan 2D → le cue n'y touche pas
            # (même mécanisme que _compute_htp_overrides). Libéré par CLEAR.
            if getattr(p, '_manual_color', False):
                continue
            if proj_state["level"] <= 0:
                p.level = 0
                p.base_color = QColor("black")
                p.color = QColor("black")
                continue
            level = int(proj_state["level"] * brightness)
            base_color = QColor(proj_state["base_color"])
            p.level = level
            p.base_color = base_color
            p.color = QColor(
                int(base_color.red()   * level / 100.0),
                int(base_color.green() * level / 100.0),
                int(base_color.blue()  * level / 100.0)
            )
            self._update_color_wheel(p, base_color)

        # Déclencher/arrêter l'effet du cue courant
        # Fallback : si le cue n'a pas d'effet propre, lire l'effet posé sur la mémoire globale
        if trigger_effect:
            mem_raw = self.memories[mem_col][row] or {}
            eff_cfg = cue.get("effect") or mem_raw.get("effect") or {}
            new_eff = eff_cfg.get("name", "") if (eff_cfg.get("layers") and fader_value > 0) else ""
            cur_eff = getattr(self, "active_effect", None) or ""
            if new_eff != cur_eff:
                if cur_eff:
                    self.stop_effect()
                    self.active_effect = None
                    self.active_effect_config = {}
                if new_eff:
                    self.active_effect = new_eff
                    self.active_effect_config = eff_cfg
                    self.start_effect(new_eff)

    def _recompute_memory_mix(self):
        """Composite TOUTES les mémoires actives (faders > 0) sur les projecteurs.

        - Fixtures RGB : mélange ADDITIF des couleurs pondéré par (niveau × fader)
          de chaque mémoire → rouge + bleu = rose.
        - Roue de couleur (sans RGB) : mélange impossible → mémoire DOMINANTE
          (niveau effectif le plus élevé).
        - Pan/Tilt/Gobo/canaux spéciaux : mémoire dominante.
        """
        # 1. Collecter les mémoires actives (fader > 0, non mutée)
        active = []   # (bright 0-1, cue, mem_raw)
        for fader_idx, row in list(self.active_memory_pads.items()):
            if fader_idx in self._muted_faders or row is None:
                continue
            mem_col = self._fader_to_mem_col(fader_idx)
            if mem_col is None:
                continue
            mem = self.memories[mem_col][row]
            if not mem:
                continue
            fv = self.faders[fader_idx].value if fader_idx in self.faders else 0
            if fv <= 0:
                continue
            self._mem_ensure_cues(mem)
            active.append((fv / 100.0, self._mem_active_cue(mem_col, row), mem))

        # 2. Compositer chaque projecteur
        for i, p in enumerate(self.projectors):
            # Prise en main depuis le plan 2D : ne pas réécrire cette fixture, sinon
            # un simple mouvement de fader effacerait la couleur posée à la main.
            if getattr(p, '_manual_color', False):
                continue
            profile  = getattr(p, 'dmx_profile', []) or []
            has_rgb  = ('R' in profile and 'G' in profile and 'B' in profile)
            is_cwheel = ('ColorWheel' in profile) and not has_rgb

            r_acc = g_acc = b_acc = 0.0
            best_eff = -1.0          # plus forte contribution lumineuse (level × fader)
            best_state = None        # → couleur dominante / roue de couleur
            best_bright = -1.0       # fader le plus haut touchant ce projo
            spec_state = None        # → canaux spéciaux (pan/tilt/gobo/UV/boosts)
            for bright, cue, _mem in active:
                states = cue.get("projectors", [])
                if i >= len(states):
                    continue
                st  = states[i]
                # Mémoire au fader le plus haut → pilote les canaux spéciaux
                if bright > best_bright:
                    best_bright, spec_state = bright, st
                lvl = st.get("level", 0) or 0
                eff = lvl * bright
                if eff <= 0:
                    continue
                if eff > best_eff:
                    best_eff, best_state = eff, st
                bc = QColor(st.get("base_color", "#000000"))
                f  = eff / 100.0
                r_acc += bc.red()   * f
                g_acc += bc.green() * f
                b_acc += bc.blue()  * f

            if spec_state is None:
                # Aucune mémoire active ne touche ce projecteur → éteint
                p.level = 0
                p.base_color = QColor("black")
                p.color = QColor("black")
                continue

            # Canaux spéciaux + pan/tilt : mémoire au fader le plus haut
            ds    = spec_state
            scale = best_bright          # luminosité du fader dominant (0-1)
            p.uv           = int(ds.get("uv",           0) * scale)
            p.amber_boost  = int(ds.get("amber_boost",  0) * scale)
            p.white_boost  = int(ds.get("white_boost",  0) * scale)
            p.orange_boost = int(ds.get("orange_boost", 0) * scale)
            p.gobo          = int(ds.get("gobo",          0))
            p.gobo_rotation = int(ds.get("gobo_rotation", 0))
            p.zoom          = int(ds.get("zoom",          0))
            p.strobe_speed  = int(ds.get("strobe_speed",  0))
            # Canaux bruts (Mode…) : pilotés par la mémoire au fader dominant
            p.channel_extras = dict(ds.get("channel_extras", {}) or {})
            # Pan/tilt pris en main depuis le plan 2D → la mémoire n'y touche plus
            # (elle continue de piloter couleur/intensité). Libéré par CLEAR.
            if ("pan" in ds or "tilt" in ds) and not getattr(p, '_manual_move', False):
                np_ = ds.get("pan",  getattr(p, 'pan',  32768))
                nt_ = ds.get("tilt", getattr(p, 'tilt', 32768))
                p.pan  = np_ * 256 if np_ <= 255 else np_
                p.tilt = nt_ * 256 if nt_ <= 255 else nt_

            if best_state is None:
                # Spécial actif mais aucune couleur (level 0 partout) → RGB éteint
                p.level = 0
                p.base_color = QColor("black")
                p.color = QColor("black")
            elif is_cwheel:
                # Roue de couleur : pas de mélange additif → mémoire dominante
                bc  = QColor(best_state.get("base_color", "#000000"))
                lvl = int(best_eff)
                p.level = lvl
                p.base_color = bc
                p.color = QColor(int(bc.red() * lvl / 100.0),
                                 int(bc.green() * lvl / 100.0),
                                 int(bc.blue() * lvl / 100.0))
                self._update_color_wheel(p, bc)
            else:
                # RGB : mélange additif (clamp 255)
                R = min(255, int(r_acc)); G = min(255, int(g_acc)); B = min(255, int(b_acc))
                max_c = max(R, G, B)
                if max_c <= 0:
                    p.level = 0; p.base_color = QColor("black"); p.color = QColor("black")
                else:
                    hue = QColor(int(R * 255 / max_c), int(G * 255 / max_c), int(B * 255 / max_c))
                    p.base_color = hue
                    p.level = int(max_c / 255.0 * 100)
                    p.color = QColor(R, G, B)
                    self._update_color_wheel(p, hue)

        # 3. Effet : piloté par la mémoire dominante (fader le plus haut)
        if active:
            dom_bright, dom_cue, dom_mem = max(active, key=lambda t: t[0])
            eff_cfg = dom_cue.get("effect") or (dom_mem or {}).get("effect") or {}
            new_eff = eff_cfg.get("name", "") if (eff_cfg.get("layers") and dom_bright > 0) else ""
        else:
            eff_cfg, new_eff = {}, ""
        cur_eff = getattr(self, "active_effect", None) or ""
        if new_eff != cur_eff:
            if cur_eff:
                self.stop_effect()
                self.active_effect = None
                self.active_effect_config = {}
            if new_eff:
                self.active_effect = new_eff
                self.active_effect_config = eff_cfg
                self.start_effect(new_eff)

    def _style_memory_pad(self, mem_col, row, active):
        """Style visuel d'un pad mémoire — met à jour toutes les colonnes mappées sur ce MEM."""
        for col_akai in self._mem_col_to_faders(mem_col):
            self._style_memory_pad_col(mem_col, row, active, col_akai)

    def _style_memory_pad_col(self, mem_col, row, active, col_akai):
        """Style visuel d'un pad mémoire pour une colonne AKAI donnée."""
        pad = self.pads.get((row, col_akai))
        if not pad:
            return

        color = self._get_memory_pad_color(mem_col, row)
        mem_d = self.memories[mem_col][row] or {}
        # Cues : afficher n/N si multi-cue et actif
        self._mem_ensure_cues(mem_d) if mem_d else None
        n_cues = len(mem_d.get("cues", [])) if mem_d else 0
        cue_idx = self._mem_cue_idx.get((mem_col, row), 0)
        cur_cue = mem_d["cues"][min(cue_idx, n_cues-1)] if n_cues > 0 else {}
        has_effect = bool(cur_cue.get("effect") or mem_d.get("effect") if mem_d else False)

        if n_cues > 1:
            pad.setText(f"{cue_idx+1}/{n_cues}")
        elif has_effect:
            pad.setText("⚡")
        else:
            pad.setText("")
        if color == QColor("black") or self.memories[mem_col][row] is None:
            pad.setProperty("base_color", QColor("black"))
            pad.setStyleSheet("""
                QPushButton {
                    background: #1a1a1a;
                    border: 1px solid #1a1a1a;
                    border-radius: 4px;
                    color: rgba(255,255,255,0.5);
                    font-size: 8px;
                }
            """)
        elif active:
            pad.setProperty("base_color", color)
            pad.setStyleSheet(f"""
                QPushButton {{
                    background: {color.name()};
                    border: 2px solid {color.lighter(130).name()};
                    border-radius: 4px;
                    color: rgba(255,255,255,0.8);
                    font-size: 8px;
                }}
            """)
        else:
            dim_color = QColor(int(color.red() * 0.5), int(color.green() * 0.5), int(color.blue() * 0.5))
            pad.setProperty("base_color", color)
            pad.setStyleSheet(f"""
                QPushButton {{
                    background: {dim_color.name()};
                    border: 1px solid #2a2a2a;
                    border-radius: 4px;
                    color: rgba(255,255,255,0.6);
                    font-size: 8px;
                }}
            """)
        pad.setToolTip(self._build_memory_tooltip(mem_col, row))

    def _build_memory_tooltip(self, mem_col, row):
        """Construit le tooltip HTML d'un pad mémoire : ce que la mémoire impose.

        Résumé par GROUPE (le détail projecteur par projecteur est dans REC
        Lumière, clic droit sur un clip Séquence > Info) : couleur dominante,
        nombre de projecteurs, niveau le plus fort.

        Deux pièges que ce tooltip doit éviter :
        - une mémoire au format « cues » n'a plus de clé `projectors` à la
          racine — lire `mem["projectors"]` directement ne renvoyait rien ;
        - une mémoire capture TOUT le rig, y compris les projecteurs qu'elle ne
          vise pas (niveau 0, pan/tilt au centre) : on ne compte donc que ceux
          réellement touchés, avec les mêmes critères que
          `light_timeline.apply_seq_memories_htp`.
        """
        label = f"MEM {mem_col + 1}.{row + 1}"
        mem = self.memories[mem_col][row]
        if not mem:
            return f"<b>{label}</b><br><small style='color:#888'>{tr('mem_tt_empty')}</small>"
        try:
            self._mem_ensure_cues(mem)
            cues    = mem.get("cues", []) or []
            n_cues  = len(cues)
            cue_idx = getattr(self, '_mem_cue_idx', {}).get((mem_col, row), 0)
            cue     = cues[max(0, min(cue_idx, n_cues - 1))] if cues else {}

            head = f"<b>{label}</b>"
            if n_cues > 1:
                head += (f" <span style='color:#888'>· "
                         f"{tr('mem_tt_cue', n=min(cue_idx, n_cues - 1) + 1, total=n_cues)}</span>")
            lines = [head]

            lit   = {}   # groupe -> [nb, niveau max, couleur du plus fort]
            moved = {}   # groupe -> nb (pan/tilt, strobe ou canal brut, mais éteint)
            for i, ps in enumerate(cue.get("projectors", []) or []):
                if i >= len(self.projectors):
                    break
                g     = self.projectors[i].group
                gname = self.GROUP_DISPLAY.get(g, g.capitalize())
                lvl   = int(ps.get("level", 0) or 0)
                if lvl > 0:
                    cur = lit.get(gname)
                    if cur is None:
                        lit[gname] = [1, lvl, ps.get("base_color", "#ffffff")]
                    else:
                        cur[0] += 1
                        if lvl > cur[1]:
                            cur[1], cur[2] = lvl, ps.get("base_color", "#ffffff")
                elif (ps.get("pan", 32768) != 32768 or ps.get("tilt", 32768) != 32768
                        or int(ps.get("strobe_speed", 0) or 0)
                        or (ps.get("channel_extras") or {})):
                    moved[gname] = moved.get(gname, 0) + 1

            for gname, (n, lvl, chex) in lit.items():
                swatch = (f"<span style='background-color:{QColor(chex).name()}'>"
                          f"&nbsp;&nbsp;&nbsp;</span>")
                lines.append(f"{swatch} <b>{gname}</b> "
                             f"<span style='color:#aaa'>{tr('mem_tt_projs', n=n)} · {lvl} %</span>")
            for gname, n in moved.items():
                lines.append(f"<span style='color:#888'>&nbsp;&nbsp;&nbsp; <b>{gname}</b> "
                             f"{tr('mem_tt_moved', n=n)}</span>")
            if not lit and not moved:
                lines.append(f"<small style='color:#888'>{tr('mem_tt_nothing')}</small>")

            eff = cue.get("effect") or mem.get("effect") or {}
            if eff.get("layers") and eff.get("name"):
                lines.append(f"<span style='color:#00d4ff'>⚡ "
                             f"{tr('mem_tt_effect', name=eff['name'])}</span>")
            return "<br>".join(lines)
        except Exception:
            # Le tooltip est reconstruit à chaque restyle de pad : une mémoire
            # au format inattendu ne doit pas casser l'affichage de la grille.
            return f"<b>{label}</b>"

    def _get_memory_pad_color(self, mem_col, row):
        """Retourne la couleur custom ou dominante du snapshot"""
        custom = self.memory_custom_colors[mem_col][row]
        if custom:
            return custom

        mem = self.memories[mem_col][row]
        if not mem:
            return QColor("black")
        self._mem_ensure_cues(mem)
        projectors = (mem["cues"][0].get("projectors", []) if mem.get("cues") else
                      mem.get("projectors", []))
        color_counts = {}
        for ms in projectors:
            if ms["level"] > 0:
                c = ms["base_color"]
                color_counts[c] = color_counts.get(c, 0) + 1
        if not color_counts:
            return QColor("black")
        dominant = max(color_counts, key=color_counts.get)
        return QColor(dominant)

    def _update_memory_pad_led(self, mem_col, row, active):
        """Envoie LED MIDI pour un pad memoire — met à jour toutes les colonnes mappées sur ce MEM."""
        if not (MIDI_AVAILABLE and hasattr(self, 'midi_handler')):
            return
        color = self._get_memory_pad_color(mem_col, row)
        for col_akai in self._mem_col_to_faders(mem_col):
            if self.memories[mem_col][row] is None or color == QColor("black"):
                self.midi_handler.set_pad_led(row, col_akai, 0, 0)
            else:
                velocity = rgb_to_akai_velocity(color)
                brightness = self.akai_active_brightness if active else self.akai_inactive_brightness
                # Passer le VRAI RGB : sans lui, les LEDs RGB natives (Launchpad MK3)
                # reconvertissent la velocity via une table de 9 couleurs → l'orange
                # sort blanc, le violet sort bleu…
                self.midi_handler.set_pad_led(row, col_akai, velocity, brightness,
                                              rgb=(color.red(), color.green(), color.blue()))

    def _blink_memory_pad(self, mem_col, row, n_blinks=6):
        """Fait clignoter un pad mémoire n_blinks fois après enregistrement."""
        col_akai = self._mem_col_to_fader(mem_col)
        pad = self.pads.get((row, col_akai))
        if not pad:
            return

        blink_state = [0]
        total_ticks = n_blinks * 2  # ON + OFF par blink

        def _tick():
            blink_state[0] += 1
            if blink_state[0] > total_ticks:
                # Restaurer le style normal
                is_active = self.active_memory_pads.get(col_akai) == row
                self._style_memory_pad(mem_col, row, active=is_active)
                self._update_memory_pad_led(mem_col, row, active=is_active)
                return

            on = (blink_state[0] % 2 == 1)
            if on:
                pad.setStyleSheet(
                    "QPushButton { background: #ffffff; border: 2px solid #cccccc; border-radius: 4px; }"
                )
                if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
                    self.midi_handler.set_pad_led(row, col_akai, 3, brightness_percent=100)
            else:
                pad.setStyleSheet(
                    "QPushButton { background: #111111; border: 1px solid #333333; border-radius: 4px; }"
                )
                if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
                    self.midi_handler.set_pad_led(row, col_akai, 0)

            QTimer.singleShot(200, _tick)

        _tick()

    def _set_memory_custom_color(self, mem_col, row, color):
        """Definit une couleur personnalisee pour un pad memoire"""
        self.memory_custom_colors[mem_col][row] = color
        col_akai = self._mem_col_to_fader(mem_col)
        is_active = self.active_memory_pads.get(col_akai) == row
        self._style_memory_pad(mem_col, row, active=is_active)
        self._update_memory_pad_led(mem_col, row, active=is_active)
        # Sauvegarde auto immediate
        self._save_akai_config_auto()

    def _build_snapshot(self) -> dict:
        """Construit un cue snapshot depuis l'état courant des projecteurs."""
        snapshot = []
        for p in self.projectors:
            snapshot.append({
                "group":        p.group,
                "base_color":   p.base_color.name() if p.level > 0 else "#000000",
                "level":        p.level,
                "pan":          getattr(p, 'pan',          32768),
                "tilt":         getattr(p, 'tilt',         32768),
                "uv":           getattr(p, 'uv',           0),
                "amber_boost":  getattr(p, 'amber_boost',  0),
                "white_boost":  getattr(p, 'white_boost',  0),
                "orange_boost": getattr(p, 'orange_boost', 0),
                "gobo":         getattr(p, 'gobo',         0),
                "gobo_rotation": getattr(p, 'gobo_rotation', 0),
                "zoom":         getattr(p, 'zoom',         0),
                "strobe_speed": getattr(p, 'strobe_speed', 0),
                # Canaux bruts prioritaires posés à la main (Mode, Effects, Reset…)
                "channel_extras": dict(getattr(p, 'channel_extras', {}) or {}),
            })
        return {"projectors": snapshot, "effect": {}, "duration": 0}

    def _record_memory(self, mem_col, row):
        """Capture l'état courant. Si la mémoire existe, propose Remplacer / Ajouter cue."""
        cue = self._build_snapshot()
        mem = self.memories[mem_col][row]

        if mem is not None:
            self._mem_ensure_cues(mem)
            n = len(mem["cues"])
            from PySide6.QtWidgets import QMessageBox
            msg = QMessageBox(self)
            msg.setWindowTitle(f"MEM {mem_col + 1}.{row + 1}")
            msg.setText(tr("mw_f_mem_has_cues", n=n, a0='s' if n > 1 else ''))
            msg.setStyleSheet("background:#1e1e1e; color:white;")
            btn_replace = msg.addButton(tr("mw_replace_cue"), QMessageBox.AcceptRole)
            btn_add     = msg.addButton(tr("mw_f_add_cue", a0=n + 1), QMessageBox.ActionRole)
            msg.addButton(tr("mw_cancel"), QMessageBox.RejectRole)
            msg.exec()
            clicked = msg.clickedButton()
            if clicked == btn_replace:
                idx = self._mem_cue_idx.get((mem_col, row), 0)
                idx = max(0, min(idx, n - 1))
                cue["label"] = mem["cues"][idx].get("label", f"Cue {idx + 1}")
                mem["cues"][idx] = cue
            elif clicked == btn_add:
                cue["label"] = f"Cue {n + 1}"
                mem["cues"].append(cue)
                if hasattr(self, '_cue_panel') and self._cue_panel.mem_col == mem_col \
                        and self._cue_panel.row == row:
                    self._cue_panel._refresh()
            else:
                return
        else:
            cue["label"] = "Cue 1"
            self.memories[mem_col][row] = {"cues": [cue], "loop": True}

        col_akai = self._mem_col_to_fader(mem_col)
        is_active = self.active_memory_pads.get(col_akai) == row
        self._style_memory_pad(mem_col, row, active=is_active)
        self._update_memory_pad_led(mem_col, row, active=is_active)
        self._save_akai_config_auto()

    def _rename_memory(self, mem_col, row):
        """Donne un nom perso (max 10 car.) à une mémoire ; affiché sur le pad MEM."""
        mem = self.memories[mem_col][row]
        if mem is None:
            return
        from PySide6.QtWidgets import QInputDialog, QLineEdit
        old = mem.get("name", "")
        name, ok = QInputDialog.getText(
            self, f"MEM {mem_col + 1}.{row + 1}",
            tr("mw_name_max10"), QLineEdit.Normal, old)
        if not ok:
            return
        name = name.strip()[:10]
        if name:
            mem["name"] = name
        else:
            mem.pop("name", None)
        self._save_akai_config_auto()

    def _show_memory_context_menu(self, pos, mem_col, row, btn):
        """Menu contextuel sur un pad memoire"""
        menu_style = """
            QMenu {
                background: #1e1e1e; color: white;
                border: 1px solid #3a3a3a; border-radius: 4px; padding: 4px;
            }
            QMenu::item { padding: 6px 20px; }
            QMenu::item:selected { background: #3a3a3a; }
        """
        menu = QMenu(self)
        menu.setStyleSheet(menu_style)

        # Header : nom de la mémoire (+ nom perso s'il existe)
        label = f"MEM {mem_col + 1}.{row + 1}"
        _mem_named = self.memories[mem_col][row]
        if isinstance(_mem_named, dict) and _mem_named.get("name"):
            label = f"{label}  ·  {_mem_named['name']}"
        from PySide6.QtWidgets import QWidgetAction, QLabel
        header_label = QLabel(f"  {label}  ")
        header_label.setStyleSheet("""
            QLabel {
                color: #aaa;
                font-size: 10px;
                font-weight: bold;
                letter-spacing: 1px;
                padding: 4px 12px 4px 12px;
                border-bottom: 1px solid #333;
                background: transparent;
            }
        """)
        header_wa = QWidgetAction(menu)
        header_wa.setDefaultWidget(header_label)
        menu.addAction(header_wa)
        menu.addSeparator()

        def _record_and_feedback():
            self._record_memory(mem_col, row)
            self._log_message(f"Rec MEM {mem_col + 1}.{row + 1} OK", "rec")
            self._blink_memory_pad(mem_col, row)

        if self.memories[mem_col][row] is None:
            save_action = menu.addAction(tr("mw_save_m"))
            save_action.triggered.connect(_record_and_feedback)
            import_action = menu.addAction(tr("mw_import_cue"))
            import_action.triggered.connect(lambda: self._import_memory(mem_col, row))
        else:
            replace_action = menu.addAction(tr("mw_replace_m"))
            replace_action.triggered.connect(_record_and_feedback)
            clear_action = menu.addAction(tr("mw_erase"))
            clear_action.triggered.connect(lambda: self._clear_memory(mem_col, row))

            rename_action = menu.addAction(tr("mw_rename_dots"))
            rename_action.triggered.connect(lambda: self._rename_memory(mem_col, row))

            mem_tmp = self.memories[mem_col][row]
            self._mem_ensure_cues(mem_tmp)
            n_cues = len(mem_tmp.get("cues", []))
            cues_lbl = f"📋  Cues  ({n_cues})" if n_cues > 1 else "📋  Cues"
            cues_action = menu.addAction(cues_lbl)
            cues_action.triggered.connect(lambda: self._open_cue_editor(mem_col, row))

            menu.addSeparator()

            # Déplacer / Exporter / Importer
            move_action = menu.addAction(tr("mw_move_to"))
            move_action.triggered.connect(lambda: self._open_move_memory_dialog(mem_col, row))
            export_action = menu.addAction(tr("mw_export_cue"))
            export_action.triggered.connect(lambda: self._export_memory(mem_col, row))
            import_action = menu.addAction(tr("mw_import_cue"))
            import_action.triggered.connect(lambda: self._import_memory(mem_col, row))

            menu.addSeparator()

            # Sous-menu couleur du pad
            color_menu = menu.addMenu(tr("mw_pad_color"))
            color_menu.setStyleSheet(menu_style)

            auto_action = color_menu.addAction(tr("mw_pad_color_auto"))
            auto_action.triggered.connect(lambda: self._set_memory_custom_color(mem_col, row, None))

            pad_colors = [
                ("Blanc", QColor(255, 255, 255)),
                ("Rouge", QColor(255, 0, 0)),
                ("Orange", QColor(255, 136, 0)),
                ("Jaune", QColor(255, 221, 0)),
                ("Vert", QColor(0, 255, 0)),
                ("Cyan", QColor(0, 221, 221)),
                ("Bleu", QColor(0, 0, 255)),
                ("Magenta", QColor(255, 0, 255)),
            ]
            for name, col in pad_colors:
                px = QPixmap(16, 16)
                px.fill(col)
                action = color_menu.addAction(QIcon(px), name)
                action.triggered.connect(lambda _, c=col: self._set_memory_custom_color(mem_col, row, c))

            # Sous-menu effet
            menu.addSeparator()
            mem_data = self.memories[mem_col][row]
            current_effect = (mem_data or {}).get("effect", {}).get("name") if mem_data else None
            eff_label = f"⚡  Effet : {current_effect}" if current_effect else "⚡  Ajouter un effet"
            effect_menu = menu.addMenu(eff_label)
            effect_menu.setStyleSheet(menu_style)

            all_effects = []
            try:
                from effect_editor import BUILTIN_EFFECTS, _load_custom_effects
                all_effects = list(BUILTIN_EFFECTS) + _load_custom_effects()
            except Exception:
                pass

            def _apply_effect(eff_or_none, mc=mem_col, r=row):
                self._set_memory_effect(mc, r, eff_or_none)
                col_akai = self._mem_col_to_fader(mc)
                self._style_memory_pad(mc, r, self.active_memory_pads.get(col_akai) == r)

            act_none = effect_menu.addAction(tr("mw_none_m"))
            act_none.setCheckable(True)
            act_none.setChecked(not current_effect)
            act_none.triggered.connect(lambda: _apply_effect(None))
            effect_menu.addSeparator()

            CATS = ["Strobe / Flash", "Mouvement", "Ambiance", "Couleur", "Spécial", "Personnalisés", "Mes Effets"]
            for cat in CATS:
                cat_effs = [e for e in all_effects if e.get("category") == cat]
                if not cat_effs:
                    continue
                hdr = effect_menu.addAction(f"  {cat.upper()}")
                hdr.setEnabled(False)
                for eff in cat_effs:
                    name_eff = eff.get("name", "")
                    act = effect_menu.addAction(f"  {name_eff}")
                    act.setCheckable(True)
                    act.setChecked(name_eff == current_effect)
                    act.triggered.connect(lambda checked=False, e=dict(eff): _apply_effect(e))

        menu.exec(btn.mapToGlobal(pos))

    def _set_memory_effect(self, mem_col, row, eff_dict_or_none):
        """Associe (ou retire) un effet à une mémoire."""
        mem = self.memories[mem_col][row]
        if mem is None:
            return
        if eff_dict_or_none is None:
            mem.pop("effect", None)
        else:
            name = eff_dict_or_none.get("name", "")
            # Chercher config complète (layers, play_mode, duration) dans les sources sauvegardées
            full_cfg = {}
            for cfg in getattr(self, '_button_effect_configs', {}).values():
                if isinstance(cfg, dict) and cfg.get("name") == name:
                    full_cfg = cfg
                    break
            if not full_cfg:
                full_cfg = getattr(self, '_effect_library_configs', {}).get(name, {})
            if full_cfg:
                mem["effect"] = dict(full_cfg)
            else:
                from effect_editor import EffectLayer
                layers = EffectLayer.layers_from_builtin(eff_dict_or_none)
                mem["effect"] = {
                    "name": name,
                    "type": eff_dict_or_none.get("type", ""),
                    "layers": [l.to_dict() for l in layers],
                    "play_mode": "loop",
                    "duration": 0,
                }
        self._save_akai_config_auto()

    def _clear_memory(self, mem_col, row):
        """Efface une memoire individuelle"""
        self.memories[mem_col][row] = None
        self.memory_custom_colors[mem_col][row] = None
        col_akai = self._mem_col_to_fader(mem_col)
        if self.active_memory_pads.get(col_akai) == row:
            del self.active_memory_pads[col_akai]
        self._style_memory_pad(mem_col, row, active=False)
        self._update_memory_pad_led(mem_col, row, active=False)
        # Sauvegarde auto immediate
        self._save_akai_config_auto()

    def _refresh_memory_pad(self, mem_col, row):
        """Rafraîchit style + LED d'un pad mémoire selon son état actif."""
        col_akai = self._mem_col_to_fader(mem_col)
        is_active = self.active_memory_pads.get(col_akai) == row
        self._style_memory_pad(mem_col, row, active=is_active)
        self._update_memory_pad_led(mem_col, row, active=is_active)

    def _open_move_memory_dialog(self, mem_col, row):
        """Dialogue de choix de la mémoire de destination, puis déplacement."""
        from PySide6.QtWidgets import (QDialog, QSpinBox, QVBoxLayout, QHBoxLayout,
                                       QLabel, QPushButton, QFormLayout)
        if self.memories[mem_col][row] is None:
            return
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("mw_f_move_mem", a0=mem_col + 1, a1=row + 1))
        dlg.setStyleSheet(
            "QDialog { background:#1e1e1e; color:#ddd; }"
            "QLabel { color:#ddd; background:transparent; }"
            "QSpinBox { background:#111; color:#ddd; border:1px solid #333; border-radius:4px; padding:3px 6px; }"
            "QPushButton { background:#2a2a2a; color:#ddd; border:1px solid #3a3a3a; border-radius:5px; padding:5px 14px; }"
            "QPushButton:hover { background:#3a3a3a; color:#fff; }"
        )
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel(tr("mw_f_move_mem_to", a0=mem_col + 1, a1=row + 1)))
        form = QFormLayout()
        col_spin = QSpinBox(); col_spin.setRange(1, _MEM_COL_MAX); col_spin.setValue(mem_col + 1)
        row_spin = QSpinBox(); row_spin.setRange(1, 8); row_spin.setValue(row + 1)
        form.addRow("Colonne MEM", col_spin)
        form.addRow("Ligne (1–8)", row_spin)
        lay.addLayout(form)
        btn_row = QHBoxLayout(); btn_row.addStretch()
        cancel = QPushButton(tr("mw_cancel")); cancel.clicked.connect(dlg.reject)
        ok = QPushButton(tr("mw_move"))
        ok.setStyleSheet("QPushButton { background:#0077bb; color:#fff; border:none; border-radius:5px; "
                         "padding:5px 14px; font-weight:bold; } QPushButton:hover { background:#0099dd; }")
        ok.clicked.connect(dlg.accept)
        btn_row.addWidget(cancel); btn_row.addWidget(ok)
        lay.addLayout(btn_row)
        if dlg.exec() != QDialog.Accepted:
            return
        self._move_memory(mem_col, row, col_spin.value() - 1, row_spin.value() - 1)

    def _move_memory(self, src_col, src_row, dst_col, dst_row):
        """Déplace le contenu (cues + couleur + effet) d'un pad mémoire vers un autre."""
        if (src_col, src_row) == (dst_col, dst_row):
            return
        src_mem = self.memories[src_col][src_row]
        if src_mem is None:
            return
        if self.memories[dst_col][dst_row] is not None:
            from PySide6.QtWidgets import QMessageBox
            if QMessageBox.question(
                self, tr("mw_mem_busy"),
                tr("mw_f_mem_overwrite", a0=dst_col + 1, a1=dst_row + 1),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No
            ) != QMessageBox.Yes:
                return
        # Transfert contenu + couleur perso + index de cue courant
        self.memories[dst_col][dst_row] = src_mem
        self.memory_custom_colors[dst_col][dst_row] = self.memory_custom_colors[src_col][src_row]
        self._mem_cue_idx[(dst_col, dst_row)] = self._mem_cue_idx.get((src_col, src_row), 0)
        self._mem_cue_idx.pop((src_col, src_row), None)
        # Vider la source
        self.memories[src_col][src_row] = None
        self.memory_custom_colors[src_col][src_row] = None
        src_akai = self._mem_col_to_fader(src_col)
        if self.active_memory_pads.get(src_akai) == src_row:
            del self.active_memory_pads[src_akai]
        self._refresh_memory_pad(src_col, src_row)
        self._refresh_memory_pad(dst_col, dst_row)
        self._save_akai_config_auto()
        self._log_message(f"MEM {src_col + 1}.{src_row + 1} → MEM {dst_col + 1}.{dst_row + 1}", "go")

    def _export_memory(self, mem_col, row):
        """Exporte le contenu d'un pad mémoire dans un fichier .mcue (JSON)."""
        from PySide6.QtWidgets import QFileDialog
        mem = self.memories[mem_col][row]
        if mem is None:
            return
        color = self.memory_custom_colors[mem_col][row]
        payload = {
            "format": "mystrow_cue",
            "version": 1,
            "label": f"MEM {mem_col + 1}.{row + 1}",
            "memory": mem,
            "color": color.name() if color else None,
        }
        default = f"MEM_{mem_col + 1}_{row + 1}.mcue"
        path, _ = QFileDialog.getSaveFileName(
            self, "Exporter le cue", default, "Cue MyStrow (*.mcue);;JSON (*.json)")
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False, indent=2)
            self._log_message(f"Cue exporté : {os.path.basename(path)}", "go")
        except Exception as e:
            self._log_message(f"Échec export cue : {e}", "warn")

    def _import_memory(self, mem_col, row):
        """Importe un cue .mcue dans le pad mémoire (avec confirmation si occupé)."""
        from PySide6.QtWidgets import QFileDialog, QMessageBox
        path, _ = QFileDialog.getOpenFileName(
            self, "Importer un cue", "", "Cue MyStrow (*.mcue *.json);;Tous (*.*)")
        if not path:
            return
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except Exception as e:
            self._log_message(f"Fichier illisible : {e}", "warn")
            return
        # Format enveloppe {"memory": {...}} ou dict mémoire brut
        mem = data.get("memory") if isinstance(data, dict) and "memory" in data else data
        if not isinstance(mem, dict) or "cues" not in mem:
            self._log_message("Format de cue non reconnu", "warn")
            return
        if self.memories[mem_col][row] is not None:
            if QMessageBox.question(
                self, tr("mw_mem_busy"),
                tr("mw_f_mem_overwrite", a0=mem_col + 1, a1=row + 1),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No
            ) != QMessageBox.Yes:
                return
        self.memories[mem_col][row] = mem
        self._mem_ensure_cues(mem)
        color_name = data.get("color") if isinstance(data, dict) else None
        self.memory_custom_colors[mem_col][row] = QColor(color_name) if color_name else None
        self._mem_cue_idx[(mem_col, row)] = 0
        self._refresh_memory_pad(mem_col, row)
        self._save_akai_config_auto()
        self._log_message(f"Cue importé dans MEM {mem_col + 1}.{row + 1}", "go")

    def set_proj_level(self, index, value):
        """Gere les faders - chaque fader est independant"""
        if index >= len(self._fader_map):
            return
        slot = self._fader_map[index]

        if slot["type"] == "play":
            # Fader de la colonne PLAY = volume du lecteur média (0-100 %).
            if index in self.faders:
                self.faders[index].value = value
            try:
                self.audio.setVolume(max(0, min(100, value)) / 100.0)
            except Exception:
                pass
            return

        if slot["type"] == "memory":
            mem_col = slot["mem_col"]
            # S'assurer que le niveau de ce fader est à jour avant le mix
            if index in self.faders:
                self.faders[index].value = value
            active_row = self.active_memory_pads.get(index)
            # Auto-activation pad du haut si aucun pad actif dans cette colonne MEM
            if active_row is None and value > 0 and self.memories[mem_col][0] is not None:
                self.active_memory_pads[index] = 0
                self._style_memory_pad(mem_col, 0, active=True)
            # Mélange de TOUTES les mémoires actives (additif RGB ; dominante pour roue de couleur)
            self._recompute_memory_mix()
            self.send_dmx_update()
            return

        if slot["type"] == "fx":
            if index in self._muted_faders:
                return
            fx_col = slot.get("fx_col", 0)
            if 0 <= fx_col < _FX_COL_MAX:
                prev_amp = self.fx_amplitudes[fx_col]
                self.fx_amplitudes[fx_col] = value
                # Fader FX descend à 0 : éteindre les projecteurs une fois pour
                # libérer la main aux colonnes MEM (sinon update_effect écrase tout)
                if value == 0 and prev_amp > 0:
                    for p in self.projectors:
                        p.color = QColor("black")
                    self.send_dmx_update()
            return

        if slot["type"] == "pos":
            if index in self._muted_faders:
                return
            # Le fader pilote pan/tilt seulement si un axe est configuré
            if slot.get("fader_axis"):
                self._apply_pos_fader_axis(slot, value)
            return

        if index in self._muted_faders:
            return

        groups = self._slot_groups(slot)
        if not groups:
            return

        # Auto-activation pad blanc si aucun pad actif dans CETTE colonne
        if index not in self.active_pads and value > 0:
            white_pad = self.pads.get((0, index))
            if white_pad:
                color = white_pad.property("base_color")
                white_pad.setStyleSheet(f"QPushButton {{ background: {color.name()}; border: 2px solid {color.lighter(130).name()}; border-radius: 4px; }}")
                self.active_pads[index] = white_pad
                for p in self.projectors:
                    if p.group in groups:
                        p.base_color = color
        elif index in self.active_pads and value > 0:
            # Resync base_color sur tous les projecteurs du groupe avec la couleur du pad actif
            # (une mémoire HTP peut avoir changé base_color d'un projecteur individuellement)
            active_color = self.active_pads[index].property("base_color")
            for p in self.projectors:
                if p.group in groups:
                    p.base_color = active_color

        brightness = value / 100.0 if value > 0 else 0
        for p in self.projectors:
            if p.group in groups:
                p.level = value
                if value > 0:
                    p.color = QColor(
                        int(p.base_color.red() * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue() * brightness))
                    # Lyres à roue de couleurs : la roue doit suivre `base_color`,
                    # comme partout ailleurs (pads, mémoires, timeline). C'était le
                    # SEUL chemin couleur qui ne la pilotait pas : un pad couleur
                    # pressé fader baissé ne posait que `base_color` (activate_pad
                    # ignore la couleur à 0), et monter le fader rallumait la lyre
                    # sur le slot précédent — « seul le dimmer répond ».
                    self._update_color_wheel(p, p.base_color)
                else:
                    p.color = QColor("black")

        # Envoi DMX immediat sans attendre le prochain tick
        self.send_dmx_update()

    def toggle_mute(self, index, active):
        """Gere les mutes - chaque fader est independant"""
        if index >= len(self._fader_map):
            return
        slot = self._fader_map[index]

        if active:
            self._muted_faders.add(index)
        else:
            self._muted_faders.discard(index)

        if slot["type"] == "memory":
            self.send_dmx_update()
            return

        if slot["type"] == "fx":
            self.send_dmx_update()
            return

        # Groupe : zéroter les projecteurs du groupe immédiatement
        groups = self._slot_groups(slot)
        for p in self.projectors:
            if p.group in groups:
                if active:
                    p.level = 0
                    p.color = QColor("black")
                else:
                    # Restaurer depuis la valeur du fader
                    fader_val = self.faders[index].value if index in self.faders else 0
                    brightness = fader_val / 100.0
                    p.level = fader_val
                    p.color = QColor(
                        int(p.base_color.red() * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue() * brightness))
        self.send_dmx_update()

    def toggle_effect(self, effect_idx):
        """Active/desactive un effet"""
        btn = self.effect_buttons[effect_idx]

        # Bascule = one-shot sur chaque appui (pas de toggle on/off)
        if btn.current_effect == "Bascule":
            self._bascule()
            btn.active = False
            btn.update_style()
            return

        # ── Mode superposition : plusieurs effets simultanés ─────────────────
        if self.effect_superposition:
            btn.active = not btn.active
            if btn.active:
                effect_name = btn.current_effect
                if not effect_name:
                    btn.active = False
                    btn.update_style()
                    self._log_message(f"Bouton {effect_idx + 1} — aucun effet assigné (clic droit pour configurer)", "warn")
                    return
                import time as _time
                eff_state = {
                    'idx': effect_idx,
                    'name': effect_name,
                    'config': self._button_effect_configs.get(effect_idx, {}),
                    'state': 0, 'hue': 0, 'brightness': 0, 'direction': 1,
                    't0': _time.monotonic(),
                }
                if not self._stacked_effects:
                    # Premier effet : sauvegarder les couleurs et démarrer le timer
                    self._snapshot_effect_state()
                    if not hasattr(self, 'effect_timer'):
                        self.effect_timer = QTimer()
                        self.effect_timer.timeout.connect(self.update_effect)
                    self.effect_timer.start(40)
                self._stacked_effects.append(eff_state)
                self.active_effect = effect_name
                self.active_effect_config = eff_state['config']
                self._log_message(f"Effet ON : {effect_name}", "effect")
            else:
                # Retirer cet effet de la pile
                old_name = next((e['name'] for e in self._stacked_effects if e['idx'] == effect_idx), btn.current_effect or "")
                self._stacked_effects = [e for e in self._stacked_effects if e['idx'] != effect_idx]
                self._log_message(f"Effet OFF : {old_name}", "effect")
                if not self._stacked_effects:
                    # Dernier effet : arrêter le timer et restaurer les couleurs
                    if hasattr(self, 'effect_timer'):
                        self.effect_timer.stop()
                    self._restore_effect_state()
                    # Ramener les Moving Heads au centre (transition fluide)
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre'):
                            self._start_pan_tilt_transition(p, 32768, 32768, 500)
                    self.active_effect = None
                    self.active_effect_config = {}
                else:
                    self.active_effect = self._stacked_effects[-1]['name']
                    self.active_effect_config = self._stacked_effects[-1]['config']
            btn.update_style()
            if MIDI_AVAILABLE and self.midi_handler.midi_out and effect_idx < 8:
                velocity = 1 if btn.active else 0
                self.midi_handler.set_pad_led(effect_idx, 8, velocity, brightness_percent=100)
            return

        # ── Mode exclusif (par défaut) : un seul effet à la fois ─────────────
        btn.active = not btn.active
        if btn.active:
            effect_name = btn.current_effect
            if not effect_name:
                btn.active = False
                btn.update_style()
                self._log_message(f"Bouton {effect_idx + 1} — aucun effet assigné (clic droit pour configurer)", "warn")
                return

            # Sauvegarder l'état précédent — uniquement si l'effet vient d'un FX pad,
            # pas d'un autre bouton d'effet (sinon désactiver B relancerait A)
            self._prev_effect_state = {
                "effect":  self.active_effect if self.active_fx_pads else None,
                "config":  dict(self.active_effect_config) if (self.active_effect_config and self.active_fx_pads) else {},
                "fx_pads": dict(self.active_fx_pads),
            }
            # Désactiver visuellement les pads FX actifs sans stopper l'effet
            # (stop_effect sera appelé par start_effect)
            for k in list(self.active_fx_pads.keys()):
                self.active_fx_pads.pop(k)
                self._style_fx_pad(k[0], k[1])

            self.active_effect = effect_name
            self.active_effect_config = self._button_effect_configs.get(effect_idx, {})
            self.start_effect(effect_name)
            self._log_message(f"Effet ON : {effect_name}", "effect")
            self._warn_effect_no_targets(self.active_effect_config)
            for j, other_btn in enumerate(self.effect_buttons):
                if j != effect_idx and other_btn.active:
                    other_btn.active = False
                    other_btn.update_style()
                    if MIDI_AVAILABLE and self.midi_handler.midi_out:
                        self.midi_handler.set_pad_led(j, 8, 0)
        else:
            # Restaurer l'état précédent s'il existait
            self._log_message(f"Effet OFF : {btn.current_effect}", "effect")
            prev = getattr(self, '_prev_effect_state', None)
            self._prev_effect_state = None
            self.stop_effect()

            restored = False
            if prev:
                # Restaurer les pads FX actifs
                for (fc, fr) in prev.get("fx_pads", {}).keys():
                    cfg = self.fx_pads[fc][fr] if fc < 4 else None
                    if cfg:
                        self.active_fx_pads[(fc, fr)] = True
                        self._style_fx_pad(fc, fr)
                        self.active_effect = cfg.get("name", "")
                        self.active_effect_config = cfg
                        self.start_effect(self.active_effect)
                        restored = True
                        break  # un seul FX actif à la fois
                # Restaurer un effet non-FX s'il n'y avait pas de pad FX
                if not restored and prev.get("effect"):
                    self.active_effect = prev["effect"]
                    self.active_effect_config = prev["config"]
                    self.start_effect(self.active_effect)
                    restored = True

            if not restored:
                self.active_effect = None
                self.active_effect_config = {}

        btn.update_style()
        # Mise a jour LED AKAI (utile quand l'effet est toggle depuis l'UI)
        if MIDI_AVAILABLE and self.midi_handler.midi_out and effect_idx < 8:
            velocity = 1 if btn.active else 0
            self.midi_handler.set_pad_led(effect_idx, 8, velocity, brightness_percent=100)

    # ── FX pad columns (standalone, right of AKAI) ───────────────────────────

    def _style_fx_pad(self, fx_col, row):
        """Rafraîchit le style des pads AKAI mappés sur ce slot FX."""
        cfg = self.fx_pads[fx_col][row] if fx_col < _FX_COL_MAX else None
        active = self.active_fx_pads.get((fx_col, row))
        for col_idx, slot in enumerate(self._fader_map):
            if slot.get("type") == "fx" and slot.get("fx_col") == fx_col:
                pad = self.pads.get((row, col_idx))
                if not pad:
                    continue
                if active and cfg:
                    pad.setStyleSheet("QPushButton { background: #33ff33; border: 2px solid #ffffff; border-radius: 4px; }")
                    pad.setToolTip(cfg.get("name", ""))
                elif cfg:
                    pad.setStyleSheet("QPushButton { background: #116611; border: 1px solid #114411; border-radius: 4px; }")
                    pad.setToolTip(cfg.get("name", ""))
                else:
                    pad.setStyleSheet("QPushButton { background: #0a1a0a; border: 1px solid #1a2a1a; border-radius: 4px; }")
                    pad.setToolTip("")

    # ══════════════════════════════════════════════════════════════════════════
    # POSITION LYRE PADS (intégrés comme colonnes AKAI, type "pos")
    # ══════════════════════════════════════════════════════════════════════════

    def _apply_pos_fader_axis(self, slot, value):
        """Fader d'une colonne POS : pilote en live le PAN ou le TILT des lyres
        du groupe choisi, balayé entre les limites configurées de chaque lyre."""
        axis = slot.get("fader_axis")           # "pan" | "tilt"
        group = slot.get("fader_group")         # None (toutes) | "A".."H"
        internal = AKAI_GROUP_MAP.get(group) if group else None
        frac = max(0.0, min(1.0, value / 100.0))

        applied = 0
        for p in self.projectors:
            if getattr(p, 'fixture_type', '') not in ('Moving Head', 'Lyre'):
                continue
            if internal is not None and getattr(p, 'group', None) != internal:
                continue
            if axis == "pan":
                lo = getattr(p, 'pan_min', 0)
                hi = getattr(p, 'pan_max', 65535)
                p.pan = max(0, min(65535, int(lo + (hi - lo) * frac)))
            else:
                lo = getattr(p, 'tilt_min', 0)
                hi = getattr(p, 'tilt_max', 65535)
                p.tilt = max(0, min(65535, int(lo + (hi - lo) * frac)))
            applied += 1

        if applied:
            self.send_dmx_update()

    def _style_position_akai_pad(self, pos_col, row):
        """Rafraîchit le style de tous les pads AKAI mappés sur ce slot POS."""
        preset_idx = self.position_pads[pos_col][row] if pos_col < _POS_COL_MAX else None
        is_active = self.active_position_pads.get(pos_col) == row
        preset = (self.position_presets[preset_idx]
                  if preset_idx is not None and preset_idx < len(self.position_presets)
                  else None)
        for col_idx, slot in enumerate(self._fader_map):
            if slot.get("type") == "pos" and slot.get("pos_col") == pos_col:
                pad = self.pads.get((row, col_idx))
                if pad is None:
                    continue
                if is_active and preset:
                    pad.setStyleSheet("QPushButton { background: #2255ee; border: 2px solid #88aaff; border-radius: 4px; }")
                elif preset:
                    pad.setStyleSheet("QPushButton { background: #0d2266; border: 1px solid #1a3399; border-radius: 4px; }")
                else:
                    pad.setStyleSheet("QPushButton { background: #0a0a22; border: 1px solid #1a1a44; border-radius: 4px; }")
                tip = preset["name"] if preset else ""
                pad.setToolTip(tip)

    def _update_pos_pad_led(self, pos_col, row):
        """Met à jour la LED MIDI physique d'un pad POS."""
        if not (MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out):
            return
        preset_idx = self.position_pads[pos_col][row] if pos_col < _POS_COL_MAX else None
        is_active = self.active_position_pads.get(pos_col) == row
        for col_idx, slot in enumerate(self._fader_map):
            if slot.get("type") == "pos" and slot.get("pos_col") == pos_col:
                if is_active and preset_idx is not None:
                    self.midi_handler.set_pad_led(row, col_idx, 45, brightness_percent=self.akai_active_brightness)
                elif preset_idx is not None:
                    self.midi_handler.set_pad_led(row, col_idx, 45, brightness_percent=self.akai_inactive_brightness)
                else:
                    self.midi_handler.set_pad_led(row, col_idx, 0, brightness_percent=0)

    def _activate_position_akai_pad(self, btn, pos_col, row, col_akai=None):
        """Clic sur un pad POS : REC → enregistre, sinon → rappelle la position."""
        if self._mem_rec_mode:
            self._record_position_akai(pos_col, row)
            self._mem_rec_mode = False
            if self._rec_mem_btn:
                self._rec_mem_btn.setStyleSheet(
                    "QPushButton { background: #1e1e1e; color: #cc3333; border: 1px solid #3a3a3a; "
                    "border-radius: 4px; font-size: 13px; } "
                    "QPushButton:hover { background: #2a2a2a; color: #ff4444; border-color: #cc3333; }"
                )
                self._rec_mem_btn.setToolTip(tr("mw_rec_mem_hint"))
            self._update_non_mem_pad_tooltips()
            return
        self._recall_position_akai(pos_col, row)

    def _recall_position_akai(self, pos_col, row):
        """Rappelle la position lyre associée à position_pads[pos_col][row]."""
        preset_idx = self.position_pads[pos_col][row] if pos_col < _POS_COL_MAX else None
        if preset_idx is None or preset_idx >= len(self.position_presets):
            self._log_message(f"POS {pos_col + 1}-{row + 1} vide — clic droit pour configurer", "warn")
            return

        preset = self.position_presets[preset_idx]
        lyres_cur = [p for p in self.projectors
                     if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')]

        # Appariement preset ↔ lyres : adresse DMX, puis nom, puis rang. Partagé
        # avec le centre des effets Pan/Tilt (colonne POSITION de l'éditeur) —
        # les deux doivent viser le même point, sinon un cercle tournerait
        # ailleurs que là où le rappel pose la lyre.
        cibles = position_preset_values(preset, lyres_cur)

        applied = 0
        for p in lyres_cur:
            pt = cibles.get(id(p))
            if pt:
                self._start_pan_tilt_transition(p, pt[0], pt[1], 500)
                applied += 1

        if applied == 0:
            self._log_message(f"POS {pos_col + 1}-{row + 1} — aucune lyre correspondante", "warn")
            return

        # Servir une partie des lyres seulement n'était signalé nulle part : une
        # position enregistrée quand le rig comptait moins de lyres laissait les
        # nouvelles immobiles, sans message — « la 2e lyre ne prend pas la
        # position », impossible à distinguer d'une panne de la lyre.
        if applied < len(lyres_cur):
            absentes = ", ".join(p.name for p in lyres_cur if not cibles.get(id(p)))
            self._log_message(
                f"Position « {preset['name']} » : {applied}/{len(lyres_cur)} lyres — "
                f"absente(s) du preset : {absentes}. Réenregistrez la position "
                f"(REC Mémoire + pad POS) pour les inclure.", "warn")

        self.active_position_pads[pos_col] = row
        for pr in range(8):
            self._style_position_akai_pad(pos_col, pr)
            self._update_pos_pad_led(pos_col, pr)
        self._log_message(f"Position « {preset['name']} »", "go")

    def _record_position_akai(self, pos_col, row):
        """Capture le pan/tilt de toutes les lyres et sauvegarde sur ce pad."""
        from PySide6.QtWidgets import QInputDialog
        lyres = [p for p in self.projectors
                 if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')]
        if not lyres:
            self._log_message("Aucune lyre patchée — impossible d'enregistrer une position", "warn")
            return

        cur_idx = self.position_pads[pos_col][row] if pos_col < _POS_COL_MAX else None
        default_name = (
            self.position_presets[cur_idx]["name"]
            if cur_idx is not None and cur_idx < len(self.position_presets)
            else f"Pos {pos_col + 1}-{row + 1}"
        )
        name, ok = QInputDialog.getText(self, tr("pos_rec_dlg_title"), tr("pos_rec_dlg_label"), text=default_name)
        if not ok or not name.strip():
            return
        name = name.strip()

        snap = [{"group": p.group, "name": p.name,
                 "start_address": str(getattr(p, 'start_address', '')),
                 "pan":  getattr(p, 'pan',  32768),
                 "tilt": getattr(p, 'tilt', 32768)} for p in lyres]
        preset = {"name": name, "projectors": snap}

        if cur_idx is not None and cur_idx < len(self.position_presets):
            self.position_presets[cur_idx] = preset
        else:
            self.position_presets.append(preset)
            if pos_col < _POS_COL_MAX:
                self.position_pads[pos_col][row] = len(self.position_presets) - 1

        self._style_position_akai_pad(pos_col, row)
        self._save_akai_config_auto()
        self._log_message(f"Position « {name} » enregistrée", "success")

    def _show_pos_context_menu(self, pos, pos_col, row, btn):
        """Menu clic droit sur un pad POS — assigner, REC, renommer, effacer."""
        from PySide6.QtWidgets import QMenu
        menu = QMenu(btn)
        menu.setStyleSheet(
            "QMenu { background: #1a1a1a; border: 1px solid #3a3a3a; padding: 2px; font-size: 11px; }"
            "QMenu::item { padding: 4px 12px; border-radius: 3px; color: #e0e0e0; }"
            "QMenu::item:selected { background: #1a2a4a; color: #fff; }"
            "QMenu::item:disabled { color: #555; font-size: 9px; letter-spacing: 1px; }"
            "QMenu::separator { background: #333; height: 1px; margin: 2px 6px; }"
        )

        cur_idx = self.position_pads[pos_col][row] if pos_col < _POS_COL_MAX else None

        rec_act = menu.addAction(tr("pos_ctx_rec"))
        rec_act.triggered.connect(lambda: self._record_position_akai(pos_col, row))

        if cur_idx is not None and cur_idx < len(self.position_presets):
            menu.addSeparator()
            pname = self.position_presets[cur_idx]["name"]
            rename_act = menu.addAction(tr("pos_ctx_rename", name=pname))
            rename_act.triggered.connect(lambda: self._rename_position_akai(pos_col, row))
            clear_act = menu.addAction(tr("pos_ctx_clear"))
            clear_act.triggered.connect(lambda: self._clear_position_akai(pos_col, row))

        # ── Presets Plan de Feu ──────────────────────────────────────────
        pdf_presets = self._load_pdf_presets()
        if pdf_presets:
            menu.addSeparator()
            pdf_hdr = menu.addAction(tr("mw_light_plan_arrow"))
            pdf_hdr.setEnabled(False)
            for pp in pdf_presets:
                act = menu.addAction("    " + pp["name"])
                act.triggered.connect(
                    lambda _, p=pp, pc=pos_col, pr=row: self._import_pdf_preset_to_pad(pc, pr, p)
                )

        menu.exec(btn.mapToGlobal(pos))

    def _load_pdf_presets(self):
        """Charge les presets Pan/Tilt du fichier Plan de Feu."""
        try:
            from plan_de_feu import _load_presets as _pdf_load
            return _pdf_load()
        except Exception:
            return []

    def sync_pdf_positions_into_akai(self):
        """Resynchronise les copies AKAI des positions sur leur preset Plan de Feu.

        Les positions vivent dans DEUX fichiers (cf. `_load_pdf_presets`). REC
        Lumière ne sait lire que les positions AKAI : quand on y glisse un preset
        du plan de feu, MyStrow en fabrique une COPIE. Cette copie datait du
        premier usage et n'était jamais rafraîchie — mémoriser à nouveau la
        position depuis le plan de feu (typiquement après avoir ajouté une lyre
        au rig) ne changeait donc rien ni à l'aperçu ni au show.

        On MET À JOUR, on n'ajoute jamais : créer les copies à la volée
        gonflerait `position_presets` de tous les presets du plan de feu à chaque
        appel. Un preset jamais utilisé dans REC Lumière n'a pas de copie, et
        c'est très bien. Le plan de feu fait foi pour un nom donné — même
        sémantique que `_import_pdf_preset_to_pad`.

        Retourne le nombre de copies mises à jour.
        """
        presets = getattr(self, 'position_presets', None)
        if not presets:
            return 0
        try:
            par_nom = {p.get("name"): i for i, p in enumerate(presets)}
            n = 0
            for pdf in (self._load_pdf_presets() or []):
                i = par_nom.get(pdf.get("name"))
                if i is None:
                    continue
                maj = self._pdf_preset_to_akai(pdf)
                if maj != presets[i]:
                    presets[i] = maj
                    n += 1
            if n:
                self._save_akai_config_auto()
            return n
        except Exception as e:
            print(f"[POS] resynchro des positions Plan de Feu impossible : {e}")
            return 0

    def _pdf_preset_to_akai(self, pdf_preset):
        """Convertit un preset Plan de Feu → format AKAI position (multi-lyre)."""
        lyres = [p for p in self.projectors
                 if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')]
        per_proj = pdf_preset.get("per_proj", {})
        snap = []
        for p in lyres:
            # Le plan de feu stocke per_proj par str(start_address) ; fallback par nom
            ps = per_proj.get(str(p.start_address)) or per_proj.get(p.name)
            if ps:
                pan_v  = ps.get("pan",  pdf_preset.get("pan",  32768))
                tilt_v = ps.get("tilt", pdf_preset.get("tilt", 32768))
            else:
                pan_v  = pdf_preset.get("pan",  32768)
                tilt_v = pdf_preset.get("tilt", 32768)
            snap.append({"group": getattr(p, 'group', ''), "name": p.name,
                         "start_address": str(getattr(p, 'start_address', '')),
                         "pan": pan_v, "tilt": tilt_v})
        return {"name": pdf_preset["name"], "projectors": snap}

    def _import_pdf_preset_to_pad(self, pos_col, row, pdf_preset):
        """Importe un preset Plan de Feu comme preset AKAI et l'assigne au pad."""
        akai = self._pdf_preset_to_akai(pdf_preset)
        # Mettre à jour si même nom existe déjà (pour prendre en compte les modifs du plan de feu)
        for i, existing in enumerate(self.position_presets):
            if existing["name"] == akai["name"]:
                self.position_presets[i] = akai
                self._assign_position_akai(pos_col, row, i)
                self._save_akai_config_auto()
                return
        self.position_presets.append(akai)
        idx = len(self.position_presets) - 1
        self._assign_position_akai(pos_col, row, idx)
        self._save_akai_config_auto()
        self._log_message(f"Preset « {akai['name']} » importé depuis Plan de Feu", "success")

    def _assign_position_akai(self, pos_col, row, preset_idx):
        """Assigne un preset existant à position_pads[pos_col][row]."""
        if pos_col < _POS_COL_MAX:
            self.position_pads[pos_col][row] = preset_idx
        self._style_position_akai_pad(pos_col, row)
        self._save_akai_config_auto()

    def _rename_position_akai(self, pos_col, row):
        """Renomme le preset assigné à ce pad."""
        from PySide6.QtWidgets import QInputDialog
        cur_idx = self.position_pads[pos_col][row] if pos_col < _POS_COL_MAX else None
        if cur_idx is None or cur_idx >= len(self.position_presets):
            return
        old_name = self.position_presets[cur_idx]["name"]
        name, ok = QInputDialog.getText(self, tr("pos_rename_dlg_title"), tr("pos_rename_dlg_label"), text=old_name)
        if ok and name.strip():
            self.position_presets[cur_idx]["name"] = name.strip()
            # Rafraîchir tous les pads qui partagent ce preset
            for pc in range(_POS_COL_MAX):
                for pr in range(8):
                    if self.position_pads[pc][pr] == cur_idx:
                        self._style_position_akai_pad(pc, pr)
            self._save_akai_config_auto()

    def _clear_position_akai(self, pos_col, row):
        """Retire l'assignation du pad (le preset reste dans la bibliothèque)."""
        if pos_col < _POS_COL_MAX:
            self.position_pads[pos_col][row] = None
        if self.active_position_pads.get(pos_col) == row:
            self.active_position_pads.pop(pos_col, None)
        self._style_position_akai_pad(pos_col, row)
        self._update_pos_pad_led(pos_col, row)
        self._save_akai_config_auto()

    def _update_fx_pad_led(self, fx_col, row):
        """Envoie la LED MIDI physique pour un pad FX sur toutes les colonnes mappées."""
        if not (MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out):
            return
        cfg = self.fx_pads[fx_col][row] if fx_col < _FX_COL_MAX else None
        is_active = self.active_fx_pads.get((fx_col, row))
        for col_idx, slot in enumerate(self._fader_map):
            if slot.get("type") == "fx" and slot.get("fx_col") == fx_col:
                if is_active and cfg:
                    self.midi_handler.set_pad_led(row, col_idx, 21, brightness_percent=self.akai_active_brightness)
                elif cfg:
                    self.midi_handler.set_pad_led(row, col_idx, 21, brightness_percent=self.akai_inactive_brightness)
                else:
                    self.midi_handler.set_pad_led(row, col_idx, 0, brightness_percent=0)

    def _open_effect_editor_for_fx_pad(self, fx_col, row):
        """Ouvre l'éditeur d'effets pour un pad FX."""
        from effect_editor import EffectEditorDialog
        current = self.fx_pads[fx_col][row]
        initial = current.get("name") if current else None
        dlg = EffectEditorDialog(clips=[], main_window=self, parent=self, initial_effect=initial)
        dlg.exec()

    def _toggle_fx_pad(self, fx_col, row):
        """Toggle an FX pad on/off."""
        # Mode REC actif : impossible d'enregistrer sur un pad FX
        if self._mem_rec_mode:
            self._mem_rec_mode = False
            if self._rec_mem_btn:
                self._rec_mem_btn.setStyleSheet(
                    "QPushButton { background: #1e1e1e; color: #cc3333; border: 1px solid #3a3a3a; "
                    "border-radius: 4px; font-size: 13px; } "
                    "QPushButton:hover { background: #2a2a2a; color: #ff4444; border-color: #cc3333; }"
                )
                self._rec_mem_btn.setToolTip(tr("mw_rec_mem_hint"))
            self._update_non_mem_pad_tooltips()
            self._show_error_toast("✖ Impossible d'enregistrer sur un FX — Pour ajouter un effet, cliquez droit sur le pad")
            return
        cfg = self.fx_pads[fx_col][row] if fx_col < _FX_COL_MAX else None
        if not cfg:
            return
        key = (fx_col, row)
        if self.active_fx_pads.get(key):
            # Turn off
            self.active_fx_pads.pop(key, None)
            self.active_effect = None
            self.active_effect_config = {}
            self.stop_effect()
        else:
            # Deactivate all other FX pads
            for k in list(self.active_fx_pads.keys()):
                self.active_fx_pads.pop(k, None)
                self._style_fx_pad(k[0], k[1])
            # Deactivate EffectButton column too
            for btn in self.effect_buttons:
                if btn.active:
                    btn.active = False
                    btn.update_style()
            # Turn on
            self.active_fx_pads[key] = True
            eff_name = cfg.get("name", "")
            self.active_effect = eff_name
            self.active_effect_config = cfg
            self.start_effect(eff_name)
        # Rafraîchir tous les pads FX (visuel + LEDs physiques)
        for fc in range(_FX_COL_MAX):
            for r in range(8):
                self._style_fx_pad(fc, r)
                self._update_fx_pad_led(fc, r)

    def _show_fx_context_menu(self, pos, fx_col, row, btn):
        """Menu clic droit sur un pad FX — identique aux petits carrés verts."""
        from PySide6.QtWidgets import (QMenu, QWidgetAction, QLineEdit, QSlider,
                                        QDoubleSpinBox, QHBoxLayout, QVBoxLayout, QLabel)

        all_effects = []
        try:
            from effect_editor import BUILTIN_EFFECTS, _load_custom_effects
            all_effects = list(BUILTIN_EFFECTS) + _load_custom_effects()
        except Exception:
            pass

        current_cfg = self.fx_pads[fx_col][row] if fx_col < _FX_COL_MAX else None
        cur = current_cfg.get("name") if current_cfg else None
        trigger_mode = (current_cfg or {}).get("trigger_mode", "toggle")
        trigger_duration = (current_cfg or {}).get("trigger_duration", 2000)

        menu = QMenu(btn)
        _MENU_BASE_SS = """
            QMenu {
                background: #1a1a1a;
                border: 1px solid #3a3a3a;
                padding: 2px;
                font-size: 11px;
            }
            QMenu::item { padding: 4px 10px; border-radius: 3px; color: #e0e0e0; }
            QMenu::item:selected { background: #2a3a3a; color: #fff; }
            QMenu::item:disabled { color: #555; font-size: 9px; letter-spacing: 1px; }
            QMenu::separator { background: #333; height: 1px; margin: 2px 6px; }
        """
        menu.setStyleSheet(_MENU_BASE_SS)

        def _select(cfg_or_none):
            if cfg_or_none is None:
                self.fx_pads[fx_col][row] = None
                self.active_fx_pads.pop((fx_col, row), None)
                if cur and self.active_effect == cur:
                    self.active_effect = None
                    self.active_effect_config = {}
                    self.stop_effect()
                    for _b in self.effect_buttons:
                        if _b.active and _b.current_effect == cur:
                            _b.active = False
                            _b.update_style()
            else:
                entry = dict(cfg_or_none)
                entry["trigger_mode"] = trigger_mode
                entry["trigger_duration"] = trigger_duration
                self.fx_pads[fx_col][row] = entry
            self._style_fx_pad(fx_col, row)
            self._save_akai_config_auto()

        # ── Section 1 : GROUPES + VITESSE ────────────────────────────────────
        _lyr0 = (current_cfg or {}).get("layers", [])
        _init_groups = list(_lyr0[0].get("target_groups", ["A","B","C","D","E","F","G","H"])) if _lyr0 else ["A","B","C","D","E","F","G","H"]
        _init_speed  = int(_lyr0[0].get("speed", 50)) if _lyr0 else 50
        _sel_groups  = list(_init_groups)

        _spd_slider = QSlider(Qt.Horizontal)
        _spd_slider.setRange(0, 100)
        _spd_slider.setValue(_init_speed)
        _spd_slider.setFixedWidth(100)
        _spd_slider.setStyleSheet(
            "QSlider::groove:horizontal{background:#333;height:4px;border-radius:2px;}"
            "QSlider::handle:horizontal{background:#00aaff;width:12px;height:12px;margin:-4px 0;border-radius:6px;}"
        )

        _GRP_ON  = "QPushButton{background:#00aaff;color:#fff;border:1px solid #0088cc;border-radius:3px;font-size:10px;font-weight:bold;}"
        _GRP_OFF = "QPushButton{background:#2a2a2a;color:#777;border:1px solid #3a3a3a;border-radius:3px;font-size:10px;}"
        _grp_btn_map = {}

        def _save_pad_layers():
            pad = self.fx_pads[fx_col][row]
            if pad and "layers" in pad:
                for _l in pad["layers"]:
                    _l["target_groups"] = list(_sel_groups)
                    _l["speed"] = _spd_slider.value()
                self._save_akai_config_auto()

        def _toggle_grp_pad(g_id):
            if g_id in _sel_groups:
                _sel_groups.remove(g_id)
            else:
                _sel_groups.append(g_id)
            _grp_btn_map[g_id].setStyleSheet(_GRP_ON if g_id in _sel_groups else _GRP_OFF)
            _save_pad_layers()

        grp_outer = QWidget(); grp_outer.setStyleSheet("background: transparent;")
        grp_vlay = QVBoxLayout(grp_outer)
        grp_vlay.setContentsMargins(10, 6, 10, 2); grp_vlay.setSpacing(4)
        grp_hdr = QLabel(tr("mw_groups_label")); grp_hdr.setStyleSheet("color:#555;font-size:9px;letter-spacing:1px;background:transparent;")
        grp_vlay.addWidget(grp_hdr)
        btns_h = QHBoxLayout(); btns_h.setSpacing(3); btns_h.setContentsMargins(0, 0, 0, 0)
        for _gid in ["A","B","C","D","E","F","G","H"]:
            _gb = QPushButton(_gid); _gb.setFixedSize(36, 22)
            _gb.setStyleSheet(_GRP_ON if _gid in _sel_groups else _GRP_OFF)
            _gb.clicked.connect(lambda _, g=_gid: _toggle_grp_pad(g))
            _grp_btn_map[_gid] = _gb; btns_h.addWidget(_gb)
        grp_vlay.addLayout(btns_h)
        spd_row = QHBoxLayout(); spd_row.setSpacing(6); spd_row.setContentsMargins(0, 2, 0, 0)
        spd_lbl = QLabel(tr("mw_speed")); spd_lbl.setStyleSheet("color:#aaa;font-size:11px;background:transparent;")
        spd_val_lbl = QLabel(f"{_init_speed}"); spd_val_lbl.setFixedWidth(26)
        spd_val_lbl.setStyleSheet("color:#fff;font-size:11px;background:transparent;")
        _spd_slider.valueChanged.connect(lambda v: spd_val_lbl.setText(f"{v}"))
        _spd_slider.valueChanged.connect(lambda _v: _save_pad_layers())
        spd_row.addWidget(spd_lbl); spd_row.addWidget(_spd_slider); spd_row.addWidget(spd_val_lbl); spd_row.addStretch()
        grp_vlay.addLayout(spd_row)
        grp_wa = QWidgetAction(menu); grp_wa.setDefaultWidget(grp_outer); menu.addAction(grp_wa)
        menu.addSeparator()

        # ── Section 2 : MODE DE DÉCLENCHEMENT (inline) ───────────────────────
        trig_outer = QWidget(); trig_outer.setStyleSheet("background: transparent;")
        trig_vlay = QVBoxLayout(trig_outer)
        trig_vlay.setContentsMargins(10, 4, 10, 6); trig_vlay.setSpacing(4)
        trig_hdr_lbl = QLabel(tr("mw_trigger")); trig_hdr_lbl.setStyleSheet("color:#555;font-size:9px;letter-spacing:1px;background:transparent;")
        trig_vlay.addWidget(trig_hdr_lbl)

        _TRIG_ON  = ("QPushButton{background:#00aaff;color:#fff;border:1px solid #0088cc;"
                     "border-radius:3px;font-size:10px;font-weight:bold;padding:2px 6px;}")
        _TRIG_OFF = ("QPushButton{background:#2a2a2a;color:#777;border:1px solid #3a3a3a;"
                     "border-radius:3px;font-size:10px;padding:2px 6px;}")
        trig_btns_row = QHBoxLayout(); trig_btns_row.setSpacing(4); trig_btns_row.setContentsMargins(0,0,0,0)
        _trig_btn_map = {}
        for _mode, _mlbl in [("toggle","Toggle"),("flash","Flash"),("timer","Timer")]:
            _tb = QPushButton(_mlbl)
            _tb.setStyleSheet(_TRIG_ON if trigger_mode == _mode else _TRIG_OFF)
            _trig_btn_map[_mode] = _tb
            trig_btns_row.addWidget(_tb)
        trig_btns_row.addStretch()
        trig_vlay.addLayout(trig_btns_row)

        dur_row = QHBoxLayout(); dur_row.setSpacing(6); dur_row.setContentsMargins(0,2,0,0)
        dur_lbl = QLabel(tr("mw_duration")); dur_lbl.setStyleSheet("color:#aaa;font-size:11px;background:transparent;")
        dur_spin = QDoubleSpinBox()
        dur_spin.setRange(0.1, 60.0); dur_spin.setSingleStep(0.5)
        dur_spin.setValue(trigger_duration / 1000.0); dur_spin.setSuffix(" s")
        dur_spin.setFixedWidth(80)
        dur_spin.setEnabled(trigger_mode == "timer")
        dur_spin.setStyleSheet(
            "QDoubleSpinBox { background:#222; color:#fff; border:1px solid #444;"
            " border-radius:3px; padding:2px 4px; font-size:11px; }"
            "QDoubleSpinBox:disabled { color:#555; border-color:#333; }"
            "QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { width:16px; background:#333; border:none; }"
        )
        def _set_dur(v):
            nonlocal trigger_duration
            trigger_duration = int(v * 1000)
            if self.fx_pads[fx_col][row]:
                self.fx_pads[fx_col][row]["trigger_duration"] = trigger_duration
        dur_spin.valueChanged.connect(_set_dur)
        dur_row.addWidget(dur_lbl); dur_row.addWidget(dur_spin); dur_row.addStretch()
        trig_vlay.addLayout(dur_row)

        def _set_trig_fx(mode):
            nonlocal trigger_mode
            trigger_mode = mode
            if self.fx_pads[fx_col][row]:
                self.fx_pads[fx_col][row]["trigger_mode"] = mode
            for m, b in _trig_btn_map.items():
                b.setStyleSheet(_TRIG_ON if m == mode else _TRIG_OFF)
            dur_spin.setEnabled(mode == "timer")

        for _mode, _tb in _trig_btn_map.items():
            _tb.clicked.connect(lambda _, m=_mode: _set_trig_fx(m))

        trig_wa = QWidgetAction(menu); trig_wa.setDefaultWidget(trig_outer); menu.addAction(trig_wa)
        menu.addSeparator()

        # ── Section 3 : EFFETS ────────────────────────────────────────────────
        search_container = QWidget(); search_container.setStyleSheet("background: transparent;")
        search_layout = QHBoxLayout(search_container)
        search_layout.setContentsMargins(6, 4, 6, 4)
        search_input = QLineEdit()
        search_input.setPlaceholderText(tr("mw_search_effect"))
        search_input.setClearButtonEnabled(True)
        search_input.setStyleSheet("""
            QLineEdit {
                background: #111; color: #e0e0e0;
                border: 1px solid #444; border-radius: 4px;
                padding: 4px 8px; font-size: 12px;
            }
            QLineEdit:focus { border-color: #00d4ff; }
        """)
        def _search_key(event):
            if event.key() in (Qt.Key_Up, Qt.Key_Down, Qt.Key_Return, Qt.Key_Enter):
                event.accept(); return
            QLineEdit.keyPressEvent(search_input, event)
        search_input.keyPressEvent = _search_key
        search_layout.addWidget(search_input)
        search_wa = QWidgetAction(menu); search_wa.setDefaultWidget(search_container); menu.addAction(search_wa)
        menu.addSeparator()

        name_is_full_match = cur and any(e.get("name") == cur for e in all_effects)
        def _is_checked(eff):
            name = eff.get("name", "")
            if name == cur: return True
            if not name_is_full_match and cur and eff.get("type") == cur:
                first = next((e for e in all_effects if e.get("type") == cur), None)
                return first is not None and first.get("name") == name
            return False

        _SEL_SS = (
            "QMenu::indicator { width: 0px; height: 0px; image: none; }"
            "QMenu::item:checked { background: #004400; color: #44ff44;"
            " font-weight: bold; border-left: 3px solid #44ff44; }"
            "QMenu::item:checked:selected { background: #005500; color: #55ff55; }"
        )
        menu.setStyleSheet(_MENU_BASE_SS + _SEL_SS)

        act_none = menu.addAction(tr("mw_none_dash"))
        act_none.setCheckable(True)
        act_none.setChecked(not cur)
        act_none.triggered.connect(lambda: _select(None))
        sep_top = menu.addSeparator()

        _CAT_KEYS = ["Strobe / Flash", "Mouvement", "Ambiance", "Couleur",
                     "Permut", "Lyre", "Spécial", "Personnalisés", "Mes Effets"]
        cat_groups = []
        for cat in _CAT_KEYS:
            cat_effs = [e for e in all_effects if e.get("category") == cat]
            if not cat_effs: continue
            hdr = menu.addAction(f"  {cat.upper()}")
            hdr.setEnabled(False)
            eff_actions = []
            for eff in cat_effs:
                name = eff.get("name", "")
                selected = _is_checked(eff)
                label = f"  {name}"
                act = menu.addAction(label)
                act.setCheckable(True)
                act.setChecked(selected)
                act.triggered.connect(lambda checked=False, e=dict(eff): _select(e))
                eff_actions.append((act, name, selected))
            cat_groups.append((hdr, eff_actions))

        other = [e for e in all_effects if e.get("category", "") not in _CAT_KEYS]
        if other:
            sep_other = menu.addSeparator()
            other_actions = []
            for eff in other:
                name = eff.get("name", "")
                selected = _is_checked(eff)
                label = f"  {name}"
                act = menu.addAction(label)
                act.setCheckable(True)
                act.setChecked(selected)
                act.triggered.connect(lambda checked=False, e=dict(eff): _select(e))
                other_actions.append((act, name, selected))
            cat_groups.append((sep_other, other_actions))

        def _apply_filter(text):
            q = text.strip().lower()
            act_none.setVisible(not q)
            sep_top.setVisible(not q)
            for hdr_act, eff_acts in cat_groups:
                any_vis = False
                for act, name, *_ in eff_acts:
                    v = not q or q in name.lower()
                    act.setVisible(v)
                    if v: any_vis = True
                hdr_act.setVisible(any_vis)
        search_input.textChanged.connect(_apply_filter)
        QTimer.singleShot(0, search_input.setFocus)

        # « Éditeur d'effets » remonté en TÊTE du menu. Il est construit ici,
        # après la liste, parce qu'il a besoin de fx_col/row — mais il est
        # ensuite déplacé en première position : la liste d'effets fait 92
        # entrées, l'entrée se retrouvait tout en bas, hors de vue sans
        # défiler. Rien ne dépend de sa place dans le menu, l'action est
        # branchée sur triggered.
        act_editor = menu.addAction(tr("mw_effect_editor"))
        act_editor.triggered.connect(lambda: self._open_effect_editor_for_fx_pad(fx_col, row))
        _premier = next((a for a in menu.actions() if a is not act_editor), None)
        if _premier is not None:
            menu.removeAction(act_editor)
            menu.insertAction(_premier, act_editor)
            menu.insertSeparator(_premier)

        menu.exec(btn.mapToGlobal(pos))

    # ── État capturé au démarrage d'un effet ─────────────────────────────────
    #
    # ⚠ Tout attribut qu'une couche d'effet peut écrire DOIT figurer ici, sinon
    # il reste figé sur la dernière image de l'effet une fois celui-ci coupé.
    # C'est ce qui est arrivé à `color_wheel` : une couche RVB (Rainbow) appelle
    # `_update_color_wheel` pour les lyres sans RVB, la roue restait donc sur la
    # dernière teinte. Invisible en 3D (qui lit `color`), bien visible sur le
    # plan 2D et sur le vrai DMX (qui lisent la position de la roue).
    # Le tuple ne peut que S'ALLONGER : plan_de_feu lit sv[0..4] par index.

    def _snapshot_effect_state(self):
        """Capture l'état des projecteurs avant application d'un effet."""
        self.effect_saved_colors = {
            id(p): (p.base_color, p.color, p.level,
                    getattr(p, 'pan', 32768), getattr(p, 'tilt', 32768),
                    getattr(p, 'white_boost', 0), getattr(p, 'amber_boost', 0),
                    getattr(p, 'uv', 0), getattr(p, 'color_wheel', 0),
                    getattr(p, 'gobo', 0), getattr(p, 'zoom', 0))
            for p in self.projectors
        }

    def _restore_effect_state(self):
        """Rend aux projecteurs leur état d'avant l'effet, puis vide la capture.

        Le vidage compte autant que la restitution : tant que la capture reste
        en place, le plan 2D croit qu'un effet tourne et redirige ses réglages
        (pan/tilt, dimmer) vers ce dictionnaire mort au lieu des projecteurs.
        """
        for p in self.projectors:
            saved = self.effect_saved_colors.get(id(p))
            if not saved:
                continue
            p.base_color, p.color, p.level = saved[0], saved[1], saved[2]
            if len(saved) > 4:
                p.pan, p.tilt = saved[3], saved[4]
            if len(saved) > 6:
                p.white_boost, p.amber_boost = saved[5], saved[6]
            if len(saved) > 7:
                p.uv = saved[7]
            if len(saved) > 8:
                p.color_wheel = saved[8]
            if len(saved) > 10:
                p.gobo, p.zoom = saved[9], saved[10]
        self.effect_saved_colors = {}

    def start_effect(self, effect_name):
        """Demarre l'effet selectionne par nom"""
        # Switch effet → effet : si un effet tourne déjà, le couper d'abord pour
        # RESTAURER ses projecteurs. Sinon les projos de l'effet précédent (hors
        # cibles du nouvel effet) restaient figés/allumés. La garde isActive()
        # évite tout doublon quand l'appelant a déjà fait stop_effect (mémoire/cue).
        if getattr(self, 'effect_timer', None) is not None and self.effect_timer.isActive():
            self.stop_effect()
        self.effect_state = 0
        self._snapshot_effect_state()

        if not hasattr(self, 'effect_timer'):
            self.effect_timer = QTimer()
            self.effect_timer.timeout.connect(self.update_effect)

        if effect_name == "Bascule":
            self._bascule()
            return  # one-shot, pas de timer

        # Si un config éditeur est actif, initialiser selon son type
        cfg = self.active_effect_config
        etype = cfg.get("type", effect_name) if cfg else effect_name
        speed_raw = cfg.get("speed", 50) if cfg else 50
        sf = max(0.05, 1.0 - speed_raw / 100.0 * 0.95)

        if cfg and cfg.get("layers"):
            import time as _time
            self.effect_t0 = _time.monotonic()
            self.effect_timer.start(40)  # 25 fps pour les effets à couches
            return

        if cfg:
            init_intervals = {
                "Strobe": max(25, int(500 - speed_raw / 100.0 * 475)),
                "Flash":  max(25, int(500 - speed_raw / 100.0 * 475)),
                "Pulse": 30, "Wave": int(50 * sf),
                "Chase": max(40, int(400 * sf)), "Comete": max(30, int(300 * sf)),
                "Etoile Filante": max(25, int(70 * sf)),
                "Rainbow": 50, "Fire": int(60 * sf),
            }
            self.effect_timer.start(init_intervals.get(etype, 80))
        else:
            intervals = {
                "Strobe": 100, "Flash": 100, "Pulse": 30,
                "Wave": 50, "Comete": 80, "Rainbow": 50,
                "Etoile Filante": 60, "Fire": 60, "Chase": 200,
            }
            self.effect_timer.start(intervals.get(effect_name, 100))

        if etype in ("Rainbow", "Wave"):
            self.effect_hue = 0
        if etype == "Pulse":
            self.effect_brightness = 0
            self.effect_direction = 1

    def _stop_once_effect(self):
        """Arrête un effet lancé en mode 'une fois' et désactive le bouton correspondant."""
        self.stop_effect()
        # Désactiver le bouton AKAI actif
        for i, btn in enumerate(self.effect_buttons):
            if btn.active:
                btn.active = False
                btn.update_style()
                if MIDI_AVAILABLE and self.midi_handler.midi_out and i < 8:
                    self.midi_handler.set_pad_led(i, 8, 0)
        self.active_effect = None
        self.active_effect_config = {}

    def _start_pan_tilt_transition(self, proj, new_pan: int, new_tilt: int, duration_ms: int = 500):
        """Lance une animation fluide pan/tilt vers (new_pan, new_tilt)."""
        import time as _t
        cur_pan  = getattr(proj, 'pan',  32768)
        cur_tilt = getattr(proj, 'tilt', 32768)
        # Si on est déjà au milieu d'une transition, repartir depuis la position actuelle
        if id(proj) in self._pan_tilt_transitions:
            tr = self._pan_tilt_transitions[id(proj)]
            cur_pan  = getattr(proj, 'pan',  tr['p1'])
            cur_tilt = getattr(proj, 'tilt', tr['t1'])
        if cur_pan == new_pan and cur_tilt == new_tilt:
            self._pan_tilt_transitions.pop(id(proj), None)
            return
        self._pan_tilt_transitions[id(proj)] = {
            'proj':     proj,
            'p0':       cur_pan,  't0': cur_tilt,
            'p1':       new_pan,  't1': new_tilt,
            'start':    _t.monotonic(),
            'duration': duration_ms / 1000.0,
        }
        if not self._pan_tilt_anim_timer.isActive():
            self._pan_tilt_anim_timer.start()

    def _tick_pan_tilt_anim(self):
        """Avance toutes les animations pan/tilt actives (~40 fps)."""
        import time as _t
        now  = _t.monotonic()
        done = []
        for pid, tr in self._pan_tilt_transitions.items():
            alpha = min(1.0, (now - tr['start']) / tr['duration'])
            # smoothstep : décélération naturelle comme une vraie lyre
            a = alpha * alpha * (3.0 - 2.0 * alpha)
            proj = tr['proj']
            proj.pan  = int(tr['p0'] + (tr['p1'] - tr['p0']) * a)
            proj.tilt = int(tr['t0'] + (tr['t1'] - tr['t0']) * a)
            if alpha >= 1.0:
                done.append(pid)
        for pid in done:
            del self._pan_tilt_transitions[pid]
        if not self._pan_tilt_transitions:
            self._pan_tilt_anim_timer.stop()
        # Rafraîchir 2D et 3D
        if hasattr(self, 'plan_de_feu'):
            self.plan_de_feu.update()
        if hasattr(self, '_plan3d') and self._plan3d.isVisible():
            self._plan3d.refresh(self.projectors)

    def stop_effect(self):
        """Arrete l'effet en cours"""
        if hasattr(self, 'effect_timer'):
            self.effect_timer.stop()

        for p in self.projectors:
            p.dmx_mode = "Manuel"

        self._restore_effect_state()

        # Ramener les Moving Heads au centre quand plus aucun effet n'est actif
        # (transition fluide) — SAUF si un clip Position de la timeline impose
        # encore une visée : la lyre doit y revenir, pas partir au milieu de
        # course. Sans cette exception, un effet Pan/Tilt posé PAR-DESSUS un clip
        # Position laissait la lyre au centre à sa dernière image, et rien ne la
        # ramenait (l'aperçu REC n'applique le clip Position qu'à son début).
        any_active = any(
            getattr(btn, 'active', False)
            for btn in getattr(self, 'effect_buttons', [])
        )
        if not any_active:
            centers = getattr(self, '_timeline_pos_centers', None) or {}
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre'):
                    pan, tilt = centers.get(id(p), (32768, 32768))
                    self._start_pan_tilt_transition(p, pan, tilt, 500)

    def _bascule(self):
        """Effet Bascule : echange les couleurs entre les deux groupes ou alterne un/deux."""
        from collections import Counter

        active = [p for p in self.projectors if p.group != "fumee" and p.level > 0]
        if not active:
            return

        def _bucket(c):
            return (c.red() // 35, c.green() // 35, c.blue() // 35)

        counts = Counter(_bucket(p.base_color) for p in active)

        def _apply(p, col):
            brightness = p.level / 100.0
            p.base_color = QColor(col)
            p.color = QColor(
                int(col.red()   * brightness),
                int(col.green() * brightness),
                int(col.blue()  * brightness),
            )

        if len(counts) >= 2:
            # Bicolore : échanger les deux couleurs dominantes
            top2 = [k for k, _ in counts.most_common(2)]
            group_a = [p for p in active if _bucket(p.base_color) == top2[0]]
            group_b = [p for p in active if _bucket(p.base_color) == top2[1]]
            col_a = QColor(group_a[0].base_color)
            col_b = QColor(group_b[0].base_color)
            for p in group_a:
                _apply(p, col_b)
            for p in group_b:
                _apply(p, col_a)
        else:
            # Monochrome : un projecteur sur deux passe en blanc, puis inversion
            phase = getattr(self, '_bascule_phase', 0) % 2
            white = QColor(255, 255, 255)
            for i, p in enumerate(active):
                if i % 2 == phase:
                    _apply(p, white)
                else:
                    _apply(p, p.base_color)
            self._bascule_phase = phase + 1

    def _apply_fx_amplitude(self):
        """Applique l'amplitude globale (fader 9) × amplitude colonne FX sur les couleurs."""
        global_amp = self.effect_amplitude / 100.0

        # Amplitude de la colonne FX active (si un pad FX déclenche l'effet)
        col_amp = 1.0
        if self.active_fx_pads:
            fx_col = next(iter(self.active_fx_pads))[0]
            col_amp = self.fx_amplitudes[fx_col] / 100.0 if 0 <= fx_col < _FX_COL_MAX else 1.0

        amp = global_amp * col_amp
        if amp >= 1.0:
            return
        for p in self.projectors:
            p.color = QColor(
                int(p.color.red()   * amp),
                int(p.color.green() * amp),
                int(p.color.blue()  * amp),
            )

    def update_effect(self):
        """Met a jour l'effet en cours"""
        # Si amplitude totale = 0, ne pas toucher aux projecteurs pour laisser
        # les colonnes MEM (ou autres sources) agir librement.
        global_amp = self.effect_amplitude / 100.0
        col_amp = 1.0
        if self.active_fx_pads:
            fx_col = next(iter(self.active_fx_pads))[0]
            col_amp = self.fx_amplitudes[fx_col] / 100.0 if 0 <= fx_col < _FX_COL_MAX else 1.0
        if global_amp * col_amp == 0:
            return

        # ── Mode superposition : applique chaque effet empilé en séquence ──
        if self.effect_superposition and self._stacked_effects:
            for eff_data in self._stacked_effects:
                self._apply_one_stacked_effect(eff_data)
            self._apply_fx_amplitude()
            return

        if self.active_effect is None:
            return

        # Config-driven path (depuis l'éditeur d'effets)
        cfg = self.active_effect_config
        if cfg:
            if cfg.get("layers"):
                self._update_effect_from_layers(cfg)
            else:
                self._update_effect_from_config(cfg)
            self._apply_fx_amplitude()
            return

        self._run_named_effect()
        self._apply_fx_amplitude()

    def _run_named_effect(self):
        """Applique un tick de l'effet nommé (lit/écrit les variables d'instance)."""
        # speed_factor : fader 0 = lent (1.0), fader 100 = rapide (0.05)
        speed_factor = max(0.05, 1.0 - (self.effect_speed / 100.0 * 0.95))

        eff = self.active_effect

        if eff == "Strobe":
            # Alternance blanc/noir — intervalle 500 ms (lent) → 25 ms (rapide)
            interval = max(25, int(500 - (self.effect_speed / 100.0) * 475))
            self.effect_timer.setInterval(interval)
            for p in self.projectors:
                if p.group == "fumee":
                    continue
                if p.level > 0:
                    p.color = QColor(255, 255, 255) if self.effect_state % 2 == 0 else QColor("black")
            self.effect_state += 1

        elif eff == "Flash":
            # Alternance couleur/noir — même mapping vitesse que Strobe
            interval = max(25, int(500 - (self.effect_speed / 100.0) * 475))
            self.effect_timer.setInterval(interval)
            for p in self.projectors:
                if p.group == "fumee":
                    continue
                if p.level > 0:
                    if self.effect_state % 2 == 0:
                        brightness = p.level / 100.0
                        p.color = QColor(
                            int(p.base_color.red() * brightness),
                            int(p.base_color.green() * brightness),
                            int(p.base_color.blue() * brightness)
                        )
                    else:
                        p.color = QColor("black")
            self.effect_state += 1

        elif eff == "Pulse":
            # Respiration douce (fade in/out)
            for p in self.projectors:
                if p.group == "fumee":
                    continue
                if p.level > 0:
                    brightness = (p.level / 127.0) * (self.effect_brightness / 100.0)
                    p.color = QColor(
                        int(p.base_color.red() * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue() * brightness)
                    )
            speed = 2 + int(self.effect_speed / 20)
            self.effect_brightness += self.effect_direction * speed
            if self.effect_brightness >= 100:
                self.effect_brightness = 100
                self.effect_direction = -1
            elif self.effect_brightness <= 0:
                self.effect_brightness = 0
                self.effect_direction = 1

        elif eff == "Wave":
            # Vague de couleur qui se deplace d'un projo a l'autre
            self.effect_timer.setInterval(int(50 * speed_factor))
            for i, p in enumerate(self.projectors):
                if p.group == "fumee":
                    continue
                if p.level > 0:
                    phase = (self.effect_state + i * 15) % 100
                    brightness = (p.level / 100.0) * (abs(50 - phase) / 50.0)
                    p.color = QColor(
                        int(p.base_color.red() * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue() * brightness)
                    )
            self.effect_state += 3 + int(self.effect_speed / 25)

        elif eff == "Comete":
            # Comète : tête blanche vive + traînée qui fondue vers la couleur de base
            self.effect_timer.setInterval(max(30, int(300 * speed_factor)))
            active = [p for p in self.projectors if p.group != "fumee" and p.level > 0]
            n = len(active)
            if n == 0:
                return
            TAIL = 4
            pos = self.effect_state % (n + TAIL)
            for i, p in enumerate(active):
                dist = pos - i
                brightness = p.level / 100.0
                if dist == 0:
                    p.color = QColor(255, 255, 255)
                elif 1 <= dist <= TAIL:
                    blend = (1.0 - dist / (TAIL + 1)) * 0.9
                    base_r = int(p.base_color.red()   * brightness)
                    base_g = int(p.base_color.green() * brightness)
                    base_b = int(p.base_color.blue()  * brightness)
                    p.color = QColor(
                        min(255, int(base_r + (255 - base_r) * blend)),
                        min(255, int(base_g + (255 - base_g) * blend)),
                        min(255, int(base_b + (255 - base_b) * blend)),
                    )
                else:
                    p.color = QColor(
                        int(p.base_color.red()   * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue()  * brightness),
                    )
            self.effect_state += 1

        elif eff == "Rainbow":
            # Rotation arc-en-ciel sur tous les projos
            for i, p in enumerate(self.projectors):
                if p.group == "fumee":
                    continue
                if p.level > 0:
                    hue = (self.effect_hue + i * 30) % 360
                    color = QColor.fromHsv(hue, 255, 255)
                    brightness = p.level / 100.0
                    p.color = QColor(
                        int(color.red() * brightness),
                        int(color.green() * brightness),
                        int(color.blue() * brightness)
                    )
            self.effect_hue += int(5 * (1 + self.effect_speed / 30))

        elif eff == "Etoile Filante":
            # Etoile filante : passage sinusoïdal au blanc avec traînée
            import math
            self.effect_timer.setInterval(max(25, int(70 * speed_factor)))
            active = [p for p in self.projectors if p.group != "fumee" and p.level > 0]
            n = len(active)
            if n == 0:
                return
            TAIL = 6
            total = n + TAIL + 4   # pause noire en fin de cycle
            pos = self.effect_state % total
            for i, p in enumerate(active):
                dist = pos - i
                brightness = p.level / 100.0
                if dist == 0:
                    # Tête : blanc pur
                    p.color = QColor(255, 255, 255)
                elif 1 <= dist <= TAIL:
                    # Traînée sinusoïdale
                    t = dist / TAIL
                    white_blend = (math.sin((1.0 - t) * math.pi / 2)) ** 1.5
                    base_r = int(p.base_color.red()   * brightness)
                    base_g = int(p.base_color.green() * brightness)
                    base_b = int(p.base_color.blue()  * brightness)
                    p.color = QColor(
                        min(255, int(base_r + (255 - base_r) * white_blend)),
                        min(255, int(base_g + (255 - base_g) * white_blend)),
                        min(255, int(base_b + (255 - base_b) * white_blend)),
                    )
                else:
                    p.color = QColor(
                        int(p.base_color.red()   * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue()  * brightness),
                    )
            self.effect_state += 1

        elif eff == "Chase":
            # Passage au blanc : chaque projecteur passe au blanc un par un
            self.effect_timer.setInterval(max(40, int(400 * speed_factor)))
            active = [p for p in self.projectors if p.group != "fumee" and p.level > 0]
            n = len(active)
            if n == 0:
                return
            current = self.effect_state % n
            for i, p in enumerate(active):
                brightness = p.level / 100.0
                if i == current:
                    p.color = QColor(255, 255, 255)
                else:
                    p.color = QColor(
                        int(p.base_color.red()   * brightness),
                        int(p.base_color.green() * brightness),
                        int(p.base_color.blue()  * brightness),
                    )
            self.effect_state += 1

        elif eff == "Fire":
            # Effet feu (rouge/orange/jaune aleatoire)
            self.effect_timer.setInterval(int(60 * speed_factor))
            fire_colors = [
                QColor(255, 50, 0), QColor(255, 100, 0), QColor(255, 150, 0),
                QColor(255, 200, 0), QColor(200, 30, 0), QColor(255, 80, 0),
            ]
            for p in self.projectors:
                if p.group == "fumee":
                    continue
                if p.level > 0:
                    base = random.choice(fire_colors)
                    brightness = p.level / 100.0
                    p.color = QColor(
                        int(base.red() * brightness),
                        int(base.green() * brightness),
                        int(base.blue() * brightness)
                    )
        # (l'amplitude FX est appliquée par l'appelant)

    def _apply_one_stacked_effect(self, eff_data):
        """Applique un tick d'un effet empilé (mode superposition).
        Sauvegarde/restaure les variables d'instance autour de l'appel."""
        # ── Sauvegarder l'état actuel ─────────────────────────────────────
        saved_eff  = self.active_effect
        saved_cfg  = self.active_effect_config
        saved_st   = self.effect_state
        saved_hue  = getattr(self, 'effect_hue', 0)
        saved_bri  = getattr(self, 'effect_brightness', 0)
        saved_dir  = getattr(self, 'effect_direction', 1)
        saved_t0   = getattr(self, 'effect_t0', 0)

        # ── Charger l'état de cet effet ──────────────────────────────────
        self.active_effect        = eff_data['name']
        self.active_effect_config = eff_data.get('config', {})
        self.effect_state         = eff_data.get('state', 0)
        self.effect_hue           = eff_data.get('hue', 0)
        self.effect_brightness    = eff_data.get('brightness', 0)
        self.effect_direction     = eff_data.get('direction', 1)
        self.effect_t0            = eff_data.get('t0', 0)

        # ── Exécuter un tick ─────────────────────────────────────────────
        cfg = self.active_effect_config
        if cfg:
            if cfg.get("layers"):
                self._update_effect_from_layers(cfg)
            else:
                self._update_effect_from_config(cfg)
        else:
            self._run_named_effect()

        # ── Sauvegarder le nouvel état dans le dict ───────────────────────
        eff_data['state']     = self.effect_state
        eff_data['hue']       = self.effect_hue
        eff_data['brightness']= self.effect_brightness
        eff_data['direction'] = self.effect_direction
        eff_data['t0']        = self.effect_t0

        # ── Restaurer les variables d'instance ────────────────────────────
        self.active_effect        = saved_eff
        self.active_effect_config = saved_cfg
        self.effect_state         = saved_st
        self.effect_hue           = saved_hue
        self.effect_brightness    = saved_bri
        self.effect_direction     = saved_dir
        self.effect_t0            = saved_t0

    # ------------------------------------------------------------------ #
    #  EDITEUR D'EFFETS                                                    #
    # ------------------------------------------------------------------ #

    def open_effect_editor(self):
        """Ouvre l'editeur d'effets (menu Edition)"""
        from effect_editor import EffectEditorDialog
        # Préférer le nom complet dans active_effect_config (ex: "Flash Simple")
        # plutôt que active_effect qui peut être un type legacy (ex: "Flash")
        cfg = getattr(self, 'active_effect_config', {}) or {}
        active_name = cfg.get('name') or getattr(self, 'active_effect', None)
        dlg = EffectEditorDialog(clips=[], main_window=self, parent=self, initial_effect=active_name)
        dlg.exec()

    def _open_effect_editor_for_btn(self, btn_idx: int):
        """Ouvre l'éditeur d'effets pré-sélectionné sur l'effet du bouton btn_idx."""
        from effect_editor import EffectEditorDialog
        cfg = self._button_effect_configs.get(btn_idx, {})
        initial_name = cfg.get('name')
        if not initial_name and btn_idx < len(self.effect_buttons):
            initial_name = self.effect_buttons[btn_idx].current_effect
        dlg = EffectEditorDialog(clips=[], main_window=self, parent=self, initial_effect=initial_name)
        dlg.exec()

    _EFFECT_ASSIGNMENTS_FILE = Path.home() / ".mystrow_effect_assignments.json"
    _EFFECT_LIBRARY_FILE     = Path.home() / ".mystrow_effect_library.json"

    def _load_effect_library(self) -> dict:
        """Charge les configs d'effets non assignés (édités mais pas sur un bouton)."""
        try:
            if self._EFFECT_LIBRARY_FILE.exists():
                return json.loads(self._EFFECT_LIBRARY_FILE.read_text(encoding="utf-8"))
        except Exception:
            pass
        return {}

    def _save_effect_library(self):
        """Sauvegarde les configs d'effets non assignés."""
        try:
            self._EFFECT_LIBRARY_FILE.write_text(
                json.dumps(self._effect_library_configs, indent=2, ensure_ascii=False),
                encoding="utf-8")
        except Exception:
            pass
        self._refresh_active_effect_config()

    def _load_effect_assignments(self) -> dict:
        """Charge les assignations bouton→effet depuis le disque."""
        try:
            if self._EFFECT_ASSIGNMENTS_FILE.exists():
                data = json.loads(self._EFFECT_ASSIGNMENTS_FILE.read_text(encoding="utf-8"))
                return {int(k): v for k, v in data.items()}
        except Exception:
            pass
        return {}

    def _save_effect_assignments(self):
        """Sauvegarde les assignations bouton→effet sur le disque."""
        try:
            self._EFFECT_ASSIGNMENTS_FILE.write_text(
                json.dumps({str(k): v for k, v in self._button_effect_configs.items()},
                           indent=2, ensure_ascii=False),
                encoding="utf-8")
        except Exception:
            pass
        # Si l'effet actif fait partie des configs mises à jour, relancer immédiatement
        self._refresh_active_effect_config()

    def _refresh_active_effect_config(self):
        """Recharge la config de l'effet actif depuis les sources à jour et le relance."""
        active_name = self.active_effect
        if not active_name:
            return

        # Vérifier qu'un bouton OU un pad FX est vraiment actif — pas juste un effet fantôme
        btn_is_active = any(
            btn.active and btn.current_effect == active_name
            for btn in self.effect_buttons
        )
        fx_is_active = bool(self.active_fx_pads)

        def _find_new_cfg():
            """Cherche la config mise à jour dans : boutons → pads FX → bibliothèque."""
            for cfg in self._button_effect_configs.values():
                if isinstance(cfg, dict) and cfg.get("name") == active_name:
                    return cfg
            for col in self.fx_pads:
                for cfg in col:
                    if isinstance(cfg, dict) and cfg.get("name") == active_name:
                        return cfg
            return self._effect_library_configs.get(active_name)

        if not btn_is_active and not fx_is_active:
            # Juste mettre à jour la config en mémoire, sans relancer
            new_cfg = _find_new_cfg()
            if new_cfg:
                self.active_effect_config = new_cfg
            return

        # Chercher la nouvelle config et relancer l'effet
        new_cfg = _find_new_cfg()
        if new_cfg:
            self.active_effect_config = new_cfg
            self.start_effect(active_name)
            # Mettre à jour _prev_effect_state si il référence le même effet
            prev = getattr(self, '_prev_effect_state', None)
            if prev and prev.get("effect") == active_name:
                prev["config"] = new_cfg

    def _on_effect_assigned(self, btn_idx: int, cfg: dict):
        """Reçoit l'assignation depuis l'éditeur ou le menu clic-droit et met à jour le bouton"""
        if cfg:
            self._button_effect_configs[btn_idx] = cfg
        else:
            self._button_effect_configs.pop(btn_idx, None)
        self._save_effect_assignments()
        if btn_idx < len(self.effect_buttons):
            name = cfg.get("name", "") if cfg else ""
            self.effect_buttons[btn_idx].setToolTip(name or "Aucun effet")
            self.effect_buttons[btn_idx].current_effect = name or None

        # Si cet effet est actuellement actif, appliquer la nouvelle config immédiatement
        if cfg and self.effect_buttons[btn_idx].active:
            self.active_effect_config = cfg
            self.active_effect = cfg.get("name", self.active_effect)
            self.start_effect(self.active_effect)

    def _on_effect_layer_overrides_changed(self, btn_idx: int, groups: list, speed: int):
        """Applique les overrides groupes/vitesse sur les couches de l'effet du bouton."""
        cfg = self._button_effect_configs.get(btn_idx)
        if not cfg:
            return
        layers = cfg.get("layers")
        if layers:
            for lyr in layers:
                lyr["target_groups"] = groups
                lyr["speed"] = speed
        else:
            cfg["layers"] = [{"target_groups": groups, "speed": speed}]
        if btn_idx < len(self.effect_buttons):
            self.effect_buttons[btn_idx]._target_groups = groups
            self.effect_buttons[btn_idx]._speed = speed
        self._save_effect_assignments()
        if btn_idx < len(self.effect_buttons) and self.effect_buttons[btn_idx].active:
            self.active_effect_config = cfg
            self.start_effect(cfg.get("name", self.active_effect))

    def _on_effect_trigger_mode_changed(self, btn_idx: int, mode: str, duration_ms: int):
        if btn_idx < len(self.effect_buttons):
            btn = self.effect_buttons[btn_idx]
            btn.trigger_mode = mode
            btn.trigger_duration = duration_ms
        self._save_effect_assignments()

    def _apply_fx_pad_speed(self, value: int):
        """Slider VITESSE permanent → applique la vitesse aux effets actifs en direct."""
        for idx, btn in enumerate(self.effect_buttons):
            if not getattr(btn, 'active', False):
                continue
            groups = list(getattr(btn, '_target_groups', None) or ["A", "B", "C", "D", "E", "F", "G", "H"])
            cfg = self._button_effect_configs.get(idx, {})
            lyr = cfg.get("layers")
            if lyr and lyr[0].get("target_groups"):
                groups = list(lyr[0]["target_groups"])
            self._on_effect_layer_overrides_changed(idx, groups, value)

    def _sync_fx_pad_speed_slider(self):
        """Aligne le slider VITESSE permanent sur la vitesse du 1er effet actif."""
        sl = getattr(self, 'fx_pad_speed_slider', None)
        if sl is None:
            return
        for btn in self.effect_buttons:
            if getattr(btn, 'active', False):
                sl.blockSignals(True)
                sl.setValue(int(getattr(btn, '_speed', 50)))
                sl.blockSignals(False)
                break

    def _on_effect_press(self, btn_idx: int):
        if btn_idx >= len(self.effect_buttons):
            return
        btn = self.effect_buttons[btn_idx]
        mode = btn.trigger_mode
        if mode == "toggle":
            self.toggle_effect(btn_idx)
        else:
            if not btn.active:
                self.toggle_effect(btn_idx)
                if mode == "timer":
                    QTimer.singleShot(btn.trigger_duration, lambda: self._ensure_effect_off(btn_idx))
        self._sync_fx_pad_speed_slider()

    def _on_effect_release(self, btn_idx: int):
        if btn_idx >= len(self.effect_buttons):
            return
        btn = self.effect_buttons[btn_idx]
        if btn.trigger_mode == "flash" and btn.active:
            self.toggle_effect(btn_idx)

    def _ensure_effect_off(self, btn_idx: int):
        if btn_idx < len(self.effect_buttons) and self.effect_buttons[btn_idx].active:
            self.toggle_effect(btn_idx)

    def _warn_effect_no_targets(self, cfg: dict):
        """Log un avertissement si l'effet ne peut rien produire visuellement."""
        _LETTER_TO_GROUP = {
            "A": "face", "B": "lat", "C": "contre",
            "D": "douche1", "E": "douche2", "F": "douche3",
            "G": "groupe_g", "H": "groupe_h",
        }
        active_projs = [p for p in self.projectors if p.group != "fumee"]
        if not active_projs:
            self._log_message("Aucun projecteur patché — l'effet ne produira rien", "warn")
            return

        # Collecte tous les groupes ciblés dans les layers (ou au niveau config)
        layers = cfg.get("layers", [])
        if layers:
            target_letters = set()
            for ld in layers:
                target_letters.update(ld.get("target_groups", []))
        else:
            target_letters = set(cfg.get("target_groups", []))

        allowed = {_LETTER_TO_GROUP[l] for l in target_letters if l in _LETTER_TO_GROUP}
        matched = [p for p in active_projs if not allowed or p.group in allowed]

        if not matched:
            labels = {"A": "Face", "B": "Lat", "C": "Contre",
                      "D": "Douche 1", "E": "Douche 2", "F": "Douche 3",
                      "G": "G", "H": "H"}
            groups_str = ", ".join(labels.get(l, l) for l in sorted(target_letters))
            self._log_message(
                f"Effet sans effet — aucun projecteur dans : {groups_str} (vérifiez votre patch)",
                "warn"
            )
            return

        # Vérifie si l'effet n'a que des couches Dim/Strobe (pas de couleur propre)
        # → dans ce cas il module la couleur existante des projecteurs
        # → si tous les projecteurs ciblés sont noirs, rien ne sera visible
        if layers:
            attrs = {ld.get("attribute", "Dimmer") for ld in layers}
            dim_only = attrs.issubset({"Dimmer", "Strobe"})
            if dim_only:
                all_black = all(
                    p.color.red() == 0 and p.color.green() == 0 and p.color.blue() == 0
                    for p in matched
                )
                if all_black:
                    self._log_message(
                        "Effet Dim/Strobe — aucune couleur sur les projecteurs ciblés, envoyez une couleur d'abord",
                        "warn"
                    )

    def _update_effect_from_layers(self, cfg: dict):
        """Exécute un effet défini par ses couches (format nouvel éditeur)."""
        import math as _math
        import time as _time

        layers_dicts = cfg.get("layers", [])
        if not layers_dicts:
            return

        t = _time.monotonic() - getattr(self, 'effect_t0', 0)

        # Mode "une fois" : stoppe l'effet après la durée configurée
        play_mode = cfg.get("play_mode", "loop")
        if play_mode == "once":
            duration = cfg.get("duration", 0)
            if duration <= 0:
                duration = 2.0  # durée par défaut d'un cycle : 2 secondes
            if t >= duration:
                self.effect_timer.stop()  # stopper immédiatement pour éviter les appels multiples
                QTimer.singleShot(0, self._stop_once_effect)
                return
        _LETTER_TO_GROUP = {"A": "face", "B": "lat", "C": "contre",
                            "D": "douche1", "E": "douche2", "F": "douche3",
                            "G": "groupe_g", "H": "groupe_h"}
        target_letters = cfg.get("target_groups", [])
        allowed_groups = {_LETTER_TO_GROUP[l] for l in target_letters if l in _LETTER_TO_GROUP}
        # Cible « Sélection » : une couche qui vise des projos précis doit pouvoir
        # les atteindre HORS du groupe du clip (elle prime sur le groupe). Dès
        # qu'une couche est en mode Sélection, on neutralise le pré-filtre par
        # groupe du cfg → la liste = tous les projos (comme l'aperçu, qui n'a
        # jamais eu ce pré-filtre) : parité aperçu/show conservée.
        _has_selection = any(ld.get("target_preset") == "Selection" for ld in layers_dicts)
        if _has_selection:
            allowed_groups = set()
        projectors = [p for p in self.projectors
                      if p.group != "fumee" and (not allowed_groups or p.group in allowed_groups)]
        n = len(projectors)
        if n == 0:
            return

        # Clés (groupe, index_local) sur la liste COMPLÈTE (convention plan de feu)
        # + set par couche → test d'appartenance O(1). Identique à _compute_preview.
        _all_keys      = projector_selection_keys(self.projectors)
        _sel_key_by_id = {id(p): k for p, k in zip(self.projectors, _all_keys)}
        # {clé: rang} et non un set : sur une cible « Sélection », l'étalement
        # suit l'ORDRE de sélection (les pastilles 1, 2, 3… du plan de feu) et
        # non l'ordre du patch — c'est ce qui permet de diriger un chenillard.
        _layer_sel = {id(ld): layer_selection_ranks(ld) for ld in layers_dicts}

        _mh_projs = [p for p in projectors if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')]
        _mh_idx   = {id(p): j for j, p in enumerate(_mh_projs)}
        _mh_n     = max(len(_mh_projs), 1)

        # SYM : lyres qui partent en Pan miroir. Partage sur la POSITION sur le
        # plan — même règle que le bouton SYM du plan 2D et que l'aperçu de
        # l'éditeur d'effets. Auparavant c'était l'index dans l'effet, ce qui
        # donnait un miroir différent selon l'ordre du patch.
        _sym_mir = (sym_mirror_ids(_mh_projs, self.projectors)
                    if any(ld.get("sym_pan") for ld in layers_dicts) else set())

        # Même chose pour le mouvement : les lyres d'une sélection sont classées
        # entre elles dans l'ordre choisi, sinon le Pan/Tilt d'un chenillard
        # repartirait dans l'ordre du patch alors que le dimmer, lui, suivrait.
        _mh_ids = {id(p) for p in _mh_projs}
        _proj_by_key = {k: p for k, p in zip(_all_keys, self.projectors)}
        _layer_mh = {}
        for _ld in layers_dicts:
            if _ld.get("target_preset") != "Selection":
                continue
            _ranks = _layer_sel.get(id(_ld), {})
            _keys  = [k for k, _ in sorted(_ranks.items(), key=lambda kv: kv[1])]
            _sub = {}
            for _k in _keys:
                _p = _proj_by_key.get(_k)
                if _p is not None and id(_p) in _mh_ids:
                    _sub[_k] = len(_sub)
            _layer_mh[id(_ld)] = _sub

        _LETTER_TO_GROUP = {
            "A": "face", "B": "lat", "C": "contre",
            "D": "douche1", "E": "douche2", "F": "douche3",
            "G": "groupe_g", "H": "groupe_h",
        }

        # POSITION : centre de la trajectoire, par couche et par lyre. Sans elle
        # un cercle tourne autour du milieu de course (le « cercle du milieu »).
        # Résolu sur TOUTES les lyres, pas sur la liste filtrée par groupe : le
        # preset a été enregistré sur l'ensemble du rig, et son appariement de
        # secours se fait par rang — filtrer décalerait les correspondances.
        _all_lyres = [p for p in self.projectors
                      if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')]
        _pos_centers = {}
        for _ld in layers_dicts:
            if _ld.get("attribute") not in ("Pan", "Tilt", "Pan/Tilt"):
                continue
            _pr = find_position_preset(getattr(self, 'position_presets', []),
                                       _ld.get("pos_preset_idx"),
                                       _ld.get("pos_preset_name", ""))
            if _pr is not None:
                _pos_centers[id(_ld)] = position_preset_values(_pr, _all_lyres)

        def _wave(forme, x):
            if forme == "Sinus":      return (_math.sin(2 * _math.pi * x) + 1) / 2
            elif forme == "Flash":    return 1.0 if x < 0.5 else 0.0
            elif forme == "Triangle": return 1.0 - abs(2 * x - 1)
            elif forme == "Montée":   return x
            elif forme == "Descente": return 1.0 - x
            # Repli seulement : le vrai « Un par un » se calcule sur le rang
            # (voir `core.chase_slot`), pas sur x.
            elif forme == "Un par un": return 1.0 if x < 0.25 else 0.0
            elif forme == "Fixe":     return 1.0
            return 0.0

        # En mode rec lumière, l'effet ne s'applique qu'aux projecteurs allumés par les clips
        _timeline_mode = hasattr(getattr(self, 'seq', None), 'timeline_playback_row')
        # Si effect_target_groups est renseigné au niveau du clip (cfg), les groupes ciblés
        # sont considérés comme explicites même si les couches individuelles disent "Tous".
        _cfg_explicit = bool(allowed_groups)

        # Effet "sans couleur" (Pulse, Strobe, Flash…) : doit hériter de la couleur
        # assignée et suivre le fade in/out du clip sous-jacent, au lieu d'imposer
        # sa couleur (blanc) à pleine intensité.
        # _fx_clip_ids est peuplé chaque frame par les DEUX moteurs timeline
        # (preview éditeur ET lecture réelle), et n'existe pas en mode live AKAI.
        _no_color = bool(cfg.get("no_color", False))
        _clip_ids = getattr(self, '_fx_clip_ids', None)

        # Compensation ratio pan/tilt (~540°/270°) → pan à demi-amplitude pour un
        # vrai cercle. Même valeur que l'aperçu de l'éditeur d'effets (parité).
        try:
            from effect_editor import PAN_ANGULAR_RATIO as _PAN_RATIO
        except Exception:
            _PAN_RATIO = 0.5

        # Amplitude min/max PAR GROUPE (répliquée sur les couches). Si un groupe a
        # une entrée, l'intensité de ses projos est remappée dans [min, max] au
        # lieu du min_val/max_val de la couche.
        _group_amp = {}
        for _ld in layers_dicts:
            _gd = _ld.get("group_amp")
            if _gd:
                _group_amp.update(_gd)

        for i, proj in enumerate(projectors):
            _base_level = proj.level   # niveau posé par les clips, avant l'effet
            _base_color = proj.color   # couleur posée par les clips, avant l'effet
            _base_pure  = getattr(proj, 'base_color', None)  # couleur pure assignée (sans dim)
            # L'effet "suit" le clip sous-jacent si ce projo est éclairé par un clip ce frame
            _follow = bool(_clip_ids is not None and id(proj) in _clip_ids)
            dim = 0.0; r = 0.0; g = 0.0; b = 0.0; w = 0.0; ambre = 0.0; uv = 0.0
            has_dim = False; has_rgb_layer = False; has_w = False; has_ambre = False; has_uv = False
            _explicitly_targeted = _cfg_explicit  # ciblage explicite par groupe/pair/impair

            for ld in layers_dicts:
                preset = ld.get("target_preset", "Tous")
                groups = ld.get("target_groups", [])
                # Index d'étalement : par défaut la place dans le patch, mais sur
                # une cible « Sélection » la place dans la SÉLECTION (pastilles
                # 1, 2, 3… du plan) — c'est ce qui rend le chenillard dirigeable.
                i_fx, n_fx = i, n
                _mh_i_sel  = None
                if preset == "Selection":
                    _ranks = _layer_sel.get(id(ld), {})
                    _k     = _sel_key_by_id.get(id(proj))
                    if _k not in _ranks:
                        continue
                    i_fx, n_fx = _ranks[_k], max(1, len(_ranks))
                    _mh_sub    = _layer_mh.get(id(ld), {})
                    if _k in _mh_sub:
                        _mh_i_sel = (_mh_sub[_k], max(1, len(_mh_sub)))
                elif preset == "Pair"   and i % 2 != 0: continue
                elif preset == "Impair" and i % 2 != 1: continue
                elif preset in _LETTER_TO_GROUP and getattr(proj, 'group', '') != _LETTER_TO_GROUP[preset]: continue
                if groups and getattr(proj, 'group', '') not in [_LETTER_TO_GROUP.get(g, g) for g in groups]: continue
                # Ciblage explicite → l'effet peut allumer ce projo même s'il est éteint
                if preset != "Tous" or groups:
                    _explicitly_targeted = True

                speed     = ld.get("speed", 50)
                size      = ld.get("size", 100)
                spread    = ld.get("spread", 0)
                phase     = ld.get("phase", 0) / 100.0
                fade      = ld.get("fade", 0) / 100.0
                direction = ld.get("direction", 1)
                forme     = ld.get("forme", "Sinus")
                attr      = ld.get("attribute", "Dimmer")

                effective_speed = cfg.get("speed_override", self.effect_speed)
                fader_mult = max(0.01, effective_speed / 100.0)
                freq = (0.05 + speed / 100.0 * 7.0) * fader_mult
                # 180° = distribution parfaite sur 1 cycle (permanent N/2 allumés avec Flash)
                # 0° = sync, 360° = double-tour (sous-groupes)
                sp   = spread / 180.0
                # GROUPER : replier l'index sur des paquets AVANT le calcul du
                # rang. Les fixtures d'un même paquet obtiennent alors le même
                # rang, donc la même phase, donc elles partent ensemble.
                _blk = ld.get("block", 1)
                i_rk, n_rk = block_index(i_fx, n_fx, _blk)
                # Rang de la fixture dans la répartition choisie. « Linéaire »
                # reproduit exactement l'ancien i/n : les effets existants sont
                # inchangés. Les autres modes donnent le même rang à plusieurs
                # fixtures, qui s'allument alors ensemble (miroir, pair/impair…).
                _rk = spread_rank(i_rk, n_rk, ld.get("spread_mode", "lineaire"))
                if direction == 0:
                    t_osc = abs(2 * ((freq * t) % 1.0) - 1)
                    x = (t_osc + _rk * sp + phase) % 1.0
                elif direction == -1:
                    x = (freq * t - _rk * sp + phase) % 1.0
                else:
                    x = (freq * t + _rk * sp + phase) % 1.0

                if forme == "Un par un":
                    # Chenillard exclusif : la fixture est allumée uniquement
                    # quand c'est SON tour. La position vient du rang, pas de la
                    # forme d'onde — c'est ce qui garantit un seul allumé à la
                    # fois quel que soit le DÉCALAGE (une forme classique reste
                    # allumée une fraction fixe du cycle, d'où plusieurs projos
                    # allumés en même temps).
                    raw = 1.0 if chase_slot(freq * t + phase, n_rk,
                                            direction) == i_rk else 0.0
                elif forme in ("Audio", "Aléatoire"):   # ancien nom + nouveau
                    import random as _rand
                    raw = _rand.random()
                else:
                    raw = _wave(forme, x)
                # Le FONDU rallumerait les voisins et ruinerait l'exclusivité :
                # il est sans objet sur « Un par un » (et grisé dans le tableau).
                if fade > 0 and forme != "Un par un":
                    sin_val = (_math.sin(2 * _math.pi * x) + 1) / 2
                    raw = raw * (1 - fade) + sin_val * fade
                _grp = getattr(proj, 'group', '')
                if _grp in _group_amp:
                    min_v = _group_amp[_grp][0] / 100.0
                    max_v = _group_amp[_grp][1] / 100.0
                else:
                    min_v = ld.get("min_val", 0) / 100.0
                    max_v = ld.get("max_val", 100) / 100.0
                scaled = (min_v + raw * (max_v - min_v)) * size / 100.0

                if attr in ("Dimmer", "Strobe"):
                    dim += scaled; has_dim = True
                elif attr == "R": r += scaled; has_rgb_layer = True
                elif attr == "V": g += scaled; has_rgb_layer = True
                elif attr == "B": b += scaled; has_rgb_layer = True
                elif attr == "W":     w     += scaled; has_w     = True
                elif attr == "Ambre": ambre += scaled; has_ambre = True
                elif attr == "UV":    uv    += scaled; has_uv    = True
                elif attr == "RGB":
                    has_rgb_layer = True
                    # Effet sans couleur suivant un clip : teinter par la couleur
                    # assignée (rouge…) plutôt que par color1 (blanc).
                    if _no_color and _follow and _base_pure is not None and _base_pure.lightness() > 0:
                        c1 = _base_pure
                    else:
                        c1 = QColor(ld.get("color1", "#ffffff"))
                    r += c1.redF() * scaled
                    g += c1.greenF() * scaled
                    b += c1.blueF() * scaled
                elif attr == "Permut":
                    has_rgb_layer = True
                    c1 = QColor(ld.get("color1", "#ff0000"))
                    c2 = QColor(ld.get("color2", "#0000ff"))
                    r2 = 1.0 - raw
                    amp = size / 100.0
                    r += (c1.redF()   * raw + c2.redF()   * r2) * amp
                    g += (c1.greenF() * raw + c2.greenF() * r2) * amp
                    b += (c1.blueF()  * raw + c2.blueF()  * r2) * amp
                elif attr in ("Pan", "Tilt"):
                    saved = self.effect_saved_colors.get(id(proj))
                    amplitude = (size / 100.0) * 8192
                    # Recalcul du dephasage sur l'index lyre + echelle /100 plafonnee
                    # (comme le Pan/Tilt couple) : le `x` global utilise l'index de
                    # tous les projos et /180, trop faible pour les lyres.
                    _mh_i_mv, _mh_n_mv = ((_mh_idx.get(id(proj), i), _mh_n)
                                          if _mh_i_sel is None else _mh_i_sel)
                    _mh_i_mv, _mh_n_mv = block_index(_mh_i_mv, _mh_n_mv, _blk)
                    _sp_move = min(1.0, spread / 100.0)
                    if forme in ("Audio", "Aléatoire", "Un par un"):
                        # Formes sans courbe échantillonnable : la valeur déjà
                        # calculée sert telle quelle (position par paliers).
                        raw_mv = raw
                    else:
                        if direction == 0:
                            _t_osc = abs(2 * ((freq * t) % 1.0) - 1)
                            _x_mv = (_t_osc + _mh_i_mv / _mh_n_mv * _sp_move + phase) % 1.0
                        elif direction == -1:
                            _x_mv = (freq * t - _mh_i_mv / _mh_n_mv * _sp_move + phase) % 1.0
                        else:
                            _x_mv = (freq * t + _mh_i_mv / _mh_n_mv * _sp_move + phase) % 1.0
                        raw_mv = _wave(forme, _x_mv)
                    # Centre du mouvement : la POSITION choisie prime sur l'état
                    # capturé au démarrage de l'effet, lui-même devant le milieu
                    # de course.
                    _ctr = _pos_centers.get(id(ld), {}).get(id(proj))
                    # À défaut de colonne POSITION, un clip de la piste
                    # Position impose le centre : sinon l'effet tourne autour
                    # d'une capture périmée et la lyre quitte sa position.
                    if _ctr is None:
                        _ctr = getattr(self, '_timeline_pos_centers', {}).get(id(proj))
                    if attr == "Pan":
                        center = (_ctr[0] if _ctr is not None else
                                  saved[3] if saved and len(saved) > 3 else 32768)
                        sym_pan  = ld.get("sym_pan", False)
                        pan_sign = -1 if (sym_pan and id(proj) in _sym_mir) else 1
                        proj.pan = int(max(0, min(65535, center + pan_sign * (raw_mv - 0.5) * 2 * amplitude * _PAN_RATIO)))
                    else:
                        center = (_ctr[1] if _ctr is not None else
                                  saved[4] if saved and len(saved) > 4 else 32768)
                        proj.tilt = int(max(0, min(65535, center + (raw_mv - 0.5) * 2 * amplitude)))

                elif attr == "Pan/Tilt":
                    # Forme de trajectoire couplée Pan+Tilt
                    try:
                        from effect_editor import PAN_TILT_SHAPES
                    except ImportError:
                        PAN_TILT_SHAPES = {}
                    shape_id  = ld.get("mouvement_shape", "cercle")
                    shape_def = PAN_TILT_SHAPES.get(shape_id, PAN_TILT_SHAPES.get("cercle", {}))
                    pan_cfg   = shape_def.get("pan",  ("Sinus",    0, 1.0))
                    tilt_cfg  = shape_def.get("tilt", ("Sinus",   25, 1.0))
                    pan_forme,  pan_phase_pct,  pan_mult  = pan_cfg
                    tilt_forme, tilt_phase_pct, tilt_mult = tilt_cfg
                    # size=100 -> course pleine (+/-32768). Les limites physiques de
                    # chaque lyre sont appliquees en aval via pan_min/pan_max et
                    # tilt_min/tilt_max (artnet_dmx). Avant : *8192 (plafonnait a +/-12,5%).
                    amplitude = (size / 100.0) * 32768
                    saved = self.effect_saved_colors.get(id(proj))

                    # Utiliser l'index relatif parmi les lyres pour le spread + symétrie
                    # (ou le rang dans la sélection quand la couche cible une sélection)
                    _mh_i, _mh_n_pt = ((_mh_idx.get(id(proj), i), _mh_n)
                                       if _mh_i_sel is None else _mh_i_sel)
                    _mh_i, _mh_n_pt = block_index(_mh_i, _mh_n_pt, _blk)
                    sym_pan  = ld.get("sym_pan", False)
                    pan_sign = -1 if (sym_pan and id(proj) in _sym_mir) else 1

                    # Dephasage mouvement : echelle /100 (alignee sur la preview de
                    # l'editeur), plafonnee a 1.0 = etalement parfait. Au-dela le
                    # potard ne re-enroule plus les lyres (plus de re-synchronisation).
                    _sp_move = min(1.0, spread / 100.0)

                    # SENS de la trajectoire : → avant · ← inverse (la lyre tourne
                    # dans l'autre sens) · ↔ aller-retour. Agit sur le TEMPS (sens de
                    # mouvement de la lyre). Parité avec l'aperçu de l'éditeur.
                    def _pt_time(freq, _d=direction):
                        if _d == 0:   return abs(2 * ((freq * t) % 1.0) - 1)
                        if _d == -1:  return -freq * t
                        return freq * t

                    # Centre de la trajectoire : POSITION choisie, sinon l'état
                    # capturé au démarrage, sinon le milieu de course.
                    _ctr = _pos_centers.get(id(ld), {}).get(id(proj))
                    if _ctr is None:
                        _ctr = getattr(self, '_timeline_pos_centers', {}).get(id(proj))

                    # Pan
                    if pan_forme and pan_forme != "Fixe":
                        pan_freq = (0.05 + speed * pan_mult / 100.0 * 7.0) * fader_mult
                        pan_x = (_pt_time(pan_freq) + _mh_i / _mh_n_pt * _sp_move + phase + pan_phase_pct / 100.0) % 1.0
                        pan_raw = _wave(pan_forme, pan_x)
                        c_pan = (_ctr[0] if _ctr is not None else
                                 saved[3] if saved and len(saved) > 3 else 32768)
                        proj.pan = int(max(0, min(65535, c_pan + pan_sign * (pan_raw - 0.5) * 2 * amplitude * _PAN_RATIO)))

                    # Tilt
                    if tilt_forme and tilt_forme != "Fixe":
                        tilt_freq = (0.05 + speed * tilt_mult / 100.0 * 7.0) * fader_mult
                        tilt_x = (_pt_time(tilt_freq) + _mh_i / _mh_n_pt * _sp_move + phase + tilt_phase_pct / 100.0) % 1.0
                        tilt_raw = _wave(tilt_forme, tilt_x)
                        c_tilt = (_ctr[1] if _ctr is not None else
                                  saved[4] if saved and len(saved) > 4 else 32768)
                        proj.tilt = int(max(0, min(65535, c_tilt + (tilt_raw - 0.5) * 2 * amplitude)))

                elif attr == "Zoom":
                    proj.zoom = int(max(0, min(255, scaled * 255)))
                elif attr == "Gobo":
                    n_gobos = 8
                    proj.gobo = int(scaled * (n_gobos - 1)) * 32
                elif attr == "ColorWheel":
                    slots = getattr(proj, 'color_wheel_slots', [])
                    if slots:
                        slot_idx = int(scaled * (len(slots) - 1))
                        proj.color_wheel = slots[max(0, min(len(slots) - 1, slot_idx))]["dmx"]
                    else:
                        proj.color_wheel = int(scaled * 255)

            # Option A — effet DÉCOUPLÉ des blocs couleur : il tourne sur toute la
            # durée de SON clip, quel que soit le niveau des clips couleur en dessous.
            # (Avant : on sautait les projos éteints `_base_level == 0`, ce qui faisait
            #  décrocher l'effet aux coutures/fondus des blocs couleur — « l'effet
            #  s'arrête » quand il chevauche plusieurs blocs.)

            # Aucune couche lumière n'a produit de signal → laisser niveau/couleur inchangés
            # (les layers Pan/Tilt ont déjà agi directement pendant la boucle)
            # has_uv/has_w/has_ambre comptent comme un signal lumière : sans eux,
            # une couche UV (ou Blanc, ou Ambre) en cible « Tous » sortait ici et
            # n'atteignait jamais la ligne qui pose le canal → l'effet marchait en
            # live AKAI mais restait mort en REC Lumière.
            if (_timeline_mode and not has_dim and not has_rgb_layer
                    and not has_uv and not has_w and not has_ambre
                    and not _explicitly_targeted):
                continue

            level = min(1.0, dim) if has_dim else 1.0
            # L'effet contrôle la luminosité indépendamment du fader :
            # on force proj.level=100 et on encode toute la brillance dans proj.color
            bv = level
            # Option A — l'effet contrôle sa PROPRE brillance et ne suit plus le fade
            # du clip couleur en dessous (sinon il s'éteignait avec lui aux jointures
            # de blocs). Découplage total. `_follow` reste utilisé plus haut uniquement
            # pour l'héritage de couleur des effets « sans couleur ».

            has_color_val = r > 0 or g > 0 or b > 0
            if has_color_val or has_rgb_layer:
                proj.level = 100  # ouvre le dimmer DMX pour laisser passer l'effet
            if has_color_val:
                cr = min(255, int(r * 255))
                cg = min(255, int(g * 255))
                cb = min(255, int(b * 255))
                proj.color = QColor(int(cr * bv), int(cg * bv), int(cb * bv))
                self._update_color_wheel(proj, proj.color)
            elif has_rgb_layer:
                proj.color = QColor(0, 0, 0)
                self._update_color_wheel(proj, proj.color)
            elif has_dim:
                # Dimmer seul : oscille le canal Dim directement
                # Utiliser base_color (couleur stable) et non proj.color (déjà modifié
                # par le frame précédent) pour éviter la boucle de feedback vers le noir.
                proj.level = int(bv * 100)
                _stable = getattr(proj, 'base_color', None) or _base_color
                proj.color = QColor(
                    int(_stable.red()   * bv),
                    int(_stable.green() * bv),
                    int(_stable.blue()  * bv),
                )
            if has_w:
                proj.white_boost = int(min(255, w * 255))
            if has_ambre:
                proj.amber_boost = int(min(255, ambre * 255))
            if has_uv:
                proj.uv = int(min(255, uv * 255))
            # Canal dédié SEUL (UV / Blanc / Ambre sans couche couleur ni dimmer) :
            # ouvrir le master de la fixture, sinon la LED dédiée reste éteinte —
            # dans le moteur DMX, Dim vaut proj.level, remis à 0 chaque image par
            # les deux moteurs timeline.
            if (has_uv or has_w or has_ambre) and not (has_color_val or has_rgb_layer or has_dim):
                proj.level = 100

    def _update_effect_from_config(self, cfg: dict):
        """Exécute l'algorithme paramétré depuis une config éditeur."""
        import math as _math

        etype      = cfg.get("type", "Pulse")
        # Fader FX : contrôle direct de la vitesse (0=lent, 100=rapide)
        fader = self.effect_speed  # 0-100
        # sf : 0 = lent (sf=1.0) → 100 = rapide (sf=0.05), identique à update_effect
        sf_fader = max(0.05, 1.0 - (fader / 100.0) * 0.95)
        speed_raw  = cfg.get("speed", 50)
        target     = cfg.get("target", "all")
        color_mode = cfg.get("color_mode", "base")
        custom_hex = cfg.get("custom_color", "#ffffff")

        sf = sf_fader  # vitesse contrôlée par le fader FX

        def resolve(p, idx):
            if color_mode == "white":  return QColor(255, 255, 255)
            if color_mode == "black":  return QColor(0, 0, 0)
            if color_mode == "custom": return QColor(custom_hex)
            if color_mode == "fire":
                return random.choice([QColor(255,50,0), QColor(255,100,0),
                                      QColor(255,150,0), QColor(255,200,0)])
            if color_mode == "rainbow":
                return QColor.fromHsv((getattr(self,"effect_hue",0) + idx*30)%360, 255, 255)
            return p.base_color  # "base"

        # Ciblage par groupes (lettres AKAI A–H) défini au niveau config (fenêtre EXT)
        _LETTER_TO_GROUP = {"A": "face", "B": "lat", "C": "contre",
                            "D": "douche1", "E": "douche2", "F": "douche3",
                            "G": "groupe_g", "H": "groupe_h"}
        _allowed = {_LETTER_TO_GROUP[l] for l in cfg.get("target_groups", []) if l in _LETTER_TO_GROUP}
        base_all = [p for p in self.projectors
                    if p.group != "fumee" and p.level > 0 and (not _allowed or p.group in _allowed)]
        if target == "even":
            active = [p for i, p in enumerate(base_all) if i % 2 == 0]
        elif target == "odd":
            active = [p for i, p in enumerate(base_all) if i % 2 == 1]
        elif target == "rl":
            active = list(reversed(base_all))
        else:
            active = base_all

        black = QColor(0, 0, 0)

        if etype in ("Strobe", "Flash"):
            interval = max(25, int(500 - (fader / 100.0) * 475))
            self.effect_timer.setInterval(interval)
            if target == "alternate":
                phase = self.effect_state % 2
                for i, p in enumerate(base_all):
                    c = resolve(p, i)
                    bv = p.level / 100.0
                    if i % 2 == phase:
                        p.color = QColor(int(c.red()*bv), int(c.green()*bv), int(c.blue()*bv))
                    else:
                        p.color = black
            else:
                on = self.effect_state % 2 == 0
                for i, p in enumerate(active):
                    c = resolve(p, i)
                    bv = p.level / 100.0
                    p.color = QColor(int(c.red()*bv), int(c.green()*bv), int(c.blue()*bv)) if on else black
            self.effect_state += 1

        elif etype == "Pulse":
            for i, p in enumerate(active):
                if target == "alternate":
                    b = (self.effect_brightness if i % 2 == 0 else 100 - self.effect_brightness) / 100.0
                else:
                    b = self.effect_brightness / 100.0
                c = resolve(p, i)
                bv = (p.level / 100.0) * b
                p.color = QColor(int(c.red()*bv), int(c.green()*bv), int(c.blue()*bv))
            step = 2 + int(fader / 20)
            self.effect_brightness += self.effect_direction * step
            if self.effect_brightness >= 100: self.effect_brightness, self.effect_direction = 100, -1
            if self.effect_brightness <= 0:   self.effect_brightness, self.effect_direction = 0, 1

        elif etype == "Wave":
            self.effect_timer.setInterval(int(50 * sf))
            for i, p in enumerate(active):
                phase = (self.effect_state + i * 15) % 100
                b = (p.level / 100.0) * (abs(50 - phase) / 50.0)
                c = resolve(p, i)
                p.color = QColor(int(c.red()*b), int(c.green()*b), int(c.blue()*b))
            self.effect_state += 3 + int(fader / 25)

        elif etype == "Chase":
            self.effect_timer.setInterval(max(40, int(400 * sf)))
            n = len(active)
            if n == 0: return
            pos = self.effect_state % n
            for i, p in enumerate(active):
                bv = p.level / 100.0
                c = resolve(p, i)
                if i == pos:
                    p.color = QColor(int(c.red()*bv), int(c.green()*bv), int(c.blue()*bv))
                else:
                    base_c = p.base_color
                    p.color = QColor(int(base_c.red()*bv), int(base_c.green()*bv), int(base_c.blue()*bv))
            self.effect_state += 1

        elif etype == "Comete":
            self.effect_timer.setInterval(max(30, int(300 * sf)))
            n = len(active)
            if n == 0: return
            TAIL = 4
            pos = self.effect_state % (n + TAIL)
            for i, p in enumerate(active):
                dist, bv = pos - i, p.level / 100.0
                c = resolve(p, i)
                if dist == 0:
                    p.color = QColor(255, 255, 255)
                elif 1 <= dist <= TAIL:
                    blend = (1.0 - dist / (TAIL+1)) * 0.9
                    p.color = QColor(
                        min(255, int(c.red()*bv   + (255-c.red()*bv)  *blend)),
                        min(255, int(c.green()*bv + (255-c.green()*bv)*blend)),
                        min(255, int(c.blue()*bv  + (255-c.blue()*bv) *blend)),
                    )
                else:
                    p.color = QColor(int(c.red()*bv), int(c.green()*bv), int(c.blue()*bv))
            self.effect_state += 1

        elif etype == "Etoile Filante":
            self.effect_timer.setInterval(max(25, int(70 * sf)))
            n = len(active)
            if n == 0: return
            TAIL, total = 6, n + 10
            pos = self.effect_state % total
            for i, p in enumerate(active):
                dist, bv = pos - i, p.level / 100.0
                c = resolve(p, i)
                if dist == 0:
                    p.color = QColor(255, 255, 255)
                elif 1 <= dist <= TAIL:
                    t = dist / TAIL
                    blend = (_math.sin((1.0 - t) * _math.pi / 2)) ** 1.5
                    p.color = QColor(
                        min(255, int(c.red()*bv   + (255-c.red()*bv)  *blend)),
                        min(255, int(c.green()*bv + (255-c.green()*bv)*blend)),
                        min(255, int(c.blue()*bv  + (255-c.blue()*bv) *blend)),
                    )
                else:
                    p.color = QColor(int(c.red()*bv), int(c.green()*bv), int(c.blue()*bv))
            self.effect_state += 1

        elif etype == "Rainbow":
            for i, p in enumerate(active):
                hue = (self.effect_hue + i * 30) % 360
                col = QColor.fromHsv(hue, 255, 255)
                bv = p.level / 100.0
                p.color = QColor(int(col.red()*bv), int(col.green()*bv), int(col.blue()*bv))
            self.effect_hue = (getattr(self,"effect_hue",0) + int(5*(1+speed_raw/30))) % 360

        elif etype == "Fire":
            self.effect_timer.setInterval(int(60 * sf))
            fire_colors = [QColor(255,50,0), QColor(255,100,0),
                           QColor(255,150,0), QColor(255,200,0)]
            for p in active:
                base = random.choice(fire_colors)
                bv = p.level / 100.0
                p.color = QColor(int(base.red()*bv), int(base.green()*bv), int(base.blue()*bv))

        elif etype == "Bascule":
            self._bascule()
            self.active_effect_config = {}  # one-shot
            return

        # Répercuter les couleurs calculées sur la roue de couleur des lyres sans RGB
        for p in base_all:
            self._update_color_wheel(p, p.color)

    def _fader8_dispatch(self, index, value):
        """Fader 9 : contrôle de la vitesse des effets."""
        self.effect_speed = value

    def set_effect_speed(self, index, value):
        """Definit la vitesse de l'effet (conservé pour compatibilité)"""
        self.effect_speed = value

    def _update_tap_go_btn_style(self):
        """Met à jour l'apparence du bouton TAP/GO selon le mode actif."""
        btn = getattr(self, '_tap_btn', None)
        if btn is None:
            return
        if self.go_mode:
            btn.setText("▶")
            btn.setFont(QFont("Segoe UI", 7, QFont.Bold))
            btn.setToolTip(tr("mw_go_next_mem"))
            btn.setStyleSheet("""
                QToolButton {
                    background: #006633;
                    border: 2px solid #00aa55;
                    border-radius: 8px;
                    color: #00ff88;
                    font-size: 8px;
                    font-weight: bold;
                }
                QToolButton:hover {
                    background: #008844;
                    border: 2px solid #00ff88;
                }
                QToolButton:pressed {
                    background: #004422;
                    border: 2px solid #00ff88;
                }
            """)
        else:
            btn.setText("")
            btn.setToolTip(tr("tooltip_tap_tempo"))
            btn.setStyleSheet("""
                QToolButton {
                    background: #4a4a4a;
                    border: 2px solid #6a6a6a;
                    border-radius: 8px;
                }
                QToolButton:hover {
                    background: #5a5a5a;
                    border: 2px solid #aaa;
                }
                QToolButton:pressed {
                    background: #333;
                    border: 2px solid #fff;
                }
            """)

    def _go_advance(self):
        """Mode GO : avance au cue suivant si multi-cue, sinon à la prochaine mémoire."""
        # Si un pad actif multi-cue → avancer son cue
        for col_akai, row in self.active_memory_pads.items():
            mem_col = self._fader_to_mem_col(col_akai)
            mem = self.memories[mem_col][row] if mem_col is not None else None
            if mem:
                self._mem_ensure_cues(mem)
                if len(mem.get("cues", [])) > 1:
                    self._mem_advance_cue(mem_col, row)
                    fader_val = self.faders[col_akai].value if col_akai in self.faders else 0
                    self._apply_memory_to_projectors(mem_col, row, fader_value=fader_val)
                    cue_idx = self._mem_cue_idx.get((mem_col, row), 0)
                    n = len(mem["cues"])
                    lbl = mem["cues"][cue_idx].get("label", f"Cue {cue_idx+1}")
                    self._log_message(f"▶  {lbl}  ({cue_idx+1}/{n})", "mem")
                    self._style_memory_pad(mem_col, row, active=True)
                    return
        if self._go_col == -1:
            next_col, next_row = 0, 0
        else:
            next_row = self._go_row + 1
            next_col = self._go_col
            if next_row > 7:
                next_row = 0
                next_col = self._go_col + 1
            if next_col > 7:
                next_col, next_row = 0, 0

        if self.memories[next_col][next_row] is None:
            msg = tr("go_empty_mem").format(col=next_col + 1, row=next_row + 1)
            self._show_error_toast(msg)
            return

        self.trigger_memory(next_col, next_row)
        self._go_col = next_col
        self._go_row = next_row

        btn = getattr(self, '_tap_btn', None)
        if btn:
            btn.setStyleSheet("""
                QToolButton {
                    background: #00aa55;
                    border: 2px solid #00ff88;
                    border-radius: 8px;
                    color: #fff;
                    font-size: 8px;
                    font-weight: bold;
                }
            """)
            QTimer.singleShot(150, self._update_tap_go_btn_style)

        self._show_mem_toast(f"▶  MEM {next_col + 1}.{next_row + 1}")

    def _go_back(self):
        """Mode GO : recule au cue précédent si multi-cue, sinon à la mémoire précédente."""
        for col_akai, row in self.active_memory_pads.items():
            mem_col = self._fader_to_mem_col(col_akai)
            mem = self.memories[mem_col][row] if mem_col is not None else None
            if mem:
                self._mem_ensure_cues(mem)
                if len(mem.get("cues", [])) > 1:
                    self._mem_go_back_cue(mem_col, row)
                    fader_val = self.faders[col_akai].value if col_akai in self.faders else 0
                    self._apply_memory_to_projectors(mem_col, row, fader_value=fader_val)
                    cue_idx = self._mem_cue_idx.get((mem_col, row), 0)
                    n = len(mem["cues"])
                    lbl = mem["cues"][cue_idx].get("label", f"Cue {cue_idx+1}")
                    self._log_message(f"◀  {lbl}  ({cue_idx+1}/{n})", "mem")
                    self._style_memory_pad(mem_col, row, active=True)
                    return
        if self._go_col == -1:
            # Pas encore démarré → aller à la dernière mémoire disponible
            next_col, next_row = 7, 7
            while next_col >= 0 and self.memories[next_col][next_row] is None:
                next_row -= 1
                if next_row < 0:
                    next_row = 7
                    next_col -= 1
            if next_col < 0:
                return
        else:
            next_row = self._go_row - 1
            next_col = self._go_col
            if next_row < 0:
                next_row = 7
                next_col = self._go_col - 1
            if next_col < 0:
                # Début → retour à la fin
                next_col, next_row = 7, 7

        if self.memories[next_col][next_row] is None:
            msg = tr("go_empty_mem").format(col=next_col + 1, row=next_row + 1)
            self._show_error_toast(msg)
            return

        self.trigger_memory(next_col, next_row)
        self._go_col = next_col
        self._go_row = next_row

        self._show_mem_toast(f"◀  MEM {next_col + 1}.{next_row + 1}")

    def _tap_tempo(self):
        """Calcule le BPM à partir des taps et règle le fader vitesse FX."""
        if self.go_mode:
            self._go_advance()
            return

        now = time.monotonic()
        # Supprimer les taps trop anciens (> 3 secondes sans tap = reset)
        self._tap_times = [t for t in self._tap_times if now - t < 3.0]
        self._tap_times.append(now)

        # Feedback visuel rapide sur le bouton
        if self._tap_btn:
            self._tap_btn.setStyleSheet(
                "QPushButton { background: #555; color: #fff; border: 1px solid #aaa; "
                "border-radius: 3px; font-size: 8px; font-weight: bold; }"
            )
            QTimer.singleShot(120, lambda: self._tap_btn.setStyleSheet(
                "QPushButton { background: #1e1e1e; color: #888; border: 1px solid #3a3a3a; "
                "border-radius: 3px; font-size: 8px; font-weight: bold; } "
                "QPushButton:pressed { background: #333; color: #fff; border-color: #aaa; }"
            ) if self._tap_btn else None)

        # Besoin d'au moins 2 taps pour calculer
        if len(self._tap_times) < 2:
            return

        # Moyenne des intervalles sur les 4 derniers taps maximum
        taps = self._tap_times[-5:]
        intervals = [taps[i+1] - taps[i] for i in range(len(taps) - 1)]
        avg_interval_s = sum(intervals) / len(intervals)
        bpm = 60.0 / avg_interval_s

        # BPM → fader 0-100 (60 BPM = 0, 300 BPM = 100)
        speed = int(max(0, min(100, (bpm - 60) / (300 - 60) * 100)))
        self.effect_speed = speed
        if 8 in self.faders:
            self.faders[8].set_value(speed)

        # Afficher le BPM détecté via un toast éphémère
        self._show_bpm_toast(int(bpm))

    def set_master_level(self, index, value):
        """Définit le niveau master général (0-100) et recompute les couleurs de sortie."""
        self.master_level = value
        factor = value / 100.0
        for p in self.projectors:
            if p.level > 0:
                lvl = p.level / 100.0
                p.color = QColor(
                    int(p.base_color.red()   * lvl * factor),
                    int(p.base_color.green() * lvl * factor),
                    int(p.base_color.blue()  * lvl * factor),
                )
            else:
                p.color = QColor("black")
        self.send_dmx_update()

    def _update_status_corner(self):
        """Rafraîchit le corner widget audio meter à chaque tick DMX (40 ms)."""
        if not hasattr(self, '_status_corner'):
            return
        try:
            import math, random as _rnd
            main_playing = self.player.playbackState()      == QMediaPlayer.PlayingState
            cart_playing = self.cart_player.playbackState() == QMediaPlayer.PlayingState
            playing = main_playing or cart_playing

            if not playing or getattr(self, 'blackout_active', False):
                self._status_corner.set_audio(0.0, False)
                return

            if main_playing:
                position = self.player.position()
                analyzed = self.audio_ai.analyzed and self.player.duration() > 0
            else:
                position = self.cart_player.position()
                analyzed = False

            if analyzed:
                level = float(self.audio_ai.get_energy_at(position))
            else:
                # Simulation punchy : basses + mids + transitoires aléatoires
                t = position / 1000.0
                bass  = 0.45 * abs(math.sin(t * 1.9))
                mid   = 0.25 * abs(math.sin(t * 4.7 + 0.8))
                hi    = 0.15 * abs(math.sin(t * 13.1 + 2.3))
                noise = _rnd.uniform(0.0, 0.15)
                level = min(0.97, bass + mid + hi + noise)

            # Pondéré par le fader master DMX
            level *= self.master_level / 100.0
            self._status_corner.set_audio(level, playing)
        except Exception:
            pass

    def activate_default_white_pads(self, group_rows=None):
        """Active un pad par colonne groupe (pur affichage : surbrillance + LED, ne pilote
        jamais les projecteurs). Par défaut = pad blanc (row 0). Si `group_rows` = {col: row}
        est fourni, c'est CE pad qui est mis en surbrillance (reflet de la couleur courante)."""
        def _active_row(col):
            if group_rows and col in group_rows:
                try:
                    return max(0, min(7, int(group_rows[col])))
                except (ValueError, TypeError):
                    return 0
            return 0

        for col, slot in enumerate(self._fader_map):
            if slot["type"] == "group":
                arow = _active_row(col)
                pad = self.pads.get((arow, col)) or self.pads.get((0, col))
                if pad:
                    color = pad.property("base_color")
                    pad.setStyleSheet(f"QPushButton {{ background: {color.name()}; border: 2px solid {color.lighter(130).name()}; border-radius: 4px; }}")
                    self.active_pads[col] = pad

        if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
            for row in range(8):
                for col in range(8):
                    pad = self.pads.get((row, col))
                    if pad:
                        slot = self._fader_map[col]
                        if slot["type"] == "group":
                            base_color = pad.property("base_color")
                            velocity = rgb_to_akai_velocity(base_color)
                            brightness = self.akai_active_brightness if row == _active_row(col) else self.akai_inactive_brightness
                            # Passe par set_pad_led → gère APC (0x90/0x96) ET Launchpad MK3 (RGB)
                            self.midi_handler.set_pad_led(row, col, velocity, brightness_percent=brightness)
                        elif slot.get("type") == "fx":
                            fx_col = slot.get("fx_col", 0)
                            cfg = self.fx_pads[fx_col][row] if 0 <= fx_col < _FX_COL_MAX else None
                            is_active = self.active_fx_pads.get((fx_col, row))
                            if is_active and cfg:
                                self.midi_handler.set_pad_led(row, col, 21, brightness_percent=self.akai_active_brightness)
                            elif cfg:
                                self.midi_handler.set_pad_led(row, col, 21, brightness_percent=self.akai_inactive_brightness)
                            else:
                                self.midi_handler.set_pad_led(row, col, 0, brightness_percent=0)
                        elif slot.get("type") == "memory":
                            mem_col = slot.get("mem_col", 0)
                            is_active = self.active_memory_pads.get(col) == row
                            self._update_memory_pad_led(mem_col, row, active=is_active)
                        elif slot.get("type") == "pos":
                            pos_col = slot.get("pos_col", 0)
                            self._update_pos_pad_led(pos_col, row)

    def _clear_akai_state(self):
        """Remet l'AKAI à zéro : faders 0-7 à 0 + pads blancs activés."""
        def _is_play(idx):
            return idx < len(self._fader_map) and self._fader_map[idx].get("type") == "play"
        # Faders à 0 — SAUF la colonne PLAY (volume) : le clear ne doit jamais
        # couper le son (piège ergonomique).
        for idx in range(8):
            if _is_play(idx):
                continue
            if idx in self.faders:
                self.faders[idx].value = 0
                self.faders[idx].update()
            self.set_proj_level(idx, 0)

        # MIDI faders à 0
        if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
            for idx in range(8):
                if _is_play(idx):
                    continue
                self.midi_handler.midi_out.send_message([0xB0, idx, 0])

        # Désactiver les pads actifs sur les colonnes groupe
        for col, pad in list(self.active_pads.items()):
            slot = self._fader_map[col] if col < len(self._fader_map) else None
            if slot and slot["type"] == "group":
                old_color = pad.property("base_color")
                dim_color = QColor(int(old_color.red() * 0.5), int(old_color.green() * 0.5), int(old_color.blue() * 0.5))
                pad.setStyleSheet(f"QPushButton {{ background: {dim_color.name()}; border: 1px solid #2a2a2a; border-radius: 4px; }}")
        self.active_pads.clear()

        # Activer les pads blancs (row 0)
        self.activate_default_white_pads()

        # Couper tous les effets (y compris empilés)
        if hasattr(self, 'effect_timer'):
            self.effect_timer.stop()
        self._stacked_effects = []
        self.active_effect = None
        self.active_effect_config = {}
        self.effect_saved_colors = {}
        for btn in self.effect_buttons:
            if btn.active:
                btn.active = False
                btn.update_style()

        # Effets du plan de feu 2D — SECOND moteur, avec son propre timer.
        # Sans ça un effet lancé par clic droit (strobe, chenillard, pan/tilt)
        # continuait d'écrire sur les projecteurs 25 fois par seconde : CLEAR
        # semblait sans effet et seul un redémarrage rendait la main.
        _pdf = getattr(self, 'plan_de_feu', None)
        if _pdf is not None:
            try:
                if hasattr(_pdf, 'stop_led_effect'):
                    _pdf.stop_led_effect(list(self.projectors))
                if hasattr(_pdf, 'stop_effect'):
                    _pdf.stop_effect(list(self.projectors))
            except Exception as _e:
                print(f"[CLEAR] arrêt des effets du plan de feu impossible : {_e}")

        # Éteindre complètement tous les projecteurs
        for p in self.projectors:
            if p.group != "fumee":
                p.level      = 0
                p.color      = QColor(0, 0, 0)
                p.base_color = QColor(0, 0, 0)
                p.shutter    = 255

        # Désactiver tous les pads FX actifs + mettre à jour visuel et LEDs physiques
        self.active_fx_pads.clear()
        mapped_fx_cols = {slot.get("fx_col") for slot in self._fader_map if slot.get("type") == "fx"}
        for fc in mapped_fx_cols:
            for r in range(8):
                self._style_fx_pad(fc, r)
                self._update_fx_pad_led(fc, r)

        # Remettre à zéro les canaux spéciaux et moving head.
        # Liste alignée sur le reset canonique du plan de feu (_clear_targets) :
        # tout ce que le plan de feu 2D peut envoyer doit revenir au repos, y
        # compris strobe_speed (sinon le strobe reste actif après CLEAR), les
        # rotations gobo/prism, les effets bruts et les canaux extras.
        for p in self.projectors:
            p.uv           = 0
            p.white_boost  = 0
            p.amber_boost  = 0
            p.orange_boost = 0
            p.strobe_speed = 0
            p.pan          = 32768
            p.tilt         = 32768
            p.gobo         = 0
            p.gobo_rotation = 0
            p.zoom         = 0
            p.shutter      = 255
            p.color_wheel  = 0
            p.prism        = 0
            p.prism_rotation = 0
            p.effects      = 0
            p.channel_extras = {}

        # Remettre tous les mutes à zéro + éteindre LEDs physiques
        for idx in list(self._muted_faders):
            if 0 <= idx < len(self.fader_buttons):
                self.fader_buttons[idx].active = False
                self.fader_buttons[idx].update_style()
            if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
                self.midi_handler.midi_out.send_message([0x90, 100 + idx, 0])
        self._muted_faders.clear()

        # Remettre tous les cues actifs au premier cue
        for (mc, r) in list(self._mem_cue_idx.keys()):
            self._mem_cue_idx[(mc, r)] = 0
        self._dur_timer.stop()
        self._dur_progress_timer.stop()
        if hasattr(self, "_cue_panel"):
            self._cue_panel.set_progress(-1)
            mc, r = self._cue_panel.mem_col, self._cue_panel.row
            if mc >= 0:
                self._cue_panel.highlight_cue(0)

        self._log_message("CLEAR — AKAI remis à zéro", "info")

    def _init_default_fx_speed(self):
        """Initialise le fader FX à 80% au démarrage."""
        self.effect_speed = 80
        if 8 in self.faders:
            self.faders[8].set_value(80)

    def turn_off_all_effects(self):
        """Eteint tous les effets au demarrage"""
        for btn in self.effect_buttons:
            btn.active = False
            btn.update_style()

        # Vider la pile de superposition et arrêter le timer
        self._stacked_effects = []
        if hasattr(self, 'effect_timer'):
            self.effect_timer.stop()
        self.active_effect = None
        self.active_effect_config = {}

        # Désactiver les pads FX + LEDs physiques
        self.active_fx_pads.clear()
        mapped_fx_cols = {slot.get("fx_col") for slot in self._fader_map if slot.get("type") == "fx"}
        for fc in mapped_fx_cols:
            for r in range(8):
                self._style_fx_pad(fc, r)
                self._update_fx_pad_led(fc, r)

        if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
            for i in range(8):
                note = 112 + i
                self.midi_handler.midi_out.send_message([0x90, note, 0])

    def show_ia_color_dialog(self):
        """Dialogue de selection de couleur dominante pour IA Lumiere"""
        dialog = QDialog(self)
        dialog.setWindowTitle(tr("mw_ai_light"))
        dialog.setFixedSize(420, 220)
        dialog.setStyleSheet("""
            QDialog { background: #1a1a1a; }
            QLabel { color: white; border: none; }
        """)

        layout = QVBoxLayout(dialog)
        layout.setContentsMargins(20, 15, 20, 15)
        layout.setSpacing(12)

        title = QLabel(tr("mw_pick_dominant"))
        title.setStyleSheet("font-size: 15px; font-weight: bold;")
        title.setAlignment(Qt.AlignCenter)
        layout.addWidget(title)

        colors_layout = QGridLayout()
        colors_layout.setSpacing(8)

        colors = [
            ("Rouge", QColor("#ff0000")),
            ("Bleu", QColor("#0066ff")),
            ("Vert", QColor("#00ff00")),
            ("Jaune", QColor("#ffdd00")),
            ("Violet", QColor("#aa00ff")),
            ("Orange", QColor("#ff8800")),
            ("Cyan", QColor("#00ddff")),
            ("Rose", QColor("#ff00aa")),
        ]

        selected_color = [None]

        for i, (name, color) in enumerate(colors):
            btn = QPushButton(name)
            btn.setFixedSize(90, 50)
            text_color = "black" if color.lightness() > 128 else "white"
            btn.setStyleSheet(f"""
                QPushButton {{
                    background: {color.name()};
                    color: {text_color};
                    border: 2px solid #3a3a3a;
                    border-radius: 8px;
                    font-weight: bold;
                    font-size: 12px;
                }}
                QPushButton:hover {{ border: 3px solid white; }}
            """)
            btn.clicked.connect(lambda _, c=color: (selected_color.__setitem__(0, c), dialog.accept()))
            colors_layout.addWidget(btn, i // 4, i % 4)

        layout.addLayout(colors_layout)

        cancel_btn = QPushButton(tr("mw_cancel"))
        cancel_btn.setStyleSheet("""
            QPushButton {
                background: #3a3a3a; color: white; border: none;
                border-radius: 6px; padding: 8px 20px;
            }
            QPushButton:hover { background: #4a4a4a; }
        """)
        cancel_btn.clicked.connect(dialog.reject)
        layout.addWidget(cancel_btn, alignment=Qt.AlignCenter)

        if dialog.exec() == QDialog.Accepted:
            return selected_color[0]
        return None

    def _get_live_lyre_positions(self):
        """Retourne [(pan 0-255, tilt 0-255)] pour chaque lyre (Moving Head)."""
        return [(p.pan // 257, p.tilt // 257)
                for p in self.projectors
                if getattr(p, 'fixture_type', '') == "Moving Head"]

    def _on_live_luminosity_changed(self, value: int):
        """Applique la luminosité globale aux projecteurs autorisés par le live panel."""
        lumi = value / 100.0
        allowed = getattr(self.seq.live_panel, '_live_config', {}).get('allowed_groups', set())
        for proj in self.projectors:
            if not allowed or proj.group in allowed:
                proj.level = int(proj.level * lumi) if lumi < 1.0 else proj.level
        self._live_luminosity = lumi

    def _on_live_source_changed(self, key: str):
        """Redémarre le moteur audio avec la nouvelle source si le live est actif."""
        if not self.seq.live_mode_active:
            return
        # Slot Qt : une exception ici terminerait l'application (comportement
        # PySide6). On protège le changement de source pour que l'échec d'un
        # micro n'entraîne au pire qu'une source inactive, jamais un crash.
        try:
            panel = self.seq.live_panel
            self.live_engine.stop()
            self.live_engine.start(
                source_key=key,
                dominant_color=panel.dominant_color,
                nervosity=panel.nerv_slider.value(),
                sensitivity=panel.sens_slider.value(),
            )
            self.live_engine.update_dimmers(panel.dimmer_values)
        except Exception as e:
            print(f"[Live] changement de source échoué ({key}) : {e}")

    def _on_live_settings_applied(self, cfg: dict):
        """Réinitialise les états persistants des lyres quand les presets changent."""
        self.__dict__.pop('_live_preset_state', None)

    def _update_video_frame_visibility(self, vue=None):
        """Affiche l'apercu video seulement quand il a un sens.

        Deux conditions le masquent :
          - le mode LIVE (pas de media joue, et ca libere de la place) ;
          - la vue centrale « aucun panneau », ou le sequenceur dont la video
            est l'apercu n'est plus affiche du tout.

        Regle UNIQUE et non deux `setVisible` concurrents : sinon la sortie du
        mode LIVE reafficherait la video alors qu'on est en « aucun panneau ».
        """
        if not hasattr(self, 'video_frame'):
            return
        if vue is None:
            vue = getattr(self, '_center_view_key', 'media')
        en_live = bool(getattr(getattr(self, 'seq', None), 'live_mode_active', False))
        visible = (not en_live) and vue != 'none'
        self.video_frame.setVisible(visible)
        # Le bas du color picker tapait dans le splitter quand la video est
        # masquee. La marge suivait « mode live » ; elle suit desormais la
        # VIDEO, qui est la vraie cause — donc aussi en « aucun panneau ».
        bloc = getattr(self, 'color_picker_block', None)
        if bloc is not None and bloc.layout() is not None:
            bloc.layout().setContentsMargins(12, 8, 12, 8 if visible else 20)

    def set_center_view(self, key: str):
        """Change ce qu'affiche la colonne centrale (menu Affichage).

        « media » et « live » sont les deux pages du séquenceur : on pilote son
        bouton LIVE, qui reste la seule source de vérité du mode (les gardes sur
        seq.live_mode_active en dépendent) et qui cache le transport tout seul
        via _on_live_toggle. « none » cache la colonne pour rendre la place à
        l'AKAI et au plan de feu.
        """
        # Mémorisé pour être restauré au prochain lancement (_akai_config)
        self._center_view_key = key

        # La video est l'apercu du LECTEUR MEDIA : sans le sequenceur affiche,
        # elle n'a plus de contexte, et elle mangeait la hauteur du plan de feu.
        self._update_video_frame_visibility(key)

        if key != "pads":
            self._release_pads_surface()

        if key == "none":
            self._center_stack.setVisible(False)
        elif key == "pads":
            self._center_stack.setVisible(True)
            self._embed_pads_surface()
        else:
            self._center_stack.setVisible(True)
            self._center_stack.setCurrentIndex(0)
            want_live = (key == "live")
            if self.seq.live_btn.isChecked() != want_live:
                # setChecked déclenche `toggled` (moteur + transport) mais pas
                # `clicked` : _toggle_live (page interne + style) reste à appeler.
                self.seq.live_btn.setChecked(want_live)
                self.seq._toggle_live(want_live)
        act = self._view_actions.get(key)
        if act:
            act.setChecked(True)

    def _restore_center_view(self, key):
        """
        Réapplique la vue centrale sauvegardée, au démarrage.

        Protégé : la config peut venir d'une version où la vue n'existe plus, et
        une exception ici empêcherait l'appli de finir de démarrer.
        """
        try:
            if getattr(self, '_center_stack', None) is None:
                return
            self.set_center_view(key)
        except Exception as e:
            print(f"[view] restauration de la vue centrale '{key}' impossible : {e}")

    def _embed_pads_surface(self):
        """Déplace la surface Pads de sa fenêtre flottante vers la colonne centrale.

        Un widget Qt n'a qu'un seul parent : la surface ne peut pas être aux deux
        endroits à la fois. On déplace donc l'unique exemplaire au lieu d'en créer
        un second — ça garde un seul writer sur l'état des blocs (et un seul
        _state_timer), et évite que deux surfaces se disputent ~/.mystrow_ext.json.
        """
        if getattr(self, "_pads_surface", None) is not None:
            self._center_stack.setCurrentWidget(self._pads_scroll)
            return
        win = self._ensure_ext_window()
        if win.isVisible():
            win.hide()
        if hasattr(self, "_ext_btn"):
            self._ext_btn.setChecked(False)
        surface = win.takeCentralWidget()
        if surface is None:
            return
        self._pads_surface = surface
        # Le passage par QScrollArea retourne autoFillBackground sur la surface,
        # et takeWidget() ne le remet pas : sans ça elle revient dans sa fenêtre
        # en peignant sa palette (claire) par-dessus le noir. On mémorise pour
        # restaurer à l'identique.
        self._pads_autofill = surface.autoFillBackground()

        # La colonne centrale est plus étroite que la fenêtre PADS (conçue pour
        # 1240 px) : sans ça les blocs de droite sont rognés et inatteignables.
        # On empêche le canvas de descendre sous son contenu et on rend le tout
        # défilant — uniquement ici, la fenêtre flottante garde son comportement.
        canvas = getattr(win, "canvas", None)
        if canvas is not None:
            cw, ch = canvas.content_size()
            canvas.setMinimumSize(max(400, cw), max(300, ch))

        self._pads_scroll = QScrollArea()
        self._pads_scroll.setWidgetResizable(True)
        # Le fond doit être imposé par feuille de style, pas par palette : la
        # règle globale `QWidget { color: #ddd; }` de la fenêtre matche tous les
        # widgets, donc Qt les considère « stylés » et ignore autoFillBackground.
        # Sans ces règles, le viewport part en blanc (le noir de MyStrow vient de
        # `QMainWindow { background: #050505; }`, que la zone défilante masque).
        self._pads_scroll.setStyleSheet(
            "QScrollArea { border: none; background: #0e0e0e; }"
            "QScrollArea > QWidget > QWidget { background: #0e0e0e; }"
        )
        self._pads_scroll.setWidget(surface)
        self._center_stack.addWidget(self._pads_scroll)
        self._center_stack.setCurrentWidget(self._pads_scroll)

    def _release_pads_surface(self):
        """Rend la surface Pads à sa fenêtre flottante."""
        surface = getattr(self, "_pads_surface", None)
        if surface is None:
            return
        # ExtWindow ne sauve son layout que dans closeEvent : embarquée, sa
        # fenêtre ne se ferme jamais, donc on sauve ici — sinon les blocs
        # déplacés en vue Pads seraient perdus.
        try:
            self._ext_window._save_layout()
        except Exception:
            pass

        # Rendre au canvas sa taille minimale d'origine, sinon la fenêtre
        # flottante hériterait de la contrainte posée pour la vue centrale.
        canvas = getattr(self._ext_window, "canvas", None)
        if canvas is not None:
            canvas.setMinimumSize(400, 300)

        self._pads_scroll.takeWidget()          # rend la propriété du widget
        self._center_stack.removeWidget(self._pads_scroll)
        self._pads_scroll.deleteLater()
        self._pads_scroll = None
        self._ext_window.setCentralWidget(surface)
        # Après setCentralWidget : la surface doit retrouver l'état exact qu'elle
        # avait avant d'être embarquée, sinon fond clair dans la fenêtre.
        surface.setAutoFillBackground(getattr(self, "_pads_autofill", False))
        self._pads_surface = None

    def _sync_view_menu(self, live_on: bool):
        """Reflète le bouton LIVE du séquenceur dans le menu Affichage."""
        if not getattr(self, "_view_actions", None):
            return
        if not getattr(self, "_center_stack", None) or not self._center_stack.isVisible():
            return
        self._view_actions["live" if live_on else "media"].setChecked(True)

    def _on_live_toggle(self, checked: bool):
        """Slot Qt — entrée/sortie du mode LIVE, protégé.

        C'était le SEUL slot du mode LIVE sans garde, alors que ses voisins en
        ont une : une exception qui remonte dans un slot Qt termine l'application
        (PySide6 appelle qFatal). Or ce slot est le plus exposé de tous — il
        touche la mise en page, le lecteur média, le moteur audio, le détecteur
        de logiciels et le panneau — et c'est justement à la sortie du live que
        des utilisateurs voyaient MyStrow se fermer tout seul.
        """
        try:
            self._on_live_toggle_inner(checked)
        except Exception as e:
            self._log_live_error('toggle', e)
            # Ne jamais laisser le moteur audio tourner derrière une UI revenue
            # au séquenceur : un échec en cours de sortie doit quand même couper.
            if not checked:
                try:
                    self.live_engine.stop()
                except Exception:
                    pass

    def _on_live_toggle_inner(self, checked: bool):
        """Démarre ou arrête le moteur audio live."""
        self.transport.setVisible(not checked)
        if not checked:
            # Forcer le transport à revenir juste sous le séquenceur
            self.transport.setMaximumHeight(16777215)
            self.transport.updateGeometry()
            self.seq.setMaximumHeight(16777215)
            self.seq.updateGeometry()
        # Visibilite de la video : regle unique, deux conditions (voir
        # _update_video_frame_visibility). Elle etait posee ici seulement,
        # donc « aucun panneau » laissait l'apercu video affiche.
        self._update_video_frame_visibility()
        if checked:
            # Mettre le media en pause si en cours de lecture
            try:
                from PySide6.QtMultimedia import QMediaPlayer as _QMP
                if self.player.playbackState() == _QMP.PlayingState:
                    self._live_was_playing = True
                    self.player.pause()
                else:
                    self._live_was_playing = False
            except Exception:
                self._live_was_playing = False
            panel = self.seq.live_panel
            self._live_ia_mode = False
            # Démarrer le détecteur de logiciels DJ
            if self.software_detector is None:
                self.software_detector = SoftwareDetector(self)
                self.software_detector.software_changed.connect(
                    panel.set_detected_software)
            else:
                self.software_detector._timer.start(2000)
                self.software_detector.force_check()
            self.live_engine.start(
                source_key=panel.source_key,
                dominant_color=panel.dominant_color,
                nervosity=panel.nerv_slider.value(),
                sensitivity=panel.sens_slider.value(),
            )
            self.live_engine.update_dimmers(panel.dimmer_values)
        else:
            self._live_ia_mode = False

            # Extinction ÉTAPE PAR ÉTAPE : chaque étape est isolée pour qu'un
            # échec (lecteur média, détecteur, widget) n'empêche pas les
            # suivantes. Avant, tout s'enchaînait à la file : une erreur au
            # milieu laissait le moteur audio en marche derrière un séquenceur
            # rendu — ou faisait tomber l'application.
            def _etape(nom, fn):
                try:
                    fn()
                except Exception as e:
                    self._log_live_error(f'sortie:{nom}', e)

            # Le moteur audio D'ABORD : c'est lui qui pilote les projecteurs à
            # 40 fps, tout le reste peut attendre une image de plus.
            _etape('moteur', self.live_engine.stop)

            def _reprendre_media():
                if getattr(self, '_live_was_playing', False):
                    self._live_was_playing = False
                    self.player.play()
            _etape('media', _reprendre_media)

            def _stop_detecteur():
                if self.software_detector is not None:
                    self.software_detector.stop()
                    self.seq.live_panel.set_detected_software("", "")
            _etape('detecteur', _stop_detecteur)

            def _reset_panneau():
                self.seq.live_panel.set_vu(0)
                self.seq.live_panel.set_status(bpm=0, section='—')
                self.seq.live_panel.set_connection_status('off')
            _etape('panneau', _reset_panneau)

            # Purger les états persistants live
            for attr in ('_live_sec', '_live_lyre_e', '_live_lyre_phase',
                         '_live_lyre_speed', '_live_lyre_amp_pan', '_live_lyre_amp_tilt',
                         '_live_lyre_last_pos', '_live_lyre_chop_until',
                         '_live_lyre_beat_idx', '_live_lyre_color_smooth',
                         '_live_transient_flash', '_live_beat_state',
                         '_live_auto_last_section', '_live_preset_state',
                         '_live_lyre_switch', '_live_lyre_color_switch', '_smart_fx',
                         '_live_col_cur_prev'):
                self.__dict__.pop(attr, None)

    def _log_live_error(self, where, exc):
        """Log throttlé d'une exception dans un slot LIVE piloté par le thread
        audio. Une exception non rattrapée dans ces slots fait crasher MyStrow
        (PySide6 abort) : on logge au lieu de crasher. On ne réémet un message
        que si le texte d'erreur change."""
        try:
            key = f"{where}:{type(exc).__name__}:{exc}"
            if getattr(self, '_last_live_error', None) != key:
                self._last_live_error = key
                import traceback
                print(f"[live:{where}] {type(exc).__name__}: {exc}")
                traceback.print_exc()
        except Exception:
            pass

    def _on_live_transient(self, hit_type: str):
        """Slot signal (thread audio) protégé — voir _log_live_error."""
        try:
            self._on_live_transient_inner(hit_type)
        except Exception as e:
            self._log_live_error('transient', e)

    def _on_live_transient_inner(self, hit_type: str):
        """Transitoire audio → effets lumière immédiats (FFT band, plus fiable que RMS)."""
        if not self.seq.live_mode_active:
            return
        if self.seq.live_panel.ia_mode in ('manuel', 'ambiance'):
            return
        if not hasattr(self, '_live_transient_flash'):
            self._live_transient_flash = {}
        if not hasattr(self, '_live_beat_state'):
            self._live_beat_state = {'beat_idx': -1, 'flash_until': 0,
                                     'strobe_until': 0, 'gobo_idx': 0}
        pos   = self.live_engine._elapsed_ms
        bs    = self._live_beat_state
        panel = self.seq.live_panel

        if hit_type == 'kick':
            self._live_transient_flash['contre_until'] = pos + 70
            # Le kick FFT est le beat le plus fiable — l'utiliser pour tout
            panel.flash_beat()
            auto = panel.is_tile_active('auto')
            if panel.is_tile_active('flash') or auto:
                bs['flash_until'] = max(bs['flash_until'], pos + 105)
            if panel.is_tile_active('strobe'):
                bs['strobe_until'] = max(bs['strobe_until'], pos + 380)
            if panel.is_tile_active('gobo') or auto:
                bs['gobo_idx'] = (bs['gobo_idx'] + 1) % 8
            # ── Strobe blanc drop — déclenché dès le premier kick du drop ─────────
            _section = getattr(self.live_engine, '_section_state', 'verse')
            import time as _t
            if not hasattr(self, '_smart_fx'):
                self._smart_fx = {'last_flash_ts': 0.0, 'last_strobe_ts': 0.0,
                                  'drop_strobe_active': False}
            _sfx = self._smart_fx
            _now = _t.monotonic()

            if _section == 'drop':
                # Activer le strobe dès le premier kick du drop
                _sfx['drop_strobe_active'] = True
            else:
                # Section ≠ drop → couper immédiatement
                _sfx['drop_strobe_active'] = False

            if _section in ('drop', 'high'):
                import random as _r
                # Flash blanc doux : 22 % de chance, cooldown 1.8 s
                if _now - _sfx['last_flash_ts'] > 1.8 and _r.random() < 0.22:
                    _sfx['last_flash_ts'] = _now
                    bs['smart_flash_until'] = pos + 140
                # Strobe blanc court. Ce déclencheur MANQUAIT : `smart_strobe_until`
                # était lu à la restitution mais jamais écrit — la branche « strobe
                # intelligent » ne pouvait pas se produire, et le mode STROB LENT
                # n'avait plus que le strobe de section « build » de la tuile AUTO,
                # d'où « on ne le voit presque jamais ».
                # Plus espacé que le flash : c'est un événement, pas une pulsation.
                if _now - _sfx['last_strobe_ts'] > _SMART_STROBE_COOLDOWN_S \
                        and _r.random() < _SMART_STROBE_CHANCE:
                    _sfx['last_strobe_ts'] = _now
                    bs['smart_strobe_until'] = pos + _SMART_STROBE_MS
        elif hit_type == 'snare':
            self._live_transient_flash['face_until'] = pos + 55
            if panel.is_tile_active('strobe'):
                bs['strobe_until'] = max(bs['strobe_until'], pos + 180)
        elif hit_type == 'hihat':
            self._live_transient_flash['lyre_chop_until'] = pos + 40

    def _on_live_ia_mode_changed(self, mode: str):
        """Slot signal protégé — le basculement de mode ne doit jamais crasher."""
        try:
            self._on_live_ia_mode_changed_inner(mode)
        except Exception as e:
            self._log_live_error('ia_mode', e)

    def _on_live_ia_mode_changed_inner(self, mode: str):
        """Changement de mode IA — réinitialise les états persistants si nécessaire."""
        for attr in ('_live_sec', '_live_beat_state', '_live_transient_flash',
                     '_ambiance_phase', '_ambiance_t', '_smart_fx',
                     '_live_lyre_switch', '_ambiance_color_switch', '_ambiance_gobo_switch'):
            self.__dict__.pop(attr, None)

        if mode == 'manuel':
            # Restaurer l'état AKAI (pads actifs + faders)
            restored = False
            for fi, row in list(self.active_memory_pads.items()):
                for mc_idx, mc in self._bank_memory_slots():
                    if mc_idx == fi:
                        fader_val = self.faders[fi].value if fi in self.faders else 100
                        try:
                            self._apply_memory_to_projectors(mc, row, fader_value=fader_val,
                                                              trigger_effect=False)
                            restored = True
                        except Exception:
                            pass
                        break
            if not restored:
                # Aucun pad actif → blackout propre
                for proj in self.projectors:
                    proj.level = 0
                    proj.color = QColor(0, 0, 0)
                    proj.base_color = QColor(0, 0, 0)
                self.dmx.blackout()

    def _apply_ambiance_live(self):
        """Mode Ambiance : lumière douce + respiration lente + lyres qui tournent."""
        import math as _math
        import time as _time

        if not hasattr(self, '_ambiance_t'):
            self._ambiance_t = _time.monotonic()
        if not hasattr(self, '_ambiance_phase'):
            self._ambiance_phase = 0.0
        if not hasattr(self, '_ambiance_lyre_phase'):
            self._ambiance_lyre_phase = 0.0

        now = _time.monotonic()
        dt  = min(0.1, now - self._ambiance_t)
        self._ambiance_t = now

        # Respiration (0.18 rad/s ≈ 1 cycle/35s)
        self._ambiance_phase = (self._ambiance_phase + dt * 0.18) % (2 * _math.pi)
        # Rotation lyres (0.35 rad/s ≈ 1 cycle/18s)
        self._ambiance_lyre_phase = (self._ambiance_lyre_phase + dt * 0.35) % (2 * _math.pi)

        breath = 0.55 + 0.35 * _math.sin(self._ambiance_phase)
        base   = self.seq.live_panel.dominant_color

        # Récupérer le mouvement choisi dans l'onglet MOUVEMENT
        _mov = self.seq.live_panel.movement_pattern  # 'cercle', 'huit', 'vague'...
        _spd = self.seq.live_panel.movement_speed / 100.0
        _sz  = self.seq.live_panel.movement_size  / 100.0
        _amp_pan  = int(10000 + _sz * 12000)   # amplitude Pan  (10k–22k)
        _amp_tilt = int(6000  + _sz * 8000)    # amplitude Tilt (6k–14k)

        # Phase globale modulée par la vitesse
        _ph = self._ambiance_lyre_phase * (_spd * 1.2)

        _lyre_idx = 0
        _allowed_grps = self.seq.live_panel.allowed_groups
        for p in self.projectors:
            # Groupes restreints : l'IA n'éclaire que les groupes sélectionnés,
            # les autres sont éteints (le mode Ambiance ne filtrait pas du tout avant).
            if _allowed_grps and p.group not in _allowed_grps:
                p.level = 0
                p.color = QColor("black")
                continue
            # Couleur / niveau
            level = int(75 * breath)
            p.level = level
            p.base_color = base
            if level > 0:
                f = level / 100.0
                p.color = QColor(int(base.red() * f), int(base.green() * f),
                                 int(base.blue() * f))
            else:
                p.color = QColor("black")

            # Mouvement lyres uniquement
            if getattr(p, 'fixture_type', '') != "Moving Head":
                continue

            _offset = _lyre_idx * (_math.pi * 0.6)   # déphasage entre lyres
            _lyre_idx += 1

            if _mov == 'huit':
                _pan_v  = int(32768 + _amp_pan  * _math.sin(_ph + _offset))
                _tilt_v = int(32768 + _amp_tilt * _math.sin(2 * (_ph + _offset)))
            elif _mov in ('vague', 'diagonale'):
                _pan_v  = int(32768 + _amp_pan  * _math.sin(_ph + _offset))
                _tilt_v = int(32768 + _amp_tilt * _math.sin(_ph + _offset + _math.pi / 3))
            else:
                # cercle (défaut)
                _pan_v  = int(32768 + _amp_pan  * _math.sin(_ph + _offset))
                _tilt_v = int(32768 + _amp_tilt * _math.cos(_ph + _offset))

            p.pan  = max(0, min(65535, _pan_v))
            p.tilt = max(0, min(65535, _tilt_v))

        # ── Dimmer par groupe (onglet DIMMER) ─────────────────────────────────
        _dv = self.seq.live_panel.dimmer_values
        if _dv:
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                cap = _dv.get(p.group, 100)
                if cap != 100:
                    p.level = int(p.level * cap / 100)

        # ── Cycling couleur depuis le pool COULEURS ───────────────────────────
        position = self.live_engine._elapsed_ms
        _col_pool = self.seq.live_panel.color_tile_pool
        if len(_col_pool) > 1:
            if not hasattr(self, '_ambiance_color_switch'):
                _bpm_a = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                _n_a   = max(2, int(2 + (self.seq.live_panel.color_duration / 100.0) * 30))
                self._ambiance_color_switch = {
                    'switch_at': position + int(_n_a * 60000.0 / _bpm_a),
                    'pool_snap': list(_col_pool),
                }
            _asw = self._ambiance_color_switch
            # Gate sur beat : switcher couleur seulement sur un nouveau beat
            _amb_new_beat = getattr(self.live_engine, '_beat_pending', False)
            if position >= _asw['switch_at'] and _amb_new_beat:
                _asw['pool_snap'] = list(_col_pool)
                try:
                    _ci = _asw['pool_snap'].index(self.seq.live_panel.current_color_tile)
                except ValueError:
                    _ci = -1
                _ni = (_ci + 1) % len(_asw['pool_snap'])
                self.seq.live_panel.set_current_color_tile(_asw['pool_snap'][_ni])
                _bpm_a2 = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                _n_a2   = max(2, int(2 + (self.seq.live_panel.color_duration / 100.0) * 30))
                _asw['switch_at'] = position + int(_n_a2 * 60000.0 / _bpm_a2)
        else:
            if hasattr(self, '_ambiance_color_switch'):
                del self._ambiance_color_switch

        # Appliquer la couleur active du pool sur tous les projecteurs (avec transition douce)
        _cur_c, _ = self.seq.live_panel.get_color_data(self.seq.live_panel.current_color_tile)
        if _cur_c:
            _amb_cs = getattr(self, '_live_color_smooth', {})
            if not isinstance(_amb_cs, dict):
                _amb_cs = {}
                self._live_color_smooth = _amb_cs
            _amb_alpha = 0.06   # transition ~400 ms à 25 fps (plus lent en ambiance)
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                _pid = id(p)
                cur = _amb_cs.get(_pid)
                if cur is None:
                    _amb_cs[_pid] = _cur_c
                    cur = _cur_c
                _dr = _cur_c.red()   - cur.red()
                _dg = _cur_c.green() - cur.green()
                _db = _cur_c.blue()  - cur.blue()
                if _dr*_dr + _dg*_dg + _db*_db < 100:
                    smooth_c = _cur_c
                else:
                    smooth_c = QColor(
                        int(cur.red()   + _amb_alpha * _dr),
                        int(cur.green() + _amb_alpha * _dg),
                        int(cur.blue()  + _amb_alpha * _db),
                    )
                _amb_cs[_pid] = smooth_c
                p.base_color = smooth_c
                f = p.level / 100.0
                p.color = QColor(int(smooth_c.red()*f), int(smooth_c.green()*f), int(smooth_c.blue()*f))

        # ── Cycling gobo depuis le pool GOBO ──────────────────────────────────
        if hasattr(self.seq.live_panel, 'current_gobo'):
            _gobo_pool_a = self.seq.live_panel.gobo_pool
            if len(_gobo_pool_a) > 1:
                if not hasattr(self, '_ambiance_gobo_switch'):
                    _bpm_g = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                    _n_g   = max(2, int(2 + (self.seq.live_panel.gobo_duration / 100.0) * 30))
                    self._ambiance_gobo_switch = {
                        'switch_at': position + int(_n_g * 60000.0 / _bpm_g),
                        'pool_snap': list(_gobo_pool_a),
                    }
                _gsw_a = self._ambiance_gobo_switch
                if position >= _gsw_a['switch_at']:
                    _gsw_a['pool_snap'] = list(_gobo_pool_a)
                    try:
                        _gi = _gsw_a['pool_snap'].index(self.seq.live_panel.current_gobo)
                    except ValueError:
                        _gi = -1
                    _gni = (_gi + 1) % len(_gsw_a['pool_snap'])
                    self.seq.live_panel._current_gobo = _gsw_a['pool_snap'][_gni]
                    self.seq.live_panel._refresh_gobo_tiles()
                    _bpm_g2 = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                    _n_g2   = max(2, int(2 + (self.seq.live_panel.gobo_duration / 100.0) * 30))
                    _gsw_a['switch_at'] = position + int(_n_g2 * 60000.0 / _bpm_g2)
            # Appliquer le gobo actif sur les lyres
            _gslot_a = self.seq.live_panel.current_gobo
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') != "Moving Head":
                    continue
                slots = getattr(p, 'gobo_wheel_slots', [])
                if slots and _gslot_a < len(slots):
                    p.gobo = slots[_gslot_a].get('dmx', 0)
                else:
                    p.gobo = _gslot_a * 32
                if self.seq.live_panel.gobo_rotation:
                    p.gobo_rotation = max(1, int(self.seq.live_panel.gobo_rot_speed * 2.55))
                else:
                    p.gobo_rotation = 0

    def _apply_live_state(self, state: dict):
        """Applique un état live, en GELANT les groupes non autorisés.

        Les groupes hors « Groupe Éclairage » doivent rester sous contrôle manuel
        (fader/pad AKAI) : on capture leur état avant le moteur IA et on le restaure
        après. Sinon les blocs strobe/drop/dimmer (qui itèrent sur TOUS les
        projecteurs sans filtre de groupe) les font clignoter et volent la main.
        """
        if not self.seq.live_mode_active:
            return
        _allowed = self.seq.live_panel.allowed_groups
        _frozen = None
        if _allowed:
            _frozen = [
                (p, p.level, QColor(p.color), QColor(p.base_color),
                 getattr(p, 'pan', None), getattr(p, 'tilt', None),
                 getattr(p, 'gobo', None), getattr(p, 'gobo_rotation', None))
                for p in self.projectors if p.group not in _allowed
            ]
        try:
            self._apply_live_state_inner(state)
        except Exception as e:
            # Slot appelé via un signal émis depuis le thread audio du moteur
            # LIVE : une exception non rattrapée ici fait crasher tout MyStrow
            # (PySide6 abort). On logge (throttlé) au lieu de crasher — notamment
            # lors du basculement Manuel ↔ Ambiance/Musical IA.
            self._log_live_error('apply_state', e)
        finally:
            if _frozen:
                for (p, lv, col, base, pan, tilt, gobo, grot) in _frozen:
                    p.level = lv
                    p.color = col
                    p.base_color = base
                    if pan  is not None: p.pan  = pan
                    if tilt is not None: p.tilt = tilt
                    if gobo is not None: p.gobo = gobo
                    if grot is not None: p.gobo_rotation = grot

    def _apply_live_state_inner(self, state: dict):
        """Applique un état lumière live aux projecteurs (remplace update_audio_ai en mode LIVE)."""
        if not self.seq.live_mode_active:
            return

        # ── Pause MIDI Clock : couper lumière + retour lyres au centre ──────────
        if getattr(self.live_engine, 'midi_paused', False):
            import time as _t_pause
            _now_pause = _t_pause.monotonic()
            if not hasattr(self, '_pause_center_start'):
                self._pause_center_start = _now_pause
            _pause_center_progress = min(1.0, (_now_pause - self._pause_center_start) / 2.0)
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                p.level = 0
                p.color = QColor(0, 0, 0)
                if getattr(p, 'fixture_type', '') == "Moving Head":
                    _cur_pan  = getattr(p, 'pan',  32768)
                    _cur_tilt = getattr(p, 'tilt', 32768)
                    p.pan  = int(_cur_pan  + _pause_center_progress * (32768 - _cur_pan))
                    p.tilt = int(_cur_tilt + _pause_center_progress * (32768 - _cur_tilt))
            return
        else:
            # Réinitialiser le compteur de centrage quand la pause se termine
            self.__dict__.pop('_pause_center_start', None)

        ia_mode_check = self.seq.live_panel.ia_mode
        # En mode Musical IA ou Ambiance : l'IA garde toujours le contrôle
        # → les effets manuels et faders sont ignorés
        # En mode Manuel : active_effect et faders ont la main (déjà géré par le return plus bas)
        if ia_mode_check not in ('musical', 'ambiance'):
            if getattr(self, 'active_effect', None) is not None:
                return

        # ── Effets SPÉCIAUX : priorité absolue, tous modes IA sauf Ambiance ────
        _special_fx = getattr(self.seq.live_panel, 'active_special', None)
        if _special_fx and ia_mode_check != 'ambiance':
            _nerv_sp = self.seq.live_panel.nervosity / 100.0
            _pos_sp  = state.get('_ia_position', self.live_engine._elapsed_ms)
            _sms_sp  = max(18, int(40 - _nerv_sp * 14))
            if _special_fx == 'fixe_blanc':
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') == "Machine a fumee":
                        continue
                    p.level = 100
                    p.color = QColor(255, 255, 255)
            elif _special_fx == 'strobe':
                _sp_on = (int(_pos_sp / _sms_sp) % 2) == 0
                for p in self.projectors:
                    _ft = getattr(p, 'fixture_type', '')
                    if _ft in ("Machine a fumee", "Moving Head"):
                        continue   # lyres : non affectées
                    if _sp_on:
                        p.level = 100; p.color = QColor(255, 255, 255)
                    else:
                        p.level = 0;   p.color = QColor("black")
            elif _special_fx == 'strobe_couleur':
                _sp_on = (int(_pos_sp / _sms_sp) % 2) == 0
                _sc1, _ = self.seq.live_panel.get_color_data(
                    self.seq.live_panel.current_color_tile)
                if _sc1 is None:
                    _pal_sp = (self.seq.live_panel.live_palette
                               or getattr(self.live_engine.audio_ai, 'palette', None)
                               or [QColor('#ffffff')])
                    _sc1 = _pal_sp[0]
                for p in self.projectors:
                    _ft = getattr(p, 'fixture_type', '')
                    if _ft in ("Machine a fumee", "Moving Head"):
                        continue   # lyres : non affectées
                    if _sp_on:
                        p.level = 100; p.color = _sc1
                    else:
                        p.level = 0;   p.color = QColor("black")
            elif _special_fx == 'passage_blanc':
                # Passage séquentiel — couleurs du pool COULEURS, blanc par défaut
                _spd_p = self.seq.live_panel.passage_speed / 100.0
                _interval_ms = max(40, int(800 - _spd_p * 760))
                _projs = [p for p in self.projectors
                          if getattr(p, 'fixture_type', '') != "Machine a fumee"]
                _n = len(_projs)
                if _n > 0:
                    # Construire la palette depuis le pool de couleurs actif
                    _col_pool = self.seq.live_panel.color_tile_pool
                    _palette_sw = []
                    for _ck in _col_pool:
                        _c1, _ = self.seq.live_panel.get_color_data(_ck)
                        if _c1:
                            _palette_sw.append(_c1)
                    if not _palette_sw:
                        _palette_sw = [QColor(255, 255, 255)]
                    _nc = len(_palette_sw)
                    _cycle = _n * _interval_ms
                    _t_in_cycle = int(_pos_sp) % max(1, _cycle)
                    for _pi, p in enumerate(_projs):
                        if _t_in_cycle >= _pi * _interval_ms:
                            p.level = 100
                            p.color = _palette_sw[_pi % _nc]
                        else:
                            p.level = 0
                            p.color = QColor(0, 0, 0)
            return   # override total — pas besoin d'aller plus loin

        ia_mode = self.seq.live_panel.ia_mode
        if ia_mode == 'manuel':
            # Mode Manuel : le moteur live ne touche rien.
            # Les projecteurs conservent leur état courant (AKAI / plan de feu / clic droit).
            return
        if ia_mode == 'ambiance':
            self._apply_ambiance_live()
            return

        import math as _math
        import time as _time

        section   = state.get('section', 'verse')
        energy    = state.get('energy', 0.5)

        # ── Musical IA : blackout progressif si silence absolu ────────────────
        # En mode Ambiance, les projecteurs restent allumés (handled above).
        # En mode Musical IA, quand le moteur audio détecte un silence total,
        # on coupe le dimmer pour éviter une lumière figée sans musique.
        if ia_mode == 'musical' and section == 'quiet':
            _silence_raw = getattr(self.live_engine, '_rms_history', None)
            _is_silence  = (
                _silence_raw is not None
                and len(_silence_raw) >= 10
                and sum(list(_silence_raw)[-10:]) / 10 < 0.008
            )
            if _is_silence:
                # Démarrer le fondu si pas encore commencé
                if not getattr(self, '_silence_fade_start', None):
                    self._silence_fade_start = _time.monotonic()
                # (on ne retourne pas — le traitement normal continue, le fade est appliqué en fin)
            else:
                # Son présent → annuler le fondu immédiatement
                self._silence_fade_start = None
        else:
            self._silence_fade_start = None
        nerv      = self.seq.live_panel.nervosity
        position  = state.get('_ia_position', self.live_engine._elapsed_ms)
        now_ts    = _time.monotonic()

        # Filtres depuis les paramètres Live
        _settings_pal = self.seq.live_panel.live_palette  # [] = palette auto
        _allowed_eff  = self.seq.live_panel.allowed_effects  # set() = tous
        _eff_ok       = lambda e: not _allowed_eff or e in _allowed_eff

        contre_alt = state.get('contre_alt')
        lat_alt    = state.get('lat_alt')
        lat_effect = state.get('lat_effect')

        # État persistant de section (wall-clock pour drop_start — résistant au trim)
        if not hasattr(self, '_live_sec'):
            self._live_sec = {'last': None, 'drop_start_ts': -1.0}
        ss = self._live_sec

        def _set_proj(p, color, level):
            p.level = max(0, min(100, level))
            p.base_color = color
            if p.level > 0:
                f = p.level / 100.0
                p.color = QColor(int(color.red()*f), int(color.green()*f), int(color.blue()*f))
            else:
                p.color = QColor("black")

        # ── 1. État de base avec ia_max_dimmers ──────────────────────────────
        _allowed_grps = self.seq.live_panel.allowed_groups
        contre_idx = lat_idx = 0
        for p in self.projectors:
            if p.group not in state:
                continue
            # Si des groupes sont sélectionnés, l'IA ne pilote QUE ceux-là et
            # ÉTEINT les autres (sinon ils restaient figés à leur dernière couleur).
            if _allowed_grps and p.group not in _allowed_grps:
                _set_proj(p, QColor("black"), 0)
                continue
            color, level = state[p.group]

            # Plafonner selon les dimmers IA configurés
            level = int(level * self.ia_max_dimmers.get(p.group, 100) / 100)

            if p.group == 'contre':
                if contre_alt and contre_idx % 2 == 1:
                    color = contre_alt
                contre_idx += 1
            elif p.group == 'lat':
                if lat_alt and lat_idx % 2 == 1:
                    color = lat_alt
                if lat_effect == 'strobe':
                    strobe_ms = int(80 - nerv * 45)
                    if not (int(position / strobe_ms) % 2) == 0:
                        level = 0
                lat_idx += 1

            _set_proj(p, color, level)

        # ── 2. Overrides de section ───────────────────────────────────────────
        white = QColor(255, 255, 255)
        # Palette depuis le pool de couleurs
        _tile_pool = self.seq.live_panel.color_tile_pool
        _pool_colors = []
        for _ck in _tile_pool:
            _c1, _ = self.seq.live_panel.get_color_data(_ck)
            if _c1:
                _pool_colors.append(_c1)
        _max_c    = self.seq.live_panel.color_max
        _restrict = self.seq.live_panel.color_restrict

        if _pool_colors and (_restrict or _max_c < 4):
            if _max_c == 1:
                _cur_c, _ = self.seq.live_panel.get_color_data(
                    self.seq.live_panel.current_color_tile)
                pal = [_cur_c] if _cur_c else [_pool_colors[0]]
            else:
                pal = _pool_colors[:_max_c]
            # ── Remapper les couleurs IA vers pal ─────────────────────────
            # La palette IA est générée autour d'UNE seule dominante : toutes
            # ses teintes sont proches. Un mapping « couleur la plus proche »
            # ferait converger tous les projos vers UNE seule couleur du pool
            # (bug : plusieurs couleurs sélectionnées → une seule affichée).
            # On mappe plutôt l'INDICE de la couleur dans la palette IA vers
            # l'indice dans le pool : ça répartit les couleurs choisies entre
            # les groupes et les anime sur les beats (l'IA fait tourner les
            # indices contre/lat/face à chaque beat).
            _ai_pal = getattr(self.live_engine.audio_ai, 'palette', None) or []
            def _map_to_pal(c):
                if len(pal) == 1:
                    return pal[0]
                if _ai_pal:
                    best_i, bd = 0, float('inf')
                    for i, pc in enumerate(_ai_pal):
                        d = (pc.red()-c.red())**2 + (pc.green()-c.green())**2 + (pc.blue()-c.blue())**2
                        if d < bd:
                            bd, best_i = d, i
                    return pal[best_i % len(pal)]
                return pal[0]
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                if p.level > 0 and p.base_color:
                    mapped = _map_to_pal(p.base_color)
                    f = p.level / 100.0
                    p.base_color = mapped
                    p.color = QColor(int(mapped.red()*f), int(mapped.green()*f), int(mapped.blue()*f))
        else:
            pal = _settings_pal or self.live_engine.audio_ai.palette or [white]
        drop_fx          = self.ia_params.get('drop_effect', 'flash_blanc')
        strobe_ms_fast   = int(38 - nerv * 13)
        strobe_ms_medium = int(55 - nerv * 20)
        strobe_ms_slow   = int(75 - nerv * 25)
        _allow_strob_fast = self.seq.live_panel.strob_fast
        _allow_strob_slow = self.seq.live_panel.strob_slow
        _allow_strob_none = self.seq.live_panel.strob_none

        if section == 'drop':
            if ss['last'] != 'drop':
                ss['drop_start_ts'] = now_ts
            drop_p = min(1.0, (now_ts - ss['drop_start_ts']) / 1.2)

            if drop_fx == 'flash_blanc':
                if drop_p < 0.30:
                    punch = 1.0 - drop_p / 0.30
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                        if int(100 * punch) > p.level:
                            _set_proj(p, white, int(100 * punch))
                strobe_on = (int(position / strobe_ms_fast) % 2) == 0
                for p in self.projectors:
                    if p.group in ('lat', 'contre') and not strobe_on:
                        p.level = 0; p.color = QColor("black")

            elif drop_fx == 'color_explosion':
                strobe_on = (int(position / strobe_ms_fast) % 2) == 0
                for i, p in enumerate(self.projectors):
                    if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                    if strobe_on:
                        _set_proj(p, pal[i % len(pal)], 100)
                    else:
                        p.level = 0; p.color = QColor("black")

            elif drop_fx == 'blackout_punch':
                if drop_p < 0.12:
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                        p.level = 0; p.color = QColor("black")
                else:
                    punch = max(0.0, 1.0 - (drop_p - 0.12) / 0.35)
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                        _set_proj(p, white, int(100 * punch))
                    if drop_p > 0.20:
                        strobe_on = (int(position / strobe_ms_medium) % 2) == 0
                        if not strobe_on:
                            for p in self.projectors:
                                if getattr(p, 'fixture_type', '') != "Machine a fumee":
                                    p.level = 0; p.color = QColor("black")

            elif drop_fx == 'stroboscope':
                strobe_ms = int(45 - nerv * 20)
                strobe_on = (int(position / strobe_ms) % 2) == 0
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                    if strobe_on:
                        _set_proj(p, white, 100)
                    else:
                        p.level = 0; p.color = QColor("black")

            elif drop_fx == 'laser_scan':
                if drop_p < 0.20:
                    punch = 1.0 - drop_p / 0.20
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') in ("Machine a fumee", "Moving Head"): continue
                        _set_proj(p, white, int(100 * punch))
                strobe_on = (int(position / strobe_ms_slow) % 2) == 0
                for p in self.projectors:
                    if p.group == 'lat' and not strobe_on:
                        p.level = 0; p.color = QColor("black")

            elif drop_fx == 'strobe_sync':
                # Strobe tous les projecteurs à la même couleur active
                _pool = self.seq.live_panel.color_tile_pool
                _sync_color = None
                for _ck in _pool:
                    _c1, _ = self.seq.live_panel.get_color_data(_ck)
                    if _c1:
                        _sync_color = _c1
                        break
                if _sync_color is None:
                    _sync_color = white
                strobe_ms = int(40 - nerv * 16)
                strobe_on = (int(position / strobe_ms) % 2) == 0
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') == "Machine a fumee":
                        continue
                    if strobe_on:
                        _set_proj(p, _sync_color, 100)
                    else:
                        p.level = 0
                        p.color = QColor("black")

            ss['last'] = 'drop'

        elif section == 'build':
            # Pas de drop prédit en live → energy comme proxy de progression
            build_p   = min(1.0, energy * 1.4)
            pulse_hz  = 2.5 + build_p * 10.0
            pulse_mod = _math.sin(position / 1000.0 * pulse_hz * 2.0 * _math.pi) * 0.5 + 0.5

            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                if p.group == 'contre':
                    r = min(255, int(p.base_color.red()   + build_p * (255 - p.base_color.red())   * 0.7))
                    g = int(p.base_color.green() * (1.0 - build_p * 0.5))
                    b = int(p.base_color.blue()  * (1.0 - build_p * 0.6))
                    lvl = min(100, int(p.level * (1.0 + build_p * 0.35) * (0.35 + 0.65 * pulse_mod)))
                    _set_proj(p, QColor(r, g, b), lvl)
                elif p.group == 'face':
                    _set_proj(p, p.base_color, min(100, int(p.level * (1.0 + build_p * 0.2))))
            ss['last'] = 'build'

        else:
            ss['last'] = section

        # ── Transient flash overrides (kick/snare/hihat) ─────────────────────
        if hasattr(self, '_live_transient_flash'):
            tf = self._live_transient_flash
            if tf.get('contre_until', 0) > position:
                for p in self.projectors:
                    if p.group == 'contre' and getattr(p, 'fixture_type', '') != "Machine a fumee":
                        p.level = min(100, p.level + 30)
                        if p.level > 0:
                            f = p.level / 100.0
                            p.color = QColor(int(p.base_color.red()*f),
                                             int(p.base_color.green()*f),
                                             int(p.base_color.blue()*f))
            if tf.get('face_until', 0) > position:
                for p in self.projectors:
                    if p.group == 'face' and getattr(p, 'fixture_type', '') != "Machine a fumee":
                        p.level = min(100, p.level + 20)
                        if p.level > 0:
                            f = p.level / 100.0
                            p.color = QColor(int(p.base_color.red()*f),
                                             int(p.base_color.green()*f),
                                             int(p.base_color.blue()*f))

        # ── Effets beat (Flash blanc · Strobe · Gobo) ────────────────────────
        if not hasattr(self, '_live_beat_state'):
            self._live_beat_state = {
                'beat_idx': -1, 'flash_until': 0,
                'strobe_until': 0, 'gobo_idx': 0,
            }
        bs = self._live_beat_state
        if '_new_beat' in state:
            _new_beat = state['_new_beat']              # source IA fichier
        else:
            cur_beat = getattr(self.live_engine.audio_ai, '_last_beat_idx', -1)
            _new_beat = cur_beat >= 0 and cur_beat != bs['beat_idx']
            if _new_beat:
                bs['beat_idx'] = cur_beat
        if _new_beat:
            if self.seq.live_panel.is_tile_active('flash') and _eff_ok('flash'):
                bs['flash_until'] = position + 110
            if self.seq.live_panel.is_tile_active('strobe') and _eff_ok('strobe'):
                bs['strobe_until'] = position + 450
            if self.seq.live_panel.is_tile_active('gobo') and _eff_ok('gobo'):
                bs['gobo_idx'] = (bs['gobo_idx'] + 1) % 8

        # Couleur du flash — suit la tuile couleur sélectionnée (None = AUTO = blanc)
        _fc1, _ = self.seq.live_panel.get_color_data(self.seq.live_panel.current_color_tile)

        # Flash coloré : éclat décroissant sur 110 ms
        if bs['flash_until'] > position and _eff_ok('flash'):
            age   = position - (bs['flash_until'] - 110)
            punch = max(0.0, 1.0 - age / 110.0)
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                flash_lvl = int(100 * punch)
                if flash_lvl > p.level:
                    p.level = flash_lvl
                    v = int(255 * punch)
                    if _fc1 is None:
                        p.color = QColor(v, v, v)
                    else:
                        p.color = QColor(
                            min(255, int(_fc1.red()   * punch * 1.25)),
                            min(255, int(_fc1.green() * punch * 1.25)),
                            min(255, int(_fc1.blue()  * punch * 1.25)),
                        )

        # Strobe beat : on/off rapide pendant 450 ms — filtré par onglet STROB
        _beat_strobe_on = (_allow_strob_fast
                           and ia_mode_check != 'ambiance'
                           and self.seq.live_panel.is_tile_active('strobe')
                           and bs['strobe_until'] > position
                           and _eff_ok('strobe'))
        _beat_gobo_on   = self.seq.live_panel.is_tile_active('gobo') and _eff_ok('gobo')
        _beat_gobo_idx  = bs['gobo_idx']

        # ── Flash intelligent (occasionnel, décroissant sur 140 ms, teinté) ─
        _smart_flash_until = bs.get('smart_flash_until', 0)
        if _smart_flash_until > position:
            _age   = position - (_smart_flash_until - 140)
            _punch = max(0.0, 1.0 - _age / 140.0)
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                _fl = int(100 * _punch)
                if _fl > p.level:
                    p.level = _fl
                    _v = int(255 * _punch)
                    if _fc1 is None:
                        p.color = QColor(_v, _v, _v)
                    else:
                        p.color = QColor(
                            min(255, int(_fc1.red()   * _punch * 1.25)),
                            min(255, int(_fc1.green() * _punch * 1.25)),
                            min(255, int(_fc1.blue()  * _punch * 1.25)),
                        )

        # ── Lyres — rotation continue dont la vitesse suit le rythme ────────
        moving_heads = [p for p in self.projectors
                        if getattr(p, 'fixture_type', '') == "Moving Head"]
        if moving_heads:
            n_lyres = len(moving_heads)

            if not hasattr(self, '_live_lyre_e'):
                self._live_lyre_e            = energy
                self._live_lyre_phase        = 0.0
                self._live_lyre_speed        = 0.08   # rot/s initial
                self._live_lyre_amp_pan      = 18.0
                self._live_lyre_amp_tilt     = 12.0
                self._live_lyre_last_pos     = position
                self._live_lyre_chop_until   = 0
                self._live_lyre_beat_idx     = -1
                self._live_lyre_color_smooth = None

            e_alpha = 0.07 if section == 'quiet' else 0.12
            self._live_lyre_e = e_alpha * energy + (1.0 - e_alpha) * self._live_lyre_e
            e = self._live_lyre_e

            dt = max(0.0, min(0.12, (position - self._live_lyre_last_pos) / 1000.0))
            self._live_lyre_last_pos = position

            # Vitesse cible (rot/s) — slider VITESSE + section + énergie
            _mspd_raw = self.seq.live_panel.movement_speed / 100.0
            _tgt_speed_section = {
                'quiet': 0.04 + e * 0.02,
                'verse': 0.12 + e * 0.08,
                'build': 0.22 + e * 0.10,
                'high':  0.30 + e * 0.12,
                'drop':  0.50 + e * 0.22,
            }.get(section, 0.12 + e * 0.08)
            _tgt_speed_manual = _mspd_raw * 0.60
            # À 0% → arrêt total ; courbe quadratique pour progressivité
            _speed_factor = _mspd_raw ** 2
            _tgt_speed = (_tgt_speed_section * (1.0 - _mspd_raw * 0.7) + _tgt_speed_manual) * _speed_factor

            spd_alpha = 0.07 if section != 'quiet' else 0.02
            if _mspd_raw < 0.02:
                self._live_lyre_speed = 0.0
            else:
                self._live_lyre_speed += spd_alpha * (_tgt_speed - self._live_lyre_speed)

            # Avancer la phase
            self._live_lyre_phase = (
                self._live_lyre_phase + dt * self._live_lyre_speed * 2.0 * _math.pi
            ) % (2.0 * _math.pi)

            # Amplitude de balayage cible
            _tgt_pan, _tgt_tilt = {
                'quiet': (6.0,  4.0),
                'verse': (18.0, 12.0),
                'build': (28.0, 20.0),
                'high':  (36.0, 25.0),
                'drop':  (46.0, 32.0),
            }.get(section, (18.0, 12.0))

            amp_alpha = 0.02 if section == 'quiet' else 0.06
            self._live_lyre_amp_pan  += amp_alpha * (_tgt_pan  - self._live_lyre_amp_pan)
            self._live_lyre_amp_tilt += amp_alpha * (_tgt_tilt - self._live_lyre_amp_tilt)

            # Chop sur les beats
            cur_beat_idx = state.get('_ia_beat_idx',
                           getattr(self.live_engine.audio_ai, '_last_beat_idx', -1))
            if cur_beat_idx >= 0 and cur_beat_idx != self._live_lyre_beat_idx:
                self._live_lyre_beat_idx = cur_beat_idx
                if e > 0.30 and section != 'quiet':
                    self._live_lyre_chop_until = position + 55

            # Hihat transient : micro-chop lyre
            if (hasattr(self, '_live_transient_flash')
                    and self._live_transient_flash.get('lyre_chop_until', 0) > position):
                self._live_lyre_chop_until = max(
                    self._live_lyre_chop_until,
                    self._live_transient_flash['lyre_chop_until'],
                )

            # ── Couleur lyre : pool de tuiles + cycle automatique ─────────
            pal_l = _settings_pal or self.live_engine.audio_ai.palette or [QColor("#ffffff")]
            c_idx = getattr(self.live_engine.audio_ai, '_contre_color_idx', 0)

            # Cycle entre les tuiles couleur sélectionnées (même logique que mouvements)
            _col_pool = self.seq.live_panel.color_tile_pool   # liste ordonnée
            _col_cur  = self.seq.live_panel.current_color_tile

            # Si l'utilisateur a changé manuellement la couleur → reset du timer de cycle
            if getattr(self, '_live_col_cur_prev', None) != _col_cur:
                self._live_col_cur_prev = _col_cur
                if hasattr(self, '_live_lyre_color_switch'):
                    del self._live_lyre_color_switch   # repart du début avec la nouvelle couleur

            if len(_col_pool) > 1:
                if not hasattr(self, '_live_lyre_color_switch'):
                    _bpm0c = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                    _n0c   = max(2, int(2 + (self.seq.live_panel.color_duration / 100.0) * 30))
                    self._live_lyre_color_switch = {
                        'switch_at': position + int(_n0c * 60000.0 / _bpm0c),
                        'pool_snap': list(_col_pool),
                    }
                _cswitch = self._live_lyre_color_switch
                if position >= _cswitch['switch_at']:
                    _cswitch['pool_snap'] = list(_col_pool)
                    try:
                        _ci = _cswitch['pool_snap'].index(_col_cur)
                    except ValueError:
                        _ci = -1
                    _ni       = (_ci + 1) % len(_cswitch['pool_snap'])
                    _next_col = _cswitch['pool_snap'][_ni]
                    self.seq.live_panel.set_current_color_tile(_next_col)
                    _col_cur = _next_col
                    _bpm_c   = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                    _n_c     = max(2, int(2 + (self.seq.live_panel.color_duration / 100.0) * 30))
                    _cswitch['switch_at'] = position + int(_n_c * 60000.0 / _bpm_c)
            else:
                if hasattr(self, '_live_lyre_color_switch'):
                    del self._live_lyre_color_switch

            # Résoudre la tuile courante → (color1, color2)
            _lyr_c1, _lyr_c2 = self.seq.live_panel.get_color_data(_col_cur)
            # color1=None → AUTO : suit la palette IA comme avant
            if _lyr_c1 is None:
                if section == 'drop':
                    drop_p_now = min(1.0, (now_ts - ss.get('drop_start_ts', now_ts)) / 1.2)
                    lyre_color_tgt = (QColor(255, 255, 255) if drop_p_now < 0.35
                                      else pal_l[int(position / 80) % len(pal_l)])
                else:
                    lyre_color_tgt = pal_l[c_idx % len(pal_l)]
            else:
                lyre_color_tgt = _lyr_c1   # couleur fixe (ou couleur A du bicolore)

            # Lissage de la couleur partagée
            if self._live_lyre_color_smooth is None:
                self._live_lyre_color_smooth = lyre_color_tgt
            if _lyr_c1 is not None:
                # Couleur fixe choisie : snapping immédiat, la couleur ne dérive jamais
                lyre_color = lyre_color_tgt
                self._live_lyre_color_smooth = lyre_color_tgt
            else:
                # AUTO : lissage fluide qui suit la palette IA
                _ac = 0.55 if section == 'drop' else (0.06 if section == 'quiet' else 0.18)
                _cc = self._live_lyre_color_smooth
                self._live_lyre_color_smooth = QColor(
                    int(_cc.red()   + _ac * (lyre_color_tgt.red()   - _cc.red())),
                    int(_cc.green() + _ac * (lyre_color_tgt.green() - _cc.green())),
                    int(_cc.blue()  + _ac * (lyre_color_tgt.blue()  - _cc.blue())),
                )
                lyre_color = self._live_lyre_color_smooth

            # Niveau lumineux
            if position < self._live_lyre_chop_until:
                lyre_level = 0
            elif section == 'quiet':
                lyre_level = int(18 + e * 14)
            elif section == 'drop':
                lyre_level = int(65 + e * 35)
            elif section == 'build':
                lyre_level = int(55 + e * 35)
            else:
                lyre_level = int(45 + e * 45)

            # Gobo auto sur changement de section (tile AUTO)
            _auto_on = self.seq.live_panel.is_tile_active('auto') and _eff_ok('auto')
            if _auto_on:
                if not hasattr(self, '_live_auto_last_section'):
                    self._live_auto_last_section = section
                if section != self._live_auto_last_section:
                    self._live_auto_last_section = section
                    if hasattr(self, '_live_beat_state'):
                        self._live_beat_state['gobo_idx'] = (
                            self._live_beat_state['gobo_idx'] + 1) % 8

            # Application pan/tilt — pattern depuis le panel Mouvements
            ph    = self._live_lyre_phase
            _mspd = self.seq.live_panel.movement_speed    / 100.0  # 0–1
            _msz  = self.seq.live_panel.movement_size     / 100.0  # 0–1
            _mdur = self.seq.live_panel.movement_duration / 100.0  # 0–1

            # ── Cycle multi-mouvements ────────────────────────────────────────
            _mov_pool = self.seq.live_panel.movement_patterns  # liste ordonnée
            _mov      = self.seq.live_panel.movement_pattern   # courant

            if len(_mov_pool) > 1:
                if not hasattr(self, '_live_lyre_switch'):
                    _bpm0 = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                    _n0   = max(2, int(2 + (self.seq.live_panel.movement_duration / 100.0) * 30))
                    self._live_lyre_switch = {
                        'switch_at': position + int(_n0 * 60000.0 / _bpm0),
                        'pool_snap': list(_mov_pool),
                    }
                _sw = self._live_lyre_switch

                if position >= _sw['switch_at']:
                    _sw['pool_snap'] = list(_mov_pool)
                    try:
                        _cur_idx = _sw['pool_snap'].index(_mov)
                    except ValueError:
                        _cur_idx = -1
                    _next_idx = (_cur_idx + 1) % len(_sw['pool_snap'])
                    _next_key = _sw['pool_snap'][_next_idx]
                    self.seq.live_panel.set_current_movement(_next_key)
                    _mov = _next_key
                    _bpm_now = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                    _n_beats = max(2, int(2 + (self.seq.live_panel.movement_duration / 100.0) * 30))
                    _sw['switch_at'] = position + int(_n_beats * 60000.0 / _bpm_now)
            else:
                # Pool d'un seul élément → pas de cycle
                if hasattr(self, '_live_lyre_switch'):
                    del self._live_lyre_switch

            # Amplitude directe en unités DMX selon slider TAILLE
            _amp_pan  = int(2000 + _msz * 22000)   # 2000 → 24000 (3% → 37% du range)
            _amp_tilt = int(1500 + _msz * 14000)   # 1500 → 15500

            for i, p in enumerate(moving_heads):
                offset = i * (2.0 * _math.pi / max(n_lyres, 1))
                ph_i   = ph + offset
                if _mov == 'cercle' or _mov == 'circle':
                    pan_v  = _math.cos(ph_i)
                    tilt_v = _math.sin(ph_i)
                elif _mov in ('huit', 'eight'):
                    pan_v  = _math.sin(ph_i)
                    tilt_v = _math.sin(2.0 * ph_i) * 0.5
                elif _mov == 'vague':
                    pan_v  = _math.sin(ph_i)
                    tilt_v = 0.0
                elif _mov == 'diagonale':
                    t      = _math.sin(ph_i)
                    pan_v  = t
                    tilt_v = t
                elif _mov == 'bounce':
                    t      = abs(_math.sin(ph_i * 0.5))
                    pan_v  = t * 2.0 - 1.0
                    tilt_v = 0.0
                elif _mov == 'spirale':
                    r      = (ph_i % (2 * _math.pi)) / (2 * _math.pi)
                    pan_v  = r * _math.cos(ph_i * 3.0)
                    tilt_v = r * _math.sin(ph_i * 3.0)
                elif _mov == 'random':
                    seed   = int(ph_i / (0.5 * _math.pi))
                    pan_v  = (((seed * 1664525 + 1013904223) & 0xFFFF) / 32767.5) - 1.0
                    tilt_v = (((seed * 22695477 + 1) & 0xFFFF) / 32767.5) - 1.0
                elif _mov == 'pixel':
                    seed   = int(ph_i / (0.15 * _math.pi))
                    pan_v  = (((seed * 69069 + 1) & 0xFFFF) / 32767.5) - 1.0
                    tilt_v = (((seed * 1664525 + 1) & 0xFFFF) / 32767.5) - 1.0
                else:                                         # Lissajous (défaut)
                    pan_v  = _math.cos(ph_i)
                    tilt_v = _math.sin(ph_i * 1.618)

                p.pan  = max(0, min(65535, 32768 + int(pan_v  * _amp_pan)))
                p.tilt = max(0, min(65535, 32768 + int(tilt_v * _amp_tilt)))
                if p.group not in state:
                    p.level = max(0, min(100, lyre_level))

                    # ── Couleur per-lyre ──────────────────────────────────────
                    # Tuile bicolore : lyres paires = color1, lyres impaires = color2
                    if _lyr_c2 is not None and i % 2 == 1:
                        p_color = _lyr_c2
                    else:
                        p_color = lyre_color   # lissée vers la couleur cible

                    p.base_color = p_color
                    f = p.level / 100.0
                    p.color = QColor(int(p_color.red()*f),
                                     int(p_color.green()*f),
                                     int(p_color.blue()*f))
                # Changement de gobo sur beat
                if _beat_gobo_on:
                    slots = getattr(p, 'gobo_wheel_slots', [])
                    if slots:
                        p.gobo = slots[_beat_gobo_idx % len(slots)].get('dmx', 0)
                    else:
                        p.gobo = (_beat_gobo_idx % 8) * 32
                elif hasattr(self.seq.live_panel, 'current_gobo'):
                    # Gobo depuis l'onglet GOBO (pool + cycle)
                    _gobo_pool = self.seq.live_panel.gobo_pool
                    if len(_gobo_pool) > 1:
                        if not hasattr(self, '_live_gobo_switch'):
                            _bpm0g = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                            _n0g   = max(2, int(2 + (self.seq.live_panel.gobo_duration / 100.0) * 30))
                            self._live_gobo_switch = {
                                'switch_at': position + int(_n0g * 60000.0 / _bpm0g),
                                'pool_snap': list(_gobo_pool),
                            }
                        _gsw = self._live_gobo_switch
                        if position >= _gsw['switch_at']:
                            _gsw['pool_snap'] = list(_gobo_pool)
                            try:
                                _gi = _gsw['pool_snap'].index(self.seq.live_panel.current_gobo)
                            except ValueError:
                                _gi = -1
                            _gni = (_gi + 1) % len(_gsw['pool_snap'])
                            self.seq.live_panel._current_gobo = _gsw['pool_snap'][_gni]
                            self.seq.live_panel._refresh_gobo_tiles()
                            _bpm_g = max(60.0, getattr(self.live_engine, '_bpm', 120.0))
                            _n_g   = max(2, int(2 + (self.seq.live_panel.gobo_duration / 100.0) * 30))
                            _gsw['switch_at'] = position + int(_n_g * 60000.0 / _bpm_g)
                    else:
                        if hasattr(self, '_live_gobo_switch'):
                            del self._live_gobo_switch

                    _gslot = self.seq.live_panel.current_gobo
                    slots = getattr(p, 'gobo_wheel_slots', [])
                    if slots and _gslot < len(slots):
                        p.gobo = slots[_gslot].get('dmx', 0)
                    else:
                        p.gobo = _gslot * 32
                    # Rotation gobo
                    if self.seq.live_panel.gobo_rotation:
                        _rot_spd = self.seq.live_panel.gobo_rot_speed
                        p.gobo_rotation = max(1, int(_rot_spd * 2.55))
                    else:
                        p.gobo_rotation = 0
                self._update_color_wheel(p, p.base_color or lyre_color)

        # ── Positions lyres prédéfinies (override du mode rotation si actif) ───
        if moving_heads:
            presets = self.seq.live_panel.lyre_presets
            if presets:
                if not hasattr(self, '_live_preset_state'):
                    self._live_preset_state = {
                        'targets': [0] * len(moving_heads),
                        'pan':     [128.0] * len(moving_heads),
                        'tilt':    [128.0] * len(moving_heads),
                    }
                ps = self._live_preset_state
                # Étendre les listes si le nombre de lyres a changé
                while len(ps['targets']) < len(moving_heads):
                    ps['targets'].append(0)
                    ps['pan'].append(128.0)
                    ps['tilt'].append(128.0)
                if _new_beat:
                    for i in range(len(moving_heads)):
                        ps['targets'][i] = (ps['targets'][i] + 1) % len(presets)
                lerp_alpha = min(0.20, 0.06 + energy * 0.14)
                for i, p in enumerate(moving_heads):
                    tgt_pan, tgt_tilt = presets[ps['targets'][i] % len(presets)]
                    ps['pan'][i]  += lerp_alpha * (tgt_pan  - ps['pan'][i])
                    ps['tilt'][i] += lerp_alpha * (tgt_tilt - ps['tilt'][i])
                    p.pan  = max(0, min(65535, int(ps['pan'][i]  * 257)))
                    p.tilt = max(0, min(65535, int(ps['tilt'][i] * 257)))

        # Lecture du flag "pas de strobe auto" (paramètres Live)
        _no_auto_strobe = getattr(self.seq.live_panel, 'no_auto_strobe', False)

        # AUTO tile — comportement intelligent par section
        _auto_on = self.seq.live_panel.is_tile_active('auto') and _eff_ok('auto')
        if _auto_on and not _no_auto_strobe:
            if section == 'drop' and _allow_strob_fast:
                auto_ms = max(22, int(48 - nerv * 18))
                if _allow_strob_none and (int(position / auto_ms) % 2) == 1:
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') != "Machine a fumee":
                            p.level = 0; p.color = QColor("black")
            elif section == 'build' and _allow_strob_slow:
                build_p = min(1.0, energy * 1.5)
                if build_p > 0.65:
                    auto_ms = max(30, int(85 - build_p * 52))
                    if _allow_strob_none and (int(position / auto_ms) % 2) == 1:
                        for p in self.projectors:
                            if getattr(p, 'fixture_type', '') != "Machine a fumee":
                                p.level = 0; p.color = QColor("black")

        # Strobe beat : override final (tue le niveau pendant les frames OFF)
        if _beat_strobe_on and not _no_auto_strobe:
            strobe_ms = max(20, int(42 - nerv * 18))
            if (int(position / strobe_ms) % 2) == 1:
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') != "Machine a fumee":
                        p.level = 0
                        p.color = QColor("black")

        # ── Strobe blanc intelligent (court — voir _SMART_STROBE_MS) ────────
        # Restitué dans les DEUX modes STROB : le mode ne décide que du hachage
        # (LENT = période nominale, RAPIDE = plus serré), pas de l'existence de
        # l'effet. « Pas de strobe » coupe les deux drapeaux, donc rien ne sort.
        _smart_strobe_until = bs.get('smart_strobe_until', 0)
        if _smart_strobe_until > position and not _no_auto_strobe \
                and (_allow_strob_slow or _allow_strob_fast) \
                and ia_mode_check != 'ambiance':
            _sms = max(22, int(45 - nerv * 12))  # 45 ms calme → 33 ms nerveux
            if _allow_strob_fast:
                _sms = max(16, int(_sms * 0.7))  # RAPIDE : hachage plus serré
            if (int(position / _sms) % 2) == 1:
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') != "Machine a fumee":
                        p.level = 0
                        p.color = QColor("black")

        # ── Filtre groupes (paramètres Live) ────────────────────────────────────
        # Filtre groupes : les groupes non autorisés sont ignorés par l'IA
        # (leur état manuel AKAI/faders est conservé — pas de blackout)
        pass  # le filtrage est fait en amont dans la boucle d'assignation

        # ── Strobe blanc drop (déclenché dès le 1er kick du drop) ───────────────
        _bs_drop = getattr(self, '_live_beat_state', {})
        _drop_strobe_active = getattr(self, '_smart_fx', {}).get('drop_strobe_active', False)
        # Synchroniser avec la section courante : stopper si on n'est plus en drop
        if _drop_strobe_active and section not in ('drop',):
            _drop_strobe_active = False
            if hasattr(self, '_smart_fx'):
                self._smart_fx['drop_strobe_active'] = False
        if _drop_strobe_active and _allow_strob_fast and ia_mode_check != 'ambiance':
            _nerv_d = self.seq.live_panel.nervosity
            _sms_d  = max(25, int(55 - _nerv_d * 25))
            _strobe_on_d = (int(position / _sms_d) % 2) == 0
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                if _strobe_on_d:
                    p.level = 100
                    p.color = QColor(255, 255, 255)
                    p.base_color = QColor(255, 255, 255)
                else:
                    p.level = 0
                    p.color = QColor(0, 0, 0)

        # ── Dimmers par groupe (onglet DIMMER) ───────────────────────────────────
        _dimmer_vals = self.seq.live_panel.dimmer_values
        if _dimmer_vals:
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                g = p.group
                cap = _dimmer_vals.get(g, 100)
                if cap != 100:
                    p.level = int(p.level * cap / 100)

        # ── Fondu progressif au silence (0 → noir en 2 s) ────────────────────
        _fade_start = getattr(self, '_silence_fade_start', None)
        if _fade_start is not None:
            _fade_t    = min(1.0, (now_ts - _fade_start) / 2.0)
            _fade_mult = 1.0 - _fade_t
            for p in self.projectors:
                if getattr(p, 'fixture_type', '') == "Machine a fumee":
                    continue
                p.level = int(p.level * _fade_mult)
                p.color = QColor(
                    int(p.color.red()   * _fade_mult),
                    int(p.color.green() * _fade_mult),
                    int(p.color.blue()  * _fade_mult),
                )

    def _drive_ia_live_tick(self):
        """Mode LIVE source 'ia_file' : pilote les effets live depuis la pré-analyse IA."""
        import bisect as _bisect
        if not self.audio_ai.analyzed:
            return
        try:
            from PySide6.QtMultimedia import QMediaPlayer as _QMP
            if self.player.playbackState() != _QMP.PlayingState:
                return
        except Exception:
            pass

        pos = self.player.position()
        dur = self.player.duration()

        # État lumière depuis la pré-analyse
        state = self.audio_ai.get_state_at(pos, dur, max_dimmers=self.ia_max_dimmers)

        # Détection de beat sur les timestamps pré-calculés
        beats = self.audio_ai.beats
        beat_idx = _bisect.bisect_right(beats, pos) - 1

        if not hasattr(self, '_ia_live_last_beat'):
            self._ia_live_last_beat = -1

        new_beat = beat_idx > self._ia_live_last_beat and beat_idx >= 0
        if new_beat:
            self._ia_live_last_beat = beat_idx
            self.seq.live_panel.flash_beat()

        # BPM depuis les intervalles récents
        if beat_idx >= 3:
            window = beats[max(0, beat_idx - 8): beat_idx + 1]
            if len(window) >= 2:
                ivs = [(window[i + 1] - window[i]) / 1000.0
                       for i in range(len(window) - 1)]
                avg_iv = sum(ivs) / len(ivs)
                if avg_iv > 0:
                    bpm = 60.0 / avg_iv
                    self.seq.live_panel.set_status(
                        bpm=bpm, section=state.get('section', 'verse'))

        # Injecter position et infos beat pour _apply_live_state
        state['_ia_position']  = pos
        state['_new_beat']     = new_beat
        state['_ia_beat_idx']  = beat_idx

        self._apply_live_state(state)

    def update_audio_ai(self):
        """IA Lumiere - Met a jour les projecteurs selon l'analyse audio avec effets creatifs"""
        try:
            # Mode LIVE actif
            if self.seq.live_mode_active:
                if getattr(self, '_live_ia_mode', False):
                    self._drive_ia_live_tick()
                return
            # Ne pas interférer avec un effet en cours — l'effet a la priorité
            if getattr(self, 'active_effect', None) is not None:
                return
            # Ne pas interférer avec le fade-out de fin de média
            if self._ia_fadeout_timer and self._ia_fadeout_timer.isActive():
                return
            if self.seq.current_row < 0:
                return
            dmx_mode = self.seq.get_dmx_mode(self.seq.current_row)
            if dmx_mode != "IA Lumiere":
                return
            if self.player.playbackState() != QMediaPlayer.PlayingState:
                return
            if not self.audio_ai.analyzed:
                return

            import math

            position = self.player.position()
            duration = self.player.duration()

            state = self.audio_ai.get_state_at(position, duration, max_dimmers=self.ia_max_dimmers)

            section     = state.get('section', 'verse')
            energy      = state.get('energy', 0.5)
            global_fade = state.get('global_fade', 1.0)

            contre_alt    = state.get('contre_alt')
            lat_alt       = state.get('lat_alt')
            contre_effect = state.get('contre_effect')
            lat_effect    = state.get('lat_effect')

            # Paramètres nervosité (0.0 → 1.0)
            nerv = max(0.0, min(1.0, self.ia_params.get('nervosity', 50) / 100.0))

            # ── 1. Appliquer l'état de base (couleurs + levels depuis l'IA) ──
            contre_idx = 0
            lat_idx    = 0

            for p in self.projectors:
                if p.group not in state:
                    continue
                color, level = state[p.group]

                if p.group == 'contre':
                    if contre_alt and contre_idx % 2 == 1:
                        color = contre_alt
                    contre_idx += 1
                elif p.group == 'lat':
                    if lat_alt and lat_idx % 2 == 1:
                        color = lat_alt
                    if lat_effect == "strobe":
                        # Nervosité → strobe plus rapide
                        strobe_ms = int(80 - nerv * 45)   # 80ms calm → 35ms nerveux
                        strobe_on = (int(position / strobe_ms) % 2) == 0
                        if not strobe_on:
                            level = 0
                    lat_idx += 1

                p.level = level
                p.base_color = color
                if level > 0:
                    brightness = level / 100.0
                    p.color = QColor(
                        int(color.red()   * brightness),
                        int(color.green() * brightness),
                        int(color.blue()  * brightness)
                    )
                else:
                    p.color = QColor("black")

            # ── 2. Overrides par section ──────────────────────────────────────

            def _set_proj(p, color, level):
                """Applique couleur+level à un projecteur (évite le code dupliqué)."""
                p.level = max(0, min(100, level))
                p.base_color = color
                if p.level > 0:
                    f = p.level / 100.0
                    p.color = QColor(int(color.red()*f), int(color.green()*f), int(color.blue()*f))
                else:
                    p.color = QColor("black")

            # Initialiser l'état de section persistant
            if not hasattr(self, '_ia_sec'):
                self._ia_sec = {'last': None, 'drop_start': -1, 'build_p': 0.0}
            ss = self._ia_sec

            # ── DROP : effet choisi par l'utilisateur ────────────────────────
            if section == 'drop':
                DROP_MS = 1200.0
                if ss['last'] != 'drop':
                    ss['drop_start'] = position
                drop_p = min(1.0, (position - ss['drop_start']) / DROP_MS)
                drop_fx = self.ia_params.get('drop_effect', 'flash_blanc')

                # Fréquences de strobe adaptées à la nervosité
                strobe_ms_fast   = int(38 - nerv * 13)   # 38ms calm → 25ms nerveux
                strobe_ms_medium = int(55 - nerv * 20)   # 55ms → 35ms
                strobe_ms_slow   = int(75 - nerv * 25)   # 75ms → 50ms

                white = QColor(255, 255, 255)
                _tile_pool2  = self.seq.live_panel.color_tile_pool
                _pool_colors2 = [c for c in (_c1 for _ck in _tile_pool2
                                   for _c1, _ in [self.seq.live_panel.get_color_data(_ck)]) if c]
                _max_c2   = self.seq.live_panel.color_max
                _restrict2 = self.seq.live_panel.color_restrict
                if _pool_colors2 and (_restrict2 or _max_c2 < 4):
                    if _max_c2 == 1:
                        _cur_c2, _ = self.seq.live_panel.get_color_data(
                            self.seq.live_panel.current_color_tile)
                        pal = [_cur_c2] if _cur_c2 else [_pool_colors2[0]]
                    else:
                        pal = _pool_colors2[:_max_c2]
                else:
                    pal = (self.audio_ai.palette if self.audio_ai.palette else [white])

                # ── Flash Blanc ──────────────────────────────────────────────
                if drop_fx == 'flash_blanc':
                    if drop_p < 0.30:
                        punch = 1.0 - drop_p / 0.30
                        for p in self.projectors:
                            if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                            boost = int(100 * punch * global_fade)
                            if boost > p.level:
                                _set_proj(p, white, boost)
                    strobe_on = (int(position / strobe_ms_fast) % 2) == 0
                    for p in self.projectors:
                        if p.group in ('lat', 'contre') and not strobe_on:
                            p.level = 0; p.color = QColor("black")

                # ── Color Explosion ──────────────────────────────────────────
                elif drop_fx == 'color_explosion':
                    strobe_on = (int(position / strobe_ms_fast) % 2) == 0
                    for i, p in enumerate(self.projectors):
                        if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                        if strobe_on:
                            col = pal[i % len(pal)]
                            _set_proj(p, col, int(100 * global_fade))
                        else:
                            p.level = 0; p.color = QColor("black")

                # ── Blackout Punch ───────────────────────────────────────────
                elif drop_fx == 'blackout_punch':
                    if drop_p < 0.12:
                        # Coupure noire
                        for p in self.projectors:
                            if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                            p.level = 0; p.color = QColor("black")
                    else:
                        # Bang blanc puis décroissance
                        punch = max(0.0, 1.0 - (drop_p - 0.12) / 0.35)
                        for p in self.projectors:
                            if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                            _set_proj(p, white, int(100 * punch * global_fade))
                        # Strobe sur tout après le bang initial
                        if drop_p > 0.20:
                            strobe_on = (int(position / strobe_ms_medium) % 2) == 0
                            if not strobe_on:
                                for p in self.projectors:
                                    if getattr(p, 'fixture_type', '') != "Machine a fumee":
                                        p.level = 0; p.color = QColor("black")

                # ── Stroboscope Total ────────────────────────────────────────
                elif drop_fx == 'stroboscope':
                    strobe_ms = int(45 - nerv * 20)   # 45ms → 25ms
                    strobe_on = (int(position / strobe_ms) % 2) == 0
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                        if strobe_on:
                            _set_proj(p, white, int(100 * global_fade))
                        else:
                            p.level = 0; p.color = QColor("black")

                # ── Laser Scan ───────────────────────────────────────────────
                elif drop_fx == 'laser_scan':
                    if drop_p < 0.20:
                        punch = 1.0 - drop_p / 0.20
                        for p in self.projectors:
                            if getattr(p, 'fixture_type', '') == "Machine a fumee": continue
                            if getattr(p, 'fixture_type', '') != "Moving Head":
                                _set_proj(p, white, int(100 * punch * global_fade))
                    strobe_on = (int(position / strobe_ms_slow) % 2) == 0
                    for p in self.projectors:
                        if p.group == 'lat' and not strobe_on:
                            p.level = 0; p.color = QColor("black")

                # ── Strobe Sync ──────────────────────────────────────────────
                elif drop_fx == 'strobe_sync':
                    _pool = self.seq.live_panel.color_tile_pool
                    _sync_color = None
                    for _ck in _pool:
                        _c1, _ = self.seq.live_panel.get_color_data(_ck)
                        if _c1:
                            _sync_color = _c1
                            break
                    if _sync_color is None:
                        _sync_color = white
                    strobe_ms = int(40 - nerv * 16)
                    strobe_on = (int(position / strobe_ms) % 2) == 0
                    for p in self.projectors:
                        if getattr(p, 'fixture_type', '') == "Machine a fumee":
                            continue
                        if strobe_on:
                            _set_proj(p, _sync_color, int(100 * global_fade))
                        else:
                            p.level = 0
                            p.color = QColor("black")

                ss['last'] = 'drop'

            # ── BUILD : montée en puissance + pulse + réchauffement ───────────
            elif section == 'build':
                # Progression vers le prochain drop (0=loin, 1=au drop)
                next_drop = next((d for d in self.audio_ai.drops if d > position), None)
                BUILD_MS = 3500.0
                build_p = max(0.0, min(1.0, 1.0 - (next_drop - position) / BUILD_MS)) \
                          if next_drop else 0.0
                ss['build_p'] = build_p

                # Pulse qui s'accélère sur les contres
                pulse_hz  = 2.5 + build_p * 10.0
                pulse_mod = math.sin(position / 1000.0 * pulse_hz * 2.0 * math.pi) * 0.5 + 0.5

                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') == "Machine a fumee":
                        continue
                    if p.group == 'contre':
                        # Couleur qui se réchauffe vers le rouge/blanc
                        r = min(255, int(p.base_color.red() + build_p * (255 - p.base_color.red()) * 0.7))
                        g = int(p.base_color.green() * (1.0 - build_p * 0.5))
                        b = int(p.base_color.blue()  * (1.0 - build_p * 0.6))
                        warm = QColor(r, g, b)
                        lvl  = min(100, int(p.level * (1.0 + build_p * 0.35) * (0.35 + 0.65 * pulse_mod)))
                        _set_proj(p, warm, lvl)
                    elif p.group == 'face':
                        # Face : monte progressivement
                        lvl = min(100, int(p.level * (1.0 + build_p * 0.2)))
                        _set_proj(p, p.base_color, lvl)

                ss['last'] = 'build'

            # ── HIGH : énergie soutenue, tout amplifié ────────────────────────
            elif section == 'high':
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') == "Machine a fumee":
                        continue
                    lvl = min(100, int(p.level * 1.15))
                    _set_proj(p, p.base_color, lvl)
                ss['last'] = 'high'

            # ── QUIET : intro/outro/pont, tout réduit ─────────────────────────
            elif section == 'quiet':
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') == "Machine a fumee":
                        continue
                    cap = int(45 * global_fade)
                    if p.group in ('contre', 'lat'):
                        cap = int(20 * global_fade)
                    lvl = min(p.level, cap)
                    _set_proj(p, p.base_color, lvl)
                ss['last'] = 'quiet'

            else:  # verse
                ss['last'] = 'verse'

            # ── 2b. Effets aléatoires : chases, rainbow, wave… ───────────────
            # Se déclenchent entre les sections (pas pendant un drop)
            if not hasattr(self, '_ia_rnd_fx'):
                self._ia_rnd_fx = {
                    'active':     None,
                    'start_beat': -1,
                    'duration':   0,
                    'last_beat':  -1,
                    'trigger_at': 10,    # premier effet après 10 beats
                    'color_idx':  0,
                }
            rfx = self._ia_rnd_fx

            beat_count = getattr(self.audio_ai, '_beat_group_count', 0)
            beat_idx   = getattr(self.audio_ai, '_last_beat_idx', -1)

            # Progression dans le beat courant (0.0 → 1.0) pour les transitions smooth
            beat_prog = 0.0
            if 0 <= beat_idx < len(self.audio_ai.beats) - 1:
                t0 = self.audio_ai.beats[beat_idx]
                t1 = self.audio_ai.beats[beat_idx + 1]
                beat_prog = max(0.0, min(1.0, (position - t0) / max(1, t1 - t0)))

            # Suspendre l'effet pendant un drop
            if section == 'drop' and rfx['active']:
                rfx['active'] = None

            # Déclenchement d'un nouvel effet (nouveau beat + hors drop/quiet)
            new_beat = (beat_count != rfx['last_beat'])
            if (rfx['active'] is None
                    and new_beat
                    and section not in ('drop', 'quiet')
                    and beat_count >= rfx['trigger_at']):
                import random as _rnd
                # Effets disponibles selon la section
                pool = ['chase_fwd', 'chase_bwd', 'rainbow', 'spotlight', 'wave', 'color_snap']
                if section == 'high':
                    pool += ['chase_fwd', 'rainbow', 'wave']   # plus fréquents
                rfx['active']     = _rnd.choice(pool)
                rfx['start_beat'] = beat_count
                rfx['duration']   = _rnd.randint(4, 8)
                rfx['color_idx']  = getattr(self.audio_ai, '_contre_color_idx', 0)
                # Prochain déclenchement : nervosité réduit l'intervalle
                lo = max(4, int(14 - nerv * 8))
                hi = max(6, int(20 - nerv * 10))
                rfx['trigger_at'] = beat_count + rfx['duration'] + _rnd.randint(lo, hi)

            rfx['last_beat'] = beat_count

            # Fin de l'effet
            if rfx['active'] and beat_count >= rfx['start_beat'] + rfx['duration']:
                rfx['active'] = None

            # Application de l'effet actif (ne pas toucher aux machines à fumée)
            if rfx['active'] and section != 'drop':
                pal_fx   = self.audio_ai.palette if self.audio_ai.palette else [QColor("#ffffff")]
                GRP_ORD  = ['face', 'lat', 'contre', 'douche1', 'douche2', 'douche3']
                n_grps   = len(GRP_ORD)
                beats_el = max(0, beat_count - rfx['start_beat'])
                fx_name  = rfx['active']
                t_s      = position / 1000.0

                # Regrouper les projecteurs par groupe (hors fumée)
                by_grp = {}
                for p in self.projectors:
                    if getattr(p, 'fixture_type', '') != "Machine a fumee":
                        by_grp.setdefault(p.group, []).append(p)

                # ── Chase avant / arrière ──────────────────────────────────
                if fx_name in ('chase_fwd', 'chase_bwd'):
                    order = GRP_ORD if fx_name == 'chase_fwd' else list(reversed(GRP_ORD))
                    active_gi = beats_el % n_grps
                    # Transition smooth : active_gi → next_gi avec beat_prog
                    next_gi   = (active_gi + 1) % n_grps
                    for gi, grp in enumerate(order):
                        if grp not in by_grp:
                            continue
                        chase_col = pal_fx[(rfx['color_idx'] + beats_el) % len(pal_fx)]
                        if gi == active_gi:
                            # Descend avec beat_prog
                            lvl = int((100 - beat_prog * 65) * global_fade)
                        elif gi == next_gi:
                            # Monte avec beat_prog (anticipation)
                            lvl = int(beat_prog * 100 * global_fade)
                        else:
                            lvl = int(15 * global_fade)
                        for p in by_grp[grp]:
                            _set_proj(p, chase_col, lvl)

                # ── Rainbow wash ───────────────────────────────────────────
                elif fx_name == 'rainbow':
                    spd = 40.0 + nerv * 40.0   # 40°/s → 80°/s
                    for gi, grp in enumerate(GRP_ORD):
                        if grp not in by_grp:
                            continue
                        hue = int((t_s * spd + gi * (360.0 / n_grps)) % 360)
                        col = QColor.fromHsv(hue, 240, 255)
                        lvl = int((65 + energy * 30) * global_fade)
                        for p in by_grp[grp]:
                            _set_proj(p, col, lvl)

                # ── Spotlight ──────────────────────────────────────────────
                elif fx_name == 'spotlight':
                    spot_grp = GRP_ORD[beats_el % n_grps]
                    # Transition : le spot entrant monte, le sortant descend
                    prev_grp = GRP_ORD[(beats_el - 1) % n_grps]
                    spot_col = pal_fx[(rfx['color_idx'] + beats_el) % len(pal_fx)]
                    for grp, projs in by_grp.items():
                        if grp == spot_grp:
                            lvl = int((beat_prog * 100) * global_fade)
                        elif grp == prev_grp:
                            lvl = int(((1.0 - beat_prog) * 100) * global_fade)
                        else:
                            lvl = int(12 * global_fade)
                        for p in projs:
                            _set_proj(p, spot_col if grp in (spot_grp, prev_grp) else p.base_color, lvl)

                # ── Wave de luminosité ─────────────────────────────────────
                elif fx_name == 'wave':
                    wave_spd = 1.2 + nerv * 1.8   # 1.2 → 3 Hz
                    for gi, grp in enumerate(GRP_ORD):
                        if grp not in by_grp:
                            continue
                        phase = gi / n_grps * 2.0 * math.pi
                        val   = math.sin(t_s * wave_spd * 2.0 * math.pi + phase)
                        lvl   = int((45 + val * 50) * global_fade)
                        col   = pal_fx[(rfx['color_idx'] + gi) % len(pal_fx)]
                        for p in by_grp[grp]:
                            _set_proj(p, col, max(0, lvl))

                # ── Color Snap (snap de couleur au beat) ───────────────────
                elif fx_name == 'color_snap':
                    snap_col = pal_fx[(rfx['color_idx'] + beats_el) % len(pal_fx)]
                    # Fondu rapide entre l'ancienne couleur et la nouvelle
                    mix = min(1.0, beat_prog * 3.0)   # atteint 1.0 en 1/3 de beat
                    for grp, projs in by_grp.items():
                        for p in projs:
                            r = int(p.base_color.red()   * (1-mix) + snap_col.red()   * mix)
                            g_c = int(p.base_color.green() * (1-mix) + snap_col.green() * mix)
                            b_c = int(p.base_color.blue()  * (1-mix) + snap_col.blue()  * mix)
                            blended = QColor(r, g_c, b_c)
                            lvl = int((70 + energy * 30) * global_fade)
                            _set_proj(p, blended, lvl)

            # ── 3. Mouvement + couleur + chop dimmer lyres (Moving Head) ────────
            moving_heads = [p for p in self.projectors
                            if getattr(p, 'fixture_type', '') == "Moving Head"]
            if moving_heads:
                energy_raw = energy

                # Lissage EWMA énergie
                if not hasattr(self, '_ia_lyre_e'):
                    self._ia_lyre_e          = energy_raw
                    self._ia_lyre_phase      = 0.0
                    self._ia_lyre_last_pos   = position
                    self._ia_lyre_chop_until = 0
                    self._ia_lyre_beat_idx   = -1
                self._ia_lyre_e = 0.07 * energy_raw + 0.93 * self._ia_lyre_e
                e = self._ia_lyre_e

                # Phase accumulée à vitesse CONSTANTE (indépendante du rythme)
                dt = max(0.0, min(0.10, (position - self._ia_lyre_last_pos) / 1000.0))
                self._ia_lyre_last_pos = position
                self._ia_lyre_phase += dt * 0.30 * 2.0 * math.pi  # ~0.30 tour/s, fixe
                ph = self._ia_lyre_phase

                # Amplitude constante (ne varie pas selon l'énergie ni la section)
                amp = 38.0

                # Couleur cible
                pal   = self.audio_ai.palette if self.audio_ai.palette else [QColor("#ffffff")]
                c_idx = getattr(self.audio_ai, '_contre_color_idx', 0)
                if section == 'drop':
                    drop_p_now = min(1.0, (position - ss.get('drop_start', position)) / 1200.0)
                    lyre_color_tgt = QColor(255, 255, 255) if drop_p_now < 0.35 \
                                     else pal[int(position / 80) % len(pal)]
                else:
                    lyre_color_tgt = pal[c_idx % len(pal)]

                # Interpolation couleur (évite les snaps brutaux au changement de beat)
                if not hasattr(self, '_ia_lyre_color_smooth'):
                    self._ia_lyre_color_smooth = lyre_color_tgt
                _ac = 0.55 if section == 'drop' else 0.18
                _cc = self._ia_lyre_color_smooth
                self._ia_lyre_color_smooth = QColor(
                    int(_cc.red()   + _ac * (lyre_color_tgt.red()   - _cc.red())),
                    int(_cc.green() + _ac * (lyre_color_tgt.green() - _cc.green())),
                    int(_cc.blue()  + _ac * (lyre_color_tgt.blue()  - _cc.blue())),
                )
                lyre_color = self._ia_lyre_color_smooth

                # Chop dimmer sur chaque beat (55 ms de noir)
                cur_beat_idx = getattr(self.audio_ai, '_last_beat_idx', -1)
                if cur_beat_idx >= 0 and cur_beat_idx != self._ia_lyre_beat_idx:
                    self._ia_lyre_beat_idx = cur_beat_idx
                    if e > 0.25:
                        self._ia_lyre_chop_until = position + 55

                if position < self._ia_lyre_chop_until:
                    lyre_level = 0
                elif section == 'quiet':
                    lyre_level = int(30 + e * 20)
                elif section == 'drop':
                    lyre_level = int(60 + e * 40)
                else:
                    lyre_level = int(50 + e * 50)

                for i, p in enumerate(moving_heads):
                    phi = i * (2.0 * math.pi / max(len(moving_heads), 1))

                    # Mouvement cercle — vitesse et amplitude fixes, indépendantes de la musique
                    pan_val  = 32768 + int(amp * 256 * math.cos(ph + phi))
                    tilt_val = 32768 + int(amp * 200 * math.sin(ph + phi))

                    p.pan  = max(0, min(65535, pan_val))
                    p.tilt = max(0, min(65535, tilt_val))

                    # Couleur : appliquée seulement si l'IA principale ne gère pas ce groupe
                    if p.group not in state:
                        p.level = max(0, min(100, lyre_level))
                        p.base_color = lyre_color
                        brightness = p.level / 100.0
                        p.color = QColor(
                            int(lyre_color.red()   * brightness),
                            int(lyre_color.green() * brightness),
                            int(lyre_color.blue()  * brightness),
                        )
                    # ColorWheel : toujours mis à jour, quelle que soit la source de la couleur
                    self._update_color_wheel(p, getattr(p, 'base_color', None) or lyre_color)

            if hasattr(self, 'plan_de_feu'):
                self.plan_de_feu.update()

        except Exception as e:
            print(f"Erreur IA Lumiere: {e}")

    def _ia_start_fadeout(self, callback=None):
        """Démarre un fade-out IA (~1.5 s) puis appelle callback."""
        # Arrêter tout fade en cours
        if self._ia_fadeout_timer and self._ia_fadeout_timer.isActive():
            self._ia_fadeout_timer.stop()

        self._ia_fadeout_levels = {id(p): p.level for p in self.projectors}
        self._ia_fadeout_steps = 0
        self._ia_fadeout_callback = callback

        if self._ia_fadeout_timer is None:
            self._ia_fadeout_timer = QTimer(self)
            self._ia_fadeout_timer.timeout.connect(self._ia_fadeout_tick)
        self._ia_fadeout_timer.start(50)

    def _ia_fadeout_tick(self):
        """Tick du fade-out IA : réduit les niveaux progressivement."""
        self._ia_fadeout_steps += 1
        progress = self._ia_fadeout_steps / self._ia_fadeout_total
        for p in self.projectors:
            orig = self._ia_fadeout_levels.get(id(p), 0)
            p.level = max(0, int(orig * (1.0 - progress)))
            if p.level <= 0:
                p.color = QColor("black")
            else:
                factor = p.level / 100.0
                p.color = QColor(
                    int(p.base_color.red() * factor),
                    int(p.base_color.green() * factor),
                    int(p.base_color.blue() * factor),
                )
        self.send_dmx_update()
        if hasattr(self, 'plan_de_feu'):
            self.plan_de_feu.update()

        if self._ia_fadeout_steps >= self._ia_fadeout_total:
            self._ia_fadeout_timer.stop()
            for p in self.projectors:
                p.level = 0
                p.color = QColor("black")
            self.send_dmx_update()
            if self._ia_fadeout_callback:
                cb = self._ia_fadeout_callback
                self._ia_fadeout_callback = None
                cb()

    def play_path(self, path):
        """Joue un fichier media"""
        self._stop_all_cartouches()
        try:
            self.player.setSource(QUrl.fromLocalFile(path))
            try:
                self.player.durationChanged.disconnect()
            except:
                pass
            row = self.seq.current_row
            self.player.durationChanged.connect(lambda d: self.update_duration_display(d, row))
            self.player.play()
            self._update_video_output_state()
        except Exception as e:
            print(f"Erreur play: {e}")

    def update_duration_display(self, duration_ms, row):
        """Met a jour l'affichage de la duree"""
        if row >= 0 and duration_ms > 0:
            minutes = duration_ms // 60000
            seconds = (duration_ms % 60000) // 1000
            dur_text = f"{minutes:02d}:{seconds:02d}"
            dur_item = self.seq.table.item(row, 2)
            if dur_item:
                dur_item.setText(dur_text)

    def on_midi_fader(self, fader_idx, value):
        """Reception d'un mouvement de fader MIDI"""
        converted_value = int((value / 127.0) * 100)

        if fader_idx == 8:
            self._fader8_dispatch(fader_idx, converted_value)
            if fader_idx in self.faders:
                self.faders[fader_idx].value = converted_value
                self.faders[fader_idx].update()
        elif 0 <= fader_idx <= 7:
            if fader_idx in self.faders:
                self.faders[fader_idx].value = converted_value
                self.faders[fader_idx].update()
            self.set_proj_level(fader_idx, converted_value)

        # Push tablette
        import tablet_server as _ts
        if _ts.is_running():
            _ts.push_fader(fader_idx, converted_value)

    def on_midi_pad(self, row, col):
        """Reception d'un appui de pad MIDI"""
        if col == 8:
            self._on_effect_press(row)
            if MIDI_AVAILABLE and self.midi_handler.midi_out:
                velocity = 1 if self.effect_buttons[row].active else 0
                self.midi_handler.set_pad_led(row, col, velocity, brightness_percent=100)
            return

        pad = self.pads.get((row, col))
        if pad:
            if col < len(self._fader_map):
                slot = self._fader_map[col]
                if slot["type"] == "group":
                    # Pads couleur standard
                    for r in range(8):
                        if r != row:
                            other_pad = self.pads.get((r, col))
                            if other_pad:
                                other_color = other_pad.property("base_color")
                                other_velocity = rgb_to_akai_velocity(other_color)
                                self.midi_handler.set_pad_led(r, col, other_velocity, brightness_percent=self.akai_inactive_brightness)

                    self.activate_pad(pad, col)
                    if MIDI_AVAILABLE and self.midi_handler.midi_out:
                        base_color = pad.property("base_color")
                        velocity = rgb_to_akai_velocity(base_color)
                        self.midi_handler.set_pad_led(row, col, velocity, brightness_percent=self.akai_active_brightness)
                elif slot["type"] == "fx":
                    # Pads FX — toggle l'effet mappé sur ce pad
                    fx_col = slot.get("fx_col", 0)
                    self._toggle_fx_pad(fx_col, row)  # met à jour visuel + LEDs physiques
                elif slot["type"] == "pos":
                    # Pads POS — rappelle la position lyre
                    pos_col = slot.get("pos_col", 0)
                    self._activate_position_akai_pad(pad, pos_col, row, col_akai=col)
                elif slot["type"] == "play":
                    # Colonne PLAY/TRANSPORT — le rôle dépend de la ligne + la variante
                    rows = _play_rows(slot)
                    action = rows[row][0] if row < len(rows) else None
                    if action:
                        self._activate_play_pad(action)
                else:
                    # Memory pads individuels
                    mem_col = slot["mem_col"]
                    if self._mem_rec_mode or self.memories[mem_col][row] is not None:
                        self._activate_memory_pad(pad, mem_col, row, col_akai=col)
                        # Update LEDs de toute la colonne
                        for r in range(8):
                            is_active = self.active_memory_pads.get(col) == r
                            self._update_memory_pad_led(mem_col, r, active=is_active)

    def on_midi_pad_released(self, row, col):
        """Reception d'un relachement de pad MIDI"""
        if col == 8:
            self._on_effect_release(row)
            if MIDI_AVAILABLE and self.midi_handler.midi_out:
                velocity = 1 if self.effect_buttons[row].active else 0
                self.midi_handler.set_pad_led(row, col, velocity, brightness_percent=100)

    def new_show(self):
        """Cree un nouveau show"""
        self.clear_sequence()

    def clear_sequence(self):
        """Vide le sequenceur"""
        # Couper le son si un media est en cours
        try:
            self.player.stop()
            self.cart_player.stop()
            self.pause_mode = False
            if hasattr(self.seq, 'tempo_timer') and self.seq.tempo_timer and self.seq.tempo_timer.isActive():
                self.seq.tempo_timer.stop()
            if hasattr(self.seq, 'timeline_playback_timer') and self.seq.timeline_playback_timer and self.seq.timeline_playback_timer.isActive():
                self.seq.timeline_playback_timer.stop()
        except Exception:
            pass

        if self.seq.table.rowCount() == 0:
            QMessageBox.information(self, tr("seq_empty_title"), tr("seq_empty_msg"))
            return

        if self.seq.is_dirty:
            msg = QMessageBox(self)
            msg.setIcon(QMessageBox.Warning)
            msg.setWindowTitle(tr("seq_clear_title"))
            msg.setText(tr("seq_save_before_clear"))
            msg.setStandardButtons(QMessageBox.Yes | QMessageBox.No | QMessageBox.Cancel)
            res = msg.exec()

            if res == QMessageBox.Yes:
                if not self.save_show():
                    return
            elif res == QMessageBox.Cancel:
                return
        else:
            res = QMessageBox.question(self, tr("seq_clear_title"),
                tr("seq_confirm_delete"),
                QMessageBox.Yes | QMessageBox.No)
            if res == QMessageBox.No:
                return

        self.seq.clear_sequence()
        self.current_show_path = None
        self.setWindowTitle(APP_NAME)

    def save_show(self):
        """Sauvegarde le show (ecrase si deja ouvert, sinon demande le chemin)"""
        # Utiliser le chemin existant ou demander un nouveau
        if self.current_show_path:
            path = self.current_show_path
        else:
            path, _ = QFileDialog.getSaveFileName(self, tr("dlg_save_show"), "", tr("tui_filter"))
            if not path:
                return False

        save_data = self._build_save_data()

        # Avertissement si des clips lumière sont orphelins (row supprimé ou séquence vide)
        row_count = self.seq.table.rowCount()
        all_clip_rows = set(self.seq.sequences.keys()) if hasattr(self.seq, 'sequences') else set()
        orphan_clips = len([r for r in all_clip_rows if r >= row_count])
        if orphan_clips > 0:
            from PySide6.QtWidgets import QMessageBox
            ret = QMessageBox.warning(
                self, tr("rec_light_warn_title"),
                tr("rec_light_warn_msg", n=orphan_clips),
                QMessageBox.Save | QMessageBox.Cancel,
                QMessageBox.Cancel
            )
            if ret == QMessageBox.Cancel:
                return False

        try:
            with open(path, 'w') as f:
                json.dump(save_data, f, indent=2)
            self.seq.is_dirty = False
            self.current_show_path = path
            self.add_recent_file(path)
            self.setWindowTitle(f"{APP_NAME} - {os.path.basename(path)}")
            self.plan_de_feu.refresh()
            self._log_message(f"Show enregistré : {os.path.basename(path)}", "success")
            return True
        except Exception as e:
            QMessageBox.critical(self, tr("err_save_title"), tr("err_save_msg", e=e))
            return False

    def save_show_as(self):
        """Sauvegarde le show sous un nouveau nom"""
        old_path = self.current_show_path
        self.current_show_path = None  # Force le dialogue
        if not self.save_show():
            self.current_show_path = old_path  # Restaurer si annule
            return False
        return True

    def _apply_show_positions_fx(self, raw: dict):
        """Applique les positions et pads FX portés par un show (.tui v6+).

        Rien n'est écrasé quand la clé est absente : un show enregistré avec une
        version antérieure ne doit pas vider la bibliothèque de positions de la
        machine qui l'ouvre. C'est la différence entre « ce show n'a pas de
        positions » et « ce show dit qu'il n'y en a aucune » — seul le second
        cas, une liste vide explicitement enregistrée, remet à zéro.
        """
        presets = raw.get("position_presets")
        pads    = raw.get("position_pads")
        fx      = raw.get("fx_pads")
        n_pos = n_fx = 0

        if isinstance(presets, list):
            self.position_presets = [dict(p) for p in presets if isinstance(p, dict)]
            n_pos = len(self.position_presets)

        if isinstance(pads, list):
            self.position_pads = [[None] * 8 for _ in range(_POS_COL_MAX)]
            for pc in range(min(_POS_COL_MAX, len(pads))):
                colonne = pads[pc] or []
                for pr in range(min(8, len(colonne))):
                    v = colonne[pr]
                    # Un index qui dépasse la bibliothèque relue laisserait un
                    # pad allumé pointant dans le vide : on le neutralise.
                    if isinstance(v, int) and 0 <= v < len(self.position_presets):
                        self.position_pads[pc][pr] = v
            self.active_position_pads.clear()

        if isinstance(fx, list):
            self.fx_pads = [[None] * 8 for _ in range(_FX_COL_MAX)]
            for fc in range(min(_FX_COL_MAX, len(fx))):
                colonne = fx[fc] or []
                for fr in range(min(8, len(colonne))):
                    cfg = colonne[fr]
                    if isinstance(cfg, dict):
                        self.fx_pads[fc][fr] = cfg
                        n_fx += 1
            self.active_fx_pads.clear()

        if presets is None and pads is None and fx is None:
            return   # show antérieur à la v6 : on ne touche à rien

        self._rebuild_akai_pads()
        # La config locale devient le reflet du show ouvert, comme pour tout le
        # reste de la surface : sans ça, le prochain démarrage relirait les
        # anciennes positions de la machine et le show repartirait amputé.
        self._save_akai_config_auto()
        if n_pos or n_fx:
            self._log_message(
                f"Show : {n_pos} position(s) et {n_fx} pad(s) FX restaurés", "info")

    def _build_save_data(self) -> dict:
        """Sérialise l'état complet du show en dict JSON-compatible (thread principal)."""
        data = []
        for r in range(self.seq.table.rowCount()):
            path_item = self.seq.table.item(r, 1)
            vol_item  = self.seq.table.item(r, 3)
            user_data = str(path_item.data(Qt.UserRole)) if path_item else ""

            if user_data == "PAUSE":
                entry = {'type': 'pause', 'd': self.seq.get_dmx_mode(r)}
                if r in self.seq.sequences and 'clips' in self.seq.sequences[r]:
                    seq = self.seq.sequences[r]
                    entry['sequence'] = {'clips': seq['clips'], 'duration': seq['duration']}
                data.append(entry)
            elif user_data.startswith("PAUSE:"):
                seconds = int(user_data.split(":")[1])
                entry = {'type': 'pause', 'duration': seconds, 'd': self.seq.get_dmx_mode(r)}
                if r in self.seq.sequences and 'clips' in self.seq.sequences[r]:
                    seq = self.seq.sequences[r]
                    entry['sequence'] = {'clips': seq['clips'], 'duration': seq['duration']}
                data.append(entry)
            else:
                dmx_mode = self.seq.get_dmx_mode(r)
                if path_item and vol_item:
                    row_data = {
                        'type': 'media',
                        'p':    path_item.data(Qt.UserRole),
                        'v':    vol_item.text(),
                        'd':    dmx_mode,
                    }
                    if self.seq.is_row_loop(r):
                        row_data['loop'] = True
                    if dmx_mode == "IA Lumiere" and r in self.seq.ia_colors:
                        row_data['ia_color'] = self.seq.ia_colors[r].name()
                    if r in self.seq.ia_analysis:
                        row_data['ia_analysis'] = self.seq.ia_analysis[r]
                    if r in self.seq.sequences:
                        seq = self.seq.sequences[r]
                        if 'clips' in seq:
                            row_data['sequence'] = {'clips': seq['clips'], 'duration': seq['duration']}
                        elif 'keyframes' in seq:
                            row_data['sequence'] = {'keyframes': seq['keyframes'], 'duration': seq['duration']}
                    if r in self.seq.image_durations:
                        row_data['image_duration'] = self.seq.image_durations[r]
                    data.append(row_data)

        cart_data = [{"path": c.media_path, "volume": c.volume} for c in self.cartouches]

        custom_colors_serial = [
            [self.memory_custom_colors[mc][mr].name() if self.memory_custom_colors[mc][mr] else None
             for mr in range(8)]
            for mc in range(_MEM_COL_MAX)
        ]

        active_pads_serial = {str(k): v for k, v in self.active_memory_pads.items()}

        overrides = self._compute_htp_overrides()
        plan_de_feu_state = []
        for proj in self.projectors:
            if overrides and id(proj) in overrides:
                level, color, base = overrides[id(proj)]
                plan_de_feu_state.append({"group": proj.group, "level": level,
                                           "base_color": base.name(), "muted": proj.muted})
            else:
                plan_de_feu_state.append({"group": proj.group, "level": proj.level,
                                           "base_color": proj.base_color.name(), "muted": proj.muted})

        faders_state     = {str(idx): fader.value for idx, fader in self.faders.items()}
        active_color_pads = {}
        for col_idx, btn in self.active_pads.items():
            bc = btn.property("base_color")
            if bc:
                active_color_pads[str(col_idx)] = bc.name()

        return {
            "version": 6,
            "sequence": data,
            "cartouches": cart_data,
            "memories": self.memories,
            "memory_custom_colors": custom_colors_serial,
            "active_memory_pads": active_pads_serial,
            "plan_de_feu": plan_de_feu_state,
            "faders": faders_state,
            "active_color_pads": active_color_pads,
            # ── Contenu de show qui ne voyageait pas (ajouté en version 6) ──
            # Ces trois entrepôts ne vivaient QUE dans ~/.maestro_akai_config.json,
            # c'est-à-dire sur la machine. Emporter son .tui sur un poste de
            # secours donnait donc un show sans positions et sans effets — et
            # surtout des REC Lumière inertes : un clip Position désigne son
            # preset par index+nom (voir core.find_position_preset), donc sans
            # `position_presets` il ne vise rien et la séquence paraît vide.
            #
            # On n'emporte QUE ce qui appartient au spectacle. Les préférences
            # de la machine — luminosité de l'APC, contrôleur épinglé, réglages
            # vMix/OBS, disposition des pages de la surface — restent locales :
            # charger le show d'un collègue ne doit pas reconfigurer votre régie.
            "position_presets": self.position_presets,
            "position_pads":    self.position_pads,
            "fx_pads":          self.fx_pads,
        }

    def _autosave(self):
        """Autosave silencieux toutes les 5 min — écriture disque en thread background."""
        if not self.seq.is_dirty or self.seq.table.rowCount() == 0:
            return

        import tempfile, datetime, threading, json as _json

        autosave_path = (
            self.current_show_path + ".autosave"
            if self.current_show_path
            else os.path.join(tempfile.gettempdir(), "mystrow_autosave.tui")
        )

        # Sérialisation sur le thread principal (accès aux widgets Qt)
        try:
            save_data = self._build_save_data()
        except Exception as e:
            print(f"[Autosave] Erreur sérialisation : {e}")
            return

        # Écriture disque en background → zéro impact sur le live
        def _write(data=save_data, path=autosave_path):
            try:
                with open(path, 'w', encoding='utf-8') as f:
                    _json.dump(data, f, indent=2)
            except Exception as e:
                print(f"[Autosave] Erreur écriture : {e}")

        threading.Thread(target=_write, daemon=True, name="autosave").start()

        # Notification discrète 3 secondes
        ts = datetime.datetime.now().strftime("%H:%M")
        lbl = getattr(self, "_autosave_lbl", None)
        if lbl:
            lbl.setText(f"💾 {ts}")
            lbl.show()
            QTimer.singleShot(3000, lbl.hide)

    def load_show(self, path=None):
        """Charge un show"""
        if not path:
            path, _ = QFileDialog.getOpenFileName(self, tr("dlg_open_show"), "", tr("tui_filter"))
        if not path:
            return

        # Stopper la lecture en cours avant de charger
        try:
            self.player.stop()
            self.cart_player.stop()
            self.pause_mode = False
            if hasattr(self.seq, 'tempo_timer') and self.seq.tempo_timer.isActive():
                self.seq.tempo_timer.stop()
            if hasattr(self.seq, 'timeline_playback_timer') and self.seq.timeline_playback_timer.isActive():
                self.seq.timeline_playback_timer.stop()
        except Exception:
            pass

        try:
            with open(path, 'r') as f:
                raw = json.load(f)

            # Retrocompatibilite: ancien format = tableau, nouveau = objet
            if isinstance(raw, list):
                data = raw
                cart_data = []
                mem_data = None
                custom_colors_data = None
                active_pads_data = None
            else:
                data = raw.get("sequence", [])
                cart_data = raw.get("cartouches", [])
                mem_data = raw.get("memories")
                custom_colors_data = raw.get("memory_custom_colors")
                active_pads_data = raw.get("active_memory_pads")

            self.seq.table.setRowCount(0)
            self.seq.sequences = {}
            self.seq.ia_colors = {}
            self.seq.ia_analysis = {}
            self.seq.image_durations = {}
            self.seq._loading = True

            try:
                for item in data:
                    item_type = item.get('type')

                    # PAUSE (indefinie ou temporisee) + retrocompat TEMPO
                    if item_type in ('pause', 'tempo'):
                        self.seq.add_pause()
                        row = self.seq.table.rowCount() - 1

                        # Determiner la duree
                        duration_val = item.get('duration')
                        if duration_val is not None:
                            pause_seconds = int(duration_val)
                            pause_item = self.seq.table.item(row, 1)
                            if pause_item:
                                pause_item.setData(Qt.UserRole, f"PAUSE:{pause_seconds}")
                                minutes = pause_seconds // 60
                                seconds = pause_seconds % 60
                                pause_item.setText(f"Pause ({minutes}m {seconds}s)" if minutes > 0 else f"Pause ({pause_seconds}s)")
                            dur_item = self.seq.table.item(row, 2)
                            if dur_item:
                                minutes = pause_seconds // 60
                                seconds = pause_seconds % 60
                                dur_item.setText(f"{minutes:02d}:{seconds:02d}")

                        # Charger le mode DMX
                        if 'd' in item:
                            combo = self.seq._get_dmx_combo(row)
                            if combo:
                                # Le combo porte les CODES, pas les libellés :
                                # c'est le bouton visible qui affiche le texte
                                # traduit. Y insérer tr(...) rendait la ligne
                                # introuvable par setCurrentText hors français,
                                # donc silencieusement laissée sur « Manuel ».
                                if item['d'] == "Play Lumiere" and combo.findText("Play Lumiere") == -1:
                                    combo.addItem("Play Lumiere")
                                combo.setCurrentText(item['d'])

                        # Charger la sequence lumiere
                        if 'sequence' in item:
                            seq_data = item['sequence']
                            if 'clips' in seq_data:
                                self.seq.sequences[row] = {
                                    'clips': seq_data['clips'],
                                    'duration': seq_data.get('duration', 0)
                                }

                    else:
                        # `add_files` REFUSE les extensions qu'il ne connaît pas
                        # (core.media_icon renvoie "file") et avale les erreurs.
                        # Sans ce contrôle, `row` désignait alors la ligne
                        # PRÉCÉDENTE : la REC Lumière du média sauté venait
                        # écraser celle du média d'avant, et tout le reste du
                        # show se décalait d'un cran. Une ligne perdue vaut
                        # mieux qu'une ligne perdue plus une ligne corrompue.
                        avant = self.seq.table.rowCount()
                        self.seq.add_files([item['p']])
                        if self.seq.table.rowCount() == avant:
                            self._log_message(
                                f"Média ignoré au chargement : {item.get('p', '?')}",
                                "warning")
                            continue
                        row = self.seq.table.rowCount() - 1
                        vol_item = self.seq.table.item(row, 3)
                        if vol_item and vol_item.text() != "--":
                            vol_item.setText(item.get('v', '100'))
                        if 'd' in item:
                            # Restaurer la couleur IA avant d'appliquer le mode
                            if 'ia_color' in item:
                                self.seq.ia_colors[row] = QColor(item['ia_color'])
                            if 'ia_analysis' in item:
                                self.seq.ia_analysis[row] = item['ia_analysis']
                            combo = self.seq._get_dmx_combo(row)
                            if combo:
                                # Voir plus haut : on ajoute le CODE, jamais le
                                # libellé traduit.
                                if item['d'] == "Play Lumiere" and combo.findText("Play Lumiere") == -1:
                                    combo.addItem("Play Lumiere")
                                combo.setCurrentText(item['d'])
                                self.seq.on_dmx_changed(row, item['d'])
                        if 'sequence' in item:
                            seq_data = item['sequence']
                            # Gerer les deux formats: 'clips' et 'keyframes'
                            if 'clips' in seq_data:
                                self.seq.sequences[row] = {
                                    'clips': seq_data['clips'],
                                    'duration': seq_data.get('duration', 0)
                                }
                            elif 'keyframes' in seq_data:
                                self.seq.sequences[row] = {
                                    'keyframes': seq_data['keyframes'],
                                    'duration': seq_data.get('duration', 0)
                                }
                        if 'image_duration' in item:
                            self.seq.image_durations[row] = int(item['image_duration'])
                        if item.get('loop'):
                            self.seq.set_row_loop(row, True)
            finally:
                self.seq._loading = False

            # Restaurer les cartouches
            for i, cd in enumerate(cart_data):
                if i < len(self.cartouches):
                    self.cartouches[i].volume = cd.get("volume", 100)
                    if cd.get("path"):
                        p = cd["path"]
                        self.cartouches[i].media_path = p
                        self.cartouches[i].media_title = Path(p).stem
                        ext = Path(p).suffix.lower()
                        if ext in CartoucheButton.VIDEO_EXTS:
                            self.cartouches[i].media_icon = "\U0001f3ac"
                        elif ext in CartoucheButton.AUDIO_EXTS:
                            self.cartouches[i].media_icon = "\U0001f3b5"
                        else:
                            self.cartouches[i].media_icon = ""
                    self.cartouches[i].set_idle()

            # Les mémoires/cues sont gérés UNIQUEMENT par la config AKAI
            # (jamais écrasés par le .tui — _load_akai_config_auto est la source de vérité)

            # Mettre a jour l'affichage des pads memoire
            for fi, mc in self._bank_memory_slots():
                for mr in range(8):
                    is_active = self.active_memory_pads.get(fi) == mr
                    self._style_memory_pad(mc, mr, active=is_active)

            # Positions et pads FX embarqués dans le show (v6+)
            #
            # Sur un poste de secours, ces données n'existent pas localement :
            # sans elles, les clips Position des REC Lumière ne visent rien.
            # On n'applique QUE ce que le fichier contient réellement : un .tui
            # antérieur à la v6 n'a pas ces clés, et il ne doit surtout pas
            # effacer les positions déjà présentes sur la machine.
            if isinstance(raw, dict):
                self._apply_show_positions_fx(raw)

            # Restaurer l'etat du plan de feu (v5+)
            if isinstance(raw, dict):
                plan_de_feu_data = raw.get("plan_de_feu")
                faders_data = raw.get("faders")
                active_color_pads_data = raw.get("active_color_pads")

                # Restaurer les faders
                if faders_data and isinstance(faders_data, dict):
                    for idx_str, value in faders_data.items():
                        idx = int(idx_str)
                        if idx in self.faders:
                            self.faders[idx].value = int(value)
                            self.faders[idx].update()

                # Restaurer les pads couleur actifs (colonnes 0-3)
                if active_color_pads_data and isinstance(active_color_pads_data, dict):
                    for col_str, color_name in active_color_pads_data.items():
                        col_idx = int(col_str)
                        target_color = QColor(color_name)
                        # Chercher le pad qui correspond a cette couleur
                        for row in range(8):
                            pad = self.pads.get((row, col_idx))
                            if pad:
                                pad_color = pad.property("base_color")
                                if pad_color and pad_color.name() == target_color.name():
                                    self.activate_pad(pad, col_idx)
                                    break

                # Restaurer l'etat des projecteurs
                if plan_de_feu_data and isinstance(plan_de_feu_data, list):
                    for i, pstate in enumerate(plan_de_feu_data):
                        if i < len(self.projectors):
                            proj = self.projectors[i]
                            proj.level = pstate.get("level", 0)
                            proj.base_color = QColor(pstate.get("base_color", "#000000"))
                            proj.muted = pstate.get("muted", False)
                            if proj.level > 0:
                                brt = proj.level / 100.0
                                proj.color = QColor(
                                    int(proj.base_color.red() * brt),
                                    int(proj.base_color.green() * brt),
                                    int(proj.base_color.blue() * brt))
                            else:
                                proj.color = QColor(0, 0, 0)

                self.plan_de_feu.refresh()

            self.seq.is_dirty = False
            self.current_show_path = path
            self.add_recent_file(path)
            self.setWindowTitle(f"{APP_NAME} - {os.path.basename(path)}")

            # Verification des fichiers medias
            self._check_missing_media()

        except Exception as e:
            self.seq._loading = False
            QMessageBox.critical(self, tr("err_save_title"), tr("err_load_msg", e=e))

    def _check_missing_media(self):
        """Verifie que tous les fichiers medias du show existent.
        Ouvre un dialog de relocalisation si des fichiers sont introuvables."""
        missing = []
        for row in range(self.seq.table.rowCount()):
            title_item = self.seq.table.item(row, 1)
            if not title_item:
                continue
            path = title_item.data(Qt.UserRole)
            if not path or str(path) == "PAUSE" or str(path).startswith("PAUSE:"):
                continue
            if not os.path.isfile(path):
                missing.append((row, Path(path).name, path))
                icon_item = self.seq.table.item(row, 0)
                if icon_item:
                    icon_item.setText("\u26a0\ufe0f")
                    icon_item.setData(Qt.UserRole, "\u26a0\ufe0f")
                for col in range(self.seq.table.columnCount()):
                    item = self.seq.table.item(row, col)
                    if item:
                        item.setForeground(QColor("#ff4444"))

        if not missing:
            return

        dlg = MissingMediaDialog(missing, self)
        dlg.exec()

        if not dlg.remapped:
            return

        _ICON_MAP = {"audio": "\U0001f3b5", "video": "\U0001f3ac", "image": "\U0001f5bc"}
        default_fg = self.seq.table.palette().color(QPalette.Text)
        for idx, new_path in dlg.remapped.items():
            orig_row, _, _ = missing[idx]
            title_item = self.seq.table.item(orig_row, 1)
            if not title_item:
                continue
            title_item.setData(Qt.UserRole, new_path)
            title_item.setText(Path(new_path).name)
            icon_item = self.seq.table.item(orig_row, 0)
            if icon_item:
                icon_text = _ICON_MAP.get(media_icon(new_path), "?")
                icon_item.setText(icon_text)
                icon_item.setData(Qt.UserRole, icon_text)
            for col in range(self.seq.table.columnCount()):
                item = self.seq.table.item(orig_row, col)
                if item:
                    item.setForeground(default_fg)
        self.seq.is_dirty = True

    # ==================== CONFIG AKAI (sauvegarde/chargement memoires) ====================

    _AKAI_CONFIG_PATH = str(Path.home() / '.maestro_akai_config.json')

    def _open_light_sync_dialog(self):
        """Réglage global de l'offset de synchro lumière/vidéo (ms).

        Compense la latence du pipeline vidéo : sur un mp4, position() peut
        devancer le son audible → les lumières partent trop tôt. À régler une
        fois par machine ; la valeur est persistée dans la config AKAI.
        """
        from PySide6.QtWidgets import (QDialog, QVBoxLayout, QHBoxLayout,
                                       QLabel, QSpinBox, QPushButton)
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("mw_sync_title"))
        dlg.setStyleSheet(
            "QDialog { background:#161616; }"
            "QLabel { color:#ddd; font-size:12px; }"
            "QSpinBox { background:#111; color:#00d4ff; border:1px solid #333;"
            " border-radius:4px; padding:4px 8px; font-size:14px; min-width:120px; }"
            "QPushButton { background:#222; color:#eee; border:1px solid #333;"
            " border-radius:5px; padding:6px 16px; }"
            "QPushButton:hover { border-color:#00d4ff; }"
        )
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(20, 18, 20, 16)
        lay.setSpacing(12)

        info = QLabel(
            tr("mw_sync_help")
        )
        info.setWordWrap(True)
        lay.addWidget(info)

        row = QHBoxLayout()
        row.addWidget(QLabel(tr("mw_light_offset")))
        spin = QSpinBox()
        spin.setRange(-5000, 20000)
        spin.setSingleStep(100)
        spin.setSuffix(" ms")
        spin.setValue(int(getattr(self, 'light_sync_offset_ms', 0) or 0))
        row.addWidget(spin)
        row.addStretch(1)
        lay.addLayout(row)

        hint = QLabel(tr("mw_sync_sign"))
        hint.setWordWrap(True)
        hint.setStyleSheet("color:#888; font-size:11px;")
        lay.addWidget(hint)

        btns = QHBoxLayout()
        btns.addStretch(1)
        b_cancel = QPushButton(tr("mw_cancel"))
        b_ok = QPushButton(tr("mw_apply"))
        b_ok.setStyleSheet("background:#0a5; color:#fff; border:none;")
        b_cancel.clicked.connect(dlg.reject)
        b_ok.clicked.connect(dlg.accept)
        btns.addWidget(b_cancel)
        btns.addWidget(b_ok)
        lay.addLayout(btns)

        if dlg.exec():
            self.light_sync_offset_ms = int(spin.value())
            try:
                self._save_akai_config_auto()
            except Exception as e:
                print(f"[SYNC] sauvegarde offset échouée: {e}")

    def _serialize_akai_config(self):
        """Serialise les memoires AKAI en dict JSON"""
        custom_colors_serial = []
        for mc in range(_MEM_COL_MAX):
            col_colors = []
            for mr in range(8):
                c = self.memory_custom_colors[mc][mr]
                col_colors.append(c.name() if c else None)
            custom_colors_serial.append(col_colors)

        active_pads_serial = {str(k): v for k, v in self.active_memory_pads.items()}

        return {
            "memories": self.memories,
            "memory_custom_colors": custom_colors_serial,
            "active_memory_pads": active_pads_serial,
            "custom_bank_slots": [dict(s) for s in self._custom_bank_slots],  # compat descendante = page active
            "bank_pages":        [[dict(s) for s in page] for page in self._bank_pages],
            "bank_page_idx":     self._bank_page_idx,
            "last_fader_mode": "FX",
            "fx_pads": self.fx_pads,
            "effect_superposition": self.effect_superposition,
            "go_mode": self.go_mode,
            "position_presets": self.position_presets,
            "position_pads": self.position_pads,
            "lyre_positions": {
                p.name: {"pan": p.pan, "tilt": p.tilt}
                for p in self.projectors
                if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')
            },
            "apc_bright_mode": getattr(self.midi_handler, '_apc_bright_mode', True),
            "akai_active_brightness": self.akai_active_brightness,
            "akai_inactive_brightness": self.akai_inactive_brightness,
            "light_sync_offset_ms": int(getattr(self, 'light_sync_offset_ms', 0) or 0),
            "pinned_controller": getattr(self.midi_handler, 'pinned_id', None),
            # Colonne centrale (menu Affichage) : media / live / pads / none
            "center_view": getattr(self, '_center_view_key', 'media'),
            # Dernier mode DMX retenu par fixture (bibliothèque)
            "fixture_mode_prefs": dict(getattr(self, '_fixture_mode_prefs', {})),
            # Régies vidéo (source à l'antenne → lumière). Si la liaison n'a
            # jamais été instanciée cette session, on réécrit la config lue au
            # démarrage telle quelle : sans ça, une sauvegarde auto effacerait
            # le réglage de tous ceux qui n'ouvrent pas le menu à chaque
            # lancement.
            "vmix": (self._vmix_link.to_config()
                     if getattr(self, '_vmix_link', None) is not None
                     else dict(getattr(self, '_vmix_config_pending', {}) or {})),
            "obs": (self._obs_link.to_config()
                    if getattr(self, '_obs_link', None) is not None
                    else dict(getattr(self, '_obs_config_pending', {}) or {})),
            "gamepad": (self._gamepad_link.to_config()
                        if getattr(self, '_gamepad_link', None) is not None
                        else dict(getattr(self, '_gamepad_config_pending', {}) or {})),
        }

    def _apply_akai_config(self, config):
        """Applique une config AKAI (memoires) depuis un dict"""
        mem_data = config.get("memories")
        custom_colors_data = config.get("memory_custom_colors")
        active_pads_data = config.get("active_memory_pads")

        self.memories = [[None]*8 for _ in range(_MEM_COL_MAX)]
        self.memory_custom_colors = [[None]*8 for _ in range(_MEM_COL_MAX)]
        self.active_memory_pads = {}

        # ── Restore des PAGES de layout (avec compat ascendante) ──────────────
        def _migrate_slots(slots):
            # Convertit les anciens slots "groups": ["face"] → "group": "A"
            out = []
            for s in slots:
                if s.get("type") == "group" and "groups" in s and "group" not in s:
                    old_groups = s["groups"]
                    letter = _AKAI_GROUP_REVERSE.get(old_groups[0], "A") if old_groups else "A"
                    out.append({"type": "group", "group": letter, "label": s.get("label", letter)})
                else:
                    out.append(dict(s))
            return out

        bank_pages = config.get("bank_pages")
        if isinstance(bank_pages, list) and bank_pages:
            pages = [_migrate_slots(p) for p in bank_pages
                     if isinstance(p, list) and len(p) == 8]
            if pages:
                self._bank_pages = pages
                self._bank_page_idx = max(0, min(int(config.get("bank_page_idx", 0)), len(pages) - 1))
                self._custom_bank_slots = self._bank_pages[self._bank_page_idx]
        else:
            # Ancien format = layout unique → une seule page
            custom_slots = config.get("custom_bank_slots")
            if custom_slots and isinstance(custom_slots, list) and len(custom_slots) == 8:
                single = _migrate_slots(custom_slots)
            else:
                old_idx = config.get("bank_preset_idx", 0)
                old_idx = old_idx if 0 <= old_idx < len(AKAI_BANK_PRESETS) else 0
                single = [dict(s) for s in AKAI_BANK_PRESETS[old_idx]["slots"]]
            self._bank_pages = [single]
            # Migration unique : injecter les presets déjà enregistrés par l'utilisateur
            # comme pages suivantes (2, 3, 4…), puisque le système de presets est remplacé
            # par les pages. Ne s'exécute qu'à la 1re bascule vers le format "bank_pages".
            try:
                _user_presets = AkaiLayoutEditorDialog._read_user_presets()
            except Exception:
                _user_presets = []
            for _up in _user_presets:
                _sl = _up.get("slots") if isinstance(_up, dict) else None
                if (isinstance(_sl, list) and len(_sl) == 8
                        and len(self._bank_pages) < _N_BANK_PAGES):
                    self._bank_pages.append(_migrate_slots(_sl))
            self._bank_page_idx = 0
            self._custom_bank_slots = self._bank_pages[0]

        # Toujours garantir _N_BANK_PAGES pages (padding des configs plus anciens)
        while len(self._bank_pages) < _N_BANK_PAGES:
            self._bank_pages.append([dict(s) for s in AKAI_BANK_PRESETS[0]["slots"]])
        self._bank_page_idx = max(0, min(self._bank_page_idx, len(self._bank_pages) - 1))
        self._custom_bank_slots = self._bank_pages[self._bank_page_idx]

        if mem_data and isinstance(mem_data, list):
            if len(mem_data) >= 1 and isinstance(mem_data[0], list):
                for mc in range(min(_MEM_COL_MAX, len(mem_data))):
                    for mr in range(min(8, len(mem_data[mc]))):
                        self.memories[mc][mr] = mem_data[mc][mr]

        if custom_colors_data and isinstance(custom_colors_data, list):
            for mc in range(min(_MEM_COL_MAX, len(custom_colors_data))):
                for mr in range(min(8, len(custom_colors_data[mc]))):
                    c = custom_colors_data[mc][mr]
                    self.memory_custom_colors[mc][mr] = QColor(c) if c else None

        # Restore FX pads assignments
        fx_pads_data = config.get("fx_pads")
        if fx_pads_data and isinstance(fx_pads_data, list):
            for fc in range(min(_FX_COL_MAX, len(fx_pads_data))):
                if isinstance(fx_pads_data[fc], list):
                    for fr in range(min(8, len(fx_pads_data[fc]))):
                        self.fx_pads[fc][fr] = fx_pads_data[fc][fr]

        # Fader 9 toujours en mode FX
        self._last_fader_mode = "FX"

        # Superposition d'effets
        self.effect_superposition = config.get("effect_superposition", False)

        # Mode GO
        self.go_mode = config.get("go_mode", False)
        self._update_tap_go_btn_style()

        # active_memory_pads non restaure : toujours demarrer sans pad actif
        # (evite le pad du haut "toujours enclenche" au demarrage)

        # Rafraichir l'affichage des pads memoire
        for fi, mc in self._bank_memory_slots():
            for mr in range(8):
                is_active = self.active_memory_pads.get(fi) == mr
                self._style_memory_pad(mc, mr, active=is_active)

        # Restaurer les positions lyre
        pos_presets = config.get("position_presets")
        if isinstance(pos_presets, list):
            self.position_presets = pos_presets
        pos_pads_data = config.get("position_pads")
        self.position_pads = [[None]*8 for _ in range(_POS_COL_MAX)]
        if isinstance(pos_pads_data, list):
            for pc in range(min(_POS_COL_MAX, len(pos_pads_data))):
                if isinstance(pos_pads_data[pc], list):
                    for pr in range(min(8, len(pos_pads_data[pc]))):
                        self.position_pads[pc][pr] = pos_pads_data[pc][pr]
        else:
            # Migration : ancien format 1D position_pad_assignments → col 0
            old_assignments = config.get("position_pad_assignments")
            if isinstance(old_assignments, list):
                for pr in range(min(8, len(old_assignments))):
                    self.position_pads[0][pr] = old_assignments[pr]
        self.active_position_pads = {}

        # Restaurer le pan/tilt courant de chaque lyre (position physique dernière session)
        lyre_positions = config.get("lyre_positions", {})
        if lyre_positions and hasattr(self, 'projectors'):
            lyre_by_name = {p.name: p for p in self.projectors
                            if getattr(p, 'fixture_type', '') in ('Moving Head', 'Lyre')}
            for name, pt in lyre_positions.items():
                p = lyre_by_name.get(name)
                if p:
                    p.pan  = int(pt.get("pan",  32768))
                    p.tilt = int(pt.get("tilt", 32768))

        # Luminosité APC Mini — respecte le réglage sauvegardé (ou auto-détection Apple Silicon)
        if "apc_bright_mode" in config and hasattr(self, 'midi_handler') and self.midi_handler:
            self.midi_handler.set_apc_bright_mode(bool(config["apc_bright_mode"]))
        if "akai_active_brightness" in config:
            self.akai_active_brightness   = int(config["akai_active_brightness"])
        if "akai_inactive_brightness" in config:
            self.akai_inactive_brightness = int(config["akai_inactive_brightness"])
        if "light_sync_offset_ms" in config:
            self.light_sync_offset_ms = int(config.get("light_sync_offset_ms", 0) or 0)

        # Colonne centrale (menu Affichage) : retrouver la vue quittée.
        # Différé : _set_center_view touche le séquenceur et la surface Pads,
        # qui ne sont pas encore prêts quand la config est appliquée.
        _cv = config.get("center_view")
        if _cv in ("media", "live", "pads", "none"):
            QTimer.singleShot(0, lambda k=_cv: self._restore_center_view(k))

        _fmp = config.get("fixture_mode_prefs")
        if isinstance(_fmp, dict):
            self._fixture_mode_prefs = {str(k): str(v) for k, v in _fmp.items()
                                        if isinstance(v, str)}

        # Régies vidéo : on mémorise la config sans instancier la liaison. Elle
        # n'est créée — et la socket ouverte — que si l'utilisateur avait coché
        # « Activer », ou s'il ouvre le menu. Le démarrage est différé : ici,
        # les mémoires et les cartouches ne sont pas encore en place, et un
        # événement reçu dans la seconde déclencherait une action dans le vide.
        # La config est TOUJOURS relue et re-sauvée (rien n'est perdu pour ceux
        # qui l'avaient déjà réglée), mais tant que le drapeau est False on
        # n'ouvre pas la socket : le menu étant masqué, personne ne pourrait
        # plus désactiver une liaison qui démarrerait toute seule.
        _vm = config.get("vmix")
        if isinstance(_vm, dict):
            self._vmix_config_pending = dict(_vm)
            if _vm.get("enabled") and VMIX_ENABLED:
                QTimer.singleShot(1500, self._start_vmix_if_enabled)

        _obs = config.get("obs")
        if isinstance(_obs, dict):
            self._obs_config_pending = dict(_obs)
            if _obs.get("enabled") and OBS_ENABLED:
                QTimer.singleShot(1500, self._start_obs_if_enabled)

        # Manette : même création paresseuse. Le démarrage différé importe moins
        # ici (aucune action n'est déclenchée, seul le pan/tilt bouge), mais les
        # projecteurs doivent exister avant que le premier mouvement n'arrive.
        _gp = config.get("gamepad")
        if isinstance(_gp, dict):
            self._gamepad_config_pending = dict(_gp)
            if _gp.get("enabled"):
                QTimer.singleShot(1500, self._start_gamepad_if_enabled)

        # Contrôleur épinglé (sélection manuelle) — reconnecte sur le bon si défini
        if hasattr(self, 'midi_handler') and self.midi_handler:
            pinned = config.get("pinned_controller")
            self.midi_handler.pinned_id = pinned or None
            if pinned:
                self.midi_handler.connect_controller()

        # Les pads FX et POS seront rafraîchis lors du prochain _rebuild_akai_pads()

    def _save_akai_config_auto(self):
        """Sauvegarde automatique de la config AKAI (mémoires) à la fermeture.

        Écriture ATOMIQUE (fichier temporaire + os.replace) pour ne jamais laisser
        un fichier tronqué si l'app crashe pendant l'écriture. Et FILET DE SÉCURITÉ :
        si on s'apprête à écrire une grille de mémoires VIDE par-dessus un fichier
        qui en contenait (typiquement après un chargement raté qui a réinitialisé
        self.memories), on archive d'abord l'ancien fichier en .bak horodaté —
        sinon les mémoires du musicien seraient perdues définitivement.
        """
        try:
            import shutil
            config = self._serialize_akai_config()
            path = self._AKAI_CONFIG_PATH

            new_mem = config.get("memories") or []
            new_has_mem = any(
                cell is not None
                for col in new_mem if isinstance(col, list)
                for cell in col
            )
            if not new_has_mem and os.path.exists(path):
                try:
                    with open(path, 'r') as f:
                        old_mem = (json.load(f) or {}).get("memories") or []
                    old_has_mem = any(
                        cell is not None
                        for col in old_mem if isinstance(col, list)
                        for cell in col
                    )
                    if old_has_mem:
                        bak = f"{path}.{time.strftime('%Y%m%d-%H%M%S')}.bak"
                        shutil.copy2(path, bak)
                        print(f"[AKAI] Mémoires vides à écrire — ancien fichier archivé : {bak}")
                except Exception:
                    pass

            tmp = path + ".tmp"
            with open(tmp, 'w') as f:
                json.dump(config, f, indent=2)
            os.replace(tmp, path)
        except Exception as e:
            print(f"Erreur sauvegarde config AKAI: {e}")

    def _load_akai_config_auto(self):
        """Charge automatique de la config AKAI au demarrage.
        Premier lancement (pas de fichier) : applique les presets par defaut."""
        try:
            if not os.path.exists(self._AKAI_CONFIG_PATH):
                # Premier lancement : charger les presets par defaut
                print("Premier lancement : application des presets AKAI par defaut")
                self._apply_akai_config(self._build_default_akai_presets())
                self._save_akai_config_auto()
            else:
                try:
                    with open(self._AKAI_CONFIG_PATH, 'r') as f:
                        config = json.load(f)
                except Exception as parse_err:
                    # Fichier illisible/corrompu : NE PAS continuer vers un état vide
                    # qui serait ensuite ré-écrit par-dessus (perte des mémoires).
                    # On archive le fichier corrompu pour récupération manuelle et on
                    # relève l'erreur — la config par défaut ne sera pas persistée ici.
                    import shutil
                    bak = f"{self._AKAI_CONFIG_PATH}.corrupt-{time.strftime('%Y%m%d-%H%M%S')}"
                    try:
                        shutil.copy2(self._AKAI_CONFIG_PATH, bak)
                        print(f"[AKAI] Config corrompue archivée : {bak}")
                    except Exception:
                        pass
                    raise parse_err
                self._apply_akai_config(config)
                # Migrer uniquement si le fichier n'a pas de section memories explicite
                # (vieux fichier de config sans memories) — évite d'écraser un effacement volontaire
                if "memories" not in config:
                    self._migrate_missing_pad_colors()
            # Reconstruire les pads/faders avec le layout restauré
            if hasattr(self, '_pads_container'):
                self._rebuild_akai_pads()
                if hasattr(self, '_fader_label_widgets'):
                    for i, lbl in enumerate(self._fader_label_widgets):
                        if i < len(self._fader_map):
                            lbl.setText(_fader_label_text(self._fader_map[i]["label"]))
                            lbl.setToolTip(_fader_label_tooltip(self._fader_map[i]))
            self._update_bank_page_indicator()   # reflète le nombre de pages chargées
            # Toujours activer le pad du haut de chaque colonne memoire au demarrage.
            # (Les faders sont forcés BAISSÉS au lancement par _startup_faders_down, ~650 ms
            # après l'init — après les syncs de connexion — pour rien allumer au démarrage.)
            self._activate_top_pads_default()
        except Exception as e:
            print(f"Erreur chargement config AKAI: {e}")

    # Couleurs de rangee par defaut (meme ordre que la grille AKAI cols 0-3)
    _DEFAULT_PAD_ROW_COLORS = [
        "#ffffff", "#ff0000", "#ff8800", "#ffdd00",
        "#00ff00", "#00dddd", "#0000ff", "#ff00ff",
    ]

    def _migrate_missing_pad_colors(self):
        """Migration : pour toute colonne memoire sans couleurs ou sans memoires,
        applique les presets par defaut (couleurs de rangee + snapshots DMX).
        S'execute une seule fois apres chargement d'un ancien fichier de config."""
        needs_save = False
        _presets = None  # charge les presets une seule fois si necessaire

        for mc in range(8):
            has_colors   = any(self.memory_custom_colors[mc][mr] is not None for mr in range(8))
            has_memories = any(self.memories[mc][mr] is not None for mr in range(8))

            if not has_colors or not has_memories:
                if _presets is None:
                    _presets = self._build_default_akai_presets()

                if not has_memories and mc < len(_presets["memories"]):
                    for mr in range(8):
                        self.memories[mc][mr] = _presets["memories"][mc][mr]

                if not has_colors:
                    for mr in range(8):
                        self.memory_custom_colors[mc][mr] = QColor(self._DEFAULT_PAD_ROW_COLORS[mr])

                col_akai = self._mem_col_to_fader(mc)
                for mr in range(8):
                    is_active = self.active_memory_pads.get(col_akai) == mr
                    self._style_memory_pad(mc, mr, active=is_active)

                needs_save = True
                print(f"Migration : colonne memoire {mc + 1} mise a jour")

        if needs_save:
            self._save_akai_config_auto()

    def _activate_top_pads_default(self):
        """Active le pad du haut (rangee 0) de chaque colonne memoire.
        Appele au demarrage. Les LEDs physiques AKAI sont envoyees par
        activate_default_white_pads() qui se declenche 100ms apres l'init."""
        for fi, mc in self._bank_memory_slots():
            if self.memories[mc][0] is not None:
                self.active_memory_pads[fi] = 0
                self._style_memory_pad(mc, 0, active=True)
                self._apply_memory_to_projectors(mc, 0)

    def _build_default_akai_presets(self) -> dict:
        """
        Construit les presets par défaut pour les 8 colonnes MEM (mc 0-7).

        Chaque LIGNE correspond à une couleur :
          Row 0 : Blanc   #ffffff
          Row 1 : Rouge   #ff0000
          Row 2 : Orange  #ff8800
          Row 3 : Jaune   #ffdd00
          Row 4 : Vert    #00ff00
          Row 5 : Cyan    #00dddd
          Row 6 : Bleu    #0000ff
          Row 7 : Magenta #ff00ff

        Chaque COLONNE correspond à une combinaison de groupes :
          MEM 1 (mc=0) : Tous les groupes
          MEM 2 (mc=1) : Face
          MEM 3 (mc=2) : Contre
          MEM 4 (mc=3) : LAT
          MEM 5 (mc=4) : Douches (douche1+2+3)
          MEM 6 (mc=5) : Face + LAT
          MEM 7 (mc=6) : Face + Contre
          MEM 8 (mc=7) : LAT + Contre
        """

        ROW_COLORS = [
            "#ffffff",  # Row 0 : Blanc
            "#ff0000",  # Row 1 : Rouge
            "#ff8800",  # Row 2 : Orange
            "#ffdd00",  # Row 3 : Jaune
            "#00ff00",  # Row 4 : Vert
            "#00dddd",  # Row 5 : Cyan
            "#0000ff",  # Row 6 : Bleu
            "#ff00ff",  # Row 7 : Magenta
        ]

        COL_GROUPS = [
            {"face", "douche1", "douche2", "douche3", "lat", "contre"},  # MEM 1 : Tous
            {"face"},                                                      # MEM 2 : Face
            {"contre"},                                                    # MEM 3 : Contre
            {"lat"},                                                       # MEM 4 : LAT
            {"douche1", "douche2", "douche3"},                            # MEM 5 : Douches
            {"face", "lat"},                                               # MEM 6 : Face + LAT
            {"face", "contre"},                                            # MEM 7 : Face + Contre
            {"lat", "contre"},                                             # MEM 8 : LAT + Contre
        ]

        def make_snapshot(color, active_groups):
            snapshot = []
            for fixture in self.projectors:
                grp = fixture.group
                if grp in active_groups:
                    snapshot.append({"group": grp, "base_color": color, "level": 100})
                else:
                    snapshot.append({"group": grp, "base_color": "#000000", "level": 0})
            return {"projectors": snapshot}

        memories      = [[None] * 8 for _ in range(8)]
        custom_colors = [[None] * 8 for _ in range(8)]

        for mc, groups in enumerate(COL_GROUPS):
            for row, color in enumerate(ROW_COLORS):
                memories[mc][row]      = make_snapshot(color, groups)
                custom_colors[mc][row] = color

        return {
            "memories": memories,
            "memory_custom_colors": custom_colors,
            "active_memory_pads": {},
        }

    def load_default_presets(self):
        """Charge (ou restaure) les 8 colonnes MEM par défaut."""
        reply = QMessageBox.question(
            self,
            tr("load_mem_title"),
            tr("load_mem_question"),
            QMessageBox.Yes | QMessageBox.Cancel
        )
        if reply != QMessageBox.Yes:
            return

        presets = self._build_default_akai_presets()

        # Stocker les données pour les 8 colonnes
        for mc in range(8):
            for mr in range(8):
                self.memories[mc][mr] = presets["memories"][mc][mr]
                c = presets["memory_custom_colors"][mc][mr]
                self.memory_custom_colors[mc][mr] = QColor(c) if c else None

        # Reconstruire l'affichage complet (rafraîchit MEM 5-8 quelle que soit la banque active)
        if hasattr(self, '_pads_container'):
            self._rebuild_akai_pads()
        self._activate_top_pads_default()
        # Synchroniser les LEDs physiques AKAI
        self.activate_default_white_pads()
        self._save_akai_config_auto()
        QMessageBox.information(
            self, tr("load_mem_success_title"),
            tr("load_mem_success_msg")
        )

    # ── Fenêtre « Effacer des données » ───────────────────────────────────
    #
    # L'entrée de menu effaçait autrefois les mémoires, et rien d'autre, sans
    # rien demander. Impossible de vider les seules positions, ou de repartir
    # d'effets propres en gardant ses mémoires. Chaque entrepôt de données est
    # donc listé ici, avec son décompte, et coché individuellement.
    #
    # Les positions vivent dans DEUX fichiers (pads POS de l'AKAI d'un côté,
    # presets du Plan de Feu de l'autre) : ils apparaissent sur deux lignes
    # distinctes, sans quoi « effacer les positions » en laisserait la moitié
    # en place.

    def _clearable_items(self):
        """[(clé, groupe, libellé, aide, nombre)] — l'inventaire de ce qui est effaçable.

        Le décompte sert autant à informer qu'à désactiver les lignes vides :
        proposer d'effacer un entrepôt déjà vide n'apporte rien.
        """
        try:
            from effect_editor import _load_custom_effects
            n_custom = len(_load_custom_effects() or [])
        except Exception:
            n_custom = 0

        n_mem = sum(1 for mc in range(_MEM_COL_MAX) for mr in range(8)
                    if self.memories[mc][mr] is not None)
        n_pos = len(getattr(self, 'position_presets', []) or [])
        n_fx = sum(1 for fc in range(_FX_COL_MAX) for fr in range(8)
                   if self.fx_pads[fc][fr])
        n_btn = len(getattr(self, '_button_effect_configs', {}) or {})
        n_lib = n_custom + len(getattr(self, '_effect_library_configs', {}) or {})
        # `_load_pdf_presets` retombe sur les presets d'usine quand le fichier
        # n'existe pas : compter son retour ferait croire qu'il y a toujours
        # quelque chose à effacer. Seul un fichier réellement écrit compte.
        try:
            from plan_de_feu import _PRESETS_FILE
            n_pdf = len(self._load_pdf_presets() or []) if os.path.exists(_PRESETS_FILE) else 0
        except Exception:
            n_pdf = 0
        n_seq = len(getattr(getattr(self, 'seq', None), 'sequences', {}) or {})

        return [
            ("mem", "pads", tr("clr_it_mem"), tr("clr_hint_mem"), n_mem),
            ("pos", "pads", tr("clr_it_pos"), tr("clr_hint_pos"), n_pos),
            ("fx",  "pads", tr("clr_it_fx"),  tr("clr_hint_fx"),  n_fx),
            ("btn", "pads", tr("clr_it_btn"), tr("clr_hint_btn"), n_btn),
            ("lib", "lib",  tr("clr_it_lib"), tr("clr_hint_lib"), n_lib),
            ("pdf", "lib",  tr("clr_it_pdf"), tr("clr_hint_pdf"), n_pdf),
            ("seq", "show", tr("clr_it_seq"), tr("clr_hint_seq"), n_seq),
        ]

    def clear_all_memories(self):
        """Ouvre la fenêtre de choix, puis efface ce qui a été coché."""
        items = self._clearable_items()
        if not any(n for _k, _g, _l, _h, n in items):
            self._show_mem_toast(tr("clr_nothing"))
            return

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("clr_dlg_title"))
        dlg.setStyleSheet(
            "QDialog { background:#141414; }"
            "QLabel { color:#ddd; background:transparent; }"
            "QCheckBox { color:#e0e0e0; background:transparent; font-size:12px; spacing:8px; }"
            "QCheckBox:disabled { color:#555; }"
            "QCheckBox::indicator { width:15px; height:15px; border-radius:3px; "
            "border:1px solid #3a3a3a; background:#0d0d0d; }"
            "QCheckBox::indicator:checked { background:#cc3333; border-color:#ff6666; }"
            "QCheckBox::indicator:disabled { border-color:#252525; background:#111; }"
            "QPushButton { background:#2a2a2a; color:#ddd; border:1px solid #3a3a3a; "
            "border-radius:5px; padding:6px 16px; font-size:11px; }"
            "QPushButton:hover { background:#3a3a3a; color:#fff; }"
        )
        root = QVBoxLayout(dlg)
        root.setContentsMargins(18, 16, 18, 14)
        root.setSpacing(10)

        intro = QLabel(tr("clr_dlg_intro"))
        intro.setStyleSheet("color:#999; font-size:11px;")
        intro.setWordWrap(True)
        root.addWidget(intro)

        checks = {}
        group_titles = {"pads": tr("clr_grp_pads"), "lib": tr("clr_grp_lib"),
                        "show": tr("clr_grp_show")}
        cur_group = None
        for key, group, label, hint, count in items:
            if group != cur_group:
                cur_group = group
                hdr = QLabel(group_titles[group])
                hdr.setStyleSheet("color:#666; font-size:9px; font-weight:bold; "
                                  "letter-spacing:1px; margin-top:6px;")
                root.addWidget(hdr)

            chk = QCheckBox(f"{label}  —  "
                            + (tr("clr_count", n=count) if count else tr("clr_empty")))
            chk.setToolTip(hint)
            chk.setEnabled(count > 0)
            root.addWidget(chk)

            sub = QLabel(hint)
            sub.setStyleSheet("color:#5a5a5a; font-size:9px; margin-left:23px;")
            sub.setWordWrap(True)
            root.addWidget(sub)

            checks[key] = (chk, label, count)

        # ── Boutons ───────────────────────────────────────────────────────
        sep = QFrame(); sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet("background:#262626; max-height:1px; margin-top:8px;")
        root.addWidget(sep)

        btn_row = QHBoxLayout()
        all_btn = QPushButton(tr("clr_select_all"))
        all_btn.setStyleSheet("QPushButton { background:transparent; color:#777; border:none; "
                              "font-size:10px; padding:4px 6px; } QPushButton:hover { color:#ccc; }")
        none_btn = QPushButton(tr("clr_select_none"))
        none_btn.setStyleSheet(all_btn.styleSheet())
        all_btn.clicked.connect(
            lambda: [c.setChecked(True) for c, _l, n in checks.values() if n])
        none_btn.clicked.connect(
            lambda: [c.setChecked(False) for c, _l, _n in checks.values()])
        btn_row.addWidget(all_btn)
        btn_row.addWidget(none_btn)
        btn_row.addStretch()

        cancel = QPushButton(tr("mw_cancel"))
        cancel.clicked.connect(dlg.reject)
        btn_row.addWidget(cancel)

        delete = QPushButton(tr("clr_btn_delete"))
        delete.setStyleSheet(
            "QPushButton { background:#7a1e1e; color:#fff; border:none; border-radius:5px; "
            "padding:6px 18px; font-size:11px; font-weight:bold; } "
            "QPushButton:hover { background:#9c2727; } "
            "QPushButton:disabled { background:#2a1c1c; color:#5a4444; }"
        )
        delete.setEnabled(False)
        delete.clicked.connect(dlg.accept)
        btn_row.addWidget(delete)
        root.addLayout(btn_row)

        def _sync_delete():
            delete.setEnabled(any(c.isChecked() for c, _l, _n in checks.values()))
        for c, _l, _n in checks.values():
            c.toggled.connect(_sync_delete)

        if dlg.exec() != QDialog.Accepted:
            return

        selected = [k for k, (c, _l, _n) in checks.items() if c.isChecked()]
        if not selected:
            return

        recap = "\n".join("  • " + checks[k][1] + f"  ({checks[k][2]})" for k in selected)
        if QMessageBox.warning(
            self, tr("clr_confirm_title"), tr("clr_confirm_msg", list=recap),
            QMessageBox.Yes | QMessageBox.Cancel
        ) != QMessageBox.Yes:
            return

        self._perform_clear(selected)
        self._show_mem_toast(tr("clr_done", list=", ".join(checks[k][1] for k in selected)))

    def _perform_clear(self, keys):
        """Efface les entrepôts demandés. `keys` ⊂ clés de `_clearable_items`."""
        keys = set(keys)
        touches_akai_config = bool(keys & {"mem", "pos", "fx"})

        if "mem" in keys:
            for mc in range(_MEM_COL_MAX):
                for mr in range(8):
                    self.memories[mc][mr] = None
                    self.memory_custom_colors[mc][mr] = None
            self.active_memory_pads.clear()
            self._mem_cue_idx.clear()
            # Éteindre les LEDs physiques de tous les pads mémoire sur l'AKAI
            if MIDI_AVAILABLE and hasattr(self, 'midi_handler') and self.midi_handler.midi_out:
                for fi, _mc in self._bank_memory_slots():
                    for mr in range(8):
                        note = (7 - mr) * 8 + fi
                        self.midi_handler.midi_out.send_message([0x90, note, 0])

        if "pos" in keys:
            self.position_presets = []
            self.position_pads = [[None] * 8 for _ in range(_POS_COL_MAX)]
            self.active_position_pads.clear()
            for pc in range(_POS_COL_MAX):
                for pr in range(8):
                    self._update_pos_pad_led(pc, pr)

        if "fx" in keys:
            # Un pad FX actif tient un effet en cours : le couper AVANT de vider
            # la config, sinon l'effet continue de tourner sans pad pour l'éteindre.
            if self.active_fx_pads:
                try:
                    self.stop_effect()
                except Exception as e:
                    print(f"[CLEAR] arrêt de l'effet FX impossible : {e}")
            self.active_fx_pads.clear()
            for fc in range(_FX_COL_MAX):
                for fr in range(8):
                    self.fx_pads[fc][fr] = None
                    self._update_fx_pad_led(fc, fr)

        if "btn" in keys:
            for i in range(len(self.effect_buttons)):
                self._on_effect_assigned(i, None)

        if "lib" in keys:
            try:
                from effect_editor import _save_custom_effects
                _save_custom_effects([])
            except Exception as e:
                print(f"[CLEAR] effets personnalisés non effacés : {e}")
            self._effect_library_configs = {}
            self._save_effect_library()

        if "pdf" in keys:
            # Fichier absent = le Plan de Feu repart sur ses positions d'usine,
            # exactement comme son bouton « ↺ ».
            try:
                from plan_de_feu import _PRESETS_FILE
                if os.path.exists(_PRESETS_FILE):
                    os.remove(_PRESETS_FILE)
            except Exception as e:
                print(f"[CLEAR] positions Plan de Feu non effacées : {e}")
            self._refresh_open_pdf_preset_bars()

        if "seq" in keys:
            # _remove_play_lumiere remet aussi le combo DMX de la ligne sur
            # Manuel : sans ça la playlist garderait un mode « Play Lumière »
            # pointant vers une séquence disparue.
            try:
                for row in list(getattr(self.seq, 'sequences', {}).keys()):
                    self.seq._remove_play_lumiere(row)
                self.seq.sequences.clear()
            except Exception as e:
                print(f"[CLEAR] séquences REC Lumière non effacées : {e}")

        self._rebuild_akai_pads()
        if touches_akai_config:
            self._save_akai_config_auto()

    def _refresh_open_pdf_preset_bars(self):
        """Recharge les presets des barres Plan de Feu déjà ouvertes.

        Le fichier fait foi, mais une fenêtre ouverte garde sa copie en mémoire
        et réécrirait les presets supprimés à la première sauvegarde.
        """
        try:
            from plan_de_feu import PresetBar, _load_presets
        except Exception:
            return
        for w in QApplication.allWidgets():
            if isinstance(w, PresetBar):
                try:
                    w._presets = _load_presets()
                    w._rebuild_buttons()
                except Exception as e:
                    print(f"[CLEAR] barre de presets non rafraîchie : {e}")

    def load_default_effects(self):
        """Charge les effets par défaut sur les boutons E1-E9."""
        reply = QMessageBox.question(
            self,
            tr("load_fx_title"),
            tr("load_fx_question"),
            QMessageBox.Yes | QMessageBox.Cancel
        )
        if reply != QMessageBox.Yes:
            return

        from effect_editor import BUILTIN_EFFECTS

        # 9 effets bien différents les uns des autres
        DEFAULT_EFFECTS = [
            "Strobe Classique",  # E1 : stroboscopique pur
            "Chase Doux",        # E2 : chase fluide avec fade
            "Pulse Doux",        # E3 : respiration lente
            "Rainbow",           # E4 : arc-en-ciel décalé
            "Comète",            # E5 : comète avec trainée
            "Bascule",           # E6 : bascule pair/impair
            "Ping Pong",         # E7 : aller-retour bounce
            "Police",            # E8 : rouge/bleu alternance
            "Spectre",           # E9 : rainbow large et lent
        ]

        effects_by_name = {e["name"]: e for e in BUILTIN_EFFECTS}
        assigned = []
        for i, name in enumerate(DEFAULT_EFFECTS):
            eff = effects_by_name.get(name)
            if not eff:
                continue
            cfg = {
                "name":   name,
                "type":   eff.get("type", ""),
                "layers": eff["layers"],
            }
            self._on_effect_assigned(i, cfg)
            assigned.append(f"E{i+1} : {name}")

        self._save_effect_assignments()
        QMessageBox.information(
            self, tr("load_fx_success_title"),
            tr("load_fx_success_msg", list="\n".join(assigned))
        )

    def export_akai_config(self):
        """Exporte la configuration AKAI dans un fichier"""
        path, _ = QFileDialog.getSaveFileName(
            self, tr("export_akai_title"), "",
            tr("akai_cfg_filter"))
        if not path:
            return
        if not path.endswith('.akai.json'):
            path += '.akai.json'
        try:
            config = self._serialize_akai_config()
            # Option A : la disposition de la fenêtre EXT est incluse dans le même fichier
            ext_layout = self._get_ext_layout_data()
            if ext_layout is not None:
                config["ext_layout"] = ext_layout
            with open(path, 'w') as f:
                json.dump(config, f, indent=2)
            QMessageBox.information(self, tr("export_ok_title"), tr("export_ok_msg"))
        except Exception as e:
            QMessageBox.critical(self, tr("err_save_title"), tr("export_err_msg", e=e))

    def import_akai_config(self):
        """Importe une configuration AKAI depuis un fichier"""
        path, _ = QFileDialog.getOpenFileName(
            self, tr("import_akai_title"), "",
            tr("akai_cfg_filter"))
        if not path:
            return
        try:
            with open(path, 'r') as f:
                config = json.load(f)
            self._apply_akai_config(config)
            # Option A : restaure aussi la disposition EXT si le fichier en contient une
            if isinstance(config.get("ext_layout"), dict):
                self._apply_ext_layout(config["ext_layout"])
            QMessageBox.information(self, tr("import_ok_title"), tr("import_ok_msg"))
        except Exception as e:
            QMessageBox.critical(self, tr("err_save_title"), tr("import_err_msg", e=e))

    def _get_ext_layout_data(self):
        """Disposition EXT courante (fenêtre ouverte) ou lue depuis son fichier."""
        win = getattr(self, "_ext_window", None)
        if win is not None:
            try:
                return win._layout_data()
            except Exception:
                pass
        try:
            from ext_window import ExtWindow
            if os.path.exists(ExtWindow.LAYOUT_FILE):
                with open(ExtWindow.LAYOUT_FILE, 'r', encoding='utf-8') as f:
                    return json.load(f)
        except Exception:
            pass
        return None

    def _apply_ext_layout(self, data):
        """Écrit la disposition EXT importée et recharge la fenêtre si elle est ouverte."""
        try:
            from ext_window import ExtWindow
            with open(ExtWindow.LAYOUT_FILE, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"[EXT] Échec écriture layout importé : {e}")
            return
        win = getattr(self, "_ext_window", None)
        if win is not None:
            try:
                win.reload_layout()
            except Exception as e:
                print(f"[EXT] Échec rechargement layout : {e}")

    # ==================== FIN CONFIG AKAI ====================

    def load_recent_files(self):
        """Charge la liste des fichiers recents"""
        try:
            recent_path = os.path.join(os.path.expanduser("~"), ".maestro_recent.json")
            if os.path.exists(recent_path):
                with open(recent_path, 'r') as f:
                    return json.load(f)
        except:
            pass
        return []

    def save_recent_files(self):
        """Sauvegarde la liste des fichiers recents"""
        try:
            recent_path = os.path.join(os.path.expanduser("~"), ".maestro_recent.json")
            with open(recent_path, 'w') as f:
                json.dump(self.recent_files, f)
        except:
            pass

    def add_recent_file(self, filepath):
        """Ajoute un fichier a la liste des recents"""
        if filepath in self.recent_files:
            self.recent_files.remove(filepath)
        self.recent_files.insert(0, filepath)
        self.recent_files = self.recent_files[:10]
        self.save_recent_files()
        self.update_recent_menu()

    def update_recent_menu(self):
        """Met a jour le menu des fichiers recents"""
        self.recent_menu.clear()
        if not self.recent_files:
            action = self.recent_menu.addAction(tr("menu_no_recent"))
            action.setEnabled(False)
            return
        for filepath in self.recent_files:
            if os.path.exists(filepath):
                filename = os.path.basename(filepath)
                action = self.recent_menu.addAction(filename)
                action.setData(filepath)
                action.triggered.connect(self.load_recent_file)

    def load_recent_file(self):
        """Charge un fichier depuis le menu recent"""
        action = self.sender()
        if action:
            filepath = action.data()
            self.load_show(filepath)

    def reconnect_midi(self):
        """Force la reconnexion MIDI"""
        if not MIDI_AVAILABLE:
            QMessageBox.information(self, tr("midi_unavail_title"), tr("midi_unavail_msg"))
            return

        try:
            self.midi_handler.connect_akai()
            if self.midi_handler.midi_in and self.midi_handler.midi_out:
                QTimer.singleShot(200, self.activate_default_white_pads)
                QTimer.singleShot(300, self.turn_off_all_effects)
                QTimer.singleShot(400, self._sync_faders_to_projectors)
                QMessageBox.information(self, tr("midi_reconnect_title"), tr("midi_reconnect_msg"))
        except Exception as e:
            QMessageBox.critical(self, tr("err_save_title"), tr("midi_err_msg", e=e))

    def open_light_editor(self, row=None):
        """Ouvre l'editeur de sequence lumiere"""
        if self.player.playbackState() == QMediaPlayer.PlayingState:
            self.player.pause()

        if row is not None:
            current_row = row
        else:
            current_row = self.seq.table.currentRow()

        if current_row < 0:
            QMessageBox.warning(self, tr("no_media_title"), tr("no_media_msg"))
            return

        item = self.seq.table.item(current_row, 1)
        if not item or not item.data(Qt.UserRole):
            return

        path = item.data(Qt.UserRole)

        # Bloquer si pause indefinie
        if path == "PAUSE":
            QMessageBox.warning(self, tr("rec_light_title"), tr("rec_light_need_dur"))
            return

        # Bloquer si image sans duree definie
        if media_icon(path) == "image":
            if current_row not in self.seq.image_durations:
                QMessageBox.warning(self, tr("rec_light_title"), tr("rec_light_need_dur2"))
                return

        editor = LightTimelineEditor(self, current_row)
        editor.showMaximized()
        if sys.platform == 'win32':
            try:
                import ctypes as _ct
                _u32 = _ct.windll.user32
                _hwnd = int(editor.winId())
                _GWL_EXSTYLE = -20
                _cur = _u32.GetWindowLongW(_hwnd, _GWL_EXSTYLE)
                _u32.SetWindowLongW(_hwnd, _GWL_EXSTYLE,
                                    (_cur | 0x80) & ~0x40000)  # +TOOLWINDOW -APPWINDOW
            except Exception:
                pass
        editor.exec()

    def _undo_plan_2d(self):
        """Ctrl+Z : annule la dernière modification faite depuis le plan 2D.

        Sans effet — et sans bip — si rien n'a encore été touché.
        """
        try:
            if hasattr(self, 'plan_de_feu') and self.plan_de_feu.undo():
                self._log_message(tr("mw_undo_done"), "go")
        except Exception as e:
            print(f"[undo plan 2D] {e}")

    def _edit_current_volume(self):
        """Edite le volume du media selectionne (audio/video uniquement)"""
        row = self.seq.table.currentRow()
        if row < 0:
            QMessageBox.warning(self, tr("no_media2_title"), tr("no_media2_msg"))
            return
        title_item = self.seq.table.item(row, 1)
        if not title_item:
            return
        path = title_item.data(Qt.UserRole)
        if path and media_icon(path) in ("audio", "video"):
            self.seq.edit_media_volume(row)
        else:
            QMessageBox.warning(self, tr("not_applicable_title"), tr("vol_not_applicable"))

    def _edit_current_duration(self):
        """Edite la duree de l'image ou de la pause selectionnee"""
        row = self.seq.table.currentRow()
        if row < 0:
            QMessageBox.warning(self, tr("no_media2_title"), tr("no_elem_msg"))
            return
        title_item = self.seq.table.item(row, 1)
        if not title_item:
            return
        data = str(title_item.data(Qt.UserRole) or "")
        if data == "PAUSE" or data.startswith("PAUSE:"):
            self.seq.edit_pause_duration(row)
        elif media_icon(data) == "image":
            self.seq.edit_image_duration(row)
        else:
            QMessageBox.warning(self, tr("not_applicable_title"), tr("dur_not_applicable"))

