    def _dmx_locked_notice(self):
        """Explique pourquoi la sortie DMX est verrouillée et propose les plans.

        Remplace le grisage du menu Sortie DMX : l'entrée reste cliquable, et
        c'est ce message qui indique l'état de la licence puis ouvre la fenêtre
        « Choisir un plan » si l'utilisateur le souhaite.
        """
        state = getattr(self._license, 'state', None)
        if state == LicenseState.TRIAL_EXPIRED:
            reason = tr("dmx_lic_trial_over")
        elif state == LicenseState.LICENSE_EXPIRED:
            reason = tr("dmx_lic_license_over")
        else:
            reason = tr("dmx_lic_not_active")

        box = QMessageBox(self)
        box.setIcon(QMessageBox.Information)
        box.setWindowTitle(tr("dmx_lic_warn_title"))
        box.setText(reason)
        box.setInformativeText(tr("dmx_lic_locked_hint"))
        btn_plan = box.addButton(tr("btn_choose_plan"), QMessageBox.AcceptRole)
        box.addButton(tr("btn_close"), QMessageBox.RejectRole)
        box.setDefaultButton(btn_plan)
        box.exec()
        if box.clickedButton() is btn_plan:
            self._open_purchase_dialog()

    def _on_activation_success(self):
        """Appele apres une activation reussie - re-verifie et applique"""
        from license_manager import pop_login_result
        new_result = pop_login_result()
        if new_result is None:
            # Fallback : re-vérification Firebase si le résultat de login n'est pas disponible
            new_result = verify_license()
        print(f"[ACTIVATION] résultat licence: {new_result}")
        self._license = new_result

        # Rafraîchir la bannière
        self._apply_license_banner()

        # Activer/desactiver DMX
        if self._license.dmx_allowed:
            if not self.dmx.connected:
                dlg = LoginSuccessDialog(dmx_allowed=True, parent=self)
                if dlg.exec() == LoginSuccessDialog.ACTIVATE_DMX:
                    self.test_dmx_on_startup()
            else:
                LoginSuccessDialog(dmx_allowed=False, parent=self).exec()
        else:
            self.dmx.connected = False
            self.plan_de_feu.set_dmx_blocked()
            LoginSuccessDialog(dmx_allowed=False, parent=self).exec()

        # Le menu Sortie DMX reste toujours cliquable : la garde licence est portée
        # par les actions elles-mêmes (voir _dmx_locked_notice).

        # Watermark video integre
        if not self._license.watermark_required:
            if hasattr(self, '_video_watermark') and self._video_watermark:
                self._video_watermark.hide()
                self._video_watermark.deleteLater()
                self._video_watermark = None
        else:
            if not hasattr(self, '_video_watermark') or not self._video_watermark:
                self._setup_video_watermark()

        # Watermark fenetre de sortie video
        if self.video_output_window:
            self.video_output_window.set_watermark(self._license.watermark_required)

    def show_license_warning_if_needed(self):
        """Affiche le dialogue d'avertissement si necessaire (appele apres show)"""
        if not self._license.show_warning:
            return
        result = LicenseWarningDialog(self._license, self).exec()
        if result == 2:  # Bouton "Activer"
            self._open_activation_dialog()

    def restart_application(self):
        """Redemarre l'application"""
        reply = QMessageBox.question(self, tr("mw_restart"),
            tr("mw_restart_confirm"),
            QMessageBox.Yes | QMessageBox.No)

        if reply == QMessageBox.Yes:
            if hasattr(self, 'midi_handler') and self.midi_handler:
                try:
                    if self.midi_handler.midi_in:
                        self.midi_handler.midi_in.close_port()
                    if self.midi_handler.midi_out:
                        self.midi_handler.midi_out.close_port()
                except:
                    pass
            python = sys.executable
            os.execv(python, [python] + sys.argv)

    def toggle_blackout_from_midi(self):
        """Toggle le blackout depuis le bouton 9 de l'AKAI"""
        self.blackout_active = not self.blackout_active

        if self.blackout_active:
            for proj in self.projectors:
                proj.color = QColor("black")
                proj.level = 0

            if MIDI_AVAILABLE and self.midi_handler.midi_out:
                self.midi_handler.midi_out.send_message([0x90, 122, 3])
        else:
            for i, fader in self.faders.items():
                if i < 8:
                    self.set_proj_level(i, fader.value)

            if MIDI_AVAILABLE and self.midi_handler.midi_out:
                self.midi_handler.midi_out.send_message([0x90, 122, 0])

    def toggle_fader_mute_from_midi(self, fader_idx):
        """Toggle le mute d'un fader depuis l'AKAI physique - tous independants"""
        if fader_idx == 8:
            return  # Pas de mute pour le fader FX

        if 0 <= fader_idx < len(self.fader_buttons):
            btn = self.fader_buttons[fader_idx]
            btn.active = not btn.active
            btn.update_style()
            self.toggle_mute(fader_idx, btn.active)

            if MIDI_AVAILABLE and self.midi_handler.midi_out:
                note = 100 + fader_idx
                velocity = 3 if btn.active else 0
                self.midi_handler.midi_out.send_message([0x90, note, velocity])

    def cycle_fader_level_from_midi(self, fader_idx):
        """Monte le fader d'une colonne par paliers : 25 → 50 → 75 → 100 → 0 → 25…

        Utilisé par la rangée du haut du Launchpad Mini MK3 (un bouton par colonne).
        """
        if not (0 <= fader_idx <= 7) or fader_idx not in self.faders:
            return
        cur = self.faders[fader_idx].value
        if cur >= 100:
            nxt = 0
        else:
            nxt = next((lvl for lvl in (25, 50, 75, 100) if lvl > cur), 0)
        self.faders[fader_idx].value = nxt
        self.faders[fader_idx].update()
        self.set_proj_level(fader_idx, nxt)
        # Push tablette (cohérent avec on_midi_fader)
        try:
            import tablet_server as _ts
            if _ts.is_running():
                _ts.push_fader(fader_idx, nxt)
        except Exception:
            pass

    # Mapping raccourcis clavier -> couleurs
    COLOR_SHORTCUTS = {
        Qt.Key_R: QColor(255, 0, 0),
        Qt.Key_G: QColor(0, 255, 0),
        Qt.Key_B: QColor(0, 0, 255),
        Qt.Key_C: QColor(0, 255, 255),
        Qt.Key_M: QColor(255, 0, 255),
        Qt.Key_Y: QColor(255, 255, 0),
        Qt.Key_W: QColor(255, 255, 255),
        Qt.Key_K: QColor(0, 0, 0),
        Qt.Key_O: QColor(255, 128, 0),
        Qt.Key_P: QColor(255, 105, 180),
    }

    # En mode LIVE, les mêmes touches couleur pilotent les "modes de couleurs"
    # du panel live (tuiles couleur) au lieu d'appliquer aux lampes sélectionnées
    # (comportement 2D). Valeur = clé de tuile dans LivePanel._COLOR_TILES.
    LIVE_COLOR_KEYS = {
        Qt.Key_R: 'rouge',
        Qt.Key_G: 'vert',
        Qt.Key_B: 'bleu',
        Qt.Key_C: 'cyan',
        Qt.Key_Y: 'jaune',
        Qt.Key_O: 'orange',
        Qt.Key_M: 'violet',
        Qt.Key_P: 'rose',
        Qt.Key_W: 'blanc',
    }

    def keyPressEvent(self, event):
        """Gere les raccourcis clavier"""
        key = event.key()

        if key in (Qt.Key_Space, Qt.Key_Return, Qt.Key_Enter):
            self.toggle_play()
            event.accept()
        elif key == Qt.Key_PageDown and (event.modifiers() & Qt.ControlModifier):
            self._next_bank_page()       # Ctrl+PageDown = page de layout suivante
            event.accept()
        elif key == Qt.Key_PageUp and (event.modifiers() & Qt.ControlModifier):
            self._prev_bank_page()       # Ctrl+PageUp = page de layout précédente
            event.accept()
        elif key == Qt.Key_PageDown:
            self.next_media()
            event.accept()
        elif key == Qt.Key_PageUp:
            self.previous_media()
            event.accept()
        elif key == Qt.Key_Right and self.go_mode:
            self._go_advance()
            event.accept()
        elif key == Qt.Key_Left and self.go_mode:
            self._go_back()
            event.accept()
        elif key in (Qt.Key_F1, Qt.Key_F2, Qt.Key_F3, Qt.Key_F4):
            cart_index = key - Qt.Key_F1  # F1=0, F2=1, F3=2, F4=3
            if cart_index < len(self.cartouches):
                self.on_cartouche_clicked(cart_index)
            event.accept()
        elif key in (Qt.Key_F5, Qt.Key_F6, Qt.Key_F7, Qt.Key_F8,
                     Qt.Key_F9, Qt.Key_F10, Qt.Key_F11, Qt.Key_F12):
            # F5-F12 = les 8 boutons d'effet (carrés verts) 0 à 7, haut → bas.
            # Respecte le mode du bouton (toggle / flash / timer) comme un vrai appui.
            if not event.isAutoRepeat():
                fx_index = key - Qt.Key_F5  # F5=0 … F12=7
                if fx_index < len(self.effect_buttons):
                    self._on_effect_press(fx_index)
            event.accept()
        elif key == Qt.Key_S and not (event.modifiers() & (Qt.ControlModifier | Qt.AltModifier | Qt.MetaModifier)):
            self._apply_strobe_shortcut()
            event.accept()
        elif key in self.COLOR_SHORTCUTS:
            if getattr(self.seq, 'live_mode_active', False):
                # LIVE : la touche couleur sélectionne le mode de couleur live
                # (comme un clic sur la tuile du panel) au lieu d'agir sur la 2D.
                tile = self.LIVE_COLOR_KEYS.get(key)
                panel = getattr(self.seq, 'live_panel', None)
                if tile and panel is not None and hasattr(panel, '_on_color_tile_selected'):
                    panel._on_color_tile_selected(tile)
            else:
                self._apply_color_shortcut(self.COLOR_SHORTCUTS[key])
            event.accept()
        else:
            super().keyPressEvent(event)

    def keyReleaseEvent(self, event):
        """Relâchement F5-F12 : coupe les effets en mode 'flash' (maintien)."""
        key = event.key()
        if key in (Qt.Key_F5, Qt.Key_F6, Qt.Key_F7, Qt.Key_F8,
                   Qt.Key_F9, Qt.Key_F10, Qt.Key_F11, Qt.Key_F12) and not event.isAutoRepeat():
            fx_index = key - Qt.Key_F5
            if fx_index < len(self.effect_buttons):
                self._on_effect_release(fx_index)
            event.accept()
        else:
            super().keyReleaseEvent(event)

    def _apply_color_shortcut(self, color):
        """Applique une couleur raccourci aux projecteurs selectionnes"""
        if not self.plan_de_feu.selected_lamps:
            return
        targets = []
        for g, i in self.plan_de_feu.selected_lamps:
            projs = [p for p in self.projectors if p.group == g]
            if i < len(projs):
                targets.append(projs[i])
        for proj in targets:
            # « BLACK LIGHT » / « Ambre » : LED dédiée seule (cf. les blocs du
            # REC Lumière). Sinon on éteint ces canaux — les boutons couleur se
            # remplacent l'un l'autre, un UV posé avant ne doit pas rester collé.
            if apply_special_block(proj, color, 100):
                continue
            clear_special_blocks(proj)
            proj.base_color = color
            proj.level = 100
            proj.color = QColor(color.red(), color.green(), color.blue())
            self._update_color_wheel(proj, color)
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        self.plan_de_feu.refresh()

    def _apply_color_to_groups(self, color, groups=None):
        """Applique une couleur aux projecteurs de groupes donnés (fenêtre EXT).

        groups == None ou "all" → tous les projecteurs ;
        groups == liste de groupes internes → seulement ces groupes.
        Retourne le nombre de projecteurs touchés."""
        if groups in (None, "all"):
            targets = list(self.projectors)
        else:
            gset = set(groups)
            targets = [p for p in self.projectors if p.group in gset]
        for proj in targets:
            # Idem : « BLACK LIGHT » pilote la LED UV seule, les autres couleurs
            # éteignent les canaux dédiés (boutons mutuellement exclusifs).
            if apply_special_block(proj, color, 100):
                continue
            clear_special_blocks(proj)
            proj.base_color = color
            proj.level = 100
            proj.color = QColor(color.red(), color.green(), color.blue())
            self._update_color_wheel(proj, color)
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        self.plan_de_feu.refresh()
        return len(targets)

    def _apply_strobe_shortcut(self):
        """Touche S : (dés)active le strobe sur les projecteurs sélectionnés.
        Bascule : si au moins un strobe est actif → tout couper, sinon strobe ON."""
        if not self.plan_de_feu.selected_lamps:
            return
        targets = []
        for g, i in self.plan_de_feu.selected_lamps:
            projs = [p for p in self.projectors if p.group == g]
            if i < len(projs):
                targets.append(projs[i])
        if not targets:
            return
        any_on = any(getattr(p, 'strobe_speed', 0) > 0 for p in targets)
        new_val = 0 if any_on else 100   # 100 = strobe rapide ; 0 = arrêt
        for proj in targets:
            proj.strobe_speed = new_val
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        self.plan_de_feu.refresh()

    def _build_effect_config_by_name(self, name: str):
        """Config jouable d'un effet à partir de son nom (mêmes sources que les mémoires).
        Retourne un dict {name, type, layers, play_mode, duration} ou None si introuvable."""
        if not name:
            return None
        # 1) configs assignées aux boutons
        for cfg in getattr(self, '_button_effect_configs', {}).values():
            if isinstance(cfg, dict) and cfg.get("name") == name:
                return dict(cfg)
        # 2) bibliothèque d'effets édités
        lib = getattr(self, '_effect_library_configs', {}) or {}
        if name in lib:
            return dict(lib[name])
        # 3) effets intégrés + personnalisés
        try:
            from effect_editor import BUILTIN_EFFECTS, _load_custom_effects, EffectLayer
            for eff in list(BUILTIN_EFFECTS) + _load_custom_effects():
                if eff.get("name") != name:
                    continue
                if eff.get("layers") and isinstance(eff["layers"][0], dict):
                    cfg = dict(eff)
                    cfg.setdefault("play_mode", "loop")
                    cfg.setdefault("duration", 0)
                    return cfg
                layers = EffectLayer.layers_from_builtin(eff)
                return {
                    "name": name, "type": eff.get("type", ""),
                    "layers": [l.to_dict() for l in layers],
                    "play_mode": "loop", "duration": 0,
                }
        except Exception:
            pass
        return None

    def _toggle_ext_effect(self, name: str, groups=None):
        """Démarre/arrête un effet par nom depuis la fenêtre EXT.
        groups : None/"all" → tous les groupes ; liste de groupes internes → ces groupes.
        Retourne True (démarré), False (arrêté) ou None (introuvable)."""
        running = hasattr(self, 'effect_timer') and self.effect_timer.isActive()
        # Re-clic sur l'effet actif → on l'arrête
        if running and getattr(self, 'active_effect', None) == name:
            self.stop_effect()
            self.active_effect = None
            self.active_effect_config = {}
            return False
        cfg = self._build_effect_config_by_name(name)
        if cfg is None:
            return None
        cfg = dict(cfg)
        # Cible : restreindre l'effet à certains groupes (lettres AKAI A–H)
        if groups in (None, "all", [], "selection"):
            cfg["target_groups"] = []          # tous les groupes
        else:
            disp = getattr(self, "GROUP_DISPLAY", {}) or {}
            letters = [disp.get(g) for g in groups]
            cfg["target_groups"] = [l for l in letters if l and len(l) == 1 and l.isalpha()]
        if running:
            self.stop_effect()   # restaure l'état avant de lancer le nouvel effet
        self.active_effect = name
        self.active_effect_config = cfg
        self.start_effect(name)
        return True

    # ── Actions « Spécial » de la fenêtre EXT ──────────────────────────
    def _ext_select_all(self) -> int:
        """Sélectionne tous les projecteurs dans le plan de feu. Retourne le nombre."""
        pdf = getattr(self, "plan_de_feu", None)
        if not pdf:
            return 0
        keys, counts = [], {}
        for p in self.projectors:
            i = counts.get(p.group, 0)
            keys.append((p.group, i))
            counts[p.group] = i + 1
        pdf.selected_lamps = set(keys)
        pdf.selected_lamps_ordered = list(keys)
        pdf.refresh()
        return len(keys)

    def _ext_clear_selection(self):
        """Vide la sélection de projecteurs."""
        pdf = getattr(self, "plan_de_feu", None)
        if not pdf:
            return
        pdf.selected_lamps = set()
        pdf.selected_lamps_ordered = []
        pdf.refresh()

    def _ext_clear(self):
        """CLEAR : éteint les couleurs de tous les projecteurs et vide la sélection
        (sans toucher aux pads AKAI ni aux effets)."""
        for p in self.projectors:
            p.base_color = QColor("black")
            p.color = QColor("black")
            p.level = 0
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        self._ext_clear_selection()

    def _ext_full_on(self) -> int:
        """Plein feu : tous les projecteurs en blanc à 100 %."""
        return self._apply_color_to_groups(QColor(255, 255, 255), "all")

    def _ext_blackout(self):
        """Blackout complet (projecteurs, pads, effets)."""
        self.full_blackout()
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        if getattr(self, "plan_de_feu", None):
            self.plan_de_feu.refresh()

    def _ext_cut_dmx(self):
        """Bascule la sortie DMX globale, comme le bouton DMX ON/OFF du plan de feu
        (la page principale reflète l'état). Retourne True = DMX ON, False = DMX OFF,
        None = indisponible."""
        pdf = getattr(self, "plan_de_feu", None)
        btn = getattr(pdf, "dmx_toggle_btn", None) if pdf else None
        if btn is None:
            return None
        btn.setChecked(not btn.isChecked())
        pdf._toggle_dmx_output()
        return btn.isChecked()

    def _ext_toggle_video(self):
        """Bascule la sortie vidéo externe (ON/OFF). Retourne l'état résultant."""
        btn = getattr(self, "video_output_btn", None)
        if btn is None:
            return None
        btn.setChecked(not btn.isChecked())
        self.toggle_video_output()
        return btn.isChecked()

    def _ext_targets_for_groups(self, groups):
        """Projecteurs ciblés par un bloc EXT (sélection / tous / liste de groupes)."""
        if groups == "selection":
            pdf = getattr(self, "plan_de_feu", None)
            out = []
            for g, i in (getattr(pdf, "selected_lamps", None) or []):
                projs = [p for p in self.projectors if p.group == g]
                if i < len(projs):
                    out.append(projs[i])
            return out
        if groups in (None, "all"):
            return list(self.projectors)
        gset = set(groups)
        return [p for p in self.projectors if p.group in gset]

    def _ext_snapshot_groups(self, groups):
        """Capture l'état couleur/niveau des projecteurs ciblés (pour flash couleur)."""
        return [(p, QColor(p.base_color), QColor(p.color), p.level)
                for p in self._ext_targets_for_groups(groups)]

    def _ext_restore_snapshot(self, snap):
        """Restaure un instantané capturé par _ext_snapshot_groups."""
        for p, base, col, lvl in snap or []:
            p.base_color = QColor(base)
            p.color = QColor(col)
            p.level = lvl
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        if getattr(self, "plan_de_feu", None):
            self.plan_de_feu.refresh()

    def _ext_is_playing(self) -> bool:
        """True si une lecture est en cours (média audio/vidéo ou tempo)."""
        try:
            if self.player.playbackState() == QMediaPlayer.PlayingState:
                return True
        except Exception:
            pass
        return bool(getattr(getattr(self, "seq", None), "tempo_running", False))

    def _ext_stop_effects(self):
        """Arrête tous les effets en cours."""
        self.turn_off_all_effects()
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        if getattr(self, "plan_de_feu", None):
            self.plan_de_feu.refresh()

    def _ext_set_group_level(self, groups, value):
        """Bloc-fader EXT : règle le niveau (0-100) des projecteurs ciblés.
        groups == "all"/"master"/None → tous ; sinon liste de groupes internes."""
        gset = None if groups in (None, "all", "master") else set(groups)
        brightness = value / 100.0 if value > 0 else 0
        for p in self.projectors:
            if gset is not None and p.group not in gset:
                continue
            p.level = value
            if value > 0:
                p.color = QColor(
                    int(p.base_color.red()   * brightness),
                    int(p.base_color.green() * brightness),
                    int(p.base_color.blue()  * brightness))
            else:
                p.color = QColor("black")
        self.send_dmx_update()

    def _ext_set_strobe(self, on: bool):
        """Bloc flash EXT : force le strobe on/off sur les projecteurs sélectionnés."""
        if not self.plan_de_feu.selected_lamps:
            return
        targets = []
        for g, i in self.plan_de_feu.selected_lamps:
            projs = [p for p in self.projectors if p.group == g]
            if i < len(projs):
                targets.append(projs[i])
        val = 100 if on else 0
        for proj in targets:
            proj.strobe_speed = val
        if self.dmx:
            self.dmx.update_from_projectors(self.projectors)
        self.plan_de_feu.refresh()

