        # ── Onglet 2 : Plan de feu ─────────────────────────────────────
        tab_canvas = QWidget()
        tab_canvas.setStyleSheet("background: #0a0a0a;")
        vl_canvas = QVBoxLayout(tab_canvas)
        vl_canvas.setContentsMargins(0, 0, 0, 0)
