    def _rj45_deep_report(self):
        """Rapport détaillé réseau / Art-Net, dans l'esprit de BRAD.

        Le test RJ45 affiche deux voyants — carte réseau, node — ce qui suffit
        à savoir SI ça marche, pas POURQUOI ça ne marche pas. Ce rapport
        rassemble ce qu'on finit toujours par demander à l'utilisateur : ses
        cartes, sa route vers le boîtier, qui répond, et qui tient le port.
        """
        import socket as _s, subprocess as _sp, sys as _sys, time as _t
        from node_connection import (_get_ethernet_adapters, _artpoll_packet,
                                     TARGET_IP, TARGET_PORT)
        L = []
        A = L.append
        A("═══ DIAGNOSTIC RÉSEAU / ART-NET ═══")
        A(f"MyStrow {VERSION} — {_sys.platform}")
        A("")

        A("[ 1 ] Cartes réseau")
        try:
            adapters = _get_ethernet_adapters()
        except Exception as e:
            adapters = []
            A(f"  ✗  énumération impossible : {e}")
        if not adapters:
            A("  ✗  aucune carte détectée — câble RJ45 branché ?")
        for name, ip, desc, up in adapters:
            mark = "★" if str(ip).startswith("2.") else " "
            A(f"  {mark} {name}")
            A(f"      IP {ip or '(non configurée)'}   {'active' if up else 'inactive'}")
        if not any(str(a[1]).startswith("2.") for a in adapters):
            A("  ⚠  AUCUNE carte en 2.x.x.x : le boîtier est inaccessible.")
            A("      Configurer 2.0.0.1 / 255.0.0.0 sur la carte du node.")
        A("")

        A("[ 2 ] Configuration MyStrow")
        A(f"  Transport   : {getattr(self.dmx, 'transport', '?')}")
        A(f"  IP cible    : {getattr(self.dmx, 'target_ip', '?')}:"
          f"{getattr(self.dmx, 'target_port', '?')}")
        A(f"  Univers     : {getattr(self.dmx, 'universe', '?')}")
        A(f"  Connecté    : {'OUI' if getattr(self.dmx, 'connected', False) else 'NON'}")
        A("")

        A("[ 3 ] Port Art-Net 6454")
        try:
            _p = _s.socket(_s.AF_INET, _s.SOCK_DGRAM)
            _p.setsockopt(_s.SOL_SOCKET, _s.SO_REUSEADDR, 1)
            _p.bind(("", TARGET_PORT))
            _p.close()
            A("  ✓  libre — aucune autre application DMX ne l'occupe")
        except Exception as e:
            A(f"  ⚠  occupé ({e})")
            A("      QLC+, Chataigne ou un autre logiciel DMX est ouvert.")
            A("      Deux applications ne peuvent pas écouter le même port.")
        A("")

        A("[ 4 ] Réponse du boîtier")
        A("  Le ping est un mauvais test : beaucoup de nodes l'ignorent")
        A("  volontairement tout en répondant parfaitement à l'Art-Net.")
        try:
            _flags = ["-n", "1", "-w", "800"] if _sys.platform == "win32" else ["-c", "1", "-W", "1"]
            _r = _sp.run(["ping"] + _flags + [TARGET_IP], capture_output=True,
                         creationflags=0x08000000 if _sys.platform == "win32" else 0)
            A(f"  {'✓' if _r.returncode == 0 else '·'}  ping {TARGET_IP} : "
              f"{'répond' if _r.returncode == 0 else 'muet (normal sur beaucoup de nodes)'}")
        except Exception as e:
            A(f"  ·  ping impossible : {e}")

        found = {}
        try:
            k = _s.socket(_s.AF_INET, _s.SOCK_DGRAM)
            k.setsockopt(_s.SOL_SOCKET, _s.SO_REUSEADDR, 1)
            k.setsockopt(_s.SOL_SOCKET, _s.SO_BROADCAST, 1)
            if hasattr(_s, "SO_REUSEPORT"):
                try: k.setsockopt(_s.SOL_SOCKET, _s.SO_REUSEPORT, 1)
                except OSError: pass
            k.bind(("", TARGET_PORT))
            k.settimeout(0.4)
            for dst in ("2.255.255.255", "255.255.255.255", TARGET_IP):
                try: k.sendto(_artpoll_packet(), (dst, TARGET_PORT))
                except Exception: pass
            fin = _t.time() + 2.5
            while _t.time() < fin:
                try:
                    data, (snd, _) = k.recvfrom(1024)
                except Exception:
                    break
                if data[:8] == b'Art-Net' + bytes([0]) and data[8:10] == bytes([0, 0x21]):
                    found[snd] = data[26:44].split(bytes([0]))[0].decode('latin-1', 'replace')
            k.close()
        except Exception as e:
            A(f"  ✗  ArtPoll impossible : {e}")
        if found:
            for ip_n, nom in sorted(found.items()):
                A(f"  ✓  ArtPoll : {ip_n}  « {nom} »")
            if TARGET_IP not in found:
                A(f"  ⚠  Le boîtier répond mais PAS sur {TARGET_IP}.")
                A(f"      Corriger l'IP cible dans MyStrow : {sorted(found)[0]}")
        else:
            A("  ✗  aucune réponse ArtPoll")
            A("      • câble sur le port RÉSEAU du boîtier (pas la sortie DMX) ?")
            A("      • boîtier alimenté, LED du port ethernet allumée ?")
            A("      • s'il a deux ports ethernet, essayer l'autre")
        A("")
        A("═══ FIN ═══")
        return chr(10).join(L)

    def open_usb_diagnostic(self):
        """Ouvre l'assistant de sortie DMX USB, sur son étape diagnostic."""
        if not self._license.dmx_allowed:
            self._dmx_locked_notice()
            return
        from enttec_setup import DmxSetupDialog
        dlg = DmxSetupDialog(self.dmx, parent=self)
        dlg.exec()
        self._refresh_dmx_menu_title()

    @staticmethod
    def _firewall_port_status(port):
        """(entrées bloquées par défaut ?, une règle couvre-t-elle ce port ?).

        Chaque valeur vaut None si l'information n'a pas pu être obtenue — on ne
        présente jamais une incertitude comme un diagnostic.

        Les libellés de `netsh` sont traduits, mais pas les mots-clés de
        politique (`BlockInbound`) ni le nom de champ `LocalPort` : on s'appuie
        uniquement sur eux, sinon le test ne marcherait qu'en français.
        """
        import subprocess as _sp
        sans_fenetre = getattr(_sp, "CREATE_NO_WINDOW", 0)

        def _netsh(args, timeout):
            return _sp.run(["netsh", "advfirewall"] + args, capture_output=True,
                           text=True, errors="replace", timeout=timeout,
                           creationflags=sans_fenetre)

        bloque = None
        try:
            r = _netsh(["show", "currentprofile"], 8)
            if r.returncode == 0:
                bloque = "BlockInbound" in r.stdout
        except Exception as e:
            print(f"[Tablet] pare-feu profil: {e}")

        regle = None
        try:
            r = _netsh(["firewall", "show", "rule", "name=all", "dir=in", "verbose"], 20)
            if r.returncode == 0:
                trouve = False
                for ligne in r.stdout.splitlines():
                    if "LocalPort" not in ligne:
                        continue
                    valeurs = ligne.split(":", 1)[-1]
                    for bout in valeurs.split(","):
                        bout = bout.strip()
                        if bout in ("Any", "*"):
                            continue
                        try:
                            if "-" in bout:      # plage « 5000-5020 »
                                lo, hi = bout.split("-", 1)
                                if int(lo) <= port <= int(hi):
                                    trouve = True
                            elif int(bout) == port:
                                trouve = True
                        except ValueError:
                            continue
                    if trouve:
                        break
                regle = trouve
        except Exception as e:
            print(f"[Tablet] pare-feu règles: {e}")

        return bloque, regle

    def test_tablet_connection(self):
        """Lance le diagnostic tablette SANS geler l'application.

        Le diagnostic enchaine des connexions reseau et deux appels `netsh`
        dont les delais autorises cumulent ~35 s. Il tournait sur le thread Qt :
        pendant tout ce temps la fenetre ne repeint plus (Windows la declare
        « ne repond pas » et propose de la fermer) et le timer DMX ne part
        plus — mesure ici : 1,14 s de gel et ~45 trames DMX perdues sur une
        machine RAPIDE, bien pire ailleurs. D'ou des utilisateurs convaincus
        que MyStrow avait plante.
        """
        from PySide6.QtCore import QThread, Signal as _Sig

        class _Worker(QThread):
            fini = _Sig(str)

            def __init__(self, fen):
                super().__init__()
                self._fen = fen

            def run(self):
                try:
                    self.fini.emit(self._fen._tablet_diag_report())
                except Exception as e:
                    import traceback as _tb
                    self.fini.emit("Diagnostic interrompu : "
                                   + str(e) + chr(10) + chr(10)
                                   + _tb.format_exc())

        self._tablet_diag_worker = _Worker(self)
        self._tablet_diag_worker.fini.connect(
            lambda r: self._show_diag_report(
                "Test tablette", r, "Diagnostic du contrôleur tablette"))
        self._tablet_diag_worker.start()

    def _tablet_diag_report(self):
        """Construit le rapport de diagnostic tablette (APPEL BLOQUANT).

        Le symptôme classique (« la tablette affiche une page vide ») a plusieurs
        causes très différentes — serveur non démarré, dépendances absentes, port
        occupé, pare-feu. Ce test les distingue au lieu de laisser deviner.
        """
        import socket as _s
        import tablet_server as _ts

        lines = []

        # Nombre de tablettes AVANT nos propres requêtes de test. Le test de la
        # route /stream ouvre lui-même une connexion SSE, que le serveur inscrit
        # aussitôt dans _clients et ne retire qu'à la fermeture effective du flux.
        # Lu après coup, le compteur affichait donc « Tablettes connectées : 1 »
        # alors qu'AUCUNE tablette n'était là — le diagnostic se comptait lui-même.
        try:
            n_clients_avant = len(_ts._clients)
        except Exception:
            n_clients_avant = 0

        def add(label, ok, detail):
            mark = "✓" if ok else "✗"
            lines.append(f"{mark}  {label} : {detail}")
            return ok

        # 1. Dépendances (Flask/waitress) — installées à la volée au 1er démarrage
        try:
            deps_ok = bool(_ts._try_import())
        except Exception as e:
            deps_ok = False
            print(f"[Tablet] test dépendances: {e}")
        add("Dépendances (Flask/waitress)", deps_ok,
            "présentes" if deps_ok else "absentes — le serveur ne peut pas démarrer")

        # 2. Serveur démarré ?
        running = False
        try:
            running = bool(_ts.is_running())
        except Exception as e:
            print(f"[Tablet] test is_running: {e}")
        add("Serveur tablette", running,
            "démarré" if running else "arrêté — Connexion ▸ Contrôle externe pour l'allumer")

        # 3. IP locale et URL à saisir sur la tablette
        ip = ""
        try:
            ip = _ts.get_local_ip()
        except Exception as e:
            print(f"[Tablet] test IP: {e}")
        add("Adresse du PC sur le réseau", bool(ip),
            f"http://{ip}:{_ts.TABLET_PORT}" if ip else "introuvable — carte réseau active ?")

        # 4. Le port répond-il vraiment ? (le serveur peut se croire démarré)
        port_ok = False
        if running:
            try:
                with _s.create_connection(("127.0.0.1", _ts.TABLET_PORT), timeout=1.5):
                    port_ok = True
            except Exception as e:
                print(f"[Tablet] test port: {e}")
            add(f"Port {_ts.TABLET_PORT} en écoute", port_ok,
                "répond" if port_ok else "ne répond pas — port occupé ou serveur planté")

        # 5. Le socket est-il ouvert sur l'IP du réseau (et pas seulement en local) ?
        #    ⚠️ Ce test NE PROUVE PAS qu'une tablette peut joindre le serveur.
        #    Une connexion partie de CE PC vers sa PROPRE adresse réseau ne
        #    traverse jamais le pare-feu entrant de Windows : elle réussit même
        #    quand le port est intégralement bloqué pour l'extérieur. Il a
        #    longtemps été présenté comme « LE test qui compte », d'où des
        #    diagnostics tout verts en face d'une tablette qui affiche
        #    « Ce site est inaccessible ». Il dit seulement que le serveur écoute
        #    sur 0.0.0.0 et non sur 127.0.0.1 — utile, mais rien de plus.
        lan_ok = False
        if running and ip:
            try:
                with _s.create_connection((ip, _ts.TABLET_PORT), timeout=1.5):
                    lan_ok = True
            except Exception as e:
                print(f"[Tablet] test LAN: {e}")
            add(f"Socket ouvert sur {ip} (vu depuis ce PC)", lan_ok,
                "oui — ne préjuge pas du pare-feu" if lan_ok else
                "NON — le serveur n'écoute que sur 127.0.0.1")

        # 6. Les deux routes que la tablette utilise réellement.
        #    /stream est le flux temps réel : c'est lui qui a déjà cassé en
        #    version compilée (en-tête « Connection » refusé par waitress → 500),
        #    avec une tablette qui affiche une page vide sans message d'erreur.
        if running and ip:
            import urllib.request as _u
            for route, libelle in (("/", "Page de la tablette"),
                                   ("/stream", "Flux temps réel (SSE)")):
                url = f"http://{ip}:{_ts.TABLET_PORT}{route}"
                try:
                    req = _u.Request(url, headers={"Accept": "text/event-stream"}
                                     if route == "/stream" else {})
                    with _u.urlopen(req, timeout=2.0) as r:
                        add(libelle, 200 <= r.status < 400, f"HTTP {r.status}")
                except Exception as e:
                    code = getattr(e, 'code', None)
                    add(libelle, False,
                        f"HTTP {code}" if code else f"injoignable ({type(e).__name__})")

        # 7. Pare-feu Windows : existe-t-il une règle entrante pour ce port ?
        #    C'est la cause n°1 de « site inaccessible » côté tablette alors que
        #    tout est vert côté PC. Absence de règle = indication forte, pas une
        #    preuve : une règle peut aussi viser le PROGRAMME (python.exe) plutôt
        #    que le port — d'où un libellé prudent.
        if sys.platform == "win32" and running:
            bloque, regle = self._firewall_port_status(_ts.TABLET_PORT)
            if bloque is not None:
                add("Pare-feu — entrées par défaut", not bloque,
                    "autorisées" if not bloque else "BLOQUÉES (une règle est nécessaire)")
            if regle is not None:
                add(f"Règle pare-feu pour le port {_ts.TABLET_PORT}", regle,
                    "présente" if regle else
                    "AUCUNE — cause la plus probable du « site inaccessible »")

        # 8. Tablettes actuellement connectées (comptées AVANT nos propres tests)
        n_clients = n_clients_avant
        lines.append(f"{'✓' if n_clients else '·'}  Tablettes connectées : {n_clients}")

        if running and lan_ok and not n_clients:
            lines.append("")
            lines.append("Le serveur écoute, mais aucune tablette n'est connectée.")
            lines.append("Rien ci-dessus ne prouve qu'un AUTRE appareil peut entrer :")
            lines.append("les tests partent de ce PC et ne traversent pas son pare-feu.")
            lines.append("")
            lines.append("Si la tablette affiche « Ce site est inaccessible », dans l'ordre :")
            lines.append(f"  1. Pare-feu Windows — autoriser le port {_ts.TABLET_PORT} en entrée.")
            lines.append("     En ligne de commande, en ADMINISTRATEUR :")
            lines.append(f'     netsh advfirewall firewall add rule name="MyStrow tablette" '
                         f'dir=in action=allow protocol=TCP localport={_ts.TABLET_PORT}')
            lines.append("  2. Tablette et PC sur le MÊME réseau Wi-Fi (pas un invité,")
            lines.append("     pas la 4G, pas un VPN actif sur l'un des deux)")
            lines.append("  3. Certaines box isolent les appareils entre eux")
            lines.append("     (« isolation client » / « réseau invité ») : à désactiver")
            lines.append(f"  4. Depuis la tablette, tester d'abord  http://{ip}:{_ts.TABLET_PORT}")
        elif running and ip and not lan_ok:
            lines.append("")
            lines.append("Le serveur tourne mais reste injoignable depuis le réseau.")
            lines.append("Cause la plus fréquente : le pare-feu Windows bloque l'entrée.")
            lines.append(f"Autoriser python.exe / MyStrow.exe sur le port {_ts.TABLET_PORT}")
            lines.append("en réseau PRIVÉ suffit dans la quasi-totalité des cas.")

        report = "\n".join(lines)
        return report

    def test_node_connection(self):
        """Diagnostic Node DMX : carte reseau + node"""
        if not self._license.dmx_allowed:
            self._dmx_locked_notice()
            return

        import socket as _socket
        from node_connection import _get_ethernet_adapters, _artpoll_packet, TARGET_IP, TARGET_PORT

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("mw_node_diag"))
        # Minimum et non taille FIXE : avec « Ouvrir l'assistant de connexion »
        # visible, la rangee de boutons reclame ~740 px pour 404 disponibles.
        dlg.setMinimumSize(460, 260)
        dlg.setWindowFlags(dlg.windowFlags() & ~Qt.WindowContextHelpButtonHint)
        dlg.setStyleSheet(
            "QDialog { background: #1a1a1a; }"
            "QLabel { color: #cccccc; border: none; background: transparent; }"
        )

        root = QVBoxLayout(dlg)
        root.setContentsMargins(28, 22, 28, 18)
        root.setSpacing(16)

        title = QLabel(tr("mw_node_diag_title"))
        title.setFont(QFont("Segoe UI", 12, QFont.Bold))
        title.setStyleSheet("color: #00d4ff;")
        root.addWidget(title)

        def _make_check_row(label_text):
            row = QHBoxLayout()
            row.setSpacing(14)
            icon = QLabel("…")
            icon.setFont(QFont("Segoe UI", 16))
            icon.setFixedWidth(26)
            icon.setAlignment(Qt.AlignCenter)
            icon.setStyleSheet("color: #555555;")
            row.addWidget(icon)
            col = QVBoxLayout()
            col.setSpacing(1)
            lbl = QLabel(label_text)
            lbl.setFont(QFont("Segoe UI", 10, QFont.Bold))
            col.addWidget(lbl)
            detail = QLabel(tr("mw_checking"))
            detail.setFont(QFont("Segoe UI", 9))
            detail.setStyleSheet("color: #555555;")
            detail.setWordWrap(True)
            col.addWidget(detail)
            row.addLayout(col, 1)
            root.addLayout(row)
            return icon, detail

        icon_net, detail_net = _make_check_row("Carte réseau")
        icon_node, detail_node = _make_check_row("Node DMX")

        root.addStretch()

        import sys as _sys
        import subprocess as _sub
        btn_row = QHBoxLayout()
        btn_row.addStretch()
        btn_config = QPushButton(tr("mw_open_conn_wizard"))
        btn_config.setFixedHeight(30)
        fit_button(btn_config)
        btn_config.setStyleSheet(
            "QPushButton { background: #1e3a4a; color: #00d4ff; border: 1px solid #00d4ff;"
            " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
            "QPushButton:hover { background: #254a5a; }"
        )
        btn_config.hide()
        btn_config.clicked.connect(lambda: (dlg.accept(), self.open_node_connection()))
        btn_row.addWidget(btn_config)
        # Bouton connexions réseau selon la plateforme
        if _sys.platform == "darwin":
            btn_net = QPushButton(tr("mw_net_prefs_mac"))
            btn_net.setFixedHeight(30)
            fit_button(btn_net)
            btn_net.setStyleSheet(
                "QPushButton { background: #2a2a3a; color: #aaaacc; border: 1px solid #44448888;"
                " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
                "QPushButton:hover { background: #333355; color: #ccccee; }"
            )
            btn_net.setToolTip(tr("mw_net_prefs_mac_t"))
            btn_net.clicked.connect(lambda: _sub.Popen(
                ["open", "x-apple.systempreferences:com.apple.preference.network"]))
        else:
            btn_net = QPushButton(tr("mw_net_conn_win"))
            btn_net.setFixedHeight(30)
            fit_button(btn_net)
            btn_net.setStyleSheet(
                "QPushButton { background: #2a2a3a; color: #aaaacc; border: 1px solid #44448888;"
                " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
                "QPushButton:hover { background: #333355; color: #ccccee; }"
            )
            btn_net.setToolTip(tr("mw_net_conn_win_t"))
            from node_connection import _open_network_connections
            btn_net.clicked.connect(_open_network_connections)
        btn_row.addWidget(btn_net)
        btn_close = QPushButton(tr("mw_close"))
        btn_close.setFixedHeight(30)
        fit_button(btn_close)
        btn_close.setStyleSheet(
            "QPushButton { background: #2a2a2a; color: #aaaaaa; border: 1px solid #3a3a3a;"
            " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
            "QPushButton:hover { background: #333333; color: white; }"
        )
        btn_close.clicked.connect(dlg.accept)
        btn_row.addWidget(btn_close)
        root.addLayout(btn_row)

        # ── Fonction de vérification (appelée à l'ouverture et sur Actualiser) ──
        def _run_checks():
            # Réinitialiser l'affichage
            icon_net.setText("…");  icon_net.setStyleSheet("color: #555555;")
            detail_net.setText(tr("mw_checking_ell")); detail_net.setStyleSheet("color: #555555;")
            icon_node.setText("…"); icon_node.setStyleSheet("color: #555555;")
            detail_node.setText(tr("mw_checking_ell")); detail_node.setStyleSheet("color: #555555;")
            btn_config.hide()
            btn_refresh.setEnabled(False)
            btn_refresh.setText("…")
            QApplication.processEvents()

            # --- Vérification 1 : carte réseau ---
            adapters = _get_ethernet_adapters()
            ok_adapters = [(n, ip) for n, ip, *_ in adapters if ip.startswith("2.0.0.")]

            if ok_adapters:
                name, ip = ok_adapters[0]
                icon_net.setText("✓")
                icon_net.setStyleSheet("color: #4CAF50;")
                detail_net.setText(tr("mw_f_name_ip", name=name, ip=ip))
                detail_net.setStyleSheet("color: #4CAF50;")
                net_ok = True
            elif adapters:
                name, ip = adapters[0][0], adapters[0][1]
                ip_display = ip if ip else "non configurée"
                icon_net.setText("⚠")
                icon_net.setStyleSheet("color: #ff9800;")
                detail_net.setText(tr("mw_f_ip_expected", name=name, ip_display=ip_display))
                detail_net.setStyleSheet("color: #ff9800;")
                net_ok = False
            else:
                icon_net.setText("✗")
                icon_net.setStyleSheet("color: #f44336;")
                detail_net.setText(tr("mw_no_ethernet"))
                detail_net.setStyleSheet("color: #f44336;")
                net_ok = False

            QApplication.processEvents()

            # --- Vérification 2 : node ArtPoll + ping fallback ---
            node_ok = False
            found_ip = None
            _node_via_artpoll = False
            from node_connection import _get_all_local_ips
            _local_ips = _get_all_local_ips()
            _ARTNET_PORT = 6454
            _probe_ips = ["2.255.255.255", "255.255.255.255", TARGET_IP]

            # 2a. ArtPoll (opcode 0x2100 = ArtPollReply, port éphémère pour éviter loopback)
            try:
                s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
                s.setsockopt(_socket.SOL_SOCKET, _socket.SO_BROADCAST, 1)
                s.bind(("", 0))
                s.settimeout(1.5)
                for _ip in _probe_ips:
                    try:
                        s.sendto(_artpoll_packet(), (_ip, _ARTNET_PORT))
                    except Exception:
                        pass
                import time as _time
                _deadline = _time.time() + 1.5
                while _time.time() < _deadline:
                    try:
                        s.settimeout(max(0.05, _deadline - _time.time()))
                        data, (sender_ip, _) = s.recvfrom(512)
                        if (data[:8] == b'Art-Net\x00'
                                and data[8:10] == b'\x00\x21'
                                and sender_ip not in _local_ips):
                            node_ok = True
                            _node_via_artpoll = True
                            found_ip = sender_ip
                            break
                    except _socket.timeout:
                        break
                    except Exception:
                        break
                s.close()
            except Exception:
                pass

            # 2b. Ping fallback — beaucoup de nodes Art-Net ne répondent pas à ArtPoll
            if not node_ok:
                import subprocess as _sp
                _ping_flags = ["-n", "1", "-w", "800"] if __import__('sys').platform == "win32" else ["-c", "1", "-W", "1"]
                try:
                    _pr = _sp.run(["ping"] + _ping_flags + [TARGET_IP],
                                  capture_output=True, creationflags=0x08000000)
                    if _pr.returncode == 0:
                        node_ok = True
                        found_ip = TARGET_IP
                except Exception:
                    pass

            if node_ok:
                icon_node.setText("✓")
                icon_node.setStyleSheet("color: #4CAF50;")
                # Mise à jour IP cible uniquement via ArtPoll (pas via ping)
                # et seulement si l'IP est différente ET dans la plage 2.x.x.x
                if _node_via_artpoll and found_ip != self.dmx.target_ip and found_ip.startswith("2."):
                    detail_node.setText(
                        tr("mw_f_node_found_updated", found_ip=found_ip, a0=self.dmx.target_ip, a1=found_ip)
                    )
                    self._connect_dmx_async(target_ip=found_ip)
                else:
                    detail_node.setText(tr("mw_f_node_found", found_ip=found_ip))
                    if not self.dmx.connected:
                        self._connect_dmx_async()
                detail_node.setStyleSheet("color: #4CAF50;")
            else:
                icon_node.setText("✗")
                icon_node.setStyleSheet("color: #f44336;")
                if net_ok:
                    detail_node.setText(
                        tr("mw_f_no_node")
                    )
                else:
                    detail_node.setText(tr("mw_config_card_first"))
                detail_node.setStyleSheet("color: #f44336;")

            if not net_ok or not node_ok:
                btn_config.show()

            btn_refresh.setEnabled(True)
            btn_refresh.setText(tr("mw_refresh_m"))
            QApplication.processEvents()

        # Bouton Actualiser (inséré avant Fermer)
        btn_refresh = QPushButton(tr("mw_refresh_m"))
        btn_refresh.setFixedHeight(30)
        btn_refresh.setStyleSheet(
            "QPushButton { background: #1a2a1a; color: #66cc66; border: 1px solid #336633;"
            " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
            "QPushButton:hover { background: #223322; color: #88ee88; }"
            "QPushButton:disabled { color: #444; border-color: #333; }"
        )
        btn_refresh.setToolTip(tr("mw_rescan_net"))
        btn_refresh.clicked.connect(_run_checks)
        btn_row.insertWidget(btn_row.count() - 1, btn_refresh)   # juste avant Fermer

        # Envoi du rapport : on relit les libellés affichés, c'est exactement ce
        # que l'utilisateur a sous les yeux au moment où il clique.
        def _rj45_report():
            return ("Test RJ45 — réseau / Node Art-Net\n\n"
                    f"IP cible configurée : {self.dmx.target_ip}\n\n"
                    f"{icon_net.text()}  Carte réseau : {detail_net.text()}\n"
                    f"{icon_node.text()}  Node Art-Net : {detail_node.text()}\n")

        btn_send = QPushButton(tr("mw_send_support"))
        btn_send.setFixedHeight(30)
        fit_button(btn_send)
        btn_send.setStyleSheet(
            "QPushButton { background: #2a2a2a; color: #ccc; border: 1px solid #444;"
            " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
            "QPushButton:hover { border-color: #666; }"
        )
        btn_send.setToolTip(tr("mw_send_report_hint"))
        btn_send.clicked.connect(lambda: send_report_email(
            dlg, "Test RJ45 (réseau / Node Art-Net)", _rj45_report(),
            intro="Bonjour,\n\nVoici le rapport du test RJ45 (réseau / Node Art-Net)."))
        btn_row.insertWidget(btn_row.count() - 1, btn_send)

        # Analyse approfondie : les deux voyants disent SI ça marche, pas
        # POURQUOI ça ne marche pas. Ce bouton ouvre le détail — cartes, route,
        # conflit de port, réponse ArtPoll nominative — avec copie et envoi.
        btn_deep = QPushButton(tr("mw_detailed_scan"))
        btn_deep.setFixedHeight(30)
        btn_deep.setStyleSheet(
            "QPushButton { background: #1a2a3a; color: #66aadd; border: 1px solid #2a4a6a;"
            " border-radius: 4px; padding: 0 14px; font-size: 10px; }"
            "QPushButton:hover { color: #88ccff; border-color: #4a7aaa; }"
        )
        btn_deep.setToolTip(tr("mw_report_contents"))
        btn_deep.clicked.connect(lambda: self._show_diag_report(
            "Analyse réseau détaillée", self._rj45_deep_report(),
            "Diagnostic réseau / Art-Net"))
        btn_row.insertWidget(btn_row.count() - 1, btn_deep)

        dlg.show()
        _run_checks()
        dlg.exec()

    def configure_node(self):
        """Configure les parametres du Node DMX"""
        if not self._license.dmx_allowed:
            self._dmx_locked_notice()
            return

        dialog = QDialog(self)
        dialog.setWindowTitle(tr("mw_node_settings"))
        dialog.setFixedSize(350, 310)
        dialog.setStyleSheet("""
            QDialog { background: #1a1a1a; }
            QLabel { color: white; border: none; }
            QLineEdit {
                background: #2a2a2a; color: white; border: 1px solid #3a3a3a;
                border-radius: 4px; padding: 6px; font-size: 12px;
            }
        """)

        layout = QVBoxLayout(dialog)
        layout.setContentsMargins(20, 15, 20, 15)
        layout.setSpacing(10)

        title = QLabel(tr("mw_node_config"))
        title.setStyleSheet("font-size: 14px; font-weight: bold;")
        title.setAlignment(Qt.AlignCenter)
        layout.addWidget(title)

        # IP
        ip_layout = QHBoxLayout()
        ip_layout.addWidget(QLabel(tr("mw_ip_addr")))
        ip_edit = QLineEdit(self.dmx.target_ip)
        ip_layout.addWidget(ip_edit)
        layout.addLayout(ip_layout)

        # Port
        port_layout = QHBoxLayout()
        port_layout.addWidget(QLabel(tr("mw_port")))
        port_edit = QLineEdit(str(self.dmx.target_port))
        port_layout.addWidget(port_edit)
        layout.addLayout(port_layout)

        # Univers
        univers_layout = QHBoxLayout()
        univers_layout.addWidget(QLabel(tr("mw_universe_colon")))
        univers_edit = QLineEdit(str(self.dmx.universe))
        univers_layout.addWidget(univers_edit)
        layout.addLayout(univers_layout)

        # Miroir sortie 2
        from PySide6.QtWidgets import QCheckBox
        mirror_chk = QCheckBox(tr("mw_mirror_out2"))
        mirror_chk.setChecked(self.dmx.mirror_output)
        mirror_chk.setStyleSheet("color: white;")
        layout.addWidget(mirror_chk)

        univers2_layout = QHBoxLayout()
        univers2_label = QLabel(tr("mw_out2_universe"))
        univers2_edit  = QLineEdit(str(self.dmx.universe2))
        univers2_layout.addWidget(univers2_label)
        univers2_layout.addWidget(univers2_edit)
        layout.addLayout(univers2_layout)

        def _toggle_univers2(checked):
            univers2_label.setEnabled(checked)
            univers2_edit.setEnabled(checked)
        _toggle_univers2(mirror_chk.isChecked())
        mirror_chk.toggled.connect(_toggle_univers2)

        # Boutons
        btn_layout = QHBoxLayout()
        apply_btn = QPushButton(tr("mw_apply"))
        apply_btn.setStyleSheet("""
            QPushButton { background: #2a5a2a; color: white; border: none;
                border-radius: 6px; padding: 8px 20px; font-weight: bold; }
            QPushButton:hover { background: #3a7a3a; }
        """)

        def apply_config():
            new_ip = ip_edit.text().strip()
            try:
                new_port = int(port_edit.text().strip())
            except ValueError:
                new_port = self.dmx.target_port
            try:
                new_universe = int(univers_edit.text().strip())
            except ValueError:
                new_universe = self.dmx.universe
            try:
                new_universe2 = int(univers2_edit.text().strip())
            except ValueError:
                new_universe2 = new_universe + 1
            new_mirror = mirror_chk.isChecked()
            # Force transport artnet (le dialog "Configure NODE" est toujours Art-Net)
            from artnet_dmx import TRANSPORT_ARTNET
            self.dmx.connected = False
            self.dmx.connect(
                transport=TRANSPORT_ARTNET,
                target_ip=new_ip,
                target_port=new_port,
                universe=new_universe,
                universe2=new_universe2,
                mirror_output=new_mirror,
            )
            dialog.accept()
            mirror_info = f"\nMiroir sortie 2: univers {self.dmx.universe2}" if new_mirror else ""
            QMessageBox.information(self, "NODE",
                tr("mw_f_node_applied", a0=self.dmx.target_ip, a1=self.dmx.target_port, a2=self.dmx.universe, mirror_info=mirror_info))

        apply_btn.clicked.connect(apply_config)
        btn_layout.addWidget(apply_btn)

        cancel_btn = QPushButton(tr("mw_cancel"))
        cancel_btn.setStyleSheet("""
            QPushButton { background: #3a3a3a; color: white; border: none;
                border-radius: 6px; padding: 8px 20px; font-weight: bold; }
            QPushButton:hover { background: #4a4a4a; }
        """)
        cancel_btn.clicked.connect(dialog.reject)
        btn_layout.addWidget(cancel_btn)
        layout.addLayout(btn_layout)

        dialog.exec()

    def play_test_sound(self):
        """Genere et joue un son de test 440Hz"""
        import wave
        import struct
        import tempfile

        # Generer un WAV 440Hz d'une seconde
        sample_rate = 44100
        duration = 1.0
        frequency = 440.0
        amplitude = 0.5

        filepath = os.path.join(tempfile.gettempdir(), "maestro_test_440hz.wav")
        try:
            with wave.open(filepath, 'w') as wf:
                wf.setnchannels(1)
                wf.setsampwidth(2)
                wf.setframerate(sample_rate)
                num_samples = int(sample_rate * duration)
                import math
                for i in range(num_samples):
                    sample = amplitude * math.sin(2.0 * math.pi * frequency * i / sample_rate)
                    wf.writeframes(struct.pack('<h', int(sample * 32767)))

            self.cart_player.setSource(QUrl.fromLocalFile(filepath))
            self.cart_player.play()
            QMessageBox.information(self, "AUDIO", tr("mw_test_sound_sent"))
        except Exception as e:
            QMessageBox.warning(self, "AUDIO", tr("mw_f_sound_err", e=e))

    def _populate_audio_output_menu(self):
        """Remplit dynamiquement le sous-menu Sortie Audio avec les peripheriques"""
        self.audio_output_menu.clear()
        devices = QMediaDevices.audioOutputs()
        current_device = self.audio.device()

        for dev in devices:
            action = self.audio_output_menu.addAction(dev.description())
            action.setCheckable(True)
            action.setChecked(dev.id() == current_device.id())
            action.triggered.connect(lambda checked, d=dev: self._set_audio_output(d))

    def _set_audio_output(self, device):
        """Change le peripherique de sortie audio"""
        self.audio.setDevice(device)
        self.cart_audio.setDevice(device)

    def _populate_screen_menu(self):
        """Remplit dynamiquement le sous-menu de choix d'ecran"""
        self.video_screen_menu.clear()
        screens = QApplication.screens()
        for i, screen in enumerate(screens):
            geo = screen.geometry()
            label = f"Ecran {i + 1} ({screen.name()} - {geo.width()}x{geo.height()})"
            action = self.video_screen_menu.addAction(label)
            action.setCheckable(True)
            action.setChecked(i == self.video_target_screen)
            action.triggered.connect(lambda checked, idx=i: self._set_video_screen(idx))

    def _set_video_screen(self, screen_index):
        """Change l'ecran cible pour la sortie video"""
        self.video_target_screen = screen_index
        # Si la fenetre est deja ouverte, la deplacer
        if self.video_output_window and self.video_output_window.isVisible():
            screens = QApplication.screens()
            if screen_index < len(screens):
                screen = screens[screen_index]
                self.video_output_window.setGeometry(screen.geometry())
                self.video_output_window.showFullScreen()

    def show_test_logo(self):
        """Affiche le logo de test pendant 3 secondes (preview + externe si active)"""
        from core import resource_path
        logo_path = resource_path("logo.png")
        if not os.path.exists(logo_path):
            QMessageBox.warning(self, "VIDEO", tr("mw_logo_missing"))
            return

        # Afficher dans le preview local (toujours)
        self.show_image(logo_path)

        # Afficher aussi dans la fenetre externe si elle est active
        if self.video_output_window and self.video_output_window.isVisible():
            pixmap = QPixmap(logo_path)
            if not pixmap.isNull():
                self.video_output_window.show_image(pixmap)

        # Masquer apres 3 secondes
        QTimer.singleShot(3000, self._hide_test_logo)

    def _hide_test_logo(self):
        """Cache le logo de test"""
        self.hide_image()
        if self.video_output_window and self.video_output_window.isVisible():
            self._update_video_output_state()

    def toggle_video_output_from_menu(self):
        """Active/desactive la sortie video depuis le menu"""
        self.video_output_btn.setChecked(not self.video_output_btn.isChecked())
        self.toggle_video_output()
        # Mettre a jour le texte du menu
        if self.video_output_btn.isChecked():
            self.video_menu_toggle.setText(tr("mw_video_out_off"))
        else:
            self.video_menu_toggle.setText(tr("mw_video_out_on"))

    def _compute_htp_overrides(self):
        """Calcule les valeurs HTP des memoires SANS modifier les projecteurs.
        Retourne un dict {id(proj): (level, QColor_display, QColor_base)} pour l'affichage."""
        overrides = {}

        for fi, mem_col in self._bank_memory_slots():
            col_akai = fi
            if col_akai in self._muted_faders:
                continue
            fv = self.faders[col_akai].value if col_akai in self.faders else 0
            active_row = self.active_memory_pads.get(col_akai)
            if fv > 0 and active_row is not None and self.memories[mem_col][active_row]:
                mem = self.memories[mem_col][active_row]
                self._mem_ensure_cues(mem)
                cue_idx = self._mem_cue_idx.get((mem_col, active_row), 0)
                cues = mem.get("cues", [])
                cue = cues[min(cue_idx, len(cues)-1)] if cues else {}
                mem_projs = cue.get("projectors", [])
                for i, proj in enumerate(self.projectors):
                    # Fixture prise en main depuis le plan 2D → la mémoire la laisse
                    # tranquille jusqu'au CLEAR.
                    if getattr(proj, '_manual_color', False):
                        continue
                    if i < len(mem_projs):
                        ms = mem_projs[i]
                        mem_level = int(ms["level"] * fv / 100.0)
                        # HTP: comparer avec le niveau actuel du projecteur ou override precedent
                        current_level = overrides[id(proj)][0] if id(proj) in overrides else proj.level
                        if mem_level > current_level:
                            base = QColor(ms["base_color"])
                            brt = mem_level / 100.0
                            color = QColor(
                                int(base.red() * brt),
                                int(base.green() * brt),
                                int(base.blue() * brt))
                            overrides[id(proj)] = (mem_level, color, base)

        return overrides

    def _apply_htp_to_projectors(self, overrides):
        """Applique temporairement les overrides HTP sur les projecteurs pour envoi DMX.
        Retourne la liste des etats sauvegardes pour restauration."""
        saved = []
        for proj in self.projectors:
            saved.append((proj.level, QColor(proj.color), QColor(proj.base_color)))
            if id(proj) in overrides:
                level, color, base = overrides[id(proj)]
                proj.level = level
                proj.color = color
                proj.base_color = base
        return saved

    def _apply_editor_live_overrides(self):
        """
        Applique la sortie live de l'éditeur d'effets, le temps d'une frame DMX.

        Format volontairement distinct des overrides HTP : l'éditeur produit
        `(level, color, pan, tilt)` — il pilote aussi le mouvement des lyres,
        ce que les mémoires ne font pas. Retourne l'état sauvegardé, à restaurer
        après l'envoi comme pour les autres sources temporaires.
        """
        ov = getattr(self, '_editor_live_overrides', None)
        if not ov:
            return None
        saved = []
        for proj in self.projectors:
            entry = ov.get(id(proj))
            if entry is None:
                continue
            saved.append((proj, proj.level, QColor(proj.color),
                          QColor(proj.base_color), proj.pan, proj.tilt))
            level, color = entry[0], entry[1]
            proj.level = level
            proj.color = QColor(color)
            proj.base_color = QColor(color)
            if len(entry) > 3:
                if entry[2] is not None:
                    proj.pan = entry[2]
                if entry[3] is not None:
                    proj.tilt = entry[3]
        return saved

    @staticmethod
    def _restore_editor_live_overrides(saved):
        if not saved:
            return
        for proj, lvl, col, base, pan, tilt in saved:
            proj.level = lvl
            proj.color = col
            proj.base_color = base
            proj.pan = pan
            proj.tilt = tilt

    def _apply_pad_overrides_htp(self):
        """Applique les pads AKAI actifs en HTP par-dessus l'etat courant des projecteurs.
        Retourne la liste des etats sauvegardes pour restauration apres envoi DMX."""
        saved = []
        for col_idx, btn in self.active_pads.items():
            if btn is None:
                continue
            if col_idx in self._muted_faders:
                continue
            color = btn.property("base_color")
            if color is None:
                continue
            fader_value = self.faders[col_idx].value if col_idx in self.faders else 0
            if fader_value <= 0:
                continue
            brightness = fader_value / 100.0
            pad_color = QColor(
                int(color.red() * brightness),
                int(color.green() * brightness),
                int(color.blue() * brightness),
            )
            # Get target groups from current fader map
            if col_idx < len(self._fader_map):
                slot = self._fader_map[col_idx]
                target_groups = self._slot_groups(slot)
            else:
                target_groups = []
            for i, proj in enumerate(self.projectors):
                if proj.group in target_groups and fader_value > proj.level:
                    saved.append((i, proj.level, proj.color, proj.base_color))
                    proj.level = fader_value
                    proj.color = pad_color
                    proj.base_color = color
        return saved

    def send_dmx_update(self):
        """Envoie les donnees DMX avec HTP memoires + pads AKAI + refresh plan de feu"""
        # Appliquer l'effet en cours — sauf si un autre moteur pilote déjà les
        # projecteurs et appelle update_effect() lui-même :
        #  • timeline (Play Lumière) → apply_timeline_to_dmx
        #  • aperçu REC Lumière → _apply_preview_to_projectors
        # Sinon l'effet serait piloté à 2 cadences déphasées (ce timer 25 ms +
        # l'autre moteur) → un effet à compteur strobe.
        _seq = getattr(self, 'seq', None)
        _timeline_active = hasattr(_seq, 'timeline_playback_row') if _seq else False
        _preview_active  = getattr(self, '_rec_preview_active', False)
        if not _timeline_active and not _preview_active \
                and getattr(self, 'active_effect', None) is not None:
            self.update_effect()

        # Zéroter temporairement les projecteurs des mémoires mutées (enforcement du mute)
        muted_saved = {}
        for fi, mem_col in self._bank_memory_slots():
            if fi not in self._muted_faders:
                continue
            active_row = self.active_memory_pads.get(fi)
            if active_row is None:
                continue
            mem = self.memories[mem_col][active_row]
            if not mem:
                continue
            self._mem_ensure_cues(mem)
            cue_idx = self._mem_cue_idx.get((mem_col, active_row), 0)
            cues = mem.get("cues", [])
            cue = cues[min(cue_idx, len(cues) - 1)] if cues else {}
            for i, ps in enumerate(cue.get("projectors", [])):
                if i < len(self.projectors) and ps.get("level", 0) > 0 and i not in muted_saved:
                    p = self.projectors[i]
                    muted_saved[i] = (p.level, QColor(p.color), QColor(p.base_color))
                    p.level = 0
                    p.color = QColor("black")
                    p.base_color = QColor("black")

        # Calculer les overrides HTP sans modifier les projecteurs
        overrides = self._compute_htp_overrides()

        # Stocker les overrides sur le plan de feu
        self.plan_de_feu.set_htp_overrides(overrides if overrides else None)

        if self.plan_de_feu.is_dmx_enabled() and self.dmx.connected:
            # Appliquer temporairement HTP memoires
            if overrides:
                saved_htp = self._apply_htp_to_projectors(overrides)

            # Appliquer temporairement les pads AKAI en HTP (fonctionne dans TOUS les modes)
            saved_pads = self._apply_pad_overrides_htp()

            # Sortie live de l'éditeur d'effets : appliquée en DERNIER, donc
            # prioritaire — c'est une action explicite de l'utilisateur qui règle
            # son effet et veut voir CE qu'il règle sur ses lampes.
            saved_editor = self._apply_editor_live_overrides()

            # Envoyer DMX
            self.dmx.update_from_projectors(self.projectors, self.effect_speed)
            self.dmx.send_dmx()

            # Restaurer dans l'ordre inverse de l'application
            self._restore_editor_live_overrides(saved_editor)

            # Restaurer etat pads
            for i, level, color, base_color in saved_pads:
                self.projectors[i].level = level
                self.projectors[i].color = color
                self.projectors[i].base_color = base_color

            # Restaurer etat HTP memoires
            if overrides:
                for i, proj in enumerate(self.projectors):
                    proj.level, proj.color, proj.base_color = saved_htp[i]
        elif self.dmx.connected and getattr(self.dmx, 'transport', '') in ('enttec', 'enttec_pro'):
            # ENTTEC : envoyer des frames nulles pour garder le lien actif (évite le timeout)
            self.dmx.send_dmx()

        # Restaurer les projecteurs des mémoires mutées
        for i, (level, color, base) in muted_saved.items():
            p = self.projectors[i]
            p.level = level
            p.color = color
            p.base_color = base

        # Rafraîchir le plan de feu à ~20fps (1 tick sur 2). La sortie DMX part à
        # chaque tick (40fps) pour le matériel, mais le repaint à l'écran n'a pas
        # besoin d'être aussi rapide : ça soulage nettement le thread UI sur les
        # shows lourds (REC long, vidéo 40 min) sans impact visible.
        self._pdf_refresh_tick = (getattr(self, '_pdf_refresh_tick', 0) + 1) & 1
        if self._pdf_refresh_tick == 0:
            self.plan_de_feu.mark_dirty()
            self.plan_de_feu.refresh()

        # Rafraichir la fenêtre 3D si visible
        if hasattr(self, '_plan3d') and self._plan3d.isVisible():
            self._plan3d.refresh(self.projectors)

    def stop_recording(self):
        """Arrete l'enregistrement"""
        if not self.seq.recording:
            return
        self.seq.recording = False
        if self.seq.recording_timer:
            self.seq.recording_timer.stop()
